const KET_WORDS = [{"w":"library","uk":"/ˈlaɪbrəri/","p":"n.","zh":"图书馆；藏书室","ex":{"en":"I borrowed three books from the library after school.","zh":"放学后，我从图书馆借了三本书。"},"tip":"library是借阅书籍的图书馆，bookshop是售书的书店。","topic":"education","cefr":"A1"},{"w":"bedroom","uk":"/ˈbedruːm/","p":"n.","zh":"卧室","ex":{"en":"My bedroom gets plenty of sunlight in the morning.","zh":"我的卧室早晨阳光很充足。"},"tip":"可数名词；a two-bedroom flat指两居室公寓。","topic":"daily","cefr":"A1"},{"w":"clothes","uk":"/kləʊðz/","p":"n.","zh":"衣服；服装","ex":{"en":"Your clean clothes are drying outside in the sunshine.","zh":"你洗干净的衣服正在外面晒太阳。"},"tip":"只有复数形式；一件衣服用an item of clothing。","topic":"daily","cefr":"A1"},{"w":"strong","uk":"/strɒŋ/","p":"adj.","zh":"强壮的；有力的","ex":{"en":"My brother is strong enough to lift this sofa.","zh":"我哥哥力气很大，能抬起这张沙发。"},"tip":"strong at表示擅长；strong通常是形容词。","topic":"daily","cefr":"A1"},{"w":"body","uk":"/ˈbɒdi/","p":"n.","zh":"身体；躯体","ex":{"en":"My whole body aches after yesterday's long walk.","zh":"昨天走了很长一段路，现在我全身酸痛。"},"tip":"body可指机构；文章的body指正文部分。","topic":"health","cefr":"A1"},{"w":"month","uk":"/mʌnθ/","p":"n.","zh":"月；一个月","ex":{"en":"I put aside a little money every month.","zh":"我每个月都会存下一点钱。"},"tip":"last、next、every month前通常不加介词。","topic":"daily","cefr":"A1"},{"w":"let","uk":"/let/","p":"v.","zh":"允许；让","ex":{"en":"Please let me know when you arrive home safely.","zh":"你平安到家后请告诉我。"},"tip":"let sb do sth中不加to；过去式、过去分词均为let。","topic":"daily","cefr":"A1"},{"w":"born","uk":"/bɔːn/","p":"v.","zh":"出生","ex":{"en":"My little sister was born on a snowy morning.","zh":"我的小妹妹出生在一个下雪的早晨。"},"tip":"出生用be born；过去出生说was/were born。","topic":"society","cefr":"A1"},{"w":"paint","uk":"/peɪnt/","p":"n.","zh":"油漆；颜料","ex":{"en":"There is blue paint all over your hands.","zh":"你的双手沾满了蓝色颜料。"},"tip":"paint多指用颜料画；draw多指用铅笔等画线条。","topic":"arts","cefr":"A1"},{"w":"use","uk":"/juːz/, /juːs/","p":"v.","zh":"使用；运用","ex":{"en":"Can I use your scissors to open this package?","zh":"我可以用你的剪刀打开这个包裹吗？"},"tip":"动词读/juːz/，名词读/juːs/。","topic":"daily","cefr":"A1"},{"w":"minute","uk":"/ˈmɪnɪt/, /maɪˈnjuːt/","p":"n.","zh":"分钟；片刻","ex":{"en":"Wait a minute while I find my keys.","zh":"等一下，我找找钥匙。"},"tip":"会议记录用复数minutes；形容词“微小的”重音在后。","topic":"daily","cefr":"A1"},{"w":"even","uk":"/ˈiːvən/","p":"adv.","zh":"甚至；连……都","ex":{"en":"Everyone joined the dance, even our shy uncle.","zh":"大家都加入了舞蹈，连我们害羞的叔叔也不例外。"},"tip":"even if表假设“即使”；even though表事实“尽管”。","topic":"daily","cefr":"A1"},{"w":"cut","uk":"/kʌt/","p":"v.","zh":"切；剪；割","ex":{"en":"She cut the apple into slices for her brother.","zh":"她把苹果切成片给弟弟吃。"},"tip":"过去式和过去分词均为cut；现在分词为cutting。","topic":"daily","cefr":"A1"},{"w":"remember","uk":"/rɪˈmembə/","p":"v.","zh":"记得；想起","ex":{"en":"I still remember the smell of my grandmother's kitchen.","zh":"我至今还记得祖母厨房里的气味。"},"tip":"remember to do是记得去做；doing是记得做过。","topic":"thinking","cefr":"A1"},{"w":"wake","uk":"/weɪk/","p":"v.","zh":"醒来；唤醒","ex":{"en":"Please wake me before you leave for work.","zh":"请在你出门上班前叫醒我。"},"tip":"过去式woke，过去分词woken；常与up连用。","topic":"daily","cefr":"A1"},{"w":"juice","uk":"/dʒuːs/","p":"n.","zh":"果汁；蔬菜汁","ex":{"en":"She squeezed fresh orange juice into a glass.","zh":"她把鲜橙汁挤进了玻璃杯里。"},"tip":"juice通常不可数；点餐时a juice可指一杯果汁。","topic":"daily","cefr":"A1"},{"w":"really","uk":"/ˈrɪəli/","p":"adv.","zh":"很；非常","ex":{"en":"This soup is really hot, so let it cool.","zh":"这汤非常烫，先让它凉一凉吧。"},"tip":"not really通常表示“不太”，语气比直接说no缓和。","topic":"daily","cefr":"A1"},{"w":"river","uk":"/ˈrɪvə/","p":"n.","zh":"河；江","ex":{"en":"We watched ducks swimming across the river this morning.","zh":"今天早上，我们看着鸭子游过河面。"},"tip":"河名通常带the，如the River Nile。","topic":"nature","cefr":"A1"},{"w":"horse","uk":"/hɔːs/","p":"n.","zh":"马","ex":{"en":"The brown horse gently took an apple from my hand.","zh":"那匹棕色的马轻轻地吃走了我手里的苹果。"},"tip":"骑马用ride a horse；on horseback表示骑在马上。","topic":"nature","cefr":"A1"},{"w":"lunch","uk":"/lʌntʃ/","p":"n.","zh":"午餐","ex":{"en":"We ate lunch under a tree beside the river.","zh":"我们在河边的一棵树下吃了午饭。"},"tip":"泛指吃午餐用have lunch，通常不加冠词。","topic":"daily","cefr":"A1"},{"w":"tall","uk":"/tɔːl/","p":"adj.","zh":"高的；高大的","ex":{"en":"A tall tree shades our garden in the afternoon.","zh":"下午，一棵高大的树为我们的花园遮阴。"},"tip":"人、树、楼通常用tall；山通常用high。","topic":"daily","cefr":"A1"},{"w":"also","uk":"/ˈɔːlsəʊ/","p":"adv.","zh":"也；而且","ex":{"en":"My sister plays tennis and also enjoys swimming.","zh":"我姐姐打网球，也喜欢游泳。"},"tip":"通常放实义动词前、be动词后；不是连词。","topic":"daily","cefr":"A1"},{"w":"coat","uk":"/kəʊt/","p":"n.","zh":"外套；大衣","ex":{"en":"Hang your wet coat by the kitchen door.","zh":"把你的湿外套挂在厨房门边。"},"tip":"动词常用coat A with B，意为给A涂上B。","topic":"daily","cefr":"A1"},{"w":"elephant","uk":"/ˈelɪfənt/","p":"n.","zh":"象；大象","ex":{"en":"The elephant sprayed water over its back with its trunk.","zh":"大象用鼻子把水喷到自己的背上。"},"tip":"复数为elephants；象鼻用trunk，不用nose。","topic":"nature","cefr":"A1"},{"w":"fast","uk":"/fɑːst/","p":"adj.","zh":"快速的","ex":{"en":"We caught a fast train and arrived before lunch.","zh":"我们赶上了一班快车，在午饭前就到了。"},"tip":"fast本身可作副词，不能说fastly。","topic":"daily","cefr":"A1"},{"w":"from","uk":"/frɒm/","p":"prep.","zh":"从；来自","ex":{"en":"This postcard came from my cousin in the mountains.","zh":"这张明信片是住在山区的表亲寄来的。"},"tip":"from表示起点，常与表示终点的to搭配。","topic":"daily","cefr":"A1"},{"w":"quickly","uk":"/ˈkwɪkli/","p":"adv.","zh":"迅速地；很快地","ex":{"en":"We quickly packed our bags when the taxi arrived.","zh":"出租车一到，我们就迅速收拾好了行李。"},"tip":"quickly是副词，修饰动作；quick是形容词，修饰名词。","topic":"daily","cefr":"A1"},{"w":"activity","uk":"/ækˈtɪvəti/","p":"n.","zh":"活动","ex":{"en":"Painting is my favourite activity on rainy afternoons.","zh":"下雨的午后，我最喜欢的活动是画画。"},"tip":"具体活动可数；泛指活跃或活动量时不可数。","topic":"daily","cefr":"A1"},{"w":"town","uk":"/taʊn/","p":"n.","zh":"城镇；市镇","ex":{"en":"Our town has a bakery beside the old bridge.","zh":"我们镇的老桥旁有一家面包店。"},"tip":"go into town指去市中心，此时town前不加冠词。","topic":"city","cefr":"A1"},{"w":"without","uk":"/wɪˈðaʊt/","p":"prep.","zh":"没有；不带；不与……一起","ex":{"en":"I left the house without my keys this morning.","zh":"今天早上我出门时没带钥匙。"},"tip":"without 是介词，后接名词、代词或动词-ing。","topic":"daily","cefr":"A1"},{"w":"picture","uk":"/ˈpɪktʃə/","p":"n.","zh":"图片；图画；照片","ex":{"en":"She hung a picture of the sea above her bed.","zh":"她在床头上方挂了一幅海景画。"},"tip":"take a picture是拍照；draw a picture是画画。","topic":"arts","cefr":"A1"},{"w":"child","uk":"/tʃaɪld/","p":"n.","zh":"儿童；小孩","ex":{"en":"The child carefully carried a bowl of water outside.","zh":"那个孩子小心翼翼地端着一碗水走到外面。"},"tip":"复数是children；childish偏贬义，childlike指天真如孩童。","topic":"society","cefr":"A1"},{"w":"kind","uk":"/kaɪnd/","p":"adj.","zh":"善良的；体贴的","ex":{"en":"Our kind neighbour brought us soup when we were ill.","zh":"我们生病时，体贴的邻居给我们送来了汤。"},"tip":"形容词常接to；种类用a kind of加名词。","topic":"society","cefr":"A1"},{"w":"nothing","uk":"/ˈnʌθɪŋ/","p":"pron.","zh":"没有任何东西；毫无","ex":{"en":"I opened the fridge, but there was nothing inside.","zh":"我打开冰箱，里面却什么也没有。"},"tip":"nothing本身含否定意义，通常不再与not连用。","topic":"daily","cefr":"A1"},{"w":"why","uk":"/waɪ/","p":"adv.","zh":"为什么","ex":{"en":"Why are your shoes still wet this morning?","zh":"为什么你的鞋今天早上还是湿的？"},"tip":"间接疑问句用陈述语序：I know why he left。","topic":"thinking","cefr":"A1"},{"w":"hat","uk":"/hæt/","p":"n.","zh":"帽子","ex":{"en":"I grabbed my hat before stepping into the sunshine.","zh":"走到阳光下之前，我拿起了帽子。"},"tip":"戴着帽子用wear；戴上帽子的动作用put on。","topic":"daily","cefr":"A1"},{"w":"worker","uk":"/ˈwɜːkə/","p":"n.","zh":"工人；工作者","ex":{"en":"A worker in orange overalls repaired the broken fence.","zh":"一名穿橙色工作服的工人修好了破损的围栏。"},"tip":"不只指体力劳动者，也可指医护等职业工作者。","topic":"work","cefr":"A1"},{"w":"chips","uk":"/tʃɪps/","p":"n.","zh":"炸薯条（英）；薯片（美）","ex":{"en":"These chips are crispy outside and soft in the middle.","zh":"这些薯条外脆内软。"},"tip":"英式chips是薯条，crisps是薯片；美式薯条叫fries。","topic":"daily","cefr":"A1"},{"w":"keep","uk":"/kiːp/","p":"v.","zh":"保留；保存","ex":{"en":"You can keep the umbrella until the rain stops.","zh":"雨停之前，你可以继续留着这把伞用。"},"tip":"过去式、过去分词均为kept；继续做用keep doing。","topic":"daily","cefr":"A1"},{"w":"left","uk":"/left/","p":"adj.","zh":"左边的；左侧的","ex":{"en":"I carry my shopping bag in my left hand.","zh":"我用左手提购物袋。"},"tip":"也是 leave 的过去式和过去分词；表剩余时置于名词后。","topic":"daily","cefr":"A1"},{"w":"put","uk":"/pʊt/","p":"v.","zh":"放；安置","ex":{"en":"Please put your wet umbrella beside the door.","zh":"请把你的湿雨伞放在门旁边。"},"tip":"过去式、过去分词均为put；放置义通常需接地点。","topic":"daily","cefr":"A1"},{"w":"rainy","uk":"/ˈreɪni/","p":"adj.","zh":"下雨的；多雨的","ex":{"en":"We stayed indoors and baked bread on that rainy afternoon.","zh":"那个下雨的下午，我们待在室内烤面包。"},"tip":"rainy是形容词；正在下雨用It is raining。","topic":"nature","cefr":"A1"},{"w":"hotel","uk":"/həʊˈtel/","p":"n.","zh":"酒店；旅馆","ex":{"en":"Our hotel room overlooks a quiet sandy beach.","zh":"我们住的酒店房间可以俯瞰一片宁静的沙滩。"},"tip":"表示住酒店可用stay at或stay in a hotel。","topic":"travel","cefr":"A1"},{"w":"skirt","uk":"/skɜːt/","p":"n.","zh":"裙子","ex":{"en":"Her blue skirt swayed as she walked upstairs.","zh":"她上楼时，蓝色裙子轻轻摆动。"},"tip":"skirt是裙子；dress通常指连衣裙。","topic":"daily","cefr":"A1"},{"w":"side","uk":"/saɪd/","p":"n.","zh":"侧面；边；旁边","ex":{"en":"Please leave your muddy boots by the side door.","zh":"请把沾满泥的靴子放在侧门旁。"},"tip":"side with表示支持某方；side by side表示并排。","topic":"daily","cefr":"A1"},{"w":"pretty","uk":"/ˈprɪti/","p":"adj.","zh":"漂亮的；秀丽的","ex":{"en":"We found a pretty cottage beside a quiet stream.","zh":"我们在一条安静的小溪边发现了一座漂亮的小屋。"},"tip":"作副词表示“相当”时偏口语，正式写作可用fairly。","topic":"daily","cefr":"A1"},{"w":"arrive","uk":"/əˈraɪv/","p":"v.","zh":"到达；抵达","ex":{"en":"Our guests arrived just as dinner was ready.","zh":"我们的客人恰好在晚饭准备好时到了。"},"tip":"小地点用 at，城市国家用 in；home 前不加介词。","topic":"travel","cefr":"A1"},{"w":"too","uk":"/tuː/","p":"adv.","zh":"太；过于","ex":{"en":"This soup is too hot to eat now.","zh":"这汤现在太烫，还不能喝。"},"tip":"too强调超过合适程度；very只强调程度高。","topic":"daily","cefr":"A1"},{"w":"glass","uk":"/ɡlɑːs/","p":"n.","zh":"玻璃","ex":{"en":"The ball hit the window and shattered the glass.","zh":"球砸中了窗户，把玻璃打碎了。"},"tip":"玻璃不可数，玻璃杯可数；眼镜用复数glasses。","topic":"daily","cefr":"A1"},{"w":"policeman","uk":"/pəˈliːsmən/","p":"n.","zh":"男警察","ex":{"en":"A policeman helped us cross the busy road.","zh":"一位男警察帮我们穿过了繁忙的马路。"},"tip":"policeman指男性；不强调性别用police officer。","topic":"society","cefr":"A1"},{"w":"or","uk":"/ɔː/","p":"conj.","zh":"或者；还是","ex":{"en":"Would you like rice or noodles with your vegetables?","zh":"蔬菜配米饭还是面条，你想选哪一种？"},"tip":"否定句中连接并列项常用or，不用and。","topic":"daily","cefr":"A1"},{"w":"once","uk":"/wʌns/","p":"adv.","zh":"一次","ex":{"en":"I water this little cactus once every two weeks.","zh":"我每两周给这株小仙人掌浇一次水。"},"tip":"once引导将来时间从句时，通常用一般现在时。","topic":"daily","cefr":"A1"},{"w":"sock","uk":"/sɒk/","p":"n.","zh":"短袜；袜子","ex":{"en":"One blue sock was hiding under the bed.","zh":"一只蓝袜子藏在床底下。"},"tip":"一双袜子说a pair of socks，sock为可数名词。","topic":"daily","cefr":"A1"},{"w":"letter","uk":"/ˈletə/","p":"n.","zh":"信；信函","ex":{"en":"A letter from my sister arrived this morning.","zh":"今天早上，我收到了姐姐寄来的信。"},"tip":"letter既指信，也指字母；character还可指汉字等字符。","topic":"daily","cefr":"A1"},{"w":"bad","uk":"/bæd/","p":"adj.","zh":"差的；劣质的","ex":{"en":"The soup tasted so bad that I stopped eating.","zh":"这汤太难喝了，我便不再喝了。"},"tip":"比较级worse，最高级worst；badly是副词。","topic":"daily","cefr":"A1"},{"w":"writing","uk":"/ˈraɪtɪŋ/","p":"n.","zh":"写作；书写","ex":{"en":"I do most of my writing before breakfast.","zh":"我的写作大多在早餐前完成。"},"tip":"writing通常不可数；也是write的现在分词，需去e。","topic":"education","cefr":"A1"},{"w":"upstairs","uk":"/ˌʌpˈsteəz/","p":"adv.","zh":"在楼上；往楼上","ex":{"en":"I left my glasses upstairs beside the bed.","zh":"我把眼镜落在楼上的床边了。"},"tip":"作副词时前面不加to：go upstairs。","topic":"daily","cefr":"A1"},{"w":"nose","uk":"/nəʊz/","p":"n.","zh":"鼻子","ex":{"en":"My nose turned red in the cold wind.","zh":"我的鼻子在冷风中冻红了。"},"tip":"擤鼻涕用blow your nose，不用clean。","topic":"health","cefr":"A1"},{"w":"postcard","uk":"/ˈpəʊstkɑːd/","p":"n.","zh":"明信片","ex":{"en":"She sent me a postcard from a seaside village.","zh":"她从一个海边村庄给我寄来了一张明信片。"},"tip":"寄给某人可说send someone a postcard或用to引出收件人。","topic":"travel","cefr":"A1"},{"w":"head","uk":"/hed/","p":"n.","zh":"头；头部","ex":{"en":"She shook her head when I offered more soup.","zh":"我问她要不要再来点汤，她摇了摇头。"},"tip":"head for＋地点表示“朝某地去”。","topic":"daily","cefr":"A1"},{"w":"yesterday","uk":"/ˈjestədeɪ/","p":"adv.","zh":"在昨天","ex":{"en":"I left my umbrella on the bus yesterday.","zh":"我昨天把雨伞落在公交车上了。"},"tip":"yesterday前通常不用介词，常与一般过去时连用。","topic":"daily","cefr":"A1"},{"w":"waitress","uk":"/ˈweɪtrəs/","p":"n.","zh":"女服务员","ex":{"en":"The waitress brought us warm bread and fresh soup.","zh":"女服务员给我们端来了温热的面包和新鲜的汤。"},"tip":"waitress特指女性；server可不区分性别。","topic":"work","cefr":"A1"},{"w":"something","uk":"/ˈsʌmθɪŋ/","p":"pron.","zh":"某事；某物","ex":{"en":"There is something soft inside this little box.","zh":"这个小盒子里有个柔软的东西。"},"tip":"修饰词放后面，如something useful；作主语用单数。","topic":"daily","cefr":"A1"},{"w":"pet","uk":"/pet/","p":"n.","zh":"宠物","ex":{"en":"Our pet rabbit loves hiding under the kitchen table.","zh":"我们的宠物兔喜欢躲在厨房桌子下面。"},"tip":"动词过去式为petted；英式英语中抚摸也常用stroke。","topic":"daily","cefr":"A1"},{"w":"stop","uk":"/stɒp/","p":"v.","zh":"停止；阻止","ex":{"en":"We stopped walking when the rain became heavier.","zh":"雨越下越大，我们便停下了脚步。"},"tip":"stop doing是停止做；stop to do是停下去做。","topic":"daily","cefr":"A1"},{"w":"holiday","uk":"/ˈhɒlədeɪ/","p":"n.","zh":"假期；度假","ex":{"en":"We spent our holiday swimming and exploring quiet villages.","zh":"我们假期里游泳，还探访了宁静的村庄。"},"tip":"英式on holiday指度假；美式通常说on vacation。","topic":"travel","cefr":"A1"},{"w":"front","uk":"/frʌnt/","p":"n.","zh":"前部；正面","ex":{"en":"Please leave your muddy boots by the front door.","zh":"请把沾满泥的靴子放在前门旁。"},"tip":"in front of指外部前方；at the front of指前部。","topic":"daily","cefr":"A1"},{"w":"night","uk":"/naɪt/","p":"n.","zh":"夜晚；夜间","ex":{"en":"We watched the stars from our balcony last night.","zh":"昨晚，我们在阳台上看星星。"},"tip":"泛指夜间用at night；last night前不加介词。","topic":"daily","cefr":"A1"},{"w":"ask","uk":"/ɑːsk/","p":"v.","zh":"问；询问","ex":{"en":"I asked the driver where the bus stopped.","zh":"我问司机公交车在哪里停。"},"tip":"ask for接想要的东西；ask someone to do表示请某人做。","topic":"daily","cefr":"A1"},{"w":"jacket","uk":"/ˈdʒækɪt/","p":"n.","zh":"夹克；短外套","ex":{"en":"I grabbed my jacket before stepping into the cold.","zh":"我抓起外套，才走进寒冷的室外。"},"tip":"jacket通常是短外套，不专指羽绒服。","topic":"daily","cefr":"A1"},{"w":"lucky","uk":"/ˈlʌki/","p":"adj.","zh":"幸运的；侥幸的","ex":{"en":"We were lucky to catch the last bus home.","zh":"我们很幸运，赶上了回家的末班公交车。"},"tip":"“有幸做某事”用be lucky to do something。","topic":"emotion","cefr":"A1"},{"w":"jeans","uk":"/dʒiːnz/","p":"n.","zh":"牛仔裤","ex":{"en":"These jeans are still wet from the wash.","zh":"这条牛仔裤洗后还没干。"},"tip":"jeans用复数；一条用a pair of jeans。","topic":"daily","cefr":"A1"},{"w":"fire","uk":"/ˈfaɪə/","p":"n.","zh":"火；火灾","ex":{"en":"We warmed our hands by the fire after dinner.","zh":"晚饭后，我们在炉火旁暖手。"},"tip":"catch fire指开始着火；be on fire指正在燃烧。","topic":"daily","cefr":"A1"},{"w":"sister","uk":"/ˈsɪstə/","p":"n.","zh":"姐姐；妹妹","ex":{"en":"My younger sister always borrows my favourite blue jumper.","zh":"我妹妹总是借穿我最喜欢的蓝色毛衣。"},"tip":"sister不分姐姐妹妹；需用older或younger说明年龄关系。","topic":"daily","cefr":"A1"},{"w":"winter","uk":"/ˈwɪntə/","p":"n.","zh":"冬季；冬天","ex":{"en":"We wear thick coats when winter brings cold winds.","zh":"冬天寒风来袭时，我们会穿上厚外套。"},"tip":"泛指在冬天用in winter；具体某年可用in the winter of…。","topic":"nature","cefr":"A1"},{"w":"doctor","uk":"/ˈdɒk.tə/","p":"n.","zh":"医生","ex":{"en":"The doctor listened carefully as I described my symptoms.","zh":"我描述症状时，医生认真地听着。"},"tip":"看医生常说see a doctor；动词doctor可指篡改。","topic":"health","cefr":"A1"},{"w":"pizza","uk":"/ˈpiːtsə/","p":"n.","zh":"比萨饼","ex":{"en":"We shared a mushroom pizza after the film.","zh":"电影结束后，我们分着吃了一张蘑菇比萨。"},"tip":"整张可数：a pizza；泛指食物可说some pizza。","topic":"daily","cefr":"A1"},{"w":"pair","uk":"/peə/","p":"n.","zh":"一双；一对；一副","ex":{"en":"I left my favourite pair of gloves on the bus.","zh":"我把最喜欢的那双手套落在公交车上了。"},"tip":"a pair of shoes作主语时，谓语用单数。","topic":"daily","cefr":"A1"},{"w":"student","uk":"/ˈstjuːdənt/","p":"n.","zh":"学生","ex":{"en":"A student left her backpack under the library desk.","zh":"一名学生把背包落在了图书馆的书桌下面。"},"tip":"student不限于大学生；pupil主要指中小学生。","topic":"education","cefr":"A1"},{"w":"yourself","uk":"/jɔːˈself/","p":"pron.","zh":"你自己；您自己","ex":{"en":"Be careful not to cut yourself with that knife.","zh":"用那把刀时要小心，别割伤自己。"},"tip":"对应单数you；对多人说“你们自己”用yourselves。","topic":"daily","cefr":"A1"},{"w":"price","uk":"/praɪs/","p":"n.","zh":"价格；价钱","ex":{"en":"The price of fresh strawberries has fallen this week.","zh":"这周新鲜草莓的价格降了。"},"tip":"价格高低用high或low；物品贵便宜用expensive或cheap。","topic":"economy","cefr":"A1"},{"w":"last","uk":"/lɑːst/","p":"adj.","zh":"最后的；最近过去的","ex":{"en":"I caught the last bus home just before midnight.","zh":"我在午夜前刚好赶上了回家的末班车。"},"tip":"last week指上周；the last week可指最后一周。","topic":"daily","cefr":"A1"},{"w":"listen","uk":"/ˈlɪsən/","p":"v.","zh":"听；倾听","ex":{"en":"I listen to music while cooking dinner every evening.","zh":"每天晚上做饭时，我都会听音乐。"},"tip":"接对象须用listen to；hear侧重听到的结果。","topic":"daily","cefr":"A1"},{"w":"poor","uk":"/pɔː/","p":"adj.","zh":"贫穷的","ex":{"en":"The poor family could barely afford fresh vegetables.","zh":"这户贫困家庭几乎买不起新鲜蔬菜。"},"tip":"poor at表示不擅长；poor in表示缺乏。","topic":"society","cefr":"A1"},{"w":"gym","uk":"/dʒɪm/","p":"n.","zh":"健身房；体育馆","ex":{"en":"I usually go to the gym before work.","zh":"我通常在上班前去健身房。"},"tip":"gym是gymnasium的简称；去健身房用go to the gym。","topic":"health","cefr":"A1"},{"w":"reading","uk":"/ˈriːdɪŋ/","p":"n.","zh":"阅读","ex":{"en":"Reading before bed helps me relax after a busy day.","zh":"忙碌一天后，睡前阅读能让我放松下来。"},"tip":"表示阅读活动通常不可数；表示读数或朗诵会可数。","topic":"education","cefr":"A1"},{"w":"guitar","uk":"/ɡɪˈtɑː/","p":"n.","zh":"吉他","ex":{"en":"My sister plays the guitar beside the window every evening.","zh":"我姐姐每天晚上都在窗边弹吉他。"},"tip":"表示弹吉他，通常说play the guitar。","topic":"arts","cefr":"A1"},{"w":"toothpaste","uk":"/ˈtuːθpeɪst/","p":"n.","zh":"牙膏","ex":{"en":"I squeezed some toothpaste onto my brush before breakfast.","zh":"早餐前，我往牙刷上挤了些牙膏。"},"tip":"toothpaste不可数；一管牙膏用a tube of toothpaste。","topic":"daily","cefr":"A1"},{"w":"sun","uk":"/sʌn/","p":"n.","zh":"太阳","ex":{"en":"The sun appeared just as we reached the beach.","zh":"我们刚到海滩，太阳就出来了。"},"tip":"指太阳通常用the sun；in the sun表示在阳光下。","topic":"nature","cefr":"A1"},{"w":"angry","uk":"/ˈæŋɡri/","p":"adj.","zh":"生气的；愤怒的","ex":{"en":"He felt angry when someone damaged his bicycle.","zh":"有人弄坏了他的自行车，他感到很生气。"},"tip":"生某人的气用angry with；因某事生气用about。","topic":"emotion","cefr":"A1"},{"w":"aeroplane","uk":"/ˈeərəpleɪn/","p":"n.","zh":"飞机","ex":{"en":"The aeroplane flew low over the sandy beach.","zh":"飞机低空飞过沙滩上方。"},"tip":"英式用aeroplane，美式用airplane；口语常用plane。","topic":"travel","cefr":"A1"},{"w":"spring","uk":"/sprɪŋ/","p":"n.","zh":"春天；春季","ex":{"en":"We plant flowers in the garden every spring.","zh":"我们每年春天都在花园里种花。"},"tip":"季节前通常用in；泉和弹簧义均为可数名词。","topic":"nature","cefr":"A1"},{"w":"band","uk":"/bænd/","p":"n.","zh":"乐队","ex":{"en":"My sister plays the drums in a local band.","zh":"我姐姐在当地一支乐队里打鼓。"},"tip":"IELTS中的band指成绩等级，不是乐队。","topic":"arts","cefr":"A1"},{"w":"east","uk":"/iːst/","p":"n.","zh":"东方；东部","ex":{"en":"Our kitchen window faces east and catches the morning sun.","zh":"我们厨房的窗户朝东，能照到早晨的阳光。"},"tip":"in the east of指内部东部；east of指在其以东。","topic":"travel","cefr":"A1"},{"w":"banana","uk":"/bəˈnɑːnə/","p":"n.","zh":"香蕉","ex":{"en":"He peeled a banana and sliced it over his cereal.","zh":"他剥了一根香蕉，切成片放在麦片上。"},"tip":"可数名词：一根香蕉是a banana。","topic":"daily","cefr":"A1"},{"w":"camera","uk":"/ˈkæmərə/","p":"n.","zh":"照相机；摄像机","ex":{"en":"She raised her camera to photograph the sleeping cat.","zh":"她举起相机，给熟睡的猫拍照。"},"tip":"camera可指照相机或摄像机，具体看语境。","topic":"technology","cefr":"A1"},{"w":"menu","uk":"/ˈmenjuː/","p":"n.","zh":"菜单","ex":{"en":"There are several vegetarian dishes on the menu.","zh":"菜单上有几道素菜。"},"tip":"说菜品在菜单上，用on the menu，不用in。","topic":"daily","cefr":"A1"},{"w":"girl","uk":"/ɡɜːl/","p":"n.","zh":"女孩；姑娘","ex":{"en":"The girl carefully carried her kitten into the house.","zh":"那个女孩小心翼翼地把小猫抱进屋里。"},"tip":"成年女性正式称woman；girl不直接表示女朋友。","topic":"society","cefr":"A1"},{"w":"answer","uk":"/ˈɑːnsə/","p":"n.","zh":"回答；答案；解决办法","ex":{"en":"I asked the price, but nobody gave an answer.","zh":"我问了价格，却没有人回答。"},"tip":"动词answer直接接问题；名词用the answer to。","topic":"education","cefr":"A1"},{"w":"line","uk":"/laɪn/","p":"n.","zh":"线；线条","ex":{"en":"Draw a straight line across the page with your ruler.","zh":"用尺子在纸上画一条直线。"},"tip":"排队在美式英语中常用stand in line，英式常用queue。","topic":"daily","cefr":"A1"},{"w":"door","uk":"/dɔː/","p":"n.","zh":"门","ex":{"en":"Please close the door before the cat gets out.","zh":"请关上门，别让猫跑出去。"},"tip":"at the door指在门口；answer the door指应声开门。","topic":"daily","cefr":"A1"},{"w":"smile","uk":"/smaɪl/","p":"v.","zh":"微笑","ex":{"en":"The baby smiled when I waved across the room.","zh":"我在房间另一头挥手时，宝宝笑了。"},"tip":"对某人微笑用smile at，不用smile to。","topic":"emotion","cefr":"A1"},{"w":"room","uk":"/ruːm/","p":"n.","zh":"房间；室","ex":{"en":"My room has a desk beside the window.","zh":"我的房间里，窗边有一张书桌。"},"tip":"指房间时可数；指空间或余地时不可数。","topic":"daily","cefr":"A1"},{"w":"rest","uk":"/rest/","p":"n.","zh":"休息","ex":{"en":"Let's have a rest under that shady tree.","zh":"我们在那棵树荫下休息一下吧。"},"tip":"the rest of后接名词，谓语单复数随所指内容变化。","topic":"daily","cefr":"A1"},{"w":"aunt","uk":"/ɑːnt/","p":"n.","zh":"姑妈；姨妈；舅妈；婶伯母","ex":{"en":"My aunt taught me how to bake bread.","zh":"我姨妈教会了我如何烤面包。"},"tip":"不区分父系或母系；美音也常读/ɑːnt/。","topic":"daily","cefr":"A1"},{"w":"watch","uk":"/wɒtʃ/","p":"v.","zh":"观看；注视","ex":{"en":"We watched the ducks swimming across the quiet pond.","zh":"我们看着鸭子游过平静的池塘。"},"tip":"watch 强调持续观看；see 强调看见这一结果。","topic":"daily","cefr":"A1"},{"w":"exciting","uk":"/ɪkˈsaɪtɪŋ/","p":"adj.","zh":"令人兴奋的；刺激的","ex":{"en":"The final minutes of the match were incredibly exciting.","zh":"比赛最后几分钟精彩刺激极了。"},"tip":"exciting形容令人兴奋的事物；excited形容人的感受。","topic":"emotion","cefr":"A1"},{"w":"sometimes","uk":"/ˈsʌmtaɪmz/","p":"adv.","zh":"有时；偶尔","ex":{"en":"I sometimes take the longer route home through the park.","zh":"我有时会绕远路穿过公园回家。"},"tip":"sometimes是有时；some time是一段时间。","topic":"daily","cefr":"A1"},{"w":"newspaper","uk":"/ˈnjuːzpeɪpə/","p":"n.","zh":"报纸","ex":{"en":"My grandfather reads the newspaper while eating breakfast.","zh":"我爷爷一边吃早饭一边看报纸。"},"tip":"一份报纸用a newspaper；作包装材料时可不可数。","topic":"media","cefr":"A1"},{"w":"fine","uk":"/faɪn/","p":"adj.","zh":"好的；健康的；优质的","ex":{"en":"I feel fine now, so let's go for a walk.","zh":"我现在感觉挺好的，我们去散步吧。"},"tip":"fine作动词也指罚款：fine sb for sth。","topic":"daily","cefr":"A1"},{"w":"boat","uk":"/bəʊt/","p":"n.","zh":"船；小船","ex":{"en":"We hired a small boat and explored the lake.","zh":"我们租了一条小船，游览了湖面。"},"tip":"by boat不加冠词；on a boat表示在船上。","topic":"travel","cefr":"A1"},{"w":"card","uk":"/kɑːd/","p":"n.","zh":"卡；卡片；证件","ex":{"en":"I tapped my card to pay for the groceries.","zh":"我刷卡支付了买食品杂货的钱。"},"tip":"play cards指打牌，cards用复数，前面不加冠词。","topic":"daily","cefr":"A1"},{"w":"afraid","uk":"/əˈfreɪd/","p":"adj.","zh":"害怕的；担心的","ex":{"en":"The puppy was afraid of the noisy vacuum cleaner.","zh":"那只小狗害怕吵闹的吸尘器。"},"tip":"通常作表语，不放名词前；用afraid of或afraid to do。","topic":"emotion","cefr":"A1"},{"w":"start","uk":"/stɑːt/","p":"v.","zh":"开始；着手","ex":{"en":"We started cooking dinner as soon as we got home.","zh":"我们一到家就开始做晚饭。"},"tip":"start doing与start to do通常都可表示开始做某事。","topic":"daily","cefr":"A1"},{"w":"hospital","uk":"/ˈhɒspɪtl/","p":"n.","zh":"医院","ex":{"en":"She works as a nurse at the local hospital.","zh":"她在当地医院当护士。"},"tip":"住院：英式in hospital，美式in the hospital。","topic":"health","cefr":"A1"},{"w":"life","uk":"/laɪf/","p":"n.","zh":"生活；人生","ex":{"en":"Life feels quieter since we moved to the countryside.","zh":"自从搬到乡下，我们的生活感觉更安静了。"},"tip":"复数是 lives；泛指生活时通常不可数。","topic":"daily","cefr":"A1"},{"w":"centre","uk":"/ˈsentə/","p":"n.","zh":"中心；中央","ex":{"en":"We placed a vase in the centre of the table.","zh":"我们在桌子中央摆了一个花瓶。"},"tip":"centre是英式拼写，美式写center；动词常接on。","topic":"city","cefr":"A1"},{"w":"magazine","uk":"/ˌmæɡəˈziːn/","p":"n.","zh":"杂志；期刊","ex":{"en":"She bought a gardening magazine at the station.","zh":"她在车站买了一本园艺杂志。"},"tip":"可数名词；英式重音通常在末音节，美式在首音节。","topic":"media","cefr":"A1"},{"w":"practise","uk":"/ˈpræktɪs/","p":"v.","zh":"练习","ex":{"en":"I practise the violin quietly after dinner each evening.","zh":"我每天晚饭后都会轻声练习小提琴。"},"tip":"英式动词用practise、名词用practice；美式均用practice。","topic":"education","cefr":"A1"},{"w":"city","uk":"/ˈsɪti/","p":"n.","zh":"城市；都市","ex":{"en":"We explored the city on foot all afternoon.","zh":"我们整个下午都在步行游览这座城市。"},"tip":"复数为cities；市中心英式用city centre。","topic":"city","cefr":"A1"},{"w":"boring","uk":"/ˈbɔːrɪŋ/","p":"adj.","zh":"无聊的；乏味的","ex":{"en":"The film was so boring that I fell asleep.","zh":"这部电影太无聊了，我都睡着了。"},"tip":"boring指令人无聊；bored指人感到无聊。","topic":"emotion","cefr":"A1"},{"w":"finish","uk":"/ˈfɪnɪʃ/","p":"v.","zh":"完成；结束；吃完","ex":{"en":"I'll finish washing the dishes before we go.","zh":"我们出门前，我会把碗洗完。"},"tip":"表示做完某事用finish doing，不用finish to do。","topic":"daily","cefr":"A1"},{"w":"pig","uk":"/pɪɡ/","p":"n.","zh":"猪","ex":{"en":"A pink pig was sleeping beside the wooden fence.","zh":"一头粉色的猪正睡在木栅栏旁。"},"tip":"pig指动物；作为食物的猪肉通常用pork。","topic":"nature","cefr":"A1"},{"w":"our","uk":"/aʊə/","p":"det.","zh":"我们的","ex":{"en":"Our kitchen smells wonderful when Dad bakes fresh bread.","zh":"爸爸烤新鲜面包时，我们的厨房里香气四溢。"},"tip":"our后须接名词；ours可独立使用。","topic":"daily","cefr":"A1"},{"w":"football","uk":"/ˈfʊtbɔːl/","p":"n.","zh":"足球；足球运动","ex":{"en":"We play football in the park every Saturday morning.","zh":"我们每周六早上都在公园踢足球。"},"tip":"英式football指足球；美式通常指美式橄榄球。","topic":"sport","cefr":"A1"},{"w":"station","uk":"/ˈsteɪʃən/","p":"n.","zh":"车站","ex":{"en":"We hurried to the station with our heavy suitcases.","zh":"我们提着沉重的行李箱匆忙赶往车站。"},"tip":"作动词常用被动式be stationed at，表示被派驻。","topic":"travel","cefr":"A1"},{"w":"tomorrow","uk":"/təˈmɒrəʊ/","p":"adv.","zh":"在明天","ex":{"en":"We are meeting at the swimming pool tomorrow morning.","zh":"我们明天早上在游泳池见面。"},"tip":"tomorrow前通常不加on；明早是tomorrow morning。","topic":"daily","cefr":"A1"},{"w":"fourth","uk":"/fɔːθ/","p":"num.","zh":"第四","ex":{"en":"Our apartment is on the fourth floor, beside the lift.","zh":"我们的公寓在四楼，就在电梯旁边。"},"tip":"第四是fourth；forth意为向前，注意拼写。","topic":"daily","cefr":"A1"},{"w":"today","uk":"/təˈdeɪ/","p":"adv.","zh":"今天；现今","ex":{"en":"Let's eat outside today while the weather is warm.","zh":"今天天气暖和，我们到外面吃饭吧。"},"tip":"today既可指今天，也可泛指当今；前面不用on。","topic":"daily","cefr":"A1"},{"w":"plane","uk":"/pleɪn/","p":"n.","zh":"飞机","ex":{"en":"Our plane landed just before the rain began.","zh":"我们的飞机刚降落，雨就下起来了。"},"tip":"by plane不加冠词；on a plane需加冠词。","topic":"travel","cefr":"A1"},{"w":"job","uk":"/dʒɒb/","p":"n.","zh":"工作；职位","ex":{"en":"My sister found a job at the local library.","zh":"我姐姐在当地图书馆找到了一份工作。"},"tip":"job指具体工作，可数；work泛指工作，通常不可数。","topic":"work","cefr":"A1"},{"w":"supermarket","uk":"/ˈsuːpəmɑːkɪt/","p":"n.","zh":"超级市场；超市","ex":{"en":"We stopped at the supermarket to buy milk and rice.","zh":"我们顺路去超市买了牛奶和大米。"},"tip":"在超市购物常说shop at a supermarket。","topic":"daily","cefr":"A1"},{"w":"kitchen","uk":"/ˈkɪtʃɪn/","p":"n.","zh":"厨房","ex":{"en":"The kitchen smells of fresh bread and roasted vegetables.","zh":"厨房里飘着新鲜面包和烤蔬菜的香味。"},"tip":"in the kitchen表示在厨房；ch读/tʃ/。","topic":"daily","cefr":"A1"},{"w":"when","uk":"/wen/","p":"adv.","zh":"什么时候","ex":{"en":"When does the next bus leave for town?","zh":"下一班去镇上的公交车什么时候发车？"},"tip":"表将来的时间从句中，when后通常用一般现在时。","topic":"daily","cefr":"A1"},{"w":"north","uk":"/nɔːθ/","p":"n.","zh":"北；北方；北部","ex":{"en":"The north of the island gets snow every winter.","zh":"这座岛的北部每年冬天都会下雪。"},"tip":"in the north of指在内部北部；north of指在其以北。","topic":"travel","cefr":"A1"},{"w":"sugar","uk":"/ˈʃʊɡə/","p":"n.","zh":"糖；食糖","ex":{"en":"She stirred a spoonful of sugar into her tea.","zh":"她往茶里加了一勺糖，搅拌均匀。"},"tip":"泛指食糖时通常不可数；a spoonful of sugar指一勺糖。","topic":"health","cefr":"A1"},{"w":"husband","uk":"/ˈhʌzbənd/","p":"n.","zh":"丈夫","ex":{"en":"Her husband brought her lunch during a busy shift.","zh":"她忙着上班时，丈夫给她送来了午饭。"},"tip":"作动词时较正式，表示节约使用资源。","topic":"society","cefr":"A1"},{"w":"correct","uk":"/kəˈrekt/","p":"adj.","zh":"正确的；准确的","ex":{"en":"You were correct about the keys being under the sofa.","zh":"你说钥匙在沙发下面，果然没错。"},"tip":"既是形容词也是动词；correctly才是副词。","topic":"education","cefr":"A1"},{"w":"animal","uk":"/ˈænɪməl/","p":"n.","zh":"动物","ex":{"en":"My sister loves watching animals at the local farm.","zh":"我妹妹喜欢在当地农场看动物。"},"tip":"animal 不仅指哺乳动物；鸟、鱼和昆虫也属于动物。","topic":"nature","cefr":"A1"},{"w":"thirsty","uk":"/ˈθɜːsti/","p":"adj.","zh":"口渴的","ex":{"en":"I felt thirsty after walking home in the sun.","zh":"我顶着太阳走回家后觉得口渴。"},"tip":"表示渴望某物用thirsty for，不用thirsty of。","topic":"health","cefr":"A1"},{"w":"pen","uk":"/pen/","p":"n.","zh":"笔；钢笔","ex":{"en":"Could you lend me a pen for this form?","zh":"你能借我一支笔填这张表吗？"},"tip":"pen泛指墨水笔；钢笔可明确说fountain pen。","topic":"daily","cefr":"A1"},{"w":"leave","uk":"/liːv/","p":"v.","zh":"离开；出发","ex":{"en":"We need to leave before the traffic gets worse.","zh":"我们得在交通变得更拥堵之前出发。"},"tip":"leave 的过去式和过去分词均为 left。","topic":"daily","cefr":"A1"},{"w":"window","uk":"/ˈwɪndəʊ/","p":"n.","zh":"窗；窗户","ex":{"en":"Please open the window and let some fresh air in.","zh":"请打开窗户，让新鲜空气进来。"},"tip":"电脑窗口也叫window；机会之窗强调时机有限。","topic":"daily","cefr":"A1"},{"w":"ride","uk":"/raɪd/","p":"v.","zh":"骑；乘坐","ex":{"en":"We ride our bikes to the lake every weekend.","zh":"我们每个周末都骑自行车去湖边。"},"tip":"不规则变化：ride—rode—ridden。","topic":"travel","cefr":"A1"},{"w":"leg","uk":"/leɡ/","p":"n.","zh":"腿","ex":{"en":"My legs felt tired after the long walk home.","zh":"走了很长一段路回家后，我的双腿很累。"},"tip":"leg也指桌椅的支脚或旅程中的一段。","topic":"daily","cefr":"A1"},{"w":"tomato","uk":"/təˈmɑːtəʊ/","p":"n.","zh":"番茄；西红柿","ex":{"en":"She sliced a ripe tomato for her cheese sandwich.","zh":"她切了一个熟番茄，放进奶酪三明治里。"},"tip":"复数是tomatoes；英美发音的重读元音不同。","topic":"daily","cefr":"A1"},{"w":"try","uk":"/traɪ/","p":"v.","zh":"尝试；试图","ex":{"en":"I'll try to fix the lamp before dinner.","zh":"我会试着在晚饭前把灯修好。"},"tip":"try to do强调努力；try doing强调试试办法。","topic":"daily","cefr":"A1"},{"w":"restaurant","uk":"/ˈrestrɒnt/","p":"n.","zh":"餐馆；餐厅","ex":{"en":"We found a quiet restaurant beside the river.","zh":"我们在河边找到了一家安静的餐馆。"},"tip":"restaurant指用餐场所；hotel主要指住宿的酒店。","topic":"daily","cefr":"A1"},{"w":"bus","uk":"/bʌs/","p":"n.","zh":"公共汽车","ex":{"en":"We caught the last bus home after the concert.","zh":"音乐会结束后，我们赶上了回家的末班公交车。"},"tip":"by bus不加冠词；take a bus需加冠词。","topic":"travel","cefr":"A1"},{"w":"father","uk":"/ˈfɑːðə/","p":"n.","zh":"父亲；爸爸","ex":{"en":"Her father taught her to ride a bicycle.","zh":"她爸爸教她骑自行车。"},"tip":"father较正式，dad更口语化；父亲节用Father's Day。","topic":"daily","cefr":"A1"},{"w":"foot","uk":"/fʊt/","p":"n.","zh":"脚；足","ex":{"en":"A tiny stone in my shoe hurt my foot.","zh":"鞋里的一颗小石子硌疼了我的脚。"},"tip":"脚和英尺的复数均为feet；步行用on foot。","topic":"daily","cefr":"A1"},{"w":"airplane","uk":"/ˈeəpleɪn/","p":"n.","zh":"飞机","ex":{"en":"We watched the airplane disappear behind a white cloud.","zh":"我们看着飞机消失在一朵白云后面。"},"tip":"airplane常用于美式英语，英式通常用aeroplane。","topic":"travel","cefr":"A1"},{"w":"him","uk":"/hɪm/","p":"pron.","zh":"他（宾格）","ex":{"en":"My brother forgot his lunch, so I brought it to him.","zh":"我哥哥忘了带午饭，所以我给他送了过去。"},"tip":"he作主语，him作动词或介词的宾语。","topic":"daily","cefr":"A1"},{"w":"beginning","uk":"/bɪˈɡɪnɪŋ/","p":"n.","zh":"开始；开端","ex":{"en":"We missed the beginning of the film yesterday.","zh":"我们昨天错过了电影的开头。"},"tip":"at the beginning of后接名词；in the beginning表示起初。","topic":"daily","cefr":"A1"},{"w":"dirty","uk":"/ˈdɜːti/","p":"adj.","zh":"脏的","ex":{"en":"Please leave your dirty boots outside the kitchen door.","zh":"请把你的脏靴子放在厨房门外。"},"tip":"比较级dirtier，最高级dirtiest。","topic":"daily","cefr":"A1"},{"w":"grammar","uk":"/ˈɡræmə/","p":"n.","zh":"语法；语法规则","ex":{"en":"Our teacher explains grammar using examples from everyday conversations.","zh":"我们的老师用日常对话中的例子讲解语法。"},"tip":"表示语法知识时不可数；一个语法错误用a grammar mistake。","topic":"education","cefr":"A1"},{"w":"that","uk":"/ðæt/","p":"det.","zh":"那；那个","ex":{"en":"Could you pass me that bowl beside the window?","zh":"你能把窗边的那个碗递给我吗？"},"tip":"作指示词时复数为those；引导宾语从句常可省略。","topic":"daily","cefr":"A1"},{"w":"ticket","uk":"/ˈtɪkɪt/","p":"n.","zh":"票；入场券","ex":{"en":"I bought a return ticket from the station machine.","zh":"我在车站的售票机上买了一张往返票。"},"tip":"英式single/return ticket分别指单程票和往返票。","topic":"travel","cefr":"A1"},{"w":"third","uk":"/θɜːd/","p":"num.","zh":"第三","ex":{"en":"Our flat is on the third floor, beside the lift.","zh":"我们的公寓在三楼，电梯旁边。"},"tip":"表示分数：one third；two thirds。","topic":"daily","cefr":"A1"},{"w":"maths","uk":"/mæθs/","p":"n.","zh":"数学","ex":{"en":"We used coloured blocks to practise maths after lunch.","zh":"午饭后，我们用彩色积木练习数学。"},"tip":"英式用 maths，美式用 math；作主语用单数动词。","topic":"education","cefr":"A1"},{"w":"second","uk":"/ˈsekənd/","p":"num.","zh":"第二","ex":{"en":"This is my second cup of tea today.","zh":"这是我今天喝的第二杯茶。"},"tip":"the second指第二个；a second可指又一个。","topic":"daily","cefr":"A1"},{"w":"floor","uk":"/flɔː/","p":"n.","zh":"地板；室内地面","ex":{"en":"My keys fell onto the kitchen floor again.","zh":"我的钥匙又掉到厨房地板上了。"},"tip":"英式first floor是二楼；美式first floor是一楼。","topic":"daily","cefr":"A1"},{"w":"farm","uk":"/fɑːm/","p":"n.","zh":"农场","ex":{"en":"We bought fresh eggs from a nearby farm.","zh":"我们从附近的农场买了新鲜鸡蛋。"},"tip":"表示在农场通常用on a farm，不用in。","topic":"work","cefr":"A1"},{"w":"low","uk":"/ləʊ/","p":"adj.","zh":"低的；少的","ex":{"en":"The low shelf is easy for children to reach.","zh":"这个低矮的架子很方便孩子们取东西。"},"tip":"价格低用low，东西便宜用cheap。","topic":"daily","cefr":"A1"},{"w":"painting","uk":"/ˈpeɪntɪŋ/","p":"n.","zh":"绘画作品；画","ex":{"en":"We hung a colourful painting above the sofa.","zh":"我们在沙发上方挂了一幅色彩鲜艳的画。"},"tip":"指一幅画时可数；指绘画活动时不可数。","topic":"arts","cefr":"A1"},{"w":"map","uk":"/mæp/","p":"n.","zh":"地图","ex":{"en":"We spread the map across the table before leaving.","zh":"出发前，我们把地图铺在桌上。"},"tip":"map作动词时，过去式mapped，分词mapping。","topic":"travel","cefr":"A1"},{"w":"move","uk":"/muːv/","p":"v.","zh":"移动；搬家","ex":{"en":"Could you move this chair closer to the window?","zh":"你能把这把椅子挪到靠窗一点的位置吗？"},"tip":"moving指令人感动的，moved指感到感动的。","topic":"daily","cefr":"A1"},{"w":"send","uk":"/send/","p":"v.","zh":"发送；寄送","ex":{"en":"Please send me a photo of your new puppy.","zh":"请发一张你家新养的小狗的照片给我。"},"tip":"过去式和过去分词均为sent；可用send sth to sb。","topic":"daily","cefr":"A1"},{"w":"sixty","uk":"/ˈsɪksti/","p":"num.","zh":"六十","ex":{"en":"My grandfather turned sixty and celebrated with a picnic.","zh":"我爷爷满六十岁时，办了一次野餐来庆祝。"},"tip":"sixty重音在首音节；sixteen通常重读末音节。","topic":"daily","cefr":"A1"},{"w":"list","uk":"/lɪst/","p":"n.","zh":"清单；名单","ex":{"en":"I made a shopping list before leaving home.","zh":"出门前，我列了一张购物清单。"},"tip":"在名单上用on the list，不用in。","topic":"daily","cefr":"A1"},{"w":"meet","uk":"/miːt/","p":"v.","zh":"遇见；会面；结识","ex":{"en":"Let's meet outside the library after lunch today.","zh":"我们今天午饭后在图书馆外见吧。"},"tip":"过去式和过去分词均为met；meet要求时意为满足。","topic":"daily","cefr":"A1"},{"w":"stay","uk":"/steɪ/","p":"v.","zh":"停留；暂住","ex":{"en":"We stayed at a small hotel beside the lake.","zh":"我们住在湖边的一家小旅馆里。"},"tip":"stay后可直接接形容词，如stay calm保持冷静。","topic":"travel","cefr":"A1"},{"w":"food","uk":"/fuːd/","p":"n.","zh":"食物；食品","ex":{"en":"We packed enough food for a picnic by the lake.","zh":"我们带了足够的食物，准备在湖边野餐。"},"tip":"泛指食物时不可数；foods表示不同种类的食物。","topic":"health","cefr":"A1"},{"w":"music","uk":"/ˈmjuːzɪk/","p":"n.","zh":"音乐；乐曲","ex":{"en":"Soft music drifted through the kitchen while we cooked.","zh":"我们做饭时，轻柔的音乐在厨房里飘荡。"},"tip":"music不可数；一首乐曲说a piece of music。","topic":"arts","cefr":"A1"},{"w":"fridge","uk":"/frɪdʒ/","p":"n.","zh":"冰箱","ex":{"en":"Put the milk back in the fridge, please.","zh":"请把牛奶放回冰箱。"},"tip":"fridge是refrigerator的常用简短说法。","topic":"daily","cefr":"A1"},{"w":"website","uk":"/ˈwebsaɪt/","p":"n.","zh":"网站","ex":{"en":"I found the museum's opening hours on its website.","zh":"我在博物馆的网站上查到了开放时间。"},"tip":"在网站上用on a website；webpage指单个网页。","topic":"technology","cefr":"A1"},{"w":"telephone","uk":"/ˈtelɪfəʊn/","p":"n.","zh":"电话；电话机","ex":{"en":"The telephone rang just as I opened the door.","zh":"我刚打开门，电话就响了。"},"tip":"telephone并非美式专用；日常通常简称phone。","topic":"technology","cefr":"A1"},{"w":"question","uk":"/ˈkwestʃən/","p":"n.","zh":"问题；疑问","ex":{"en":"I raised my hand to ask the teacher a question.","zh":"我举手向老师提了一个问题。"},"tip":"动词question可直接接人，表示询问或盘问。","topic":"thinking","cefr":"A1"},{"w":"village","uk":"/ˈvɪlɪdʒ/","p":"n.","zh":"村庄","ex":{"en":"Our village has a bakery beside the old bridge.","zh":"我们村的老桥旁有一家面包店。"},"tip":"the whole village可指全村居民，而非建筑。","topic":"city","cefr":"A1"},{"w":"news","uk":"/njuːz/","p":"n.","zh":"新闻；消息","ex":{"en":"She called her sister to share the good news.","zh":"她给姐姐打电话，分享这个好消息。"},"tip":"news不可数且接单数谓语：The news is good。","topic":"media","cefr":"A1"},{"w":"word","uk":"/wɜːd/","p":"n.","zh":"单词；词","ex":{"en":"I looked up the unfamiliar word in a dictionary.","zh":"我在词典里查了那个不认识的单词。"},"tip":"keep your word指守信，其中word不用复数。","topic":"education","cefr":"A1"},{"w":"dark","uk":"/dɑːk/","p":"adj.","zh":"黑暗的；昏暗的","ex":{"en":"The hallway was too dark to find my shoes.","zh":"走廊太暗了，我找不到自己的鞋。"},"tip":"dark既指光线暗，也指颜色深；黑暗常用the dark。","topic":"daily","cefr":"A1"},{"w":"see","uk":"/siː/","p":"v.","zh":"看见","ex":{"en":"I can see a rainbow above the trees.","zh":"我能看见树梢上方有一道彩虹。"},"tip":"过去式saw，过去分词seen；强调看见而非观看。","topic":"daily","cefr":"A1"},{"w":"potato","uk":"/pəˈteɪtəʊ/","p":"n.","zh":"土豆；马铃薯","ex":{"en":"I baked a potato and filled it with cheese.","zh":"我烤了一个土豆，并在里面填上奶酪。"},"tip":"复数是 potatoes，词尾加 es。","topic":"daily","cefr":"A1"},{"w":"my","uk":"/maɪ/","p":"det.","zh":"我的","ex":{"en":"I left my umbrella beside the front door.","zh":"我把我的伞放在前门旁边了。"},"tip":"my后须接名词；mine可独立使用，表示“我的”。","topic":"daily","cefr":"A1"},{"w":"later","uk":"/ˈleɪtə/","p":"adv.","zh":"后来；稍后","ex":{"en":"I'll wash the dishes later, after we finish eating.","zh":"等我们吃完饭，我稍后再洗碗。"},"tip":"later表示稍后；latter表示两者中的后者。","topic":"daily","cefr":"A1"},{"w":"soon","uk":"/suːn/","p":"adv.","zh":"不久；很快","ex":{"en":"Dinner will be ready soon, so wash your hands.","zh":"晚饭很快就好了，去洗手吧。"},"tip":"as soon as引导将来时间从句时，通常用一般现在时。","topic":"daily","cefr":"A1"},{"w":"umbrella","uk":"/ʌmˈbrelə/","p":"n.","zh":"雨伞；阳伞","ex":{"en":"We shared an umbrella on the walk home.","zh":"走路回家时，我们共撑一把伞。"},"tip":"umbrella term指涵盖多个相关概念的统称。","topic":"daily","cefr":"A1"},{"w":"after","uk":"/ˈɑːftə/","p":"prep.","zh":"在……之后","ex":{"en":"We usually take a short walk after dinner.","zh":"我们通常在晚饭后散一小会儿步。"},"tip":"介词后接名词或动名词；连词后接完整从句。","topic":"daily","cefr":"A1"},{"w":"around","uk":"/əˈraʊnd/","p":"prep.","zh":"围绕；在…周围","ex":{"en":"We sat around the fire and watched the stars.","zh":"我们围坐在火堆旁看星星。"},"tip":"around可表大约；around ten即十点或十个左右。","topic":"daily","cefr":"A1"},{"w":"by","uk":"/baɪ/","p":"prep.","zh":"由；被","ex":{"en":"This wooden bowl was made by my grandfather.","zh":"这个木碗是我祖父做的。"},"tip":"by表示截止时间；until表示状态持续到某时。","topic":"daily","cefr":"A1"},{"w":"smell","uk":"/smel/","p":"n.","zh":"气味；嗅觉","ex":{"en":"The smell of fresh bread filled our kitchen.","zh":"新鲜面包的香味弥漫在我们的厨房里。"},"tip":"smell作系动词后接形容词，如smell good。","topic":"daily","cefr":"A1"},{"w":"grandparent","uk":"/ˈɡrænpeərənt/","p":"n.","zh":"祖父母或外祖父母之一","ex":{"en":"Each grandparent brought a homemade dish to our picnic.","zh":"每位祖辈都带了一道自制的菜来参加我们的野餐。"},"tip":"单数指一位祖辈；复数可指祖父母或外祖父母。","topic":"daily","cefr":"A1"},{"w":"friendly","uk":"/ˈfrendli/","p":"adj.","zh":"友好的；亲切的","ex":{"en":"Our new neighbour is friendly and always waves hello.","zh":"我们的新邻居很友善，总是挥手打招呼。"},"tip":"虽以-ly结尾，却是形容词，不是副词。","topic":"society","cefr":"A1"},{"w":"wide","uk":"/waɪd/","p":"adj.","zh":"宽的；宽阔的","ex":{"en":"The sofa will not fit through this wide doorway.","zh":"即使门口这么宽，这张沙发也搬不进去。"},"tip":"wide表示张开程度；widely常表示广泛地。","topic":"daily","cefr":"A1"},{"w":"fly","uk":"/flaɪ/","p":"v.","zh":"飞；飞行","ex":{"en":"Small birds fly over our garden every morning.","zh":"每天早晨都有小鸟飞过我们的花园。"},"tip":"动词变化fly–flew–flown；苍蝇复数为flies。","topic":"travel","cefr":"A1"},{"w":"cold","uk":"/kəʊld/","p":"adj.","zh":"冷的；寒冷的","ex":{"en":"My hands were cold, so I put on gloves.","zh":"我的手很冷，于是戴上了手套。"},"tip":"“觉得冷”用be cold；“感冒了”用have a cold。","topic":"daily","cefr":"A1"},{"w":"children","uk":"/ˈtʃɪldrən/","p":"n.","zh":"儿童；孩子们","ex":{"en":"The children built a sandcastle together on the beach.","zh":"孩子们一起在海滩上堆了一座沙堡。"},"tip":"child 的不规则复数；所有格为 children's。","topic":"society","cefr":"A1"},{"w":"trousers","uk":"/ˈtraʊzəz/","p":"n.","zh":"裤子；长裤","ex":{"en":"These trousers are too long, so I need them shortened.","zh":"这条裤子太长了，我需要把它改短。"},"tip":"用复数：trousers are；一条用a pair of trousers。","topic":"daily","cefr":"A1"},{"w":"farmer","uk":"/ˈfɑːmə/","p":"n.","zh":"农民；农场主","ex":{"en":"The farmer feeds her chickens before the sun rises.","zh":"这位农民在日出前给她的鸡喂食。"},"tip":"farmer指人，farm指农场，farming指农业生产。","topic":"work","cefr":"A1"},{"w":"coffee","uk":"/ˈkɒfi/","p":"n.","zh":"咖啡；咖啡粉；咖啡豆","ex":{"en":"I drink coffee with milk before leaving for work.","zh":"我上班出门前会喝一杯加奶咖啡。"},"tip":"通常不可数；点单时two coffees指两杯咖啡。","topic":"daily","cefr":"A1"},{"w":"shoe","uk":"/ʃuː/","p":"n.","zh":"鞋","ex":{"en":"There was a small stone inside my shoe.","zh":"我的鞋里有一颗小石子。"},"tip":"一双鞋用a pair of shoes，shoe为可数名词。","topic":"daily","cefr":"A1"},{"w":"bike","uk":"/baɪk/","p":"n.","zh":"自行车；摩托车","ex":{"en":"I locked my bike outside the corner shop.","zh":"我把自行车锁在街角商店外面。"},"tip":"by bike不加冠词；ride a bike中的a不能省。","topic":"travel","cefr":"A1"},{"w":"little","uk":"/ˈlɪtəl/","p":"adj.","zh":"小的；年幼的","ex":{"en":"A little bird landed on our kitchen windowsill.","zh":"一只小鸟落在我们厨房的窗台上。"},"tip":"little加不可数名词表示几乎没有；a little表示有一点。","topic":"daily","cefr":"A1"},{"w":"sweet","uk":"/swiːt/","p":"adj.","zh":"甜的","ex":{"en":"These strawberries are sweet enough to eat without sugar.","zh":"这些草莓已经够甜了，不加糖也好吃。"},"tip":"糖果英式常用sweets，美式常用candy。","topic":"daily","cefr":"A1"},{"w":"morning","uk":"/ˈmɔːnɪŋ/","p":"n.","zh":"早晨；上午","ex":{"en":"I open the curtains every morning and water my plants.","zh":"我每天早晨拉开窗帘，给植物浇水。"},"tip":"泛指用in the morning；具体某天早上用on。","topic":"daily","cefr":"A1"},{"w":"outside","uk":"/ˌaʊtˈsaɪd/","p":"adv.","zh":"在外面；向外面","ex":{"en":"The children played outside while their parents prepared lunch.","zh":"父母准备午饭时，孩子们在外面玩耍。"},"tip":"后接地点用介词 outside；单独使用可作副词。","topic":"daily","cefr":"A1"},{"w":"pasta","uk":"/ˈpæstə/","p":"n.","zh":"意大利面食","ex":{"en":"We cooked pasta with fresh tomatoes and mushrooms.","zh":"我们用新鲜番茄和蘑菇做了意大利面。"},"tip":"不可数；一份意面可说a bowl of pasta。","topic":"daily","cefr":"A1"},{"w":"black","uk":"/blæk/","p":"adj.","zh":"黑色的","ex":{"en":"She wore a black coat and bright yellow boots.","zh":"她穿着黑色外套和亮黄色靴子。"},"tip":"指族裔时常大写为Black；避免用作单数名词称人。","topic":"daily","cefr":"A1"},{"w":"basketball","uk":"/ˈbɑːskɪtbɔːl/","p":"n.","zh":"篮球运动","ex":{"en":"We play basketball at the park after school.","zh":"放学后，我们在公园打篮球。"},"tip":"play basketball不加冠词；指一个球用a basketball。","topic":"sport","cefr":"A1"},{"w":"tiger","uk":"/ˈtaɪɡə/","p":"n.","zh":"老虎","ex":{"en":"The tiger rested in the shade beside a pool.","zh":"那只老虎在水池旁的阴凉处休息。"},"tip":"可数名词；一只老虎用a tiger。","topic":"nature","cefr":"A1"},{"w":"desk","uk":"/desk/","p":"n.","zh":"书桌；办公桌","ex":{"en":"I keep my pencils in the top desk drawer.","zh":"我把铅笔放在书桌最上面的抽屉里。"},"tip":"在书桌前用at a desk，不用on a desk。","topic":"education","cefr":"A1"},{"w":"tell","uk":"/tel/","p":"v.","zh":"告诉；讲述","ex":{"en":"Please tell me what happened at school today.","zh":"请告诉我今天在学校发生了什么。"},"tip":"tell常直接接人；say接人时通常用to。","topic":"daily","cefr":"A1"},{"w":"course","uk":"/kɔːs/","p":"n.","zh":"课程","ex":{"en":"I joined a cooking course at the community centre.","zh":"我报名参加了社区中心的烹饪课程。"},"tip":"course 是整门课程；lesson 是其中的一节课。","topic":"education","cefr":"A1"},{"w":"beach","uk":"/biːtʃ/","p":"n.","zh":"海滩；湖滩","ex":{"en":"We collected smooth stones on the beach after breakfast.","zh":"早餐后，我们在海滩上捡了些光滑的石头。"},"tip":"在海滩上用on the beach；shore泛指岸边。","topic":"travel","cefr":"A1"},{"w":"below","uk":"/bɪˈləʊ/","p":"prep.","zh":"在……下方；低于","ex":{"en":"Our cat sleeps on the shelf below the window.","zh":"我们的猫睡在窗户下方的架子上。"},"tip":"below强调位置或数值较低，不一定在正下方。","topic":"daily","cefr":"A1"},{"w":"wife","uk":"/waɪf/","p":"n.","zh":"妻子","ex":{"en":"His wife packed sandwiches for their afternoon walk.","zh":"他的妻子为他们下午的散步准备了三明治。"},"tip":"复数为wives；spouse指配偶，不限定性别。","topic":"society","cefr":"A1"},{"w":"there","uk":"/ðeə/","p":"adv.","zh":"在那里；往那里","ex":{"en":"Leave your muddy boots there, beside the back door.","zh":"把你沾满泥的靴子放在那儿，就在后门旁边。"},"tip":"there表地点或引出存在句；别与their混淆。","topic":"daily","cefr":"A1"},{"w":"drive","uk":"/draɪv/","p":"v.","zh":"驾驶；开车","ex":{"en":"Can you drive me to the station after breakfast?","zh":"早饭后你能开车送我去车站吗？"},"tip":"不规则变化：drive—drove—driven；送某人用drive sb to。","topic":"travel","cefr":"A1"},{"w":"face","uk":"/feɪs/","p":"n.","zh":"脸；面部","ex":{"en":"He washed his face before sitting down for breakfast.","zh":"他洗了脸才坐下来吃早餐。"},"tip":"面对困难可说face difficulties或be faced with difficulties。","topic":"daily","cefr":"A1"},{"w":"teacher","uk":"/ˈtiːtʃə/","p":"n.","zh":"教师；老师","ex":{"en":"Our teacher brought a plant into class today.","zh":"我们的老师今天带了一株植物来上课。"},"tip":"英语中称呼老师通常用Mr、Ms等加姓，不直接喊Teacher。","topic":"education","cefr":"A1"},{"w":"road","uk":"/rəʊd/","p":"n.","zh":"道路；公路","ex":{"en":"Look both ways before you cross the road.","zh":"过马路前要向两边看。"},"tip":"on the road常指在旅途中；road to可比喻通往某结果的途径。","topic":"travel","cefr":"A1"},{"w":"hot","uk":"/hɒt/","p":"adj.","zh":"热的；温度高的","ex":{"en":"Be careful; the soup is still very hot.","zh":"小心，汤还很烫。"},"tip":"形容食物时可指“烫”或“辣”，需结合语境。","topic":"daily","cefr":"A1"},{"w":"blue","uk":"/bluː/","p":"adj.","zh":"蓝色的","ex":{"en":"He wore a blue jacket to the picnic.","zh":"他穿了一件蓝色夹克去野餐。"},"tip":"feel blue表示心情低落；颜色较浅用light blue。","topic":"daily","cefr":"A1"},{"w":"tonight","uk":"/təˈnaɪt/","p":"adv.","zh":"在今晚","ex":{"en":"We are making vegetable soup for dinner tonight.","zh":"我们今晚要做蔬菜汤当晚餐。"},"tip":"作时间状语时直接用tonight，前面不加介词。","topic":"daily","cefr":"A1"},{"w":"internet","uk":"/ˈɪntənet/","p":"n.","zh":"互联网；因特网","ex":{"en":"The internet stopped working halfway through our video call.","zh":"我们视频通话进行到一半时断网了。"},"tip":"通常说 the internet；作定语时不用 the。","topic":"technology","cefr":"A1"},{"w":"taxi","uk":"/ˈtæksi/","p":"n.","zh":"出租车","ex":{"en":"We took a taxi home with our heavy bags.","zh":"我们带着沉重的行李，打车回了家。"},"tip":"乘出租车可说take a taxi或by taxi。","topic":"travel","cefr":"A1"},{"w":"lose","uk":"/luːz/","p":"v.","zh":"丢失；遗失","ex":{"en":"I always lose my keys inside this enormous bag.","zh":"我总是在这个大包里找不到钥匙。"},"tip":"过去式和过去分词都是lost；别与loose混淆。","topic":"daily","cefr":"A1"},{"w":"your","uk":"/jɔː/","p":"det.","zh":"你的；你们的","ex":{"en":"Please leave your shoes by the door before entering.","zh":"进来前请把你的鞋放在门边。"},"tip":"your后接名词；yours独立使用；you're意为你是。","topic":"daily","cefr":"A1"},{"w":"star","uk":"/stɑː/","p":"n.","zh":"星；恒星","ex":{"en":"We watched the stars from our tent beside the lake.","zh":"我们在湖边的帐篷里仰望星空。"},"tip":"star in表示“主演”；过去式starred，进行式starring。","topic":"nature","cefr":"A1"},{"w":"actor","uk":"/ˈæktə/","p":"n.","zh":"演员","ex":{"en":"The actor wore a silver crown on stage.","zh":"那位演员在舞台上戴着一顶银色王冠。"},"tip":"actor可指任何性别的演员；actress专指女演员。","topic":"arts","cefr":"A1"},{"w":"art","uk":"/ɑːt/","p":"n.","zh":"艺术；美术","ex":{"en":"We spent the afternoon making art with coloured paper.","zh":"我们花了一下午用彩纸创作艺术作品。"},"tip":"art指艺术通常不可数；一件作品用a work of art。","topic":"arts","cefr":"A1"},{"w":"break","uk":"/breɪk/","p":"v.","zh":"打破；折断；破裂","ex":{"en":"Be careful not to break that glass bowl.","zh":"小心别打碎那个玻璃碗。"},"tip":"动词变化为break—broke—broken；休息用take a break。","topic":"daily","cefr":"A1"},{"w":"egg","uk":"/eɡ/","p":"n.","zh":"蛋；卵","ex":{"en":"She cracked an egg into the hot frying pan.","zh":"她把一个鸡蛋打进了热煎锅。"},"tip":"scrambled eggs指炒蛋；egg white指蛋清。","topic":"daily","cefr":"A1"},{"w":"bookshop","uk":"/ˈbʊkʃɒp/","p":"n.","zh":"书店","ex":{"en":"We found a tiny bookshop beside the railway station.","zh":"我们在火车站旁发现了一家小书店。"},"tip":"bookshop常用于英式英语，美式多用bookstore。","topic":"daily","cefr":"A1"},{"w":"year","uk":"/jɪə/","p":"n.","zh":"年；一年","ex":{"en":"We moved into this flat almost a year ago.","zh":"我们搬进这套公寓快一年了。"},"tip":"last year等时间短语前不加介词；年龄用years old。","topic":"daily","cefr":"A1"},{"w":"free","uk":"/friː/","p":"adj.","zh":"免费的","ex":{"en":"The café offers free biscuits with every hot drink.","zh":"这家咖啡馆每卖一杯热饮都会赠送饼干。"},"tip":"be free to do表示可以自由做；for free表示免费。","topic":"daily","cefr":"A1"},{"w":"museum","uk":"/mjuˈziːəm/","p":"n.","zh":"博物馆","ex":{"en":"We saw a huge dinosaur skeleton at the museum.","zh":"我们在博物馆看到了一具巨大的恐龙骨架。"},"tip":"museum是可数名词；参观博物馆说visit a museum。","topic":"arts","cefr":"A1"},{"w":"shop","uk":"/ʃɒp/","p":"n.","zh":"商店；店铺","ex":{"en":"The little shop near our house sells fresh bread.","zh":"我们家附近的小店卖新鲜面包。"},"tip":"买某类商品用shop for；泛指去购物用go shopping。","topic":"daily","cefr":"A1"},{"w":"weekend","uk":"/ˌwiːkˈend/","p":"n.","zh":"周末","ex":{"en":"We usually visit the farmers' market at the weekend.","zh":"我们通常在周末逛农贸市场。"},"tip":"英式常说 at the weekend，美式常用 on。","topic":"daily","cefr":"A1"},{"w":"sweater","uk":"/ˈswetə/","p":"n.","zh":"毛衣；针织套衫","ex":{"en":"I pulled on a warm sweater before going outside.","zh":"出门前，我套上了一件暖和的毛衣。"},"tip":"英式英语也常用jumper；sweatshirt指运动衫。","topic":"daily","cefr":"A1"},{"w":"mother","uk":"/ˈmʌðə/","p":"n.","zh":"母亲；妈妈","ex":{"en":"My mother taught me how to ride a bicycle.","zh":"我妈妈教会了我骑自行车。"},"tip":"英式口语常用mum，美式口语常用mom。","topic":"daily","cefr":"A1"},{"w":"tired","uk":"/ˈtaɪəd/","p":"adj.","zh":"疲倦的；累的","ex":{"en":"I felt too tired to cook after the walk.","zh":"散步后我累得不想做饭。"},"tip":"tired形容人感到累；tiring形容事情令人累。","topic":"health","cefr":"A1"},{"w":"play","uk":"/pleɪ/","p":"v.","zh":"玩耍；参加游戏或运动","ex":{"en":"The children played with wooden blocks on the floor.","zh":"孩子们在地板上玩木制积木。"},"tip":"球类前通常不加冠词；乐器前通常用the。","topic":"daily","cefr":"A1"},{"w":"different","uk":"/ˈdɪfrənt/","p":"adj.","zh":"不同的；不一样的","ex":{"en":"These gloves look similar, but their sizes are different.","zh":"这些手套看起来相似，但尺码不同。"},"tip":"与……不同常用different from，适合正式写作。","topic":"daily","cefr":"A1"},{"w":"pool","uk":"/puːl/","p":"n.","zh":"游泳池；水塘","ex":{"en":"We spent the afternoon swimming in the outdoor pool.","zh":"我们整个下午都在室外游泳池游泳。"},"tip":"pool resources指集中资源；play pool则指打美式台球。","topic":"daily","cefr":"A1"},{"w":"before","uk":"/bɪˈfɔː/","p":"prep.","zh":"在……之前","ex":{"en":"Please put your shoes by the door before dinner.","zh":"请在晚饭前把鞋放到门边。"},"tip":"时间从句表将来时，before后通常用一般现在时。","topic":"daily","cefr":"A1"},{"w":"wonderful","uk":"/ˈwʌndəfəl/","p":"adj.","zh":"极好的；令人愉快的","ex":{"en":"We had a wonderful picnic beside the lake.","zh":"我们在湖边度过了一段美好的野餐时光。"},"tip":"表示极好或令人愉快，不等于奇怪的。","topic":"emotion","cefr":"A1"},{"w":"notebook","uk":"/ˈnəʊtbʊk/","p":"n.","zh":"笔记本；笔记簿","ex":{"en":"She keeps a small notebook beside her bed.","zh":"她在床边放着一本小笔记本。"},"tip":"通常指纸质笔记本；电脑义也可说notebook computer。","topic":"education","cefr":"A1"},{"w":"white","uk":"/waɪt/","p":"adj.","zh":"白色的","ex":{"en":"She wore a white cotton shirt to the picnic.","zh":"她穿着一件白色棉衬衫去野餐。"},"tip":"egg white指蛋清；蛋黄是yolk。","topic":"daily","cefr":"A1"},{"w":"large","uk":"/lɑːdʒ/","p":"adj.","zh":"大的；大量的","ex":{"en":"A large dog was sleeping beside the kitchen door.","zh":"一只大狗正睡在厨房门旁。"},"tip":"large number接可数名词，large amount接不可数名词。","topic":"daily","cefr":"A1"},{"w":"hour","uk":"/ˈaʊə/","p":"n.","zh":"小时","ex":{"en":"The walk to the lake took us an hour.","zh":"我们走到湖边花了一个小时。"},"tip":"h不发音，所以说an hour，而不是a hour。","topic":"daily","cefr":"A1"},{"w":"married","uk":"/ˈmærid/","p":"adj.","zh":"已婚的","ex":{"en":"My sister is married and lives near the coast.","zh":"我姐姐已婚，住在海岸附近。"},"tip":"与某人结婚用 be/get married to，不用 with。","topic":"society","cefr":"A1"},{"w":"full","uk":"/fʊl/","p":"adj.","zh":"满的；装满的","ex":{"en":"The basket is full, so we need another one.","zh":"篮子已经满了，我们得再拿一个。"},"tip":"full of表示“充满”；注意full与fool发音不同。","topic":"daily","cefr":"A1"},{"w":"happen","uk":"/ˈhæpən/","p":"v.","zh":"发生","ex":{"en":"What happened to the plant beside your window?","zh":"你窗边那盆植物怎么了？"},"tip":"不用于被动语态；happen to do表示碰巧做某事。","topic":"daily","cefr":"A1"},{"w":"number","uk":"/ˈnʌmbə/","p":"n.","zh":"数；数字；号码","ex":{"en":"I saved your phone number on my new phone.","zh":"我把你的电话号码存到了新手机里。"},"tip":"a number of接复数谓语；the number of接单数谓语。","topic":"daily","cefr":"A1"},{"w":"take","uk":"/teɪk/","p":"v.","zh":"拿；取；带走","ex":{"en":"Take an umbrella because it might rain this afternoon.","zh":"带把伞吧，今天下午可能会下雨。"},"tip":"过去式took，过去分词taken；take带走，bring带来。","topic":"daily","cefr":"A1"},{"w":"enjoy","uk":"/ɪnˈdʒɔɪ/","p":"v.","zh":"享受；喜爱","ex":{"en":"We enjoy walking beside the river after dinner.","zh":"我们喜欢晚饭后在河边散步。"},"tip":"接动词时用-ing形式，不用to do。","topic":"daily","cefr":"A1"},{"w":"hobby","uk":"/ˈhɒbi/","p":"n.","zh":"业余爱好","ex":{"en":"Growing herbs on my balcony has become my favourite hobby.","zh":"在阳台种香草已成了我最喜欢的业余爱好。"},"tip":"可数名词，复数为hobbies；开始一种爱好用take up。","topic":"daily","cefr":"A1"},{"w":"artist","uk":"/ˈɑːtɪst/","p":"n.","zh":"艺术家；画家","ex":{"en":"The artist painted the harbour in soft blue colours.","zh":"这位画家用柔和的蓝色描绘了港口。"},"tip":"artist指艺术家；artistic是形容词“艺术的”。","topic":"arts","cefr":"A1"},{"w":"stand","uk":"/stænd/","p":"v.","zh":"站立；起立","ex":{"en":"Please stand near the door until the bus stops.","zh":"请站在车门附近，等公交车停稳。"},"tip":"过去式和过去分词均为stood；忍受常用can't stand。","topic":"daily","cefr":"A1"},{"w":"must","uk":"/mʌst/","p":"v.","zh":"必须","ex":{"en":"You must wear a helmet when riding here.","zh":"在这里骑车必须戴头盔。"},"tip":"must是情态动词；mustn't表禁止，不是“不必”。","topic":"daily","cefr":"A1"},{"w":"sky","uk":"/skaɪ/","p":"n.","zh":"天空","ex":{"en":"The sky turned orange as we walked home.","zh":"我们步行回家时，天空变成了橙色。"},"tip":"通常用the sky；skies常用于描述天气或某地天空。","topic":"nature","cefr":"A1"},{"w":"about","uk":"/əˈbaʊt/","p":"prep.","zh":"关于","ex":{"en":"We talked about our holiday plans over dinner.","zh":"我们吃晚饭时聊了假期计划。"},"tip":"about可表示话题或约数；be about to表示即将。","topic":"daily","cefr":"A1"},{"w":"sandwich","uk":"/ˈsænwɪdʒ/","p":"n.","zh":"三明治","ex":{"en":"I packed a cheese sandwich and an apple for lunch.","zh":"我带了一个奶酪三明治和一个苹果当午餐。"},"tip":"动词常用被动结构be sandwiched between。","topic":"daily","cefr":"A1"},{"w":"slow","uk":"/sləʊ/","p":"adj.","zh":"缓慢的；耗时的","ex":{"en":"We took a slow walk along the river.","zh":"我们沿着河边慢慢散步。"},"tip":"slow多作形容词；修饰一般动作通常用slowly。","topic":"daily","cefr":"A1"},{"w":"make","uk":"/meɪk/","p":"v.","zh":"制作；制造","ex":{"en":"We made a small table from leftover pieces of wood.","zh":"我们用剩下的木料做了一张小桌子。"},"tip":"主动式make sb do；被动式be made to do。","topic":"daily","cefr":"A1"},{"w":"every","uk":"/ˈevri/","p":"det.","zh":"每个；每一","ex":{"en":"Every child brought a favourite toy to the picnic.","zh":"每个孩子都带了一件最喜欢的玩具去野餐。"},"tip":"every后通常接单数可数名词，谓语也用单数。","topic":"daily","cefr":"A1"},{"w":"quiet","uk":"/ˈkwaɪət/","p":"adj.","zh":"安静的；轻声的","ex":{"en":"The house was quiet after the children fell asleep.","zh":"孩子们睡着后，屋子里安静了下来。"},"tip":"quiet是“安静的”，quite是“相当”，注意拼写。","topic":"daily","cefr":"A1"},{"w":"add","uk":"/æd/","p":"v.","zh":"添加；增加","ex":{"en":"Add a little milk if the soup is too thick.","zh":"如果汤太稠，就加一点牛奶。"},"tip":"add A to B表示把A加入B；add to还可表示增添。","topic":"daily","cefr":"A1"},{"w":"fact","uk":"/fækt/","p":"n.","zh":"事实；真实情况","ex":{"en":"We checked the facts before booking our train tickets.","zh":"我们核实了相关情况后才订火车票。"},"tip":"the fact that后接完整从句，说明事实内容。","topic":"thinking","cefr":"A1"},{"w":"nice","uk":"/naɪs/","p":"adj.","zh":"令人愉快的；美好的","ex":{"en":"We had a nice picnic beside the lake.","zh":"我们在湖边愉快地野餐了一次。"},"tip":"nice含义较宽，正式写作宜换成更具体的形容词。","topic":"daily","cefr":"A1"},{"w":"flower","uk":"/ˈflaʊə/","p":"n.","zh":"花；开花植物","ex":{"en":"She placed fresh flowers in a vase by the window.","zh":"她把鲜花插进窗边的花瓶里。"},"tip":"flower既可作名词“花”，也可作动词“开花”。","topic":"nature","cefr":"A1"},{"w":"cloudy","uk":"/ˈklaʊdi/","p":"adj.","zh":"多云的；阴天的","ex":{"en":"It was cloudy, so we left our sunglasses at home.","zh":"当时天阴着，所以我们把太阳镜留在了家里。"},"tip":"既可形容天空多云，也可形容液体浑浊。","topic":"nature","cefr":"A1"},{"w":"important","uk":"/ɪmˈpɔːtənt/","p":"adj.","zh":"重要的；重大的","ex":{"en":"Keep your important documents in this waterproof folder.","zh":"把你的重要文件放在这个防水文件夹里。"},"tip":"用It is important to do；importance是名词形式。","topic":"daily","cefr":"A1"},{"w":"house","uk":"/haʊs/","p":"n.","zh":"房屋；住宅","ex":{"en":"Their house has a small garden behind the kitchen.","zh":"他们的房子在厨房后面有一个小花园。"},"tip":"名词读/haʊs/，动词读/haʊz/；home更强调家的归属感。","topic":"city","cefr":"A1"},{"w":"lady","uk":"/ˈleɪdi/","p":"n.","zh":"女士；夫人","ex":{"en":"A kind lady helped me find the station.","zh":"一位好心的女士帮我找到了车站。"},"tip":"woman是中性通用词；lady常用于礼貌称呼。","topic":"society","cefr":"A1"},{"w":"piano","uk":"/piˈænəʊ/","p":"n.","zh":"钢琴","ex":{"en":"My sister practises the piano after dinner every evening.","zh":"我姐姐每天晚饭后练钢琴。"},"tip":"表示弹钢琴通常说play the piano。","topic":"arts","cefr":"A1"},{"w":"market","uk":"/ˈmɑːkɪt/","p":"n.","zh":"集市；市场","ex":{"en":"We bought fresh peaches at the market this morning.","zh":"今天早上我们在集市买了新鲜桃子。"},"tip":"a market for sth指对某物的市场需求。","topic":"economy","cefr":"A1"},{"w":"hill","uk":"/hɪl/","p":"n.","zh":"小山；丘陵","ex":{"en":"We climbed the hill and watched the sunset.","zh":"我们爬上小山，看了日落。"},"tip":"hill通常比mountain低矮，但没有统一高度界限。","topic":"nature","cefr":"A1"},{"w":"late","uk":"/leɪt/","p":"adj.","zh":"迟到的；晚期的","ex":{"en":"I was late because my bicycle had a flat tyre.","zh":"我迟到了，因为我的自行车轮胎没气了。"},"tip":"late作副词指迟、晚；lately指最近，不能混用。","topic":"daily","cefr":"A1"},{"w":"age","uk":"/eɪdʒ/","p":"n.","zh":"年龄；存在年限","ex":{"en":"My grandmother learned to swim at the age of seventy.","zh":"我奶奶七十岁时学会了游泳。"},"tip":"表示在几岁时用at the age of，不用in。","topic":"society","cefr":"A1"},{"w":"cake","uk":"/keɪk/","p":"n.","zh":"蛋糕","ex":{"en":"We shared a slice of lemon cake after lunch.","zh":"午饭后，我们分着吃了一片柠檬蛋糕。"},"tip":"整个蛋糕可数；泛指蛋糕这种食物时常不可数。","topic":"daily","cefr":"A1"},{"w":"photograph","uk":"/ˈfəʊtəɡrɑːf/","p":"n.","zh":"照片；相片","ex":{"en":"This photograph shows my grandparents standing beside their first house.","zh":"这张照片里，我的祖父母站在他们的第一所房子旁。"},"tip":"拍照用take a photograph，不用make。","topic":"arts","cefr":"A1"},{"w":"sound","uk":"/saʊnd/","p":"n.","zh":"声音；声响","ex":{"en":"The sound of rain woke me before sunrise.","zh":"天还没亮，雨声就把我吵醒了。"},"tip":"sound后接形容词；sound like后接名词。","topic":"daily","cefr":"A1"},{"w":"nationality","uk":"/ˌnæʃəˈnæləti/","p":"n.","zh":"国籍","ex":{"en":"The application form asks for my nationality and address.","zh":"申请表要求填写我的国籍和地址。"},"tip":"nationality指国籍，不等同于出生地或族裔。","topic":"society","cefr":"A1"},{"w":"ruler","uk":"/ˈruːlə/","p":"n.","zh":"尺子；直尺","ex":{"en":"Use a ruler to draw a straight line here.","zh":"用尺子在这里画一条直线。"},"tip":"a ruler可指一把尺子或一位统治者，需看语境。","topic":"education","cefr":"A1"},{"w":"open","uk":"/ˈəʊpən/","p":"adj.","zh":"敞开的；营业的","ex":{"en":"Leave the window open so fresh air can come in.","zh":"让窗户开着，好让新鲜空气进来。"},"tip":"be open表示开着的状态；open作动词表示打开的动作。","topic":"daily","cefr":"A1"},{"w":"singer","uk":"/ˈsɪŋə/","p":"n.","zh":"歌手；歌唱家","ex":{"en":"The singer smiled as the audience began to clap.","zh":"观众开始鼓掌时，歌手露出了笑容。"},"tip":"sing 的过去式、过去分词分别是 sang、sung。","topic":"arts","cefr":"A1"},{"w":"television","uk":"/ˈtelɪvɪʒən/","p":"n.","zh":"电视；电视节目","ex":{"en":"We watched a wildlife programme on television after dinner.","zh":"晚饭后我们在电视上看了一档野生动物节目。"},"tip":"watch television不加冠词；指一台电视机用a television。","topic":"media","cefr":"A1"},{"w":"back","uk":"/bæk/","p":"n.","zh":"背部；后部","ex":{"en":"My back feels stiff after sitting all morning.","zh":"坐了一上午后，我感觉背部僵硬。"},"tip":"go back表示回去；back作动词可表示支持。","topic":"daily","cefr":"A1"},{"w":"gray","uk":"/ɡreɪ/","p":"adj.","zh":"灰色的；灰白的","ex":{"en":"My grandfather wears a gray coat every winter.","zh":"我祖父每年冬天都穿一件灰色外套。"},"tip":"gray为美式拼写，英式通常写grey。","topic":"daily","cefr":"A1"},{"w":"anyone","uk":"/ˈeniwʌn/","p":"pron.","zh":"任何人","ex":{"en":"Anyone can join our weekend walk by the river.","zh":"任何人都可以参加我们周末的河边散步活动。"},"tip":"作主语时谓语用单数；any one强调任意一个。","topic":"society","cefr":"A1"},{"w":"beautiful","uk":"/ˈbjuːtɪfl/","p":"adj.","zh":"美丽的；优美的","ex":{"en":"The garden looks beautiful after the spring rain.","zh":"春雨过后，花园看起来很美。"},"tip":"可修饰景色、声音等；比较级用more beautiful。","topic":"nature","cefr":"A1"},{"w":"tooth","uk":"/tuːθ/","p":"n.","zh":"牙齿","ex":{"en":"The dentist checked each tooth with a small mirror.","zh":"牙医用一面小镜子检查了每颗牙齿。"},"tip":"复数是不规则形式teeth，注意元音也变化。","topic":"health","cefr":"A1"},{"w":"relax","uk":"/rɪˈlæks/","p":"v.","zh":"放松；休息","ex":{"en":"I like to relax with music after dinner.","zh":"我喜欢晚饭后听音乐放松。"},"tip":"人感到放松用relaxed；事物令人放松用relaxing。","topic":"health","cefr":"A1"},{"w":"summer","uk":"/ˈsʌmə/","p":"n.","zh":"夏天；夏季","ex":{"en":"We often eat outside during the long summer evenings.","zh":"夏天傍晚很长，我们常在户外吃饭。"},"tip":"泛指夏季可用in summer；季节名称通常小写。","topic":"nature","cefr":"A1"},{"w":"group","uk":"/ɡruːp/","p":"n.","zh":"组；群；团体","ex":{"en":"A group of cyclists stopped outside the village bakery.","zh":"一群骑行者在村里的面包店外停了下来。"},"tip":"a group of后常接复数名词；动词常用group A by B。","topic":"society","cefr":"A1"},{"w":"member","uk":"/ˈmembə/","p":"n.","zh":"成员；会员","ex":{"en":"Each club member brought a dish to share.","zh":"每位俱乐部成员都带了一道菜与大家分享。"},"tip":"表示某团体的成员，用a member of。","topic":"society","cefr":"A1"},{"w":"fish","uk":"/fɪʃ/","p":"n.","zh":"鱼；鱼肉","ex":{"en":"We watched small fish swimming under the wooden bridge.","zh":"我们看着小鱼在木桥下游动。"},"tip":"表示多条鱼通常仍用fish；鱼肉为不可数名词。","topic":"nature","cefr":"A1"},{"w":"daughter","uk":"/ˈdɔːtə/","p":"n.","zh":"女儿","ex":{"en":"Their daughter made pancakes for the whole family.","zh":"他们的女儿给全家人做了薄煎饼。"},"tip":"daughter-in-law是儿媳，不是继女。","topic":"society","cefr":"A1"},{"w":"sheep","uk":"/ʃiːp/","p":"n.","zh":"绵羊","ex":{"en":"Several sheep were resting under a tree near the farm.","zh":"几只绵羊正在农场附近的一棵树下休息。"},"tip":"sheep单复数同形；山羊是goat。","topic":"nature","cefr":"A1"},{"w":"school","uk":"/skuːl/","p":"n.","zh":"学校；上学","ex":{"en":"We walk to school together along the river.","zh":"我们一起沿着河边步行上学。"},"tip":"go to school指上学；go to the school指去校址。","topic":"education","cefr":"A1"},{"w":"always","uk":"/ˈɔːlweɪz/","p":"adv.","zh":"总是；每次都","ex":{"en":"My neighbour always waves when she sees me.","zh":"我的邻居每次看见我都会挥手。"},"tip":"通常放实义动词前、be动词后；not always是并非总是。","topic":"daily","cefr":"A1"},{"w":"usually","uk":"/ˈjuːʒuəli/","p":"adv.","zh":"通常；一般地","ex":{"en":"I usually walk to work unless it rains.","zh":"除非下雨，我通常步行上班。"},"tip":"通常放在实义动词前、be动词后。","topic":"daily","cefr":"A1"},{"w":"history","uk":"/ˈhɪstəri/","p":"n.","zh":"历史；历史学","ex":{"en":"Our guide explained the history of the old castle.","zh":"导游讲述了这座古堡的历史。"},"tip":"historical指与历史有关；historic指有历史意义。","topic":"history","cefr":"A1"},{"w":"feet","uk":"/fiːt/","p":"n.","zh":"脚（foot的复数）","ex":{"en":"My feet felt cold against the kitchen tiles.","zh":"我的脚踩在厨房瓷砖上，感觉冰凉。"},"tip":"foot的复数是feet；作前置修饰语用单数，如six-foot。","topic":"daily","cefr":"A1"},{"w":"wash","uk":"/wɒʃ/","p":"v.","zh":"洗；清洗","ex":{"en":"Please wash your hands before you help prepare dinner.","zh":"帮忙准备晚餐前，请先洗手。"},"tip":"wash强调用水洗；clean泛指清洁，不一定用水。","topic":"daily","cefr":"A1"},{"w":"sofa","uk":"/ˈsəʊfə/","p":"n.","zh":"沙发","ex":{"en":"We curled up on the sofa after dinner.","zh":"晚饭后，我们蜷坐在沙发上。"},"tip":"坐在沙发上用on the sofa，不用in。","topic":"daily","cefr":"A1"},{"w":"interesting","uk":"/ˈɪntrəstɪŋ/","p":"adj.","zh":"有趣的；引人关注的","ex":{"en":"We found an interesting little museum near the station.","zh":"我们在车站附近发现了一家有趣的小博物馆。"},"tip":"interesting形容事物引人兴趣，不等于funny好笑。","topic":"thinking","cefr":"A1"},{"w":"rice","uk":"/raɪs/","p":"n.","zh":"大米；米饭；稻","ex":{"en":"We had rice with steamed fish for dinner.","zh":"我们晚餐吃了米饭和清蒸鱼。"},"tip":"rice通常不可数；一粒米用a grain of rice。","topic":"daily","cefr":"A1"},{"w":"area","uk":"/ˈeəriə/","p":"n.","zh":"地区；区域","ex":{"en":"There is a quiet picnic area beside the lake.","zh":"湖边有一处安静的野餐区。"},"tip":"表示面积时常用平方米等单位；也可指研究领域。","topic":"city","cefr":"A1"},{"w":"clean","uk":"/kliːn/","p":"adj.","zh":"干净的；清洁的","ex":{"en":"There are clean towels on the shelf beside you.","zh":"你旁边的架子上有干净的毛巾。"},"tip":"clean是干净；clear是清澈或清楚，不能随意互换。","topic":"daily","cefr":"A1"},{"w":"business","uk":"/ˈbɪznəs/","p":"n.","zh":"商业；生意","ex":{"en":"Business is usually slow at the café on Mondays.","zh":"这家咖啡馆周一的生意通常比较清淡。"},"tip":"指商业活动时不可数；指具体企业时可数。","topic":"work","cefr":"A1"},{"w":"walking","uk":"/ˈwɔːkɪŋ/","p":"n.","zh":"步行；散步","ex":{"en":"Walking to the shops takes about ten minutes.","zh":"步行去商店大约需要十分钟。"},"tip":"walking中的l不发音；步行去某地也可用on foot。","topic":"health","cefr":"A1"},{"w":"name","uk":"/neɪm/","p":"n.","zh":"名字；名称","ex":{"en":"What name did you choose for your new kitten?","zh":"你给新来的小猫取了什么名字？"},"tip":"英式name A after B表示以B的名字命名A。","topic":"daily","cefr":"A1"},{"w":"airport","uk":"/ˈeəpɔːt/","p":"n.","zh":"机场","ex":{"en":"We arrived at the airport before the sun rose.","zh":"太阳还没升起，我们就到了机场。"},"tip":"在机场通常用at the airport；航站楼是terminal。","topic":"travel","cefr":"A1"},{"w":"often","uk":"/ˈɒfən/","p":"adv.","zh":"经常；常常","ex":{"en":"We often walk by the river after dinner.","zh":"我们经常在晚饭后沿河散步。"},"tip":"通常放实义动词前、be动词后；t也可发音。","topic":"daily","cefr":"A1"},{"w":"dollar","uk":"/ˈdɒlə/","p":"n.","zh":"美元；元（货币单位）","ex":{"en":"I paid one dollar for this small notebook.","zh":"我花了一美元买这本小笔记本。"},"tip":"不只指美元，也用于加拿大元、澳大利亚元等。","topic":"economy","cefr":"A1"},{"w":"it","uk":"/ɪt/","p":"pron.","zh":"它；这；那","ex":{"en":"I found your scarf and put it by the door.","zh":"我找到了你的围巾，把它放在门边了。"},"tip":"小写it是代词；大写IT才表示信息技术。","topic":"daily","cefr":"A1"},{"w":"baby","uk":"/ˈbeɪbi/","p":"n.","zh":"婴儿；幼崽","ex":{"en":"The baby fell asleep while her father sang softly.","zh":"爸爸轻声唱歌时，宝宝睡着了。"},"tip":"复数为babies；baby作动词常含“过度照顾”之意。","topic":"daily","cefr":"A1"},{"w":"rabbit","uk":"/ˈræbɪt/","p":"n.","zh":"兔；家兔","ex":{"en":"A white rabbit hopped across the grass towards us.","zh":"一只白兔蹦蹦跳跳地穿过草地，朝我们跑来。"},"tip":"rabbit泛指兔；hare通常指腿耳更长的野兔。","topic":"nature","cefr":"A1"},{"w":"water","uk":"/ˈwɔːtə/","p":"n.","zh":"水","ex":{"en":"Please water the plants before we leave today.","zh":"今天出门前请给植物浇水。"},"tip":"表示水通常不可数：a glass of water是一杯水。","topic":"daily","cefr":"A1"},{"w":"half","uk":"/hɑːf/","p":"n.","zh":"一半；半场","ex":{"en":"I saved half of my sandwich for later.","zh":"我留了一半三明治，准备晚点吃。"},"tip":"复数为halves；“半小时”用half an hour。","topic":"daily","cefr":"A1"},{"w":"knife","uk":"/naɪf/","p":"n.","zh":"刀；餐刀","ex":{"en":"Use a sharp knife to slice the bread.","zh":"用一把锋利的刀把面包切成片。"},"tip":"k不发音；复数把-fe变为-ves：knives。","topic":"daily","cefr":"A1"},{"w":"thanks","uk":"/θæŋks/","p":"int.","zh":"谢谢","ex":{"en":"Thanks for helping me carry these heavy bags upstairs.","zh":"谢谢你帮我把这些沉重的袋子搬上楼。"},"tip":"thanks for后接名词或动名词；thanks to表示多亏。","topic":"daily","cefr":"A1"},{"w":"dangerous","uk":"/ˈdeɪndʒərəs/","p":"adj.","zh":"危险的","ex":{"en":"That broken step is dangerous, so please avoid it.","zh":"那级破损的台阶很危险，请避开它。"},"tip":"dangerous是形容词；修饰动作要用dangerously。","topic":"health","cefr":"A1"},{"w":"message","uk":"/ˈmesɪdʒ/","p":"n.","zh":"消息；口信","ex":{"en":"Please leave a message if I miss your call.","zh":"如果我没接到你的电话，请留言。"},"tip":"message是可数名词；information通常不可数。","topic":"technology","cefr":"A1"},{"w":"sea","uk":"/siː/","p":"n.","zh":"海；海洋","ex":{"en":"The children watched small boats sailing across the sea.","zh":"孩子们看着小船在海上航行。"},"tip":"at sea指在海上；by the sea指在海边。","topic":"nature","cefr":"A1"},{"w":"bread","uk":"/bred/","p":"n.","zh":"面包","ex":{"en":"Fresh bread was cooling beside the kitchen window.","zh":"刚出炉的面包放在厨房窗边晾凉。"},"tip":"bread通常不可数；一片用a slice of bread。","topic":"daily","cefr":"A1"},{"w":"between","uk":"/bɪˈtwiːn/","p":"prep.","zh":"在……之间","ex":{"en":"The cat squeezed between the sofa and the wall.","zh":"猫从沙发和墙之间挤了过去。"},"tip":"between不只限于两者，也可用于多个明确对象之间。","topic":"daily","cefr":"A1"},{"w":"far","uk":"/fɑː/","p":"adv.","zh":"远；遥远地","ex":{"en":"We walked so far that our feet began to ache.","zh":"我们走了很远，走得脚都开始疼了。"},"tip":"far可修饰比较级，如far better；不用far good。","topic":"travel","cefr":"A1"},{"w":"eighteen","uk":"/ˌeɪˈtiːn/","p":"num.","zh":"十八","ex":{"en":"We baked eighteen muffins for the picnic this morning.","zh":"我们今天早上为野餐烤了十八个松饼。"},"tip":"eighteen是十八，eighty是八十；注意词尾发音。","topic":"daily","cefr":"A1"},{"w":"time","uk":"/taɪm/","p":"n.","zh":"时间；时刻","ex":{"en":"We still have time for a walk before dinner.","zh":"晚饭前我们还有时间散步。"},"tip":"时间通常不可数；表示次数时可数，如three times。","topic":"daily","cefr":"A1"},{"w":"company","uk":"/ˈkʌmpəni/","p":"n.","zh":"公司","ex":{"en":"My sister works for a company that makes bicycles.","zh":"我姐姐在一家制造自行车的公司工作。"},"tip":"表“公司”可数；表“陪伴”不可数。","topic":"work","cefr":"A1"},{"w":"bathroom","uk":"/ˈbɑːθruːm/","p":"n.","zh":"浴室；卫生间","ex":{"en":"She hung a clean towel beside the bathroom sink.","zh":"她在浴室洗手池旁挂了一条干净毛巾。"},"tip":"美式英语中bathroom也可指没有浴缸的厕所。","topic":"daily","cefr":"A1"},{"w":"dance","uk":"/dɑːns/","p":"v.","zh":"跳舞","ex":{"en":"We danced in the kitchen while dinner was cooking.","zh":"晚饭还在做的时候，我们在厨房里跳起了舞。"},"tip":"随音乐跳舞用dance to music，介词用to。","topic":"arts","cefr":"A1"},{"w":"favorite","uk":"/ˈfeɪvərɪt/","p":"adj.","zh":"最喜欢的","ex":{"en":"This blue sweater is my favorite winter item.","zh":"这件蓝色毛衣是我冬天最喜欢的一件衣服。"},"tip":"favorite是美式拼写，英式为favourite；通常不用most修饰。","topic":"daily","cefr":"A1"},{"w":"tea","uk":"/tiː/","p":"n.","zh":"茶；茶水","ex":{"en":"I made a pot of tea while you rested.","zh":"你休息的时候，我泡了一壶茶。"},"tip":"茶水通常不可数；点单时two teas指两杯茶。","topic":"daily","cefr":"A1"},{"w":"change","uk":"/tʃeɪndʒ/","p":"v.","zh":"改变；更换；兑换","ex":{"en":"We changed our plans when the rain started falling.","zh":"开始下雨时，我们改变了计划。"},"tip":"表示“零钱、找零”时不可数，不能说a change。","topic":"daily","cefr":"A1"},{"w":"ready","uk":"/ˈredi/","p":"adj.","zh":"准备好的；可用的","ex":{"en":"Dinner is ready, so please bring your plate.","zh":"晚饭好了，请把你的盘子拿来。"},"tip":"ready for后接名词；ready to后接动词原形。","topic":"daily","cefr":"A1"},{"w":"idea","uk":"/aɪˈdɪə/","p":"n.","zh":"主意；想法","ex":{"en":"Your idea of growing herbs on the balcony sounds lovely.","zh":"你在阳台上种香草的主意听起来很棒。"},"tip":"idea是可数名词；“不知道”可说have no idea。","topic":"thinking","cefr":"A1"},{"w":"draw","uk":"/drɔː/","p":"v.","zh":"画；绘制","ex":{"en":"She drew a sleeping cat in her sketchbook.","zh":"她在素描本上画了一只熟睡的猫。"},"tip":"过去式drew，过去分词drawn；另可指平局。","topic":"arts","cefr":"A1"},{"w":"down","uk":"/daʊn/","p":"adv.","zh":"向下；在下面","ex":{"en":"The cat jumped down from the kitchen table.","zh":"猫从厨房的桌子上跳了下来。"},"tip":"down后接名词可作介词；feel down表示心情低落。","topic":"daily","cefr":"A1"},{"w":"machine","uk":"/məˈʃiːn/","p":"n.","zh":"机器；机械装置","ex":{"en":"The washing machine shook loudly during its final spin.","zh":"洗衣机在最后脱水时剧烈晃动，声音很大。"},"tip":"machine是可数名词；machinery是不可数集合名词。","topic":"technology","cefr":"A1"},{"w":"get","uk":"/ɡet/","p":"v.","zh":"获得；收到","ex":{"en":"I got a warm scarf for my birthday.","zh":"我生日时收到了一条暖和的围巾。"},"tip":"过去式got；美式过去分词也用gotten。","topic":"daily","cefr":"A1"},{"w":"but","uk":"/bʌt/","p":"conj.","zh":"但是；而是","ex":{"en":"The bag looks small, but it holds everything I need.","zh":"这个包看起来小，却装得下我需要的所有东西。"},"tip":"although与but通常不在同一句中成对使用。","topic":"daily","cefr":"A1"},{"w":"red","uk":"/red/","p":"adj.","zh":"红色的","ex":{"en":"She wore a red coat to the winter market.","zh":"她穿着一件红色外套去了冬季集市。"},"tip":"in the red表示负债或亏损，不是字面上的红色。","topic":"daily","cefr":"A1"},{"w":"conversation","uk":"/ˌkɒnvəˈseɪʃən/","p":"n.","zh":"交谈；谈话","ex":{"en":"We had a friendly conversation while waiting for the bus.","zh":"等公交车时，我们友好地聊了一会儿。"},"tip":"与某人谈某事：have a conversation with某人about某事。","topic":"daily","cefr":"A1"},{"w":"dinner","uk":"/ˈdɪnə/","p":"n.","zh":"正餐；晚餐","ex":{"en":"Dinner is ready, so please bring the plates.","zh":"晚饭做好了，请把盘子拿来。"},"tip":"日常说 have dinner，不加冠词；正式宴会可说 a dinner。","topic":"daily","cefr":"A1"},{"w":"bring","uk":"/brɪŋ/","p":"v.","zh":"带来；拿来","ex":{"en":"Please bring a warm coat when you visit.","zh":"你来时请带一件暖和的外套。"},"tip":"bring强调带到说话者或指定地点；过去式brought。","topic":"daily","cefr":"A1"},{"w":"reason","uk":"/ˈriːzən/","p":"n.","zh":"原因；理由","ex":{"en":"The heavy rain was the reason we stayed home.","zh":"大雨是我们待在家里的原因。"},"tip":"常用reason for加名词，或reason why加从句。","topic":"thinking","cefr":"A1"},{"w":"colour","uk":"/ˈkʌlə/","p":"n.","zh":"颜色；色彩","ex":{"en":"What colour should we paint the kitchen walls?","zh":"我们该把厨房的墙刷成什么颜色？"},"tip":"英式拼写为colour，美式为color。","topic":"daily","cefr":"A1"},{"w":"eye","uk":"/aɪ/","p":"n.","zh":"眼睛","ex":{"en":"She closed her eyes and listened to the rain.","zh":"她闭上眼睛，听着雨声。"},"tip":"an eye for表示鉴赏力；keep an eye on表示照看。","topic":"health","cefr":"A1"},{"w":"afternoon","uk":"/ˌɑːftəˈnuːn/","p":"n.","zh":"下午","ex":{"en":"We spent the afternoon baking bread in the kitchen.","zh":"我们整个下午都在厨房里烤面包。"},"tip":"泛指下午用in；具体某天下午用on。","topic":"daily","cefr":"A1"},{"w":"end","uk":"/end/","p":"n.","zh":"结束；末尾；尽头","ex":{"en":"There's a small bakery at the end of our street.","zh":"我们这条街的尽头有一家小面包店。"},"tip":"at the end指末尾；in the end指最终。","topic":"daily","cefr":"A1"},{"w":"delicious","uk":"/dɪˈlɪʃəs/","p":"adj.","zh":"美味的；可口的","ex":{"en":"This delicious vegetable pie is still warm from the oven.","zh":"这份美味的蔬菜派刚出炉，还热乎着。"},"tip":"delicious本身语气较强，常用absolutely加强。","topic":"daily","cefr":"A1"},{"w":"fill","uk":"/fɪl/","p":"v.","zh":"装满；充满","ex":{"en":"Please fill the jug with water for our guests.","zh":"请把水壶装满水，给客人们喝。"},"tip":"fill A with B表示用B装满A；be filled with表示充满。","topic":"daily","cefr":"A1"},{"w":"become","uk":"/bɪˈkʌm/","p":"v.","zh":"变得；成为","ex":{"en":"The streets become quiet after the shops close.","zh":"商店关门后，街道变得安静起来。"},"tip":"变化形式：become—became—become；后接名词或形容词。","topic":"daily","cefr":"A1"},{"w":"up","uk":"/ʌp/","p":"adv.","zh":"向上；在高处","ex":{"en":"The child looked up at the bright red balloon.","zh":"孩子抬头看着那个鲜红的气球。"},"tip":"up后接地点名词可作介词，如up the hill。","topic":"daily","cefr":"A1"},{"w":"world","uk":"/wɜːld/","p":"n.","zh":"世界；地球","ex":{"en":"She dreams of travelling around the world by train.","zh":"她梦想乘火车环游世界。"},"tip":"指整个世界通常用the world；商界为the business world。","topic":"society","cefr":"A1"},{"w":"drink","uk":"/drɪŋk/","p":"v.","zh":"喝；饮","ex":{"en":"I always drink some water after walking the dog.","zh":"我遛完狗总会喝些水。"},"tip":"不规则变化：drink—drank—drunk。","topic":"health","cefr":"A1"},{"w":"grey","uk":"/ɡreɪ/","p":"adj.","zh":"灰色的；灰白的","ex":{"en":"A grey cat was sleeping on the windowsill.","zh":"一只灰猫正在窗台上睡觉。"},"tip":"grey为英式拼写，gray为美式拼写。","topic":"daily","cefr":"A1"},{"w":"much","uk":"/mʌtʃ/","p":"det.","zh":"许多；大量","ex":{"en":"We do not have much milk left for breakfast.","zh":"我们剩下的早餐牛奶不多了。"},"tip":"修饰不可数名词；可数名词复数用many。","topic":"daily","cefr":"A1"},{"w":"learn","uk":"/lɜːn/","p":"v.","zh":"学习；学会","ex":{"en":"My grandfather is learning to swim at the local pool.","zh":"我爷爷正在附近的游泳池学游泳。"},"tip":"learn to do表示学会做；过去式可用learnt或learned。","topic":"education","cefr":"A1"},{"w":"south","uk":"/saʊθ/","p":"n.","zh":"南；南方","ex":{"en":"Our balcony faces south and gets plenty of sunshine.","zh":"我们的阳台朝南，阳光很充足。"},"tip":"南部用in the south；向南用go south，不加to。","topic":"travel","cefr":"A1"},{"w":"can","uk":"/kæn/","p":"v.","zh":"能；可以；可能","ex":{"en":"I can carry both bags if you open the door.","zh":"你要是把门打开，我就能把两个袋子都提进去。"},"tip":"作情态动词后接动词原形，第三人称不加s。","topic":"daily","cefr":"A1"},{"w":"hey","uk":"/heɪ/","p":"int.","zh":"嘿；喂；嗨","ex":{"en":"Hey, you left your umbrella beside the door!","zh":"喂，你把伞落在门边了！"},"tip":"适合熟人间打招呼；正式邮件避免使用。","topic":"daily","cefr":"A1"},{"w":"cola","uk":"/ˈkəʊlə/","p":"n.","zh":"可乐","ex":{"en":"He poured cold cola into a glass with ice.","zh":"他把冰可乐倒进一个放了冰块的玻璃杯。"},"tip":"泛指饮料时不可数；a cola可指一杯或一份可乐。","topic":"daily","cefr":"A1"},{"w":"shower","uk":"/ˈʃaʊə/","p":"n.","zh":"淋浴；淋浴器","ex":{"en":"I always take a warm shower after cycling home.","zh":"我骑车回家后总会洗个温水澡。"},"tip":"洗淋浴可用take或have a shower；阵雨也叫shower。","topic":"daily","cefr":"A1"},{"w":"tree","uk":"/triː/","p":"n.","zh":"树；树木","ex":{"en":"A small bird built its nest in our tree.","zh":"一只小鸟在我们家的树上筑了巢。"},"tip":"tree是树；wood可指木材，woods通常指树林。","topic":"nature","cefr":"A1"},{"w":"build","uk":"/bɪld/","p":"v.","zh":"建造；建立","ex":{"en":"We built a small wooden shelter in the garden.","zh":"我们在花园里搭了一个小木棚。"},"tip":"过去式和过去分词均为built；体格可用build。","topic":"city","cefr":"A1"},{"w":"man","uk":"/mæn/","p":"n.","zh":"成年男子；男人","ex":{"en":"A man in a blue coat held the door open.","zh":"一位穿蓝色外套的男子扶着门，让别人通过。"},"tip":"复数为men；泛指人类时现代写作更常用humankind。","topic":"society","cefr":"A1"},{"w":"early","uk":"/ˈɜːli/","p":"adj.","zh":"早期的；较早的","ex":{"en":"We caught an early train and arrived before breakfast.","zh":"我们赶上了一班早车，在早餐前就到了。"},"tip":"early兼作形容词和副词，不加-ly。","topic":"daily","cefr":"A1"},{"w":"these","uk":"/ðiːz/","p":"det.","zh":"这些","ex":{"en":"These strawberries smell lovely, so let's buy a basket.","zh":"这些草莓闻起来很香，我们买一篮吧。"},"tip":"these是this的复数，后接复数名词。","topic":"daily","cefr":"A1"},{"w":"favourite","uk":"/ˈfeɪvərɪt/","p":"adj.","zh":"最喜欢的","ex":{"en":"This little bakery sells my favourite kind of bread.","zh":"这家小面包店卖我最喜欢的那种面包。"},"tip":"英式拼写favourite，美式favorite；一般不用most修饰。","topic":"daily","cefr":"A1"},{"w":"adult","uk":"/ˈædʌlt/","p":"n.","zh":"成年人；成年动物","ex":{"en":"Children must visit the swimming pool with an adult.","zh":"儿童必须由成年人陪同前往游泳池。"},"tip":"既可作可数名词，也可作形容词，如adult education。","topic":"society","cefr":"A1"},{"w":"clock","uk":"/klɒk/","p":"n.","zh":"时钟","ex":{"en":"The kitchen clock stopped while we were making lunch.","zh":"我们做午饭时，厨房的时钟停了。"},"tip":"clock通常指钟；戴在手腕上的表叫watch。","topic":"daily","cefr":"A1"},{"w":"downstairs","uk":"/ˌdaʊnˈsteəz/","p":"adv.","zh":"在楼下；往楼下","ex":{"en":"I went downstairs when I smelled fresh bread.","zh":"闻到新鲜面包的香味后，我下了楼。"},"tip":"作副词时直接说go downstairs，不加to。","topic":"daily","cefr":"A1"},{"w":"information","uk":"/ˌɪnfəˈmeɪʃən/","p":"n.","zh":"信息；资料","ex":{"en":"The receptionist gave us useful information about local buses.","zh":"接待员向我们提供了有关当地公交车的实用信息。"},"tip":"不可数：说some information，不说an information。","topic":"media","cefr":"A1"},{"w":"blackboard","uk":"/ˈblækbɔːd/","p":"n.","zh":"黑板","ex":{"en":"Our teacher drew a huge circle on the blackboard.","zh":"老师在黑板上画了一个大圆圈。"},"tip":"在黑板上用on the blackboard；配合粉笔使用。","topic":"education","cefr":"A1"},{"w":"party","uk":"/ˈpɑːti/","p":"n.","zh":"聚会；派对","ex":{"en":"We held a small party in the garden yesterday.","zh":"昨天我们在花园里办了一场小聚会。"},"tip":"合同中的party指当事方，不是聚会或政党。","topic":"society","cefr":"A1"},{"w":"meal","uk":"/miːl/","p":"n.","zh":"一餐；一顿饭","ex":{"en":"Dad cooked a warm meal after our long walk.","zh":"我们长途步行回来后，爸爸做了一顿热乎乎的饭。"},"tip":"meal指一顿饭；food泛指食物，通常不可数。","topic":"daily","cefr":"A1"},{"w":"chair","uk":"/tʃeə/","p":"n.","zh":"椅子","ex":{"en":"She pulled a chair closer to the window.","zh":"她把一把椅子拉到离窗户更近的地方。"},"tip":"chair作动词直接接meeting，表示主持会议。","topic":"daily","cefr":"A1"},{"w":"never","uk":"/ˈnevə/","p":"adv.","zh":"从不；从未","ex":{"en":"I never leave home without my water bottle.","zh":"我出门从来都带着水瓶。"},"tip":"通常放在实义动词前，be动词或助动词后。","topic":"daily","cefr":"A1"},{"w":"middle","uk":"/ˈmɪdəl/","p":"n.","zh":"中间；中部","ex":{"en":"Someone left a suitcase in the middle of the hallway.","zh":"有人把一个行李箱放在了走廊正中央。"},"tip":"名词常用the middle of；形容词直接修饰名词。","topic":"daily","cefr":"A1"},{"w":"cool","uk":"/kuːl/","p":"adj.","zh":"凉的；凉爽的","ex":{"en":"A cool breeze drifted through the open kitchen window.","zh":"一阵凉爽的微风从敞开的厨房窗户吹了进来。"},"tip":"cool 比 cold 温和；口语中还可表示“很酷的”。","topic":"daily","cefr":"A1"},{"w":"easy","uk":"/ˈiːzi/","p":"adj.","zh":"容易的；不费力的","ex":{"en":"This soup is easy to make with fresh vegetables.","zh":"用新鲜蔬菜做这道汤很容易。"},"tip":"常用easy to do；修饰动作通常用easily。","topic":"daily","cefr":"A1"},{"w":"thing","uk":"/θɪŋ/","p":"n.","zh":"东西；物品","ex":{"en":"Could you move that heavy thing off my chair?","zh":"你能把那个沉东西从我的椅子上搬走吗？"},"tip":"thing很笼统；正式写作尽量换成具体名词。","topic":"daily","cefr":"A1"},{"w":"mouth","uk":"/maʊθ/ (n.); /maʊð/ (v.)","p":"n.","zh":"嘴；口腔","ex":{"en":"The dentist asked me to open my mouth wider.","zh":"牙医让我把嘴张大一点。"},"tip":"名词末音为/θ/；动词末音为/ð/。","topic":"health","cefr":"A1"},{"w":"study","uk":"/ˈstʌdi/","p":"v.","zh":"学习；研究","ex":{"en":"I study English on the bus every morning.","zh":"我每天早上在公交车上学英语。"},"tip":"study强调学习过程，learn常强调学会或获得知识。","topic":"education","cefr":"A1"},{"w":"anything","uk":"/ˈeniθɪŋ/","p":"pron.","zh":"任何事物","ex":{"en":"You can choose anything from this basket of toys.","zh":"你可以从这篮玩具里随便挑一件。"},"tip":"疑问句中常指“什么”；陈述句中可指“任何事物”。","topic":"daily","cefr":"A1"},{"w":"player","uk":"/ˈpleɪə/","p":"n.","zh":"运动员；比赛参加者","ex":{"en":"Each player shook hands before the football match began.","zh":"足球比赛开始前，每位球员都握了手。"},"tip":"乐器演奏者可用“乐器名＋player”，如piano player。","topic":"sport","cefr":"A1"},{"w":"forty","uk":"/ˈfɔːti/","p":"num.","zh":"四十","ex":{"en":"We waited forty minutes before the bus finally arrived.","zh":"我们等了四十分钟，公交车才终于到。"},"tip":"拼写是forty，不是fourty；四十多岁用in one's forties。","topic":"daily","cefr":"A1"},{"w":"chocolate","uk":"/ˈtʃɒklət/","p":"n.","zh":"巧克力","ex":{"en":"He shared a bar of chocolate with his sister.","zh":"他和妹妹分享了一块巧克力。"},"tip":"食材巧克力不可数；单颗巧克力糖可数。","topic":"daily","cefr":"A1"},{"w":"size","uk":"/saɪz/","p":"n.","zh":"大小；规模","ex":{"en":"This suitcase is just the right size for weekends.","zh":"这个行李箱的大小正适合周末出行。"},"tip":"问尺码用What size，不用How much size。","topic":"daily","cefr":"A1"},{"w":"small","uk":"/smɔːl/","p":"adj.","zh":"小的；少的","ex":{"en":"Our small kitchen has room for only two chairs.","zh":"我们的小厨房只能放下两把椅子。"},"tip":"数量少可说a small number of，不能说small people。","topic":"daily","cefr":"A1"},{"w":"sport","uk":"/spɔːt/","p":"n.","zh":"体育运动","ex":{"en":"Swimming is the only sport my sister really enjoys.","zh":"游泳是我姐姐唯一真正喜欢的运动。"},"tip":"泛指体育时英式常用sport，美式常用sports。","topic":"sport","cefr":"A1"},{"w":"exam","uk":"/ɪɡˈzæm/","p":"n.","zh":"考试；测验","ex":{"en":"I have a maths exam on Friday morning.","zh":"我周五上午有一场数学考试。"},"tip":"exam是examination的常用缩写；参加考试用take。","topic":"education","cefr":"A1"},{"w":"cow","uk":"/kaʊ/","p":"n.","zh":"母牛；奶牛","ex":{"en":"A brown cow stood quietly beside the farm gate.","zh":"一头棕色母牛静静地站在农场门旁。"},"tip":"cow指成年母牛；cattle统称牛，不能说a cattle。","topic":"nature","cefr":"A1"},{"w":"ball","uk":"/bɔːl/","p":"n.","zh":"球；球状物","ex":{"en":"The dog chased the ball across the grass.","zh":"那只狗追着球跑过草地。"},"tip":"球类运动前通常不用冠词，如play football。","topic":"sport","cefr":"A1"},{"w":"picnic","uk":"/ˈpɪknɪk/","p":"n.","zh":"野餐","ex":{"en":"We had a picnic under a shady tree.","zh":"我们在一棵树的荫凉下野餐。"},"tip":"动词过去式为picnicked，进行形式为picnicking。","topic":"daily","cefr":"A1"},{"w":"begin","uk":"/bɪˈɡɪn/","p":"v.","zh":"开始；着手","ex":{"en":"We begin dinner when everyone is sitting at the table.","zh":"大家都在餐桌旁坐好后，我们开始吃晚饭。"},"tip":"过去式began，过去分词begun；后接不定式或动名词。","topic":"daily","cefr":"A1"},{"w":"enough","uk":"/ɪˈnʌf/","p":"det.","zh":"足够的","ex":{"en":"We have enough rice to feed everyone tonight.","zh":"我们的米够今晚所有人吃。"},"tip":"修饰名词放前面，修饰形容词或副词放后面。","topic":"daily","cefr":"A1"},{"w":"class","uk":"/klɑːs/","p":"n.","zh":"班级；课","ex":{"en":"Our class is learning how to grow vegetables.","zh":"我们班正在学习如何种蔬菜。"},"tip":"in class通常指在上课；in the class指在这个班里。","topic":"education","cefr":"A1"},{"w":"few","uk":"/fjuː/","p":"det.","zh":"很少的；几个","ex":{"en":"There were few customers in the shop this morning.","zh":"今天上午店里的顾客很少。"},"tip":"few表几乎没有，a few表有几个；均接可数名词复数。","topic":"daily","cefr":"A1"},{"w":"country","uk":"/ˈkʌntri/","p":"n.","zh":"国家","ex":{"en":"She hopes to visit another country next summer.","zh":"她希望明年夏天去另一个国家旅行。"},"tip":"表示“乡下”常用 the country，与国家义区分。","topic":"government","cefr":"A1"},{"w":"understand","uk":"/ˌʌndəˈstænd/","p":"v.","zh":"理解；懂得","ex":{"en":"I finally understand how to use this washing machine.","zh":"我终于懂得怎么用这台洗衣机了。"},"tip":"过去式和过去分词均为understood。","topic":"thinking","cefr":"A1"},{"w":"die","uk":"/daɪ/","p":"v.","zh":"死亡；枯死","ex":{"en":"These plants will die if we forget to water them.","zh":"如果忘了浇水，这些植物就会枯死。"},"tip":"die是动词，dead是形容词，death是名词。","topic":"nature","cefr":"A1"},{"w":"with","uk":"/wɪð/","p":"prep.","zh":"和；与……一起","ex":{"en":"I cooked dinner with my sister last night.","zh":"昨晚我和姐姐一起做了晚饭。"},"tip":"with后接名词或代词宾格，如with me。","topic":"daily","cefr":"A1"},{"w":"plate","uk":"/pleɪt/","p":"n.","zh":"盘子；碟子","ex":{"en":"She placed a warm pancake on my plate.","zh":"她在我的盘子里放了一张热乎乎的薄煎饼。"},"tip":"plate通常指浅盘，bowl指较深的碗。","topic":"daily","cefr":"A1"},{"w":"together","uk":"/təˈɡeðə/","p":"adv.","zh":"一起；共同","ex":{"en":"We cooked dinner together and shared stories about our day.","zh":"我们一起做晚饭，分享各自一天的见闻。"},"tip":"together通常作副词：一起做某事用动词加together。","topic":"society","cefr":"A1"},{"w":"brown","uk":"/braʊn/","p":"adj.","zh":"棕色的；褐色的","ex":{"en":"A small brown dog was sleeping beside the door.","zh":"一只棕色的小狗正在门边睡觉。"},"tip":"brown作动词常用于烹饪，指把食物煎或烤至褐色。","topic":"daily","cefr":"A1"},{"w":"spend","uk":"/spend/","p":"v.","zh":"花费钱","ex":{"en":"We spent all our money on fresh fruit.","zh":"我们把钱全花在了新鲜水果上。"},"tip":"用spend时间doing或spend钱on；过去式spent。","topic":"economy","cefr":"A1"},{"w":"autumn","uk":"/ˈɔːtəm/","p":"n.","zh":"秋天；秋季","ex":{"en":"We collect fallen leaves in the park every autumn.","zh":"我们每年秋天都在公园里收集落叶。"},"tip":"字母n不发音；美式英语常用fall表示秋天。","topic":"nature","cefr":"A1"},{"w":"help","uk":"/help/","p":"v.","zh":"帮助；有助于","ex":{"en":"Could you help me carry these bags upstairs?","zh":"你能帮我把这些袋子提上楼吗？"},"tip":"help后接动词原形或to不定式均可。","topic":"daily","cefr":"A1"},{"w":"high","uk":"/haɪ/","p":"adj.","zh":"高的；高处的","ex":{"en":"The shelf is too high for me to reach.","zh":"架子太高了，我够不着。"},"tip":"high常指位置或程度；人的身高用tall。","topic":"daily","cefr":"A1"},{"w":"soup","uk":"/suːp/","p":"n.","zh":"汤；羹","ex":{"en":"She warmed her hands around a bowl of soup.","zh":"她双手捧着一碗汤取暖。"},"tip":"通常不可数；点餐时two soups可指两份汤。","topic":"daily","cefr":"A1"},{"w":"choose","uk":"/tʃuːz/","p":"v.","zh":"选择；挑选","ex":{"en":"You can choose a seat beside the window.","zh":"你可以选一个靠窗的座位。"},"tip":"过去式chose，过去分词chosen；后接to do。","topic":"thinking","cefr":"A1"},{"w":"movie","uk":"/ˈmuːvi/","p":"n.","zh":"电影","ex":{"en":"We watched a funny movie after dinner last night.","zh":"昨晚晚饭后，我们看了一部有趣的电影。"},"tip":"movie偏美式，英式常用film；the movies可指电影院。","topic":"arts","cefr":"A1"},{"w":"believe","uk":"/bɪˈliːv/","p":"v.","zh":"相信；信以为真","ex":{"en":"I believe you, but your story sounds quite unusual.","zh":"我相信你，但你讲的事情听起来很不寻常。"},"tip":"believe someone指相信其话；believe in someone指信任其能力。","topic":"thinking","cefr":"A1"},{"w":"train","uk":"/treɪn/","p":"n.","zh":"火车；列车","ex":{"en":"We caught the last train home after dinner.","zh":"晚饭后，我们赶上了回家的末班火车。"},"tip":"交通方式用by train；在某列火车上用on the train。","topic":"travel","cefr":"A1"},{"w":"paper","uk":"/ˈpeɪpə/","p":"n.","zh":"纸；纸张","ex":{"en":"She wrapped the small gift in bright yellow paper.","zh":"她用鲜黄色的纸把小礼物包了起来。"},"tip":"纸不可数，用a piece of paper；论文、报纸可数。","topic":"education","cefr":"A1"},{"w":"if","uk":"/ɪf/","p":"conj.","zh":"如果；假如","ex":{"en":"If it rains, we can play indoors instead.","zh":"如果下雨，我们可以改在室内玩。"},"tip":"谈未来条件时，if从句通常用一般现在时。","topic":"thinking","cefr":"A1"},{"w":"big","uk":"/bɪɡ/","p":"adj.","zh":"大的；大量的","ex":{"en":"We need a big bag for all these towels.","zh":"我们需要一个大袋子来装所有这些毛巾。"},"tip":"big较口语；正式写作可按语境用large或major。","topic":"daily","cefr":"A1"},{"w":"hand","uk":"/hænd/","p":"n.","zh":"手","ex":{"en":"She held the warm cup in her left hand.","zh":"她用左手握着温热的杯子。"},"tip":"give someone a hand表示帮忙；by hand表示手工。","topic":"daily","cefr":"A1"},{"w":"yellow","uk":"/ˈjeləʊ/","p":"adj.","zh":"黄色的","ex":{"en":"She picked a yellow umbrella for the rainy walk.","zh":"她挑了一把黄色雨伞，准备在雨中散步。"},"tip":"可作动词表示变黄；不要用它描述人的种族。","topic":"daily","cefr":"A1"},{"w":"rich","uk":"/rɪtʃ/","p":"adj.","zh":"富有的；富裕的","ex":{"en":"Their rich uncle owns a large house by the sea.","zh":"他们富有的叔叔在海边拥有一栋大房子。"},"tip":"“富含……”用 rich in，不用 rich of。","topic":"economy","cefr":"A1"},{"w":"know","uk":"/nəʊ/","p":"v.","zh":"知道；懂得","ex":{"en":"Do you know how to fix this bicycle?","zh":"你知道怎么修这辆自行车吗？"},"tip":"过去式knew，过去分词known；通常不用进行时。","topic":"thinking","cefr":"A1"},{"w":"cousin","uk":"/ˈkʌzən/","p":"n.","zh":"堂兄弟姐妹；表兄弟姐妹","ex":{"en":"My cousin taught me to ride a bicycle yesterday.","zh":"我的表姐昨天教我骑自行车。"},"tip":"不区分堂表、性别或长幼；需要时另加说明。","topic":"society","cefr":"A1"},{"w":"cafe","uk":"/ˈkæfeɪ/","p":"n.","zh":"咖啡馆；小餐馆","ex":{"en":"We shared a sandwich at the cafe beside the station.","zh":"我们在车站旁的小餐馆分着吃了一份三明治。"},"tip":"也写作café；通常提供饮料和简餐。","topic":"daily","cefr":"A1"},{"w":"live","uk":"/lɪv/, /laɪv/","p":"v.","zh":"居住；生活；活着","ex":{"en":"My grandparents live in a quiet village near the coast.","zh":"我的祖父母住在海边一个安静的村庄里。"},"tip":"动词读/lɪv/；形容词及表示现场直播的副词读/laɪv/。","topic":"daily","cefr":"A1"},{"w":"her","uk":"/hə(r)/","p":"pron.","zh":"她（宾格）","ex":{"en":"I called her after lunch to arrange a walk.","zh":"午饭后我给她打了电话，约好一起散步。"},"tip":"her可作宾语或接名词表所属；hers独立使用。","topic":"daily","cefr":"A1"},{"w":"quick","uk":"/kwɪk/","p":"adj.","zh":"迅速的；敏捷的","ex":{"en":"Her quick reaction stopped the glass from falling.","zh":"她反应敏捷，及时接住了差点掉落的玻璃杯。"},"tip":"正式表达中用副词quickly修饰动作。","topic":"daily","cefr":"A1"},{"w":"bag","uk":"/bæɡ/","p":"n.","zh":"包；袋","ex":{"en":"She put the apples in a reusable bag.","zh":"她把苹果放进了一个可重复使用的袋子里。"},"tip":"a bag of后接所装物品，如a bag of rice。","topic":"daily","cefr":"A1"},{"w":"tennis","uk":"/ˈtenɪs/","p":"n.","zh":"网球运动","ex":{"en":"We play tennis at the park on Sundays.","zh":"我们每逢周日都在公园打网球。"},"tip":"说 play tennis，不加冠词；球拍用 racket。","topic":"sport","cefr":"A1"},{"w":"cat","uk":"/kæt/","p":"n.","zh":"猫","ex":{"en":"Our cat sleeps in a sunny spot by the window.","zh":"我们家的猫睡在窗边阳光照得到的地方。"},"tip":"big cats指狮、虎等大型猫科动物。","topic":"nature","cefr":"A1"},{"w":"place","uk":"/pleɪs/","p":"n.","zh":"地方；地点","ex":{"en":"This shady spot is a lovely place for a picnic.","zh":"这处阴凉的地方很适合野餐。"},"tip":"take place表示发生或举行，不用被动语态。","topic":"daily","cefr":"A1"},{"w":"dress","uk":"/dres/","p":"n.","zh":"连衣裙","ex":{"en":"She wore a blue dress to her sister's party.","zh":"她穿了一条蓝色连衣裙去参加姐姐的聚会。"},"tip":"a dress指连衣裙；get dressed指穿好衣服。","topic":"daily","cefr":"A1"},{"w":"mouse","uk":"/maʊs/","p":"n.","zh":"老鼠","ex":{"en":"A tiny mouse slipped behind the cupboard before breakfast.","zh":"早饭前，一只小老鼠溜到了橱柜后面。"},"tip":"老鼠的复数是mice；鼠标的复数可用mice或mouses。","topic":"nature","cefr":"A1"},{"w":"car","uk":"/kɑː/","p":"n.","zh":"汽车；轿车","ex":{"en":"Our car is parked under the tree outside.","zh":"我们的汽车停在外面的树下。"},"tip":"by car不加冠词；in a car需要冠词。","topic":"travel","cefr":"A1"},{"w":"breakfast","uk":"/ˈbrekfəst/","p":"n.","zh":"早餐；早饭","ex":{"en":"I usually have breakfast before taking the bus.","zh":"我通常吃完早餐再去坐公交车。"},"tip":"泛指吃早餐用have breakfast，不加冠词。","topic":"daily","cefr":"A1"},{"w":"spell","uk":"/spel/","p":"v.","zh":"拼写","ex":{"en":"Could you spell your surname slowly for me, please?","zh":"请你把姓氏慢慢拼给我听，好吗？"},"tip":"过去式及过去分词英式可用spelt或spelled。","topic":"education","cefr":"A1"},{"w":"catch","uk":"/kætʃ/","p":"v.","zh":"接住；抓住","ex":{"en":"Can you catch the ball with just one hand?","zh":"你能只用一只手接住球吗？"},"tip":"过去式和过去分词均为caught；感冒用catch a cold。","topic":"daily","cefr":"A1"},{"w":"love","uk":"/lʌv/","p":"v.","zh":"爱；热爱；非常喜欢","ex":{"en":"I love walking by the river after dinner.","zh":"我很喜欢晚饭后沿着河边散步。"},"tip":"love doing和love to do均可表示喜欢做某事。","topic":"emotion","cefr":"A1"},{"w":"four","uk":"/fɔː/","p":"num.","zh":"四；四个","ex":{"en":"We put four chairs around the kitchen table.","zh":"我们在厨房桌子周围放了四把椅子。"},"tip":"four是基数词；表示顺序“第四”用fourth。","topic":"daily","cefr":"A1"},{"w":"show","uk":"/ʃəʊ/","p":"v.","zh":"展示；给……看","ex":{"en":"Please show me how to fold this paper bird.","zh":"请教我怎么折这只纸鸟。"},"tip":"过去式showed，过去分词通常用shown。","topic":"daily","cefr":"A1"},{"w":"above","uk":"/əˈbʌv/","p":"prep.","zh":"在……上方","ex":{"en":"A small wooden shelf hangs above the kitchen sink.","zh":"厨房水槽上方挂着一个小木架。"},"tip":"above 表示位置更高，不一定正上方，也不表示接触。","topic":"daily","cefr":"A1"},{"w":"beginner","uk":"/bɪˈɡɪnə/","p":"n.","zh":"初学者；新手","ex":{"en":"This swimming class is perfect for a complete beginner.","zh":"这堂游泳课非常适合完全没有基础的初学者。"},"tip":"beginner是可数名词，单数前通常要有限定词。","topic":"education","cefr":"A1"},{"w":"cry","uk":"/kraɪ/","p":"v.","zh":"哭；流泪","ex":{"en":"The baby began to cry when her toy fell.","zh":"玩具掉了，宝宝就哭了起来。"},"tip":"过去式cried；现在分词crying；表示喊叫常用cry out。","topic":"emotion","cefr":"A1"},{"w":"buy","uk":"/baɪ/","p":"v.","zh":"购买","ex":{"en":"I need to buy some bread before breakfast.","zh":"我需要在吃早饭前买些面包。"},"tip":"过去式和过去分词均为bought；不要写成buyed。","topic":"daily","cefr":"A1"},{"w":"short","uk":"/ʃɔːt/","p":"adj.","zh":"短的；短暂的；矮的","ex":{"en":"We took a short walk before dinner tonight.","zh":"今晚晚饭前，我们散了一小会儿步。"},"tip":"short of表示缺少；shortly通常意为“不久”。","topic":"daily","cefr":"A1"},{"w":"sentence","uk":"/ˈsentəns/","p":"n.","zh":"句子","ex":{"en":"Our teacher asked us to write one sentence about autumn.","zh":"老师让我们写一个关于秋天的句子。"},"tip":"判某人某种刑罚用sentence sb to sth。","topic":"education","cefr":"A1"},{"w":"wear","uk":"/weə/","p":"v.","zh":"穿；戴","ex":{"en":"I always wear thick socks when the floor feels cold.","zh":"地板凉的时候，我总会穿上厚袜子。"},"tip":"wear强调穿戴状态，put on强调动作；过去式wore。","topic":"daily","cefr":"A1"},{"w":"day","uk":"/deɪ/","p":"n.","zh":"一天；一日","ex":{"en":"We spent the whole day building sandcastles on the beach.","zh":"我们一整天都在海滩上堆沙堡。"},"tip":"every day意为每天；everyday是形容词，意为日常的。","topic":"daily","cefr":"A1"},{"w":"homework","uk":"/ˈhəʊmwɜːk/","p":"n.","zh":"家庭作业","ex":{"en":"I finished my homework before dinner and went outside.","zh":"我在晚饭前做完了作业，然后出门了。"},"tip":"不可数名词；一项作业用a piece of homework。","topic":"education","cefr":"A1"},{"w":"better","uk":"/ˈbetə/","p":"adj.","zh":"更好的；更合适的","ex":{"en":"This backpack is better than my old one.","zh":"这个背包比我原来的那个好。"},"tip":"是good和well的比较级，不说more better。","topic":"daily","cefr":"A1"},{"w":"into","uk":"/ˈɪntə/","p":"prep.","zh":"进入；到……里面","ex":{"en":"The kitten jumped into the basket beside my chair.","zh":"小猫跳进了我椅子旁的篮子里。"},"tip":"into强调进入的过程；in通常表示在里面。","topic":"daily","cefr":"A1"},{"w":"bicycle","uk":"/ˈbaɪsɪkəl/","p":"n.","zh":"自行车","ex":{"en":"I locked my bicycle outside the small bakery.","zh":"我把自行车锁在那家小面包店外面。"},"tip":"by bicycle不加冠词；ride a bicycle要加冠词。","topic":"travel","cefr":"A1"},{"w":"visit","uk":"/ˈvɪzɪt/","p":"v.","zh":"拜访；参观；游览","ex":{"en":"We visited our neighbours and shared some homemade soup.","zh":"我们去拜访邻居，和他们分享了一些自制的汤。"},"tip":"动词visit后直接接宾语；名词用a visit to。","topic":"travel","cefr":"A1"},{"w":"everyone","uk":"/ˈevriwʌn/","p":"pron.","zh":"每个人；所有人","ex":{"en":"Everyone brought a dish to share at the picnic.","zh":"每个人都带了一道菜，在野餐时一起分享。"},"tip":"everyone接单数谓语；every one强调逐个。","topic":"society","cefr":"A1"},{"w":"wrong","uk":"/rɒŋ/","p":"adj.","zh":"错误的；不合适的","ex":{"en":"I took the wrong bus and ended up near the airport.","zh":"我坐错了公交车，结果到了机场附近。"},"tip":"go wrong表示出问题；wrong的词首w不发音。","topic":"daily","cefr":"A1"},{"w":"problem","uk":"/ˈprɒbləm/","p":"n.","zh":"问题；困难","ex":{"en":"There's a problem with the kitchen tap: it keeps dripping.","zh":"厨房的水龙头有问题：它一直滴水。"},"tip":"……有问题用a problem with；问题的解决办法用to。","topic":"daily","cefr":"A1"},{"w":"uncle","uk":"/ˈʌŋkəl/","p":"n.","zh":"叔伯；舅舅；姑姨父","ex":{"en":"My uncle taught me how to mend a bicycle.","zh":"我叔叔教过我怎样修自行车。"},"tip":"uncle不区分父母哪一方，也不区分长幼。","topic":"daily","cefr":"A1"},{"w":"key","uk":"/kiː/","p":"n.","zh":"钥匙","ex":{"en":"I left my house key in my coat pocket.","zh":"我把家门钥匙放在外套口袋里了。"},"tip":"the key to中to是介词，后接名词或动名词。","topic":"daily","cefr":"A1"},{"w":"speak","uk":"/spiːk/","p":"v.","zh":"说话；交谈","ex":{"en":"Could I speak to you after the lesson?","zh":"下课后我能和你谈谈吗？"},"tip":"过去式spoke，过去分词spoken；语言前不用介词。","topic":"daily","cefr":"A1"},{"w":"read","uk":"/riːd/","p":"v.","zh":"阅读；读懂","ex":{"en":"I read a few pages before bed every night.","zh":"我每天晚上睡前都会读几页书。"},"tip":"原形读/riːd/；过去式及过去分词读/red/。","topic":"education","cefr":"A1"},{"w":"email","uk":"/ˈiːmeɪl/","p":"n.","zh":"电子邮件；电子邮件通信","ex":{"en":"Please email me the photos from our camping trip.","zh":"请把我们露营旅行的照片通过电子邮件发给我。"},"tip":"指一封邮件时可数；指通信方式时不可数，如by email。","topic":"technology","cefr":"A1"},{"w":"test","uk":"/test/","p":"n.","zh":"测验；测试；检查","ex":{"en":"I have a spelling test at school tomorrow.","zh":"我明天在学校有拼写测验。"},"tip":"参加测验用take a test；通过测验用pass a test。","topic":"education","cefr":"A1"},{"w":"zero","uk":"/ˈzɪərəʊ/","p":"num.","zh":"零","ex":{"en":"The temperature fell below zero while we were sleeping.","zh":"我们睡觉时，气温降到了零度以下。"},"tip":"读电话号码时零也常读作oh；温度用zero。","topic":"science","cefr":"A1"},{"w":"again","uk":"/əˈɡen/","p":"adv.","zh":"再一次；又","ex":{"en":"Could you say that again a little more slowly?","zh":"你能再说一遍，稍微慢一点吗？"},"tip":"again表示重复；again and again强调反复多次。","topic":"daily","cefr":"A1"},{"w":"hello","uk":"/həˈləʊ/","p":"int.","zh":"你好；喂","ex":{"en":"Hello, would you like to sit next to me?","zh":"你好，你愿意坐在我旁边吗？"},"tip":"电话开头的hello可译为“喂”；say hello to表示向某人问好。","topic":"daily","cefr":"A1"},{"w":"people","uk":"/ˈpiːpəl/","p":"n.","zh":"人；人们","ex":{"en":"Several people were waiting outside the bakery this morning.","zh":"今天早晨，有几个人在面包店外等候。"},"tip":"表示人们时用people；peoples指多个民族。","topic":"society","cefr":"A1"},{"w":"monkey","uk":"/ˈmʌŋki/","p":"n.","zh":"猴子","ex":{"en":"A little monkey swung between branches above our heads.","zh":"一只小猴子在我们头顶的树枝间荡来荡去。"},"tip":"monkey通常有尾巴；ape指猿类，通常无尾。","topic":"nature","cefr":"A1"},{"w":"sit","uk":"/sɪt/","p":"v.","zh":"坐；坐下","ex":{"en":"Come and sit beside me on the garden bench.","zh":"过来坐在花园长椅上，坐我旁边。"},"tip":"过去式和过去分词均为sat；现在分词为sitting。","topic":"daily","cefr":"A1"},{"w":"seat","uk":"/siːt/","p":"n.","zh":"座位","ex":{"en":"She saved me a seat near the front.","zh":"她在靠前的位置给我留了一个座位。"},"tip":"sit是不及物动词；seat常接人，be seated表就座。","topic":"daily","cefr":"A1"},{"w":"cup","uk":"/kʌp/","p":"n.","zh":"杯子；一杯的量","ex":{"en":"I warmed my hands around a cup of tea.","zh":"我双手捧着一杯茶取暖。"},"tip":"a cup of后接饮品；cup作动词可表示用手捧住。","topic":"daily","cefr":"A1"},{"w":"film","uk":"/fɪlm/","p":"n.","zh":"电影","ex":{"en":"We watched a funny film after dinner yesterday.","zh":"昨天晚饭后，我们看了一部有趣的电影。"},"tip":"表示电影时，film偏英式，movie偏美式。","topic":"arts","cefr":"A1"},{"w":"else","uk":"/els/","p":"adv.","zh":"其他；另外","ex":{"en":"Would you like anything else with your soup?","zh":"除了汤，你还想要点别的吗？"},"tip":"放在不定代词或疑问词后，如someone else。","topic":"daily","cefr":"A1"},{"w":"in","uk":"/ɪn/","p":"prep.","zh":"在……里面；在……中","ex":{"en":"Your keys are in the bowl beside the door.","zh":"你的钥匙在门边的碗里。"},"tip":"in two days常指两天后；月份、年份前也用in。","topic":"daily","cefr":"A1"},{"w":"top","uk":"/tɒp/","p":"n.","zh":"顶部；顶端","ex":{"en":"She placed the star on top of the tree.","zh":"她把那颗星星放在树顶上。"},"tip":"on top of指在上面；at the top of指在顶端。","topic":"daily","cefr":"A1"},{"w":"purple","uk":"/ˈpɜːpəl/","p":"adj.","zh":"紫色的","ex":{"en":"He wore a purple scarf with his grey coat.","zh":"他穿着灰色外套，围了一条紫色围巾。"},"tip":"purple可作形容词或名词；purplish表示“略带紫色的”。","topic":"daily","cefr":"A1"},{"w":"bottle","uk":"/ˈbɒtl/","p":"n.","zh":"瓶子；一瓶的量","ex":{"en":"She filled her water bottle before leaving the house.","zh":"她出门前把水瓶装满了。"},"tip":"a bottle of water是一瓶水；water bottle是水瓶。","topic":"daily","cefr":"A1"},{"w":"turn","uk":"/tɜːn/","p":"v.","zh":"转动；转向","ex":{"en":"Turn the handle gently and pull the door towards you.","zh":"轻轻转动把手，然后朝自己这边拉门。"},"tip":"表示变得时，turn后接形容词；turn into后接名词。","topic":"daily","cefr":"A1"},{"w":"piece","uk":"/piːs/","p":"n.","zh":"块；片；件","ex":{"en":"She saved the last piece of cake for her brother.","zh":"她把最后一块蛋糕留给了弟弟。"},"tip":"a piece of可量化advice等不可数名词。","topic":"daily","cefr":"A1"},{"w":"pink","uk":"/pɪŋk/","p":"adj.","zh":"粉红色的","ex":{"en":"The tree outside our window has pink flowers.","zh":"我们窗外的树开着粉红色的花。"},"tip":"pink既可作形容词，也可作名词表示粉红色。","topic":"daily","cefr":"A1"},{"w":"lesson","uk":"/ˈlesən/","p":"n.","zh":"课；一节课","ex":{"en":"Our swimming lesson starts after school on Thursday.","zh":"我们的游泳课在周四放学后开始。"},"tip":"learn a lesson常指吸取教训，不只是学习课程。","topic":"education","cefr":"A1"},{"w":"garden","uk":"/ˈɡɑːdən/","p":"n.","zh":"花园；菜园","ex":{"en":"We picked fresh beans from the garden before lunch.","zh":"午饭前，我们从菜园里摘了新鲜的豆角。"},"tip":"英式garden可指住宅庭院；美式常用yard。","topic":"daily","cefr":"A1"},{"w":"geography","uk":"/dʒiˈɒɡrəfi/","p":"n.","zh":"地理学","ex":{"en":"In geography today, we learned how rivers shape valleys.","zh":"今天的地理课上，我们学习了河流如何塑造河谷。"},"tip":"geography是地理学；geology是地质学。","topic":"education","cefr":"A1"},{"w":"salt","uk":"/sɔːlt/","p":"n.","zh":"盐；食盐","ex":{"en":"Please pass the salt before the soup gets cold.","zh":"趁汤还没凉，请把盐递过来。"},"tip":"食盐通常不可数；“一小撮盐”用a pinch of salt。","topic":"health","cefr":"A1"},{"w":"until","uk":"/ənˈtɪl/","p":"prep.","zh":"直到……为止","ex":{"en":"We waited outside until the rain finally stopped.","zh":"我们在外面一直等到雨终于停了。"},"tip":"until强调持续到某时；by强调不迟于某时。","topic":"daily","cefr":"A1"},{"w":"each","uk":"/iːtʃ/","p":"det.","zh":"每个；各个","ex":{"en":"Each child carried a small basket into the garden.","zh":"每个孩子都提着一个小篮子走进花园。"},"tip":"each后接单数名词；each of后接复数名词或代词。","topic":"daily","cefr":"A1"},{"w":"women","uk":"/ˈwɪmɪn/","p":"n.","zh":"成年女性（复数）","ex":{"en":"Three women were planting flowers in the shared garden.","zh":"三位女性正在公共花园里种花。"},"tip":"woman的复数；首音节读/wɪ/，不是/wʊ/。","topic":"society","cefr":"A1"},{"w":"feeling","uk":"/ˈfiːlɪŋ/","p":"n.","zh":"情绪；感受","ex":{"en":"A feeling of relief washed over me after the exam.","zh":"考试结束后，我顿时感到如释重负。"},"tip":"feelings常指感情；have a feeling that表示直觉。","topic":"emotion","cefr":"A1"},{"w":"bath","uk":"/bɑːθ/","p":"n.","zh":"洗澡；泡澡","ex":{"en":"A warm bath helped me relax after the hike.","zh":"徒步之后，泡个温水澡让我放松了下来。"},"tip":"英式常说have a bath；美式常说take a bath。","topic":"daily","cefr":"A1"},{"w":"nine","uk":"/naɪn/","p":"num.","zh":"九","ex":{"en":"We packed nine apples for our picnic today.","zh":"我们为今天的野餐装了九个苹果。"},"tip":"nine是基数词；序数词第九写作ninth。","topic":"daily","cefr":"A1"},{"w":"twelve","uk":"/twelv/","p":"num.","zh":"十二","ex":{"en":"There are twelve fresh eggs in this carton.","zh":"这个蛋盒里有十二枚新鲜鸡蛋。"},"tip":"twelve是基数词；序数词twelfth拼写有变化。","topic":"daily","cefr":"A1"},{"w":"moment","uk":"/ˈməʊmənt/","p":"n.","zh":"片刻；一会儿","ex":{"en":"Wait a moment while I put my shoes on.","zh":"等一会儿，我穿上鞋就好。"},"tip":"at the moment指现在；in a moment指马上。","topic":"daily","cefr":"A1"},{"w":"want","uk":"/wɒnt/","p":"v.","zh":"想要；希望","ex":{"en":"I want to grow tomatoes on our balcony.","zh":"我想在我们的阳台上种番茄。"},"tip":"用want to do或want sb to do，不用want doing表想做。","topic":"daily","cefr":"A1"},{"w":"think","uk":"/θɪŋk/","p":"v.","zh":"认为；觉得","ex":{"en":"I think this soup needs a little more salt.","zh":"我觉得这汤需要再加一点盐。"},"tip":"过去式、过去分词均为thought；认为时通常不用进行时。","topic":"thinking","cefr":"A1"},{"w":"another","uk":"/əˈnʌðə/","p":"det.","zh":"又一；另一","ex":{"en":"This cup is cracked, so please bring me another.","zh":"这个杯子裂了，请再给我拿一个。"},"tip":"通常接单数名词；another two days表示再两天。","topic":"daily","cefr":"A1"},{"w":"building","uk":"/ˈbɪldɪŋ/","p":"n.","zh":"建筑物；楼房","ex":{"en":"Our apartment building has a garden on the roof.","zh":"我们住的公寓楼屋顶上有一个花园。"},"tip":"指建筑物时可数，指建造活动时通常不可数。","topic":"city","cefr":"A1"},{"w":"sunny","uk":"/ˈsʌni/","p":"adj.","zh":"阳光充足的；晴朗的","ex":{"en":"We ate breakfast on the sunny balcony this morning.","zh":"今天早上，我们在阳光充足的阳台上吃了早餐。"},"tip":"sunny强调阳光足，不一定表示气温高。","topic":"nature","cefr":"A1"},{"w":"swim","uk":"/swɪm/","p":"v.","zh":"游泳；游过","ex":{"en":"We swim in the indoor pool every Saturday morning.","zh":"我们每周六早上都在室内泳池游泳。"},"tip":"不规则变化：swim—swam—swum。","topic":"sport","cefr":"A1"},{"w":"science","uk":"/ˈsaɪəns/","p":"n.","zh":"科学；自然科学","ex":{"en":"We grew tiny crystals in our science class today.","zh":"今天的科学课上，我们培育了微小的晶体。"},"tip":"泛指科学通常不可数；指具体学科可用a science。","topic":"science","cefr":"A1"},{"w":"snow","uk":"/snəʊ/","p":"n.","zh":"雪；积雪","ex":{"en":"Fresh snow covered the garden when we woke up.","zh":"我们醒来时，新下的雪覆盖了花园。"},"tip":"snow作名词通常不可数；下雪用it snows。","topic":"nature","cefr":"A1"},{"w":"forget","uk":"/fəˈɡet/","p":"v.","zh":"忘记；记不起","ex":{"en":"I always forget where I put my reading glasses.","zh":"我总是忘记把老花镜放在哪里了。"},"tip":"forget to do忘记去做；forget doing忘记做过。","topic":"thinking","cefr":"A1"},{"w":"slowly","uk":"/ˈsləʊli/","p":"adv.","zh":"缓慢地；慢慢地","ex":{"en":"She slowly poured the hot soup into bowls.","zh":"她慢慢地把热汤倒进碗里。"},"tip":"slowly是副词，修饰动作；slow通常作形容词。","topic":"daily","cefr":"A1"},{"w":"flat","uk":"/flæt/","p":"n.","zh":"公寓；一套住房","ex":{"en":"We rent a small flat above a busy bakery.","zh":"我们在一家生意兴隆的面包店楼上租了一套小公寓。"},"tip":"“公寓”英式常用 flat，美式常用 apartment。","topic":"city","cefr":"A1"},{"w":"glasses","uk":"/ˈɡlɑːsɪz/","p":"n.","zh":"眼镜","ex":{"en":"I left my glasses beside the bed last night.","zh":"我昨晚把眼镜落在床边了。"},"tip":"指眼镜时用复数；一副眼镜用a pair of glasses。","topic":"daily","cefr":"A1"},{"w":"special","uk":"/ˈspeʃəl/","p":"adj.","zh":"特别的；特殊的","ex":{"en":"We saved this special cake for your birthday.","zh":"我们把这个特别的蛋糕留到了你生日时享用。"},"tip":"specially强调专门；especially常表示尤其。","topic":"daily","cefr":"A1"},{"w":"plant","uk":"/plɑːnt/","p":"n.","zh":"植物","ex":{"en":"This little plant needs more sunlight and less water.","zh":"这株小植物需要更多阳光和更少的水。"},"tip":"plant可指植物或工厂；作动词时常表示种植。","topic":"nature","cefr":"A1"},{"w":"meat","uk":"/miːt/","p":"n.","zh":"肉；食用肉类","ex":{"en":"We keep raw meat separate from vegetables in the fridge.","zh":"我们把生肉和蔬菜分开放在冰箱里。"},"tip":"泛指食用肉时不可数；meats指不同种类的肉。","topic":"daily","cefr":"A1"},{"w":"swimming","uk":"/ˈswɪmɪŋ/","p":"n.","zh":"游泳","ex":{"en":"We go swimming at the indoor pool every Saturday.","zh":"我们每周六都去室内泳池游泳。"},"tip":"表示运动时不可数；去游泳用go swimming。","topic":"sport","cefr":"A1"},{"w":"grass","uk":"/ɡrɑːs/","p":"n.","zh":"草；草地","ex":{"en":"We spread a blanket on the grass beside the river.","zh":"我们在河边的草地上铺了一条毯子。"},"tip":"通常不可数；一片草叶用a blade of grass。","topic":"nature","cefr":"A1"},{"w":"teach","uk":"/tiːtʃ/","p":"v.","zh":"教；教授；教导","ex":{"en":"My aunt taught me how to mend a shirt.","zh":"姑姑教会了我如何缝补衬衫。"},"tip":"过去式和过去分词均为taught；教某人做用teach sb to do。","topic":"education","cefr":"A1"},{"w":"carry","uk":"/ˈkæri/","p":"v.","zh":"拿；提；搬运","ex":{"en":"Could you carry this heavy bag upstairs for me?","zh":"你能帮我把这个沉重的袋子拿上楼吗？"},"tip":"carry强调携带或搬运；bring和take还体现方向。","topic":"daily","cefr":"A1"},{"w":"hair","uk":"/heə/","p":"n.","zh":"头发；毛发","ex":{"en":"She tied her hair back before making lunch.","zh":"她做午饭前把头发扎了起来。"},"tip":"整体头发不可数；一根头发用a hair。","topic":"daily","cefr":"A1"},{"w":"green","uk":"/ɡriːn/","p":"adj.","zh":"绿色的","ex":{"en":"She wore a green jacket to match her shoes.","zh":"她穿了一件绿色夹克来搭配鞋子。"},"tip":"除颜色外，green常表示环保；形容人还可指缺乏经验。","topic":"daily","cefr":"A1"},{"w":"call","uk":"/kɔːl/","p":"v.","zh":"打电话；呼叫","ex":{"en":"I'll call you when I get home tonight.","zh":"今晚到家后我会给你打电话。"},"tip":"call sb表示给某人打电话，不加to。","topic":"daily","cefr":"A1"},{"w":"cheese","uk":"/tʃiːz/","p":"n.","zh":"奶酪；干酪","ex":{"en":"I added some cheese to my warm vegetable sandwich.","zh":"我在热乎乎的蔬菜三明治里加了些奶酪。"},"tip":"通常不可数；一块奶酪用a piece of cheese。","topic":"daily","cefr":"A1"},{"w":"long","uk":"/lɒŋ/","p":"adj.","zh":"长的；长时间的","ex":{"en":"Her long scarf nearly touched the wet pavement.","zh":"她的长围巾差点碰到湿漉漉的人行道。"},"tip":"动词long后接for加名词，或to加动词原形。","topic":"daily","cefr":"A1"},{"w":"meeting","uk":"/ˈmiːtɪŋ/","p":"n.","zh":"会议","ex":{"en":"Our team meeting starts right after lunch today.","zh":"我们团队今天午饭后马上开会。"},"tip":"参加会议用attend a meeting；meeting也可指会面。","topic":"work","cefr":"A1"},{"w":"waiter","uk":"/ˈweɪtə/","p":"n.","zh":"餐厅服务员；男侍者","ex":{"en":"The waiter brought our soup and two warm rolls.","zh":"服务员端来了我们的汤和两个热乎乎的小面包。"},"tip":"waiter传统上指男服务员；server更不强调性别。","topic":"work","cefr":"A1"},{"w":"bank","uk":"/bæŋk/","p":"n.","zh":"银行","ex":{"en":"I went to the bank to open an account.","zh":"我去银行开了一个账户。"},"tip":"岸边用on the bank；银行里用at或in the bank。","topic":"economy","cefr":"A1"},{"w":"classroom","uk":"/ˈklɑːsruːm/","p":"n.","zh":"教室","ex":{"en":"Sunlight filled the classroom as we opened our books.","zh":"我们打开书本时，阳光洒满了教室。"},"tip":"in the classroom强调教室内；in class强调上课中。","topic":"education","cefr":"A1"},{"w":"plan","uk":"/plæn/","p":"n.","zh":"计划；方案","ex":{"en":"Our plan is to leave early and avoid traffic.","zh":"我们的计划是早点出发，避开拥堵。"},"tip":"plan to do表示打算做；过去式planned双写n。","topic":"thinking","cefr":"A1"},{"w":"funny","uk":"/ˈfʌni/","p":"adj.","zh":"滑稽的；好笑的","ex":{"en":"That funny story made everyone at the table laugh.","zh":"那个好笑的故事逗得桌边的人都笑了。"},"tip":"funny侧重好笑或奇怪；fun侧重令人愉快、有趣。","topic":"emotion","cefr":"A1"},{"w":"pay","uk":"/peɪ/","p":"v.","zh":"支付；付工资","ex":{"en":"Can I pay for these apples by card?","zh":"这些苹果可以刷卡付款吗？"},"tip":"pay for接所购物品；pay接账单或款额；过去式paid。","topic":"daily","cefr":"A1"},{"w":"old","uk":"/əʊld/","p":"adj.","zh":"年老的；古老的；旧的","ex":{"en":"Our old dog sleeps beside the warm kitchen stove.","zh":"我们家的老狗睡在温暖的厨房炉子旁。"},"tip":"an old friend通常指相识已久，不一定年纪大。","topic":"daily","cefr":"A1"},{"w":"mistake","uk":"/mɪˈsteɪk/","p":"n.","zh":"错误；失误","ex":{"en":"I took your umbrella by mistake this morning.","zh":"今天早上我误拿了你的伞。"},"tip":"说make a mistake，不说do；动词过去式为mistook。","topic":"thinking","cefr":"A1"},{"w":"repeat","uk":"/rɪˈpiːt/","p":"v.","zh":"重复；重说；重做","ex":{"en":"Could you repeat the address a little more slowly?","zh":"你能把地址再慢一点说一遍吗？"},"tip":"repeat已含“再次”之意，通常不必再加again。","topic":"education","cefr":"A1"},{"w":"welcome","uk":"/ˈwelkəm/","p":"v.","zh":"欢迎；欣然接受","ex":{"en":"Our neighbours came outside to welcome us home.","zh":"邻居们走到外面，欢迎我们回家。"},"tip":"be welcome to do表示可随意做；You're welcome用于回应感谢。","topic":"society","cefr":"A1"},{"w":"strawberry","uk":"/ˈstrɔːbəri/","p":"n.","zh":"草莓","ex":{"en":"I picked a ripe strawberry and put it in my basket.","zh":"我摘了一颗熟透的草莓，放进篮子里。"},"tip":"可数名词，复数为strawberries。","topic":"daily","cefr":"A1"},{"w":"sixteen","uk":"/ˌsɪkˈstiːn/","p":"num.","zh":"十六","ex":{"en":"We baked sixteen small cakes for the family picnic.","zh":"我们为家庭野餐烤了十六个小蛋糕。"},"tip":"注意与sixty（六十）区分，sixteen词尾有/n/。","topic":"daily","cefr":"A1"},{"w":"week","uk":"/wiːk/","p":"n.","zh":"周；星期","ex":{"en":"I borrowed this book from the library last week.","zh":"我上周从图书馆借了这本书。"},"tip":"last/next/this week前不加介词。","topic":"daily","cefr":"A1"},{"w":"seventeen","uk":"/ˌsevənˈtiːn/","p":"num.","zh":"十七","ex":{"en":"My sister is seventeen and loves playing volleyball.","zh":"我妹妹十七岁，喜欢打排球。"},"tip":"注意与seventy（七十）区分，词尾读清。","topic":"daily","cefr":"A1"},{"w":"new","uk":"/njuː/","p":"adj.","zh":"新的；新近出现的","ex":{"en":"Our new neighbours brought us a basket of apples.","zh":"我们的新邻居送来了一篮苹果。"},"tip":"be new to表示初次接触、不熟悉，to是介词。","topic":"daily","cefr":"A1"},{"w":"cooking","uk":"/ˈkʊkɪŋ/","p":"n.","zh":"烹饪；烹调","ex":{"en":"My brother does the cooking while I wash dishes.","zh":"我哥哥做饭，我洗碗。"},"tip":"cooking指烹饪活动；cook可指厨师，cooker指炊具。","topic":"daily","cefr":"A1"},{"w":"family","uk":"/ˈfæməli/","p":"n.","zh":"家庭；家人；亲属","ex":{"en":"My family gathers around the kitchen table every Sunday.","zh":"我的家人每周日都会围坐在厨房的餐桌旁。"},"tip":"family作整体用单数；英式英语强调成员时可用复数。","topic":"daily","cefr":"A1"},{"w":"example","uk":"/ɪɡˈzɑːmpl/","p":"n.","zh":"例子；实例","ex":{"en":"Could you give me an example of a healthy breakfast?","zh":"你能给我举一个健康早餐的例子吗？"},"tip":"for example用于举例；set an example意为树立榜样。","topic":"education","cefr":"A1"},{"w":"metre","uk":"/ˈmiːtə/","p":"n.","zh":"米；公尺","ex":{"en":"This shelf is just over a metre long.","zh":"这个架子长一米多一点。"},"tip":"长度单位英式写metre，美式写meter；复数metres。","topic":"science","cefr":"A1"},{"w":"hate","uk":"/heɪt/","p":"v.","zh":"憎恨；非常讨厌","ex":{"en":"I hate finding wet socks on the bathroom floor.","zh":"我特别讨厌在浴室地板上发现湿袜子。"},"tip":"hate后可接动名词或不定式，语气比dislike强。","topic":"emotion","cefr":"A1"},{"w":"sleep","uk":"/sliːp/","p":"v.","zh":"睡觉","ex":{"en":"Our cat likes to sleep beside the warm radiator.","zh":"我们的猫喜欢睡在温暖的暖气片旁边。"},"tip":"过去式和过去分词均为slept；入睡用fall asleep。","topic":"health","cefr":"A1"},{"w":"toothbrush","uk":"/ˈtuːθbrʌʃ/","p":"n.","zh":"牙刷","ex":{"en":"I packed my toothbrush in the side pocket.","zh":"我把牙刷装进了侧面的口袋。"},"tip":"复数是toothbrushes，不是teethbrushes。","topic":"health","cefr":"A1"},{"w":"table","uk":"/ˈteɪbəl/","p":"n.","zh":"桌子","ex":{"en":"We gathered around the table to share fresh bread.","zh":"我们围坐在桌边，一起吃新鲜面包。"},"tip":"set the table指摆餐具，不是摆放桌子。","topic":"daily","cefr":"A1"},{"w":"join","uk":"/dʒɔɪn/","p":"v.","zh":"加入；参加","ex":{"en":"Would you like to join us for lunch today?","zh":"你今天愿意和我们一起吃午饭吗？"},"tip":"join a club指加入组织；join in指参与活动。","topic":"society","cefr":"A1"},{"w":"useful","uk":"/ˈjuːsfəl/","p":"adj.","zh":"有用的；有帮助的","ex":{"en":"This little torch is useful when the power fails.","zh":"停电时，这个小手电筒很有用。"},"tip":"首音是辅音/j/，所以说a useful tool，不用an。","topic":"daily","cefr":"A1"},{"w":"like","uk":"/laɪk/","p":"v.","zh":"喜欢；喜爱","ex":{"en":"I like reading by the window on rainy afternoons.","zh":"我喜欢在下雨的午后坐在窗边读书。"},"tip":"would like to do 比 want to do 更礼貌。","topic":"daily","cefr":"A1"},{"w":"note","uk":"/nəʊt/","p":"n.","zh":"便条；笔记","ex":{"en":"I left a note beside your breakfast bowl.","zh":"我在你的早餐碗旁留了一张便条。"},"tip":"记笔记用take notes；note that后接完整句子。","topic":"education","cefr":"A1"},{"w":"fall","uk":"/fɔːl/","p":"v.","zh":"落下；跌倒；下降","ex":{"en":"Golden leaves fall onto the path outside our house.","zh":"金黄的叶子落在我们屋外的小路上。"},"tip":"过去式fell，过去分词fallen；秋天英式常用autumn。","topic":"daily","cefr":"A1"},{"w":"thirty","uk":"/ˈθɜːti/","p":"num.","zh":"三十","ex":{"en":"The soup needs another thirty minutes on the stove.","zh":"这锅汤还需要在炉子上再煮三十分钟。"},"tip":"thirty重音在前；thirteen重音通常在后。","topic":"daily","cefr":"A1"},{"w":"best","uk":"/best/","p":"adj.","zh":"最好的；最佳的","ex":{"en":"This bakery makes the best bread in our neighbourhood.","zh":"这家面包店做的面包是我们街区最好的。"},"tip":"best是good和well的最高级；形容词前通常加the。","topic":"daily","cefr":"A1"},{"w":"any","uk":"/ˈeni/","p":"det.","zh":"一些；任何一个","ex":{"en":"You can borrow any book from this shelf.","zh":"这个书架上的书，你想借哪本都可以。"},"tip":"疑问、否定句中常表“一些”；肯定句中常表“任何”。","topic":"daily","cefr":"A1"},{"w":"computer","uk":"/kəmˈpjuːtə/","p":"n.","zh":"计算机；电脑","ex":{"en":"My computer froze while I was editing holiday photos.","zh":"我编辑度假照片时，电脑卡住了。"},"tip":"在电脑上工作用work on a computer。","topic":"technology","cefr":"A1"},{"w":"shopping","uk":"/ˈʃɒpɪŋ/","p":"n.","zh":"购物","ex":{"en":"We usually do our shopping early on Saturday mornings.","zh":"我们通常在星期六一早去购物。"},"tip":"shopping作名词不可数；“去购物”用go shopping。","topic":"daily","cefr":"A1"},{"w":"alphabet","uk":"/ˈælfəbet/","p":"n.","zh":"字母表","ex":{"en":"My little sister learned the alphabet through a song.","zh":"我的小妹妹通过一首歌学会了字母表。"},"tip":"alphabet指整套字母；单个字母用letter。","topic":"education","cefr":"A1"},{"w":"address","uk":"/əˈdres/","p":"n.","zh":"地址；网址","ex":{"en":"Please send me your address before I post the parcel.","zh":"请在我寄包裹之前把你的地址发给我。"},"tip":"美音动词读/əˈdres/；address问题不等于已解决。","topic":"daily","cefr":"A1"},{"w":"win","uk":"/wɪn/","p":"v.","zh":"获胜；赢得","ex":{"en":"Our team won the match despite the heavy rain.","zh":"尽管下着大雨，我们队还是赢得了比赛。"},"tip":"过去式和过去分词均为won；赢比赛用win，击败人用beat。","topic":"sport","cefr":"A1"},{"w":"grow","uk":"/ɡrəʊ/","p":"v.","zh":"生长；增长；发展","ex":{"en":"We grow fresh herbs in pots beside the kitchen window.","zh":"我们在厨房窗边的花盆里种新鲜香草。"},"tip":"过去式grew，过去分词grown；表变得后接形容词。","topic":"nature","cefr":"A1"},{"w":"box","uk":"/bɒks/","p":"n.","zh":"盒子；箱子","ex":{"en":"The kitten fell asleep inside an empty cardboard box.","zh":"小猫在一个空纸箱里睡着了。"},"tip":"复数为boxes；a box of后接盒中物品。","topic":"daily","cefr":"A1"},{"w":"fun","uk":"/fʌn/","p":"n.","zh":"乐趣；快乐","ex":{"en":"We had so much fun building sandcastles together yesterday.","zh":"昨天我们一起堆沙堡，玩得特别开心。"},"tip":"fun作名词不可数；funny多指好笑的或奇怪的。","topic":"daily","cefr":"A1"},{"w":"beard","uk":"/bɪəd/","p":"n.","zh":"胡须；络腮胡子","ex":{"en":"He trimmed his beard before leaving for work.","zh":"他上班出门前修剪了胡须。"},"tip":"beard指下巴及两颊胡须；moustache指上唇胡须。","topic":"daily","cefr":"A1"},{"w":"wet","uk":"/wet/","p":"adj.","zh":"湿的；潮湿的","ex":{"en":"My socks got wet when I stepped in a puddle.","zh":"我踩进水坑，把袜子弄湿了。"},"tip":"damp指微湿；soaking wet表示湿透。","topic":"daily","cefr":"A1"},{"w":"money","uk":"/ˈmʌni/","p":"n.","zh":"钱；货币","ex":{"en":"I saved enough money to buy a new bicycle.","zh":"我攒够了买一辆新自行车的钱。"},"tip":"通常不可数：说much money，不说many money。","topic":"economy","cefr":"A1"},{"w":"agree","uk":"/əˈɡriː/","p":"v.","zh":"同意；赞成","ex":{"en":"I agree with you that this soup needs salt.","zh":"我同意你的看法，这汤需要加盐。"},"tip":"同意某人用with；商定某事用on；答应做用to do。","topic":"thinking","cefr":"A1"},{"w":"now","uk":"/naʊ/","p":"adv.","zh":"现在；如今","ex":{"en":"We live near the station now, so walking is easy.","zh":"我们现在住在车站附近，步行过去很方便。"},"tip":"now that引导原因从句，强调情况已发生变化。","topic":"daily","cefr":"A1"},{"w":"real","uk":"/rɪəl/","p":"adj.","zh":"真实的；实际存在的","ex":{"en":"I thought the bird was plastic, but it was real.","zh":"我以为那只鸟是塑料的，没想到是真的。"},"tip":"real修饰名词；表示“很、真正地”通常用really。","topic":"daily","cefr":"A1"},{"w":"someone","uk":"/ˈsʌmwʌn/","p":"pron.","zh":"某人；有人","ex":{"en":"Someone left a blue umbrella beside the front door.","zh":"有人把一把蓝色雨伞落在了前门旁边。"},"tip":"作主语时谓语用单数；后文可用they指代。","topic":"daily","cefr":"A1"},{"w":"hear","uk":"/hɪə/","p":"v.","zh":"听见；听到","ex":{"en":"I can hear birds singing outside my bedroom window.","zh":"我能听见卧室窗外的鸟鸣声。"},"tip":"hear强调听见；listen to强调主动听。过去式heard。","topic":"daily","cefr":"A1"},{"w":"please","uk":"/pliːz/","p":"adv.","zh":"请；劳驾","ex":{"en":"Could you please hold the door for me?","zh":"你能帮我扶一下门吗？"},"tip":"please是动词；感到满意用be pleased。","topic":"daily","cefr":"A1"},{"w":"hard","uk":"/hɑːd/","p":"adj.","zh":"坚硬的","ex":{"en":"This bread is too hard to bite into.","zh":"这块面包太硬了，咬不动。"},"tip":"hard可作副词“努力地”；hardly意为“几乎不”。","topic":"daily","cefr":"A1"},{"w":"terrible","uk":"/ˈterəbl/","p":"adj.","zh":"糟糕的；令人不快的","ex":{"en":"The soup tasted terrible, so I made a sandwich.","zh":"汤很难喝，于是我做了个三明治。"},"tip":"terrible是形容词；表示“非常”通常用terribly。","topic":"daily","cefr":"A1"},{"w":"feel","uk":"/fiːl/","p":"v.","zh":"感到；觉得","ex":{"en":"I feel much warmer with this soft blanket.","zh":"盖着这条柔软的毯子，我觉得暖和多了。"},"tip":"过去式和过去分词均为felt；feel后可直接接形容词。","topic":"emotion","cefr":"A1"},{"w":"toy","uk":"/tɔɪ/","p":"n.","zh":"玩具","ex":{"en":"The baby dropped her toy behind the sofa.","zh":"宝宝把她的玩具掉到了沙发后面。"},"tip":"动词常用toy with；toy with an idea指并不认真地考虑。","topic":"daily","cefr":"A1"},{"w":"so","uk":"/səʊ/","p":"adv.","zh":"这么；如此；非常","ex":{"en":"The soup was so hot that I had to wait.","zh":"汤太烫了，我只好等一会儿。"},"tip":"so修饰形容词或副词；such通常修饰名词短语。","topic":"daily","cefr":"A1"},{"w":"climb","uk":"/klaɪm/","p":"v.","zh":"攀登；爬","ex":{"en":"We climbed the hill before stopping for a picnic.","zh":"我们爬上山坡，然后停下来野餐。"},"tip":"词尾b不发音；climb a mountain不加介词。","topic":"sport","cefr":"A1"},{"w":"bird","uk":"/bɜːd/","p":"n.","zh":"鸟","ex":{"en":"A small bird built a nest above our window.","zh":"一只小鸟在我们窗户上方筑了巢。"},"tip":"鸟群用a flock of birds；bird本身是可数名词。","topic":"nature","cefr":"A1"},{"w":"game","uk":"/ɡeɪm/","p":"n.","zh":"游戏；比赛","ex":{"en":"We played a board game after dinner yesterday.","zh":"昨天晚饭后我们玩了一个桌游。"},"tip":"猎物义不可数；be game for表示愿意尝试。","topic":"sport","cefr":"A1"},{"w":"single","uk":"/ˈsɪŋɡəl/","p":"adj.","zh":"单个的；仅一个的","ex":{"en":"A single candle lit the room during the power cut.","zh":"停电时，房间里只有一支蜡烛照明。"},"tip":"单程票英式常说single ticket，美式用one-way ticket。","topic":"daily","cefr":"A1"},{"w":"park","uk":"/pɑːk/","p":"n.","zh":"公园","ex":{"en":"We shared a picnic under the trees in the park.","zh":"我们在公园的树下共进了野餐。"},"tip":"公园用park；英式英语中停车场用car park。","topic":"city","cefr":"A1"},{"w":"boy","uk":"/bɔɪ/","p":"n.","zh":"男孩","ex":{"en":"The boy carefully carried his puppy across the puddle.","zh":"那个男孩小心地抱着小狗跨过水坑。"},"tip":"通常指未成年男性；称成年男性为boy可能不礼貌。","topic":"daily","cefr":"A1"},{"w":"chicken","uk":"/ˈtʃɪkɪn/","p":"n.","zh":"鸡","ex":{"en":"The chickens scratched the soil beside our vegetable patch.","zh":"那些鸡在我们的菜地旁刨土。"},"tip":"指活鸡时可数，指鸡肉时不可数；小鸡常用chick。","topic":"daily","cefr":"A1"},{"w":"milk","uk":"/mɪlk/","p":"n.","zh":"奶；牛奶","ex":{"en":"I poured some cold milk over my cereal.","zh":"我往麦片上倒了些冷牛奶。"},"tip":"milk通常不可数；说a glass of milk，不说a milk。","topic":"daily","cefr":"A1"},{"w":"and","uk":"/ænd/","p":"conj.","zh":"和；并且","ex":{"en":"I bought fresh bread and cheese for our picnic.","zh":"我为我们的野餐买了新鲜面包和奶酪。"},"tip":"连接并列成分时注意结构一致；口语常弱读/ən/。","topic":"daily","cefr":"A1"},{"w":"most","uk":"/məʊst/","p":"det.","zh":"大多数的；最多的","ex":{"en":"Most shops here close before we finish work.","zh":"这里大多数商店在我们下班前就关门了。"},"tip":"泛指用most people；特指用most of the people。","topic":"daily","cefr":"A1"},{"w":"story","uk":"/ˈstɔːri/","p":"n.","zh":"故事；经历的叙述","ex":{"en":"Grandma told us a funny story about her childhood.","zh":"奶奶给我们讲了一个她童年的趣事。"},"tip":"楼层英式写storey，美式写story；高度不固定。","topic":"arts","cefr":"A1"},{"w":"other","uk":"/ˈʌðə/","p":"det.","zh":"其他的；另外的","ex":{"en":"This shoe fits, but where is the other one?","zh":"这只鞋合脚，但另一只在哪里？"},"tip":"other后接名词；others独立使用；两者中另一个用the other。","topic":"daily","cefr":"A1"},{"w":"apple","uk":"/ˈæpəl/","p":"n.","zh":"苹果","ex":{"en":"I packed an apple and a sandwich for lunch.","zh":"我装了一个苹果和一个三明治当午餐。"},"tip":"可数名词；“一个苹果”用an apple。","topic":"daily","cefr":"A1"},{"w":"air","uk":"/eə/","p":"n.","zh":"空气","ex":{"en":"I opened the window to let fresh air in.","zh":"我打开窗户，让新鲜空气进来。"},"tip":"表示空气时不可数；an air of表示“带有某种气质”。","topic":"environment","cefr":"A1"},{"w":"because","uk":"/bɪˈkɒz/","p":"conj.","zh":"因为；由于","ex":{"en":"I closed the window because the room felt cold.","zh":"我关上了窗户，因为房间里有点冷。"},"tip":"because 后接从句；because of 后接名词或动名词。","topic":"daily","cefr":"A1"},{"w":"team","uk":"/tiːm/","p":"n.","zh":"队；团队","ex":{"en":"Our team celebrated with pizza after winning the match.","zh":"我们队赢得比赛后，吃披萨庆祝了一番。"},"tip":"英式英语中team可接单数或复数谓语。","topic":"work","cefr":"A1"},{"w":"right","uk":"/raɪt/","p":"adj.","zh":"正确的；合适的","ex":{"en":"You picked the right key to open the door.","zh":"你选对了开门的钥匙。"},"tip":"表示权利用a right to；表示在右边用on the right。","topic":"daily","cefr":"A1"},{"w":"difficult","uk":"/ˈdɪfɪkəlt/","p":"adj.","zh":"困难的；费力的","ex":{"en":"This heavy suitcase is difficult to carry upstairs.","zh":"这个沉重的行李箱很难搬上楼。"},"tip":"常用find it difficult to do，勿把difficulty当形容词。","topic":"daily","cefr":"A1"},{"w":"pencil","uk":"/ˈpensl/","p":"n.","zh":"铅笔","ex":{"en":"She sharpened her pencil before sketching the sleeping cat.","zh":"她削好铅笔，开始画那只熟睡的猫。"},"tip":"用铅笔写说in pencil；pencil in指暂定安排。","topic":"education","cefr":"A1"},{"w":"somebody","uk":"/ˈsʌmbədi/","p":"pron.","zh":"某人；有人","ex":{"en":"Somebody left a blue umbrella beside the front door.","zh":"有人把一把蓝色雨伞落在了前门旁边。"},"tip":"作主语时谓语用单数；回指常用they。","topic":"daily","cefr":"A1"},{"w":"person","uk":"/ˈpɜːsən/","p":"n.","zh":"人；个人","ex":{"en":"Only one person was waiting outside the bakery.","zh":"只有一个人在面包店外等候。"},"tip":"普通复数用people；persons多见于正式法律语境。","topic":"society","cefr":"A1"},{"w":"street","uk":"/striːt/","p":"n.","zh":"街道","ex":{"en":"We crossed the street to reach the bakery.","zh":"我们穿过街道来到面包店。"},"tip":"street多指城镇中两旁有建筑的道路。","topic":"city","cefr":"A1"},{"w":"include","uk":"/ɪnˈkluːd/","p":"v.","zh":"包括；包含","ex":{"en":"Does the price include breakfast and a clean towel?","zh":"这个价格包含早餐和一条干净毛巾吗？"},"tip":"include常列出部分内容，不表示完整清单。","topic":"daily","cefr":"A1"},{"w":"radio","uk":"/ˈreɪdiəʊ/","p":"n.","zh":"收音机","ex":{"en":"Dad keeps a small radio on the kitchen shelf.","zh":"爸爸在厨房架子上放着一台小收音机。"},"tip":"听广播常说listen to the radio；在广播中用on the radio。","topic":"media","cefr":"A1"},{"w":"ice","uk":"/aɪs/","p":"n.","zh":"冰","ex":{"en":"She dropped a few cubes of ice into her juice.","zh":"她往果汁里放了几块冰。"},"tip":"ice指冰时通常不可数；一块冰用an ice cube。","topic":"nature","cefr":"A1"},{"w":"evening","uk":"/ˈiːvnɪŋ/","p":"n.","zh":"傍晚；晚上","ex":{"en":"We spent the evening cooking and listening to music.","zh":"我们做饭、听音乐，度过了这个晚上。"},"tip":"泛指晚上用in the evening；this evening前不加介词。","topic":"daily","cefr":"A1"},{"w":"everything","uk":"/ˈevriθɪŋ/","p":"pron.","zh":"一切；所有事物","ex":{"en":"Everything in my bag got wet during the storm.","zh":"暴风雨把我包里的东西全弄湿了。"},"tip":"作主语时谓语用单数：Everything is ready。","topic":"daily","cefr":"A1"},{"w":"west","uk":"/west/","p":"n.","zh":"西；西方；西部","ex":{"en":"Our kitchen window faces west, catching the evening sunshine.","zh":"我们厨房的窗户朝西，能照到傍晚的阳光。"},"tip":"方位一般小写；the West指西方国家时大写。","topic":"travel","cefr":"A1"},{"w":"brother","uk":"/ˈbrʌðə/","p":"n.","zh":"兄；弟","ex":{"en":"My younger brother borrowed my bicycle this morning.","zh":"我弟弟今天早上借用了我的自行车。"},"tip":"brother不区分兄弟；用older或younger说明长幼。","topic":"daily","cefr":"A1"},{"w":"mountain","uk":"/ˈmaʊntɪn/","p":"n.","zh":"山；高山","ex":{"en":"Snow covered the mountain even in the middle of summer.","zh":"即使在盛夏，那座山仍被白雪覆盖。"},"tip":"一座山用 mountain；山脉通常用 mountain range。","topic":"nature","cefr":"A1"},{"w":"than","uk":"/ðæn/","p":"prep.","zh":"比","ex":{"en":"My new backpack is lighter than my old one.","zh":"我的新背包比旧的轻。"},"tip":"than用于比较；then表示“然后”，注意拼写。","topic":"daily","cefr":"A1"},{"w":"warm","uk":"/wɔːm/","p":"adj.","zh":"温暖的；暖和的","ex":{"en":"This thick blanket keeps me warm on chilly evenings.","zh":"这条厚毯子让我在凉飕飕的夜晚保持暖和。"},"tip":"warm比hot温度低；warm to某人指渐渐喜欢对方。","topic":"daily","cefr":"A1"},{"w":"future","uk":"/ˈfjuːtʃə/","p":"n.","zh":"未来；前途","ex":{"en":"We talked about our future while walking home.","zh":"我们走路回家时聊了聊我们的未来。"},"tip":"in the future指将来；英式in future常指从今以后。","topic":"thinking","cefr":"A1"},{"w":"all","uk":"/ɔːl/","p":"det.","zh":"所有的；整个的","ex":{"en":"All the children brought fruit for the picnic.","zh":"所有孩子都带了水果来野餐。"},"tip":"all可接复数或不可数名词；every接单数可数名词。","topic":"daily","cefr":"A1"},{"w":"come","uk":"/kʌm/","p":"v.","zh":"来；来到","ex":{"en":"Come inside and warm your hands by the fire.","zh":"进来在火边暖暖手吧。"},"tip":"不规则变化：come–came–come；come from表示来自。","topic":"daily","cefr":"A1"},{"w":"eat","uk":"/iːt/","p":"v.","zh":"吃；进食","ex":{"en":"We usually eat breakfast together before leaving the house.","zh":"我们通常一起吃完早饭再出门。"},"tip":"不规则变化：eat—ate—eaten。","topic":"daily","cefr":"A1"},{"w":"carrot","uk":"/ˈkærət/","p":"n.","zh":"胡萝卜","ex":{"en":"She sliced a carrot and added it to the soup.","zh":"她把一根胡萝卜切片，放进汤里。"},"tip":"比喻奖励或诱因；carrot and stick指奖惩并用。","topic":"daily","cefr":"A1"},{"w":"near","uk":"/nɪə/","p":"prep.","zh":"在附近；接近","ex":{"en":"We found a quiet café near the station.","zh":"我们在车站附近找到了一家安静的咖啡馆。"},"tip":"near可直接接地点；nearly通常表示“几乎”。","topic":"daily","cefr":"A1"},{"w":"parent","uk":"/ˈpeərənt/","p":"n.","zh":"父亲或母亲","ex":{"en":"Each parent brought a snack for the school picnic.","zh":"每位家长都为学校野餐带了一份点心。"},"tip":"parent指父母中的一位；parents通常指父母双方。","topic":"society","cefr":"A1"},{"w":"famous","uk":"/ˈfeɪməs/","p":"adj.","zh":"著名的；出名的","ex":{"en":"This village is famous for its delicious apple pies.","zh":"这个村庄以美味的苹果派闻名。"},"tip":"famous for接出名的原因，famous as接身份。","topic":"society","cefr":"A1"},{"w":"just","uk":"/dʒʌst/","p":"adv.","zh":"仅仅；只是","ex":{"en":"I need just one more minute to finish packing.","zh":"我只需要再一分钟就能收拾好行李。"},"tip":"作副词可指仅仅、刚刚；作形容词指公正的。","topic":"daily","cefr":"A1"},{"w":"birthday","uk":"/ˈbɜːθdeɪ/","p":"n.","zh":"生日","ex":{"en":"My sister baked a lemon cake for my birthday.","zh":"姐姐为我的生日烤了一个柠檬蛋糕。"},"tip":"在某人生日当天用on，不用in或at。","topic":"daily","cefr":"A1"},{"w":"butter","uk":"/ˈbʌtə/","p":"n.","zh":"黄油","ex":{"en":"She spread some butter on a slice of warm bread.","zh":"她在一片温热的面包上抹了些黄油。"},"tip":"butter是黄油，cream是奶油；作食品名通常不可数。","topic":"daily","cefr":"A1"},{"w":"college","uk":"/ˈkɒlɪdʒ/","p":"n.","zh":"学院；高等专科学校","ex":{"en":"My cousin is studying nursing at a local college.","zh":"我表姐正在当地一所学院学习护理。"},"tip":"美式常泛指大学；英式多指学院或继续教育院校。","topic":"education","cefr":"A1"},{"w":"close","uk":"/kləʊz/, /kləʊs/","p":"v.","zh":"关上；关闭；结束","ex":{"en":"Please close the window before the rain comes in.","zh":"请在雨飘进来之前关上窗户。"},"tip":"动词读/z/；形容词和副词读/s/。","topic":"daily","cefr":"A1"},{"w":"off","uk":"/ɒf/","p":"adv.","zh":"离开；脱离","ex":{"en":"The dog ran off when the gate opened.","zh":"门一开，那只狗就跑走了。"},"tip":"off强调离开或关闭；of常表示所属，勿混淆。","topic":"daily","cefr":"A1"},{"w":"wait","uk":"/weɪt/","p":"v.","zh":"等待；等候","ex":{"en":"Please wait here while I find my keys.","zh":"请在这里等一下，我去找钥匙。"},"tip":"等人用wait for someone；等着做用wait to do。","topic":"daily","cefr":"A1"},{"w":"under","uk":"/ˈʌndə/","p":"prep.","zh":"在…下面","ex":{"en":"The cat curled up under the kitchen table.","zh":"猫蜷缩在厨房的桌子下面。"},"tip":"under可表位置、数量或状态：under pressure。","topic":"daily","cefr":"A1"},{"w":"on","uk":"/ɒn/","p":"prep.","zh":"在……上","ex":{"en":"Your keys are on the table beside the door.","zh":"你的钥匙在门旁的桌子上。"},"tip":"具体某天用on；月份用in；钟点用at。","topic":"daily","cefr":"A1"},{"w":"personal","uk":"/ˈpɜːsənəl/","p":"adj.","zh":"个人的；本人的","ex":{"en":"Please keep your personal belongings close while boarding the train.","zh":"上火车时，请将个人物品放在身边。"},"tip":"personal指个人的；personnel指全体员工，注意拼写。","topic":"daily","cefr":"A1"},{"w":"possible","uk":"/ˈpɒsəbl/","p":"adj.","zh":"可能的；可实现的","ex":{"en":"Is it possible to book a table for tonight?","zh":"可以预订今晚的餐桌吗？"},"tip":"常用it is possible to do；不说人is possible to do。","topic":"thinking","cefr":"A1"},{"w":"cent","uk":"/sent/","p":"n.","zh":"分（货币单位）","ex":{"en":"I found a cent under the sofa cushion.","zh":"我在沙发坐垫下面找到了一枚一分硬币。"},"tip":"cent是可数名词；金额超过一分通常用cents。","topic":"economy","cefr":"A1"},{"w":"describe","uk":"/dɪˈskraɪb/","p":"v.","zh":"描述；形容","ex":{"en":"Can you describe the bag you left on the bus?","zh":"你能描述一下你落在公交车上的包吗？"},"tip":"说describe something to someone，不说describe someone something。","topic":"education","cefr":"A1"},{"w":"say","uk":"/seɪ/","p":"v.","zh":"说；表达","ex":{"en":"Please say your name again so I can remember it.","zh":"请再说一遍你的名字，好让我记住。"},"tip":"说某事用say something；告诉某人用tell someone。","topic":"daily","cefr":"A1"},{"w":"lot","uk":"/lɒt/","p":"pron.","zh":"大量；许多","ex":{"en":"We bought a lot of fresh fruit today.","zh":"我们今天买了很多新鲜水果。"},"tip":"a lot of接可数复数或不可数名词；a lot可修饰动词。","topic":"daily","cefr":"A1"},{"w":"grandfather","uk":"/ˈɡrænfɑːðə/","p":"n.","zh":"祖父；外祖父","ex":{"en":"My grandfather taught me how to grow tomatoes.","zh":"我的祖父教过我如何种番茄。"},"tip":"不区分父系母系；外祖父可说maternal grandfather。","topic":"society","cefr":"A1"},{"w":"dear","uk":"/dɪə/","p":"adj.","zh":"亲爱的；珍爱的","ex":{"en":"This little garden is very dear to my grandmother.","zh":"祖母十分珍爱这座小花园。"},"tip":"dear表“贵”主要用于英式口语；称呼常用Dear。","topic":"emotion","cefr":"A1"},{"w":"sorry","uk":"/ˈsɒri/","p":"adj.","zh":"抱歉的；后悔的","ex":{"en":"I'm sorry I spilled juice on your clean shirt.","zh":"很抱歉，我把果汁洒在了你的干净衬衫上。"},"tip":"sorry for doing表示为所做之事道歉。","topic":"emotion","cefr":"A1"},{"w":"ear","uk":"/ɪə/","p":"n.","zh":"耳朵","ex":{"en":"My ears felt cold, so I pulled on a hat.","zh":"我的耳朵觉得冷，于是我戴上了帽子。"},"tip":"have an ear for表示善于辨听音乐、语言等。","topic":"health","cefr":"A1"},{"w":"healthy","uk":"/ˈhelθi/","p":"adj.","zh":"健康的","ex":{"en":"Our cat stays healthy with regular exercise and checkups.","zh":"我们家的猫通过经常运动和定期检查保持健康。"},"tip":"既可形容身体健康，也可形容饮食等有益健康。","topic":"health","cefr":"A1"},{"w":"laugh","uk":"/lɑːf/","p":"v.","zh":"笑；发笑","ex":{"en":"The baby's funny dance made everyone laugh at dinner.","zh":"宝宝滑稽的舞蹈让吃晚饭的每个人都笑了。"},"tip":"laugh at人常指嘲笑；laugh with人指一起笑。","topic":"emotion","cefr":"A1"},{"w":"find","uk":"/faɪnd/","p":"v.","zh":"找到；发现","ex":{"en":"I finally found my keys inside my coat pocket.","zh":"我终于在外套口袋里找到了钥匙。"},"tip":"过去式和过去分词均为found；find＋宾语＋形容词。","topic":"daily","cefr":"A1"},{"w":"sell","uk":"/sel/","p":"v.","zh":"卖；出售","ex":{"en":"They sell fresh bread at the market every Saturday.","zh":"他们每周六都在市场卖新鲜面包。"},"tip":"过去式和过去分词均为sold；sell well常用主动形式。","topic":"economy","cefr":"A1"},{"w":"walk","uk":"/wɔːk/","p":"v.","zh":"走；步行","ex":{"en":"We walk to the bakery every Sunday morning.","zh":"我们每个星期天早上都步行去面包店。"},"tip":"字母l不发音；walk the dog意为遛狗。","topic":"daily","cefr":"A1"},{"w":"as","uk":"/əz/","p":"prep.","zh":"作为；以……身份","ex":{"en":"She works as a guide at the local museum.","zh":"她在当地博物馆担任讲解员。"},"tip":"as表示实际身份；like表示相似。重读时读/æz/。","topic":"daily","cefr":"A1"},{"w":"run","uk":"/rʌn/","p":"v.","zh":"跑；奔跑","ex":{"en":"We ran through the park before breakfast today.","zh":"今天早饭前，我们跑步穿过了公园。"},"tip":"过去式ran，过去分词run；现在分词running。","topic":"daily","cefr":"A1"},{"w":"light","uk":"/laɪt/","p":"n.","zh":"光；光线；灯","ex":{"en":"Warm light came through the curtains into our bedroom.","zh":"温暖的光线透过窗帘照进了我们的卧室。"},"tip":"光线通常不可数；一盏灯用a light；动词过去式常用lit。","topic":"daily","cefr":"A1"},{"w":"look","uk":"/lʊk/","p":"v.","zh":"看；注视","ex":{"en":"Look at the tiny bird beside the window.","zh":"看窗边那只小鸟。"},"tip":"look at后接看的对象；look作系动词后接形容词。","topic":"daily","cefr":"A1"},{"w":"first","uk":"/fɜːst/","p":"num.","zh":"第一","ex":{"en":"This is my first visit to the seaside.","zh":"这是我第一次到海边来。"},"tip":"at first指起初；first可用于列举第一点。","topic":"daily","cefr":"A1"},{"w":"expensive","uk":"/ɪkˈspensɪv/","p":"adj.","zh":"昂贵的；花钱多的","ex":{"en":"These boots are too expensive for my budget.","zh":"这双靴子太贵，超出了我的预算。"},"tip":"物品贵用expensive，价格高用high。","topic":"economy","cefr":"A1"},{"w":"language","uk":"/ˈlæŋɡwɪdʒ/","p":"n.","zh":"语言","ex":{"en":"My neighbour teaches me a little of her language.","zh":"邻居教我一点她的语言。"},"tip":"指某种语言时可数；泛指语言能力时常不可数。","topic":"education","cefr":"A1"},{"w":"busy","uk":"/ˈbɪzi/","p":"adj.","zh":"忙碌的","ex":{"en":"I am busy making soup for dinner right now.","zh":"我现在正忙着做晚餐要喝的汤。"},"tip":"用busy doing或busy with，不用busy to do。","topic":"daily","cefr":"A1"},{"w":"write","uk":"/raɪt/","p":"v.","zh":"写；书写","ex":{"en":"Please write your address on this small card.","zh":"请把你的地址写在这张小卡片上。"},"tip":"不规则变化：write—wrote—written。","topic":"education","cefr":"A1"},{"w":"dog","uk":"/dɒɡ/","p":"n.","zh":"狗；犬","ex":{"en":"Our dog waits by the door every afternoon.","zh":"我们的狗每天下午都守在门边。"},"tip":"动词常见被动式be dogged by，表示长期受困扰。","topic":"nature","cefr":"A1"},{"w":"wine","uk":"/waɪn/","p":"n.","zh":"葡萄酒","ex":{"en":"The restaurant uses a little wine in this mushroom sauce.","zh":"这家餐馆在这款蘑菇酱里加了少量葡萄酒。"},"tip":"泛指葡萄酒时不可数；多种葡萄酒可用wines。","topic":"daily","cefr":"A1"},{"w":"talk","uk":"/tɔːk/","p":"v.","zh":"说话；交谈；谈论","ex":{"en":"We talked about our weekend plans over breakfast.","zh":"我们吃早饭时聊了聊周末的计划。"},"tip":"talk about接话题；talk to或with接人。","topic":"daily","cefr":"A1"},{"w":"office","uk":"/ˈɒfɪs/","p":"n.","zh":"办公室；办公楼","ex":{"en":"I left my umbrella under the desk at the office.","zh":"我把伞落在办公室的桌子下面了。"},"tip":"在办公室用in the office；任公职用in office。","topic":"work","cefr":"A1"},{"w":"pants","uk":"/pænts/","p":"n.","zh":"裤子（美式）","ex":{"en":"These pants have deep pockets for my keys.","zh":"这条裤子的口袋很深，可以装我的钥匙。"},"tip":"美式指裤子，英式常指内裤；用 a pair of 计数。","topic":"daily","cefr":"A1"},{"w":"friend","uk":"/frend/","p":"n.","zh":"朋友；友人","ex":{"en":"I met an old friend at the market yesterday.","zh":"我昨天在市场遇到了一位老朋友。"},"tip":"“与某人交朋友”用make friends with，friends用复数。","topic":"society","cefr":"A1"},{"w":"sure","uk":"/ʃɔː/","p":"adj.","zh":"确信的；有把握的","ex":{"en":"Are you sure you left your keys here?","zh":"你确定把钥匙落在这里了吗？"},"tip":"be sure of表确信；be sure to可表必然或叮嘱。","topic":"thinking","cefr":"A1"},{"w":"very","uk":"/ˈveri/","p":"adv.","zh":"很；非常","ex":{"en":"The soup is very hot, so let it cool.","zh":"汤很烫，先让它凉一凉。"},"tip":"very通常修饰形容词或副词；修饰动词常用very much。","topic":"daily","cefr":"A1"},{"w":"dancing","uk":"/ˈdɑːnsɪŋ/","p":"n.","zh":"跳舞；舞蹈","ex":{"en":"We go dancing together at the community centre every Saturday.","zh":"我们每周六都一起去社区中心跳舞。"},"tip":"作活动名词通常不可数；去跳舞用go dancing。","topic":"arts","cefr":"A1"},{"w":"more","uk":"/mɔː/","p":"det.","zh":"更多的；额外的","ex":{"en":"Could you add more rice to my bowl, please?","zh":"请再给我的碗里添点米饭，好吗？"},"tip":"可修饰可数或不可数名词；是 many、much 的比较级。","topic":"daily","cefr":"A1"},{"w":"book","uk":"/bʊk/","p":"n.","zh":"书；书籍","ex":{"en":"I left my book on the kitchen table.","zh":"我把书落在厨房的桌子上了。"},"tip":"book 作动词表示预订，可直接接房间、机票等。","topic":"education","cefr":"A1"},{"w":"home","uk":"/həʊm/","p":"n.","zh":"家；住所；家乡","ex":{"en":"We walked home together after dinner at the café.","zh":"在咖啡馆吃过晚饭后，我们一起走回家。"},"tip":"home作副词时前面不加to：go home。","topic":"daily","cefr":"A1"},{"w":"date","uk":"/deɪt/","p":"n.","zh":"日期","ex":{"en":"Have you chosen a date for the picnic?","zh":"你选好野餐的日期了吗？"},"tip":"date back to表示始于某时期，不用被动语态。","topic":"daily","cefr":"A1"},{"w":"club","uk":"/klʌb/","p":"n.","zh":"俱乐部；社团","ex":{"en":"I joined a chess club to meet new people.","zh":"我加入了一个国际象棋俱乐部，想认识些新朋友。"},"tip":"join a club表示加入社团，不用join in a club。","topic":"society","cefr":"A1"},{"w":"hundred","uk":"/ˈhʌndrəd/","p":"num.","zh":"一百","ex":{"en":"The hall can hold about a hundred people.","zh":"这个大厅大约能容纳一百人。"},"tip":"具体数词后用hundred；泛指数百用hundreds of。","topic":"education","cefr":"A1"},{"w":"toilet","uk":"/ˈtɔɪlət/","p":"n.","zh":"马桶；便器","ex":{"en":"The toilet upstairs keeps making a strange dripping sound.","zh":"楼上的马桶一直发出奇怪的滴水声。"},"tip":"美式toilet通常指马桶；问公共洗手间常用restroom。","topic":"daily","cefr":"A1"},{"w":"grandmother","uk":"/ˈɡrænmʌðə/","p":"n.","zh":"祖母；外祖母","ex":{"en":"My grandmother grows fresh herbs on her kitchen windowsill.","zh":"我的祖母在厨房窗台上种新鲜的香草。"},"tip":"可指祖母或外祖母；口语常用grandma。","topic":"daily","cefr":"A1"},{"w":"lion","uk":"/ˈlaɪən/","p":"n.","zh":"狮子","ex":{"en":"The lion rested beneath a tree in the shade.","zh":"那头狮子在树荫下休息。"},"tip":"狮群用a pride of lions；母狮称lioness。","topic":"nature","cefr":"A1"},{"w":"exercise","uk":"/ˈeksəsaɪz/","p":"n.","zh":"运动；练习","ex":{"en":"I get some exercise by walking to the shops.","zh":"我步行去商店，顺便锻炼一下。"},"tip":"泛指运动时不可数；一项练习或一套动作中的动作可数。","topic":"health","cefr":"A1"},{"w":"wall","uk":"/wɔːl/","p":"n.","zh":"墙；围墙","ex":{"en":"We hung a colourful painting on the kitchen wall.","zh":"我们在厨房墙上挂了一幅色彩鲜艳的画。"},"tip":"图片挂在墙上用on；嵌在墙内用in。","topic":"daily","cefr":"A1"},{"w":"some","uk":"/sʌm/","p":"det.","zh":"一些；若干","ex":{"en":"I bought some fresh bread on my way home.","zh":"我在回家的路上买了些新鲜面包。"},"tip":"可修饰复数名词或不可数名词；弱读常为/səm/。","topic":"daily","cefr":"A1"},{"w":"interested","uk":"/ˈɪntrəstɪd/","p":"adj.","zh":"感兴趣的","ex":{"en":"My sister is interested in learning to grow vegetables.","zh":"我姐姐对学习种菜很感兴趣。"},"tip":"人感到有兴趣用interested；后接in加名词或动名词。","topic":"emotion","cefr":"A1"},{"w":"which","uk":"/wɪtʃ/","p":"det.","zh":"哪一个；哪些","ex":{"en":"Which jacket should I wear to dinner tonight?","zh":"今晚去吃饭我该穿哪件夹克？"},"tip":"which常用于限定范围内的选择；what范围更开放。","topic":"daily","cefr":"A1"},{"w":"way","uk":"/weɪ/","p":"n.","zh":"方法；方式","ex":{"en":"Show me an easier way to fold this sheet.","zh":"教我一个更简单的叠床单方法吧。"},"tip":"“做某事的方法”可用way to do或way of doing。","topic":"daily","cefr":"A1"},{"w":"arm","uk":"/ɑːm/","p":"n.","zh":"手臂","ex":{"en":"She carried the sleeping baby gently in her arms.","zh":"她轻轻地把熟睡的宝宝抱在怀里。"},"tip":"表“武器”用复数arms；arm还可作动词。","topic":"daily","cefr":"A1"},{"w":"woman","uk":"/ˈwʊmən/","p":"n.","zh":"成年女性；女子","ex":{"en":"The woman next door grows beautiful flowers on her balcony.","zh":"隔壁那位女士在阳台上种了漂亮的花。"},"tip":"复数women读/ˈwɪmɪn/，注意首音节变化。","topic":"society","cefr":"A1"},{"w":"next","uk":"/nekst/","p":"adj.","zh":"下一个的；紧接着的","ex":{"en":"Our next bus leaves in about ten minutes.","zh":"我们要坐的下一班公交车大约十分钟后发车。"},"tip":"“下周”用next week，不加the；the next week指随后一周。","topic":"daily","cefr":"A1"},{"w":"bookstore","uk":"/ˈbʊkstɔː/","p":"n.","zh":"书店","ex":{"en":"The bookstore near my flat stays open until nine.","zh":"我公寓附近的书店一直营业到九点。"},"tip":"bookstore是美式常用词，不是借书的library。","topic":"daily","cefr":"A1"},{"w":"police","uk":"/pəˈliːs/","p":"n.","zh":"警察；警方","ex":{"en":"The police helped us find our missing bicycle.","zh":"警方帮我们找到了丢失的自行车。"},"tip":"the police作主语用复数；一名警察用a police officer。","topic":"society","cefr":"A1"},{"w":"young","uk":"/jʌŋ/","p":"adj.","zh":"年轻的；幼小的","ex":{"en":"A young kitten fell asleep inside my empty shoe.","zh":"一只小猫在我空着的鞋子里睡着了。"},"tip":"the young指年轻人群体；动物的幼崽也可用young。","topic":"daily","cefr":"A1"},{"w":"photo","uk":"/ˈfəʊtəʊ/","p":"n.","zh":"照片","ex":{"en":"We took a photo beside the old bridge.","zh":"我们在那座老桥旁拍了张照片。"},"tip":"photo是photograph的常用简称；复数为photos。","topic":"daily","cefr":"A1"},{"w":"everybody","uk":"/ˈevribɒdi/","p":"pron.","zh":"每个人；所有人","ex":{"en":"Everybody is waiting outside for the doors to open.","zh":"所有人都在外面等着开门。"},"tip":"作主语时谓语用单数：Everybody is ready。","topic":"society","cefr":"A1"},{"w":"orange","uk":"/ˈɒrɪndʒ/","p":"n.","zh":"橙；橙子","ex":{"en":"I peeled an orange and shared it with my sister.","zh":"我剥了一个橙子，和妹妹分着吃。"},"tip":"橙子可数；表示橙色时通常不可数。","topic":"daily","cefr":"A1"},{"w":"cinema","uk":"/ˈsɪnəmə/","p":"n.","zh":"电影院","ex":{"en":"We met outside the cinema and bought some popcorn.","zh":"我们在电影院外碰面，买了些爆米花。"},"tip":"英式常说go to the cinema，美式常说go to the movies。","topic":"arts","cefr":"A1"},{"w":"match","uk":"/mætʃ/","p":"n.","zh":"比赛","ex":{"en":"We watched a football match at the local park.","zh":"我们在附近的公园看了一场足球比赛。"},"tip":"match强调搭配协调；fit常指尺寸合适。","topic":"sport","cefr":"A1"},{"w":"dining-room","uk":"/ˈdaɪnɪŋ ruːm/","p":"n.","zh":"餐厅；饭厅","ex":{"en":"We put fresh flowers on the dining-room table.","zh":"我们在饭厅的餐桌上摆了鲜花。"},"tip":"现代通常写作dining room，指用餐房间。","topic":"daily","cefr":"A1"},{"w":"need","uk":"/niːd/","p":"v.","zh":"需要；必须","ex":{"en":"These plants need more water during hot weather.","zh":"天气炎热时，这些植物需要更多的水。"},"tip":"need to do表需要做；need doing表需要被做。","topic":"daily","cefr":"A1"},{"w":"hungry","uk":"/ˈhʌŋɡri/","p":"adj.","zh":"饥饿的","ex":{"en":"I felt hungry after our long walk by the river.","zh":"在河边走了很久之后，我觉得饿了。"},"tip":"hungry for后接名词，表示渴望某物。","topic":"daily","cefr":"A1"},{"w":"ago","uk":"/əˈɡəʊ/","p":"adv.","zh":"以前","ex":{"en":"I left my umbrella on the bus an hour ago.","zh":"一小时前，我把雨伞落在了公交车上。"},"tip":"ago放在时间段后，通常搭配一般过去时。","topic":"daily","cefr":"A1"},{"w":"fruit","uk":"/fruːt/","p":"n.","zh":"水果；果实","ex":{"en":"She packed fresh fruit in my lunch box.","zh":"她在我的午餐盒里放了新鲜水果。"},"tip":"泛指水果通常不可数；fruits可指种类或成果。","topic":"health","cefr":"A1"},{"w":"son","uk":"/sʌn/","p":"n.","zh":"儿子","ex":{"en":"Their son helped them plant flowers in the garden.","zh":"他们的儿子帮他们在花园里种花。"},"tip":"son与sun同音；成年男性也仍是父母的son。","topic":"society","cefr":"A1"},{"w":"over","uk":"/ˈəʊvə/","p":"prep.","zh":"在……上方；越过","ex":{"en":"A small bird flew over the garden wall.","zh":"一只小鸟飞过了花园的围墙。"},"tip":"over可指越过或超过；be over表示结束。","topic":"daily","cefr":"A1"},{"w":"vegetable","uk":"/ˈvedʒtəbl/","p":"n.","zh":"蔬菜","ex":{"en":"We bought fresh vegetables at the market this morning.","zh":"我们今天早上在市场买了新鲜蔬菜。"},"tip":"通常为可数名词；泛指多种蔬菜用vegetables。","topic":"health","cefr":"A1"},{"w":"dictionary","uk":"/ˈdɪkʃənəri/","p":"n.","zh":"词典；字典","ex":{"en":"I checked the pronunciation of this word in a dictionary.","zh":"我查了词典，确认这个词的发音。"},"tip":"查词用look up a word in a dictionary。","topic":"education","cefr":"A1"},{"w":"maybe","uk":"/ˈmeɪbi/","p":"adv.","zh":"也许；可能","ex":{"en":"Maybe we can have a picnic if the weather improves.","zh":"如果天气好转，也许我们可以去野餐。"},"tip":"maybe是副词；may be是情态动词加be。","topic":"thinking","cefr":"A1"},{"w":"they","uk":"/ðeɪ/","p":"pron.","zh":"他们；她们；它们","ex":{"en":"The children waved as they boarded the bus.","zh":"孩子们一边上公交车一边挥手。"},"tip":"单数they也搭配are、have，不用is、has。","topic":"daily","cefr":"A1"},{"w":"many","uk":"/ˈmeni/","p":"det.","zh":"许多的","ex":{"en":"How many apples do we need for the pie?","zh":"做这个派需要多少个苹果？"},"tip":"many 接可数名词复数；much 接不可数名词。","topic":"daily","cefr":"A1"},{"w":"cook","uk":"/kʊk/","p":"v.","zh":"烹调；煮；烧","ex":{"en":"I usually cook vegetable soup when the weather turns cold.","zh":"天气变冷时，我通常会煮蔬菜汤。"},"tip":"cook可指厨师；cooker在英式英语中指炉灶。","topic":"daily","cefr":"A1"},{"w":"away","uk":"/əˈweɪ/","p":"adv.","zh":"离开；远离","ex":{"en":"The little bird flew away when I opened the window.","zh":"我打开窗户时，小鸟飞走了。"},"tip":"away是副词；表示“远离某处”用away from。","topic":"daily","cefr":"A1"},{"w":"salad","uk":"/ˈsæləd/","p":"n.","zh":"沙拉；凉拌菜","ex":{"en":"I added cucumber and tomatoes to the salad.","zh":"我往沙拉里加了黄瓜和番茄。"},"tip":"可指一份沙拉，也可不可数地指沙拉这种食物。","topic":"daily","cefr":"A1"},{"w":"out","uk":"/aʊt/","p":"adv.","zh":"在外；向外；不在家","ex":{"en":"We went out for a walk after dinner.","zh":"晚饭后我们出去散步了。"},"tip":"out 常作副词；在某物外面可用 outside。","topic":"daily","cefr":"A1"},{"w":"excited","uk":"/ɪkˈsaɪtɪd/","p":"adj.","zh":"兴奋的；激动的","ex":{"en":"The children were excited about their first camping trip.","zh":"孩子们对第一次露营旅行感到兴奋。"},"tip":"人感到兴奋用excited；事物令人兴奋用exciting。","topic":"emotion","cefr":"A1"},{"w":"invite","uk":"/ɪnˈvaɪt/","p":"v.","zh":"邀请","ex":{"en":"Let's invite our new neighbours over for dinner.","zh":"我们邀请新邻居过来吃晚饭吧。"},"tip":"invite sb to＋活动；invite sb to do＋动作。","topic":"society","cefr":"A1"},{"w":"phone","uk":"/fəʊn/","p":"n.","zh":"电话；手机","ex":{"en":"My phone rang while I was washing the dishes.","zh":"我洗碗时，电话响了。"},"tip":"动词直接接人：phone someone，不加to。","topic":"technology","cefr":"A1"},{"w":"miss","uk":"/mɪs/","p":"v.","zh":"错过；未赶上","ex":{"en":"Hurry up, or we will miss the last bus.","zh":"快点，否则我们会错过末班公交车。"},"tip":"miss后接名词或动名词，不接to do。","topic":"daily","cefr":"A1"},{"w":"travel","uk":"/ˈtrævl/","p":"v.","zh":"旅行；行进","ex":{"en":"We usually travel by train to visit our grandparents.","zh":"我们通常坐火车去看望祖父母。"},"tip":"泛指旅行时travel不可数；一次旅行用a trip。","topic":"travel","cefr":"A1"},{"w":"follow","uk":"/ˈfɒləʊ/","p":"v.","zh":"跟随；沿着走","ex":{"en":"Follow this path until you reach the wooden bridge.","zh":"沿着这条小路走，直到到达木桥。"},"tip":"follow直接接宾语：follow me，不加with。","topic":"daily","cefr":"A1"},{"w":"weather","uk":"/ˈweðə(r)/","p":"n.","zh":"天气","ex":{"en":"The weather turned sunny just before our picnic.","zh":"就在我们野餐前，天气转晴了。"},"tip":"表示天气时不可数；climate指长期气候特征。","topic":"environment","cefr":"A1"},{"w":"twice","uk":"/twaɪs/","p":"adv.","zh":"两次","ex":{"en":"I checked my bag twice but couldn't find my keys.","zh":"我检查了两次包，却没找到钥匙。"},"tip":"两倍常用twice as…as或twice the＋名词。","topic":"daily","cefr":"A1"},{"w":"sing","uk":"/sɪŋ/","p":"v.","zh":"唱；唱歌","ex":{"en":"We sing our favourite songs while washing the dishes.","zh":"我们一边洗碗，一边唱自己最喜欢的歌。"},"tip":"不规则变化：sing—sang—sung。","topic":"arts","cefr":"A1"},{"w":"university","uk":"/ˌjuːnɪˈvɜːsəti/","p":"n.","zh":"大学","ex":{"en":"My sister studies engineering at a university near home.","zh":"我姐姐在离家不远的一所大学读工程学。"},"tip":"用a university而非an，因开头发辅音/j/。","topic":"education","cefr":"A1"},{"w":"give","uk":"/ɡɪv/","p":"v.","zh":"给；赠送","ex":{"en":"Please give your sister a clean towel after swimming.","zh":"游泳后请给你妹妹一条干净的毛巾。"},"tip":"give sb sth＝give sth to sb；过去式gave。","topic":"daily","cefr":"A1"},{"w":"shirt","uk":"/ʃɜːt/","p":"n.","zh":"衬衫","ex":{"en":"He ironed his blue shirt before the interview.","zh":"他在面试前熨好了自己的蓝衬衫。"},"tip":"shirt通常指衬衫；T-shirt才是T恤。","topic":"daily","cefr":"A1"},{"w":"giraffe","uk":"/dʒəˈrɑːf/","p":"n.","zh":"长颈鹿","ex":{"en":"The giraffe stretched its neck to reach the highest leaves.","zh":"那只长颈鹿伸长脖子去够最高处的叶子。"},"tip":"重音在第二音节，复数通常加-s。","topic":"nature","cefr":"A1"},{"w":"behind","uk":"/bɪˈhaɪnd/","p":"prep.","zh":"在……后面","ex":{"en":"Your umbrella is behind the door in the kitchen.","zh":"你的伞在厨房的门后面。"},"tip":"behind可作介词或副词；fall behind表示落后。","topic":"daily","cefr":"A1"},{"w":"cheap","uk":"/tʃiːp/","p":"adj.","zh":"便宜的；价低的","ex":{"en":"We found a cheap café near the train station.","zh":"我们在火车站附近找到了一家价格实惠的咖啡馆。"},"tip":"cheap有时暗示质量差；中性表达可用inexpensive。","topic":"economy","cefr":"A1"},{"w":"great","uk":"/ɡreɪt/","p":"adj.","zh":"极好的；出色的","ex":{"en":"We had a great afternoon swimming in the lake.","zh":"我们在湖里游泳，度过了一个愉快的下午。"},"tip":"a great deal of后接不可数名词，表示大量。","topic":"daily","cefr":"A1"},{"w":"rain","uk":"/reɪn/","p":"n.","zh":"雨；雨水","ex":{"en":"Heavy rain kept us inside for the whole afternoon.","zh":"大雨让我们整个下午都待在屋里。"},"tip":"rain作名词通常不可数；说下雨用It rains。","topic":"nature","cefr":"A1"},{"w":"good","uk":"/ɡʊd/","p":"adj.","zh":"好的；优质的","ex":{"en":"This bakery makes good bread with a crisp crust.","zh":"这家面包店做的面包很好，外皮酥脆。"},"tip":"good是形容词；修饰动作通常用well。","topic":"daily","cefr":"A1"},{"w":"both","uk":"/bəʊθ/","p":"det.","zh":"两者都","ex":{"en":"Both windows were open, letting in the cool breeze.","zh":"两扇窗户都开着，凉风吹了进来。"},"tip":"both指两者；both A and B作主语用复数谓语。","topic":"daily","cefr":"A1"},{"w":"inside","uk":"/ˌɪnˈsaɪd/","p":"prep.","zh":"在……里面；向……里面","ex":{"en":"Your keys are inside the small pocket of your bag.","zh":"你的钥匙在包的小口袋里。"},"tip":"inside后接名词时是介词；单独用可作副词。","topic":"daily","cefr":"A1"},{"w":"eraser","uk":"/ɪˈreɪzə/","p":"n.","zh":"橡皮擦","ex":{"en":"I borrowed an eraser to correct my pencil drawing.","zh":"我借了一块橡皮擦来修改铅笔画。"},"tip":"eraser常用于美式英语；英式英语常说rubber。","topic":"education","cefr":"A1"},{"w":"trip","uk":"/trɪp/","p":"n.","zh":"旅行；出行","ex":{"en":"Our weekend trip to the coast was wonderfully relaxing.","zh":"我们周末的海滨之旅让人十分放松。"},"tip":"trip 是可数名词；travel 表示旅行活动时通常不可数。","topic":"travel","cefr":"A1"},{"w":"driver","uk":"/ˈdraɪvə/","p":"n.","zh":"司机；驾驶员","ex":{"en":"The bus driver waited while I found my ticket.","zh":"公交车司机等着我找到车票。"},"tip":"a driver of change指推动变化的因素。","topic":"travel","cefr":"A1"},{"w":"one","uk":"/wʌn/","p":"num.","zh":"一；一个","ex":{"en":"There is only one apple left in the bowl.","zh":"碗里只剩一个苹果了。"},"tip":"one可替代单数可数名词；复数用ones。","topic":"daily","cefr":"A1"},{"w":"writer","uk":"/ˈraɪtə/","p":"n.","zh":"作家；作者","ex":{"en":"The writer filled her notebook while waiting for the train.","zh":"那位作家等火车时，把笔记本写得满满的。"},"tip":"writer范围较广；author常指某部作品的作者。","topic":"arts","cefr":"A1"},{"w":"bed","uk":"/bed/","p":"n.","zh":"床","ex":{"en":"The cat curled up on my bed after lunch.","zh":"午饭后，猫蜷缩在我的床上。"},"tip":"go to bed指就寝，不加the；make the bed指铺床。","topic":"daily","cefr":"A1"},{"w":"same","uk":"/seɪm/","p":"adj.","zh":"相同的；同一个的","ex":{"en":"We take the same bus to school every morning.","zh":"我们每天早上乘同一班公交车上学。"},"tip":"通常用the same；比较时用the same as。","topic":"daily","cefr":"A1"},{"w":"video","uk":"/ˈvɪdiəʊ/","p":"n.","zh":"视频；录像","ex":{"en":"We watched a video of penguins sliding across ice.","zh":"我们看了一段企鹅在冰上滑行的视频。"},"tip":"一段视频用a video；泛指视频媒介时可不可数。","topic":"media","cefr":"A1"},{"w":"during","uk":"/ˈdjʊərɪŋ/","p":"prep.","zh":"在……期间","ex":{"en":"Please keep your phone silent during the concert.","zh":"音乐会期间请将手机调为静音。"},"tip":"during后接名词；while后常接句子；for表示持续时长。","topic":"daily","cefr":"A1"},{"w":"cloud","uk":"/klaʊd/","p":"n.","zh":"云","ex":{"en":"A dark cloud drifted slowly across the afternoon sky.","zh":"一朵乌云缓缓飘过午后的天空。"},"tip":"cloud作动词可指使判断不清，如cloud your judgment。","topic":"nature","cefr":"A2"},{"w":"alive","uk":"/əˈlaɪv/","p":"adj.","zh":"活着的","ex":{"en":"The tiny plant is still alive after our holiday.","zh":"我们度假回来后，那株小植物还活着。"},"tip":"通常放在系动词后；“活鱼”说a live fish。","topic":"nature","cefr":"A2"},{"w":"circle","uk":"/ˈsɜːkəl/","p":"n.","zh":"圆；圆圈","ex":{"en":"The children sat in a circle on the grass.","zh":"孩子们在草地上围坐成一圈。"},"tip":"circle是圆或圆圈；cycle才常指循环或周期。","topic":"daily","cefr":"A2"},{"w":"pardon","uk":"/ˈpɑːdən/","p":"int.","zh":"请再说一遍","ex":{"en":"Pardon? I couldn't hear you over the washing machine.","zh":"请再说一遍？洗衣机太吵，我没听清。"},"tip":"没听清时可说Pardon?，语调通常上扬。","topic":"daily","cefr":"A2"},{"w":"succeed","uk":"/səkˈsiːd/","p":"v.","zh":"成功；达成目标","ex":{"en":"After several attempts, I succeeded in fixing the lamp.","zh":"尝试了几次后，我终于把灯修好了。"},"tip":"表示成功做成某事，用succeed in doing，不用to do。","topic":"work","cefr":"A2"},{"w":"easily","uk":"/ˈiːzəli/","p":"adv.","zh":"容易地；轻松地","ex":{"en":"This small suitcase fits easily beneath the train seat.","zh":"这个小行李箱轻轻松松就能放到火车座位下面。"},"tip":"easily可修饰最高级：easily the best表示远胜其他。","topic":"daily","cefr":"A2"},{"w":"bit","uk":"/bɪt/","p":"n.","zh":"一点；少量；小块","ex":{"en":"There is a bit of cake left for you.","zh":"还给你留了一点蛋糕。"},"tip":"a bit of接名词；a bit可修饰形容词；bit也是bite过去式。","topic":"daily","cefr":"A2"},{"w":"typing","uk":"/ˈtaɪpɪŋ/","p":"n.","zh":"打字；键盘输入","ex":{"en":"My typing has become faster since I started practising.","zh":"开始练习以后，我的打字速度变快了。"},"tip":"作名词时不可数；也是type的现在分词。","topic":"technology","cefr":"A2"},{"w":"male","uk":"/meɪl/","p":"adj.","zh":"男性的；雄性的","ex":{"en":"The male duck has a shiny green head.","zh":"这只公鸭有一个亮闪闪的绿色脑袋。"},"tip":"male可作形容词或名词；日常指男人通常用man。","topic":"society","cefr":"A2"},{"w":"album","uk":"/ˈælbəm/","p":"n.","zh":"音乐专辑","ex":{"en":"Her new album kept us singing all afternoon.","zh":"她的新专辑让我们跟着唱了整整一个下午。"},"tip":"音乐专辑用album；单曲用single。","topic":"arts","cefr":"A2"},{"w":"burn","uk":"/bɜːn/","p":"v.","zh":"燃烧；烧毁","ex":{"en":"A small fire burned quietly in the fireplace.","zh":"壁炉里，一小团火静静地燃烧着。"},"tip":"过去式和过去分词可用burnt或burned。","topic":"daily","cefr":"A2"},{"w":"knock","uk":"/nɒk/","p":"v.","zh":"敲；敲击","ex":{"en":"Please knock on the door before you come in.","zh":"进来之前请先敲门。"},"tip":"词首k不发音；敲门用knock on或at the door。","topic":"daily","cefr":"A2"},{"w":"ski","uk":"/skiː/","p":"v.","zh":"滑雪","ex":{"en":"We learned to ski on a gentle snowy slope.","zh":"我们在一处平缓的雪坡上学会了滑雪。"},"tip":"过去式skied，现在分词skiing；ski复数为skis。","topic":"sport","cefr":"A2"},{"w":"sneaker","uk":"/ˈsniːkə/","p":"n.","zh":"运动鞋（美式）","ex":{"en":"One sneaker was hiding under the kitchen chair.","zh":"一只运动鞋藏在厨房的椅子下面。"},"tip":"美式常用 sneakers，英式通常说 trainers。","topic":"daily","cefr":"A2"},{"w":"bell","uk":"/bel/","p":"n.","zh":"铃；钟","ex":{"en":"The bicycle bell rang as a cyclist approached.","zh":"一位骑车人靠近时，自行车铃响了。"},"tip":"ring a bell也可表示“听着耳熟；似曾相识”。","topic":"daily","cefr":"A2"},{"w":"design","uk":"/dɪˈzaɪn/","p":"v.","zh":"设计；构思","ex":{"en":"My cousin designed a wooden desk for her bedroom.","zh":"我表姐为自己的卧室设计了一张木书桌。"},"tip":"be designed to do表示“旨在做……”。","topic":"arts","cefr":"A2"},{"w":"bright","uk":"/braɪt/","p":"adj.","zh":"明亮的；鲜艳的","ex":{"en":"Bright sunlight streamed through the kitchen window this morning.","zh":"今天早晨，明亮的阳光从厨房窗户照了进来。"},"tip":"形容光线强用bright；形容房间暗用dim。","topic":"daily","cefr":"A2"},{"w":"boss","uk":"/bɒs/","p":"n.","zh":"老板；上司","ex":{"en":"My boss let me leave early for my appointment.","zh":"我的上司允许我提前下班去赴约。"},"tip":"boss较口语；作动词常用boss someone around。","topic":"work","cefr":"A2"},{"w":"violin","uk":"/ˌvaɪəˈlɪn/","p":"n.","zh":"小提琴","ex":{"en":"My sister practises the violin after dinner every evening.","zh":"我姐姐每天晚饭后都练习小提琴。"},"tip":"小提琴手是violinist；拉小提琴常说play the violin。","topic":"arts","cefr":"A2"},{"w":"rude","uk":"/ruːd/","p":"adj.","zh":"粗鲁的；无礼的","ex":{"en":"It was rude to interrupt her during dinner.","zh":"吃晚饭时打断她说话很不礼貌。"},"tip":"对某人无礼用 rude to someone，不用 rude with。","topic":"society","cefr":"A2"},{"w":"glove","uk":"/ɡlʌv/","p":"n.","zh":"手套","ex":{"en":"I found my missing glove under the kitchen chair.","zh":"我在厨房椅子下面找到了丢失的那只手套。"},"tip":"一副手套用 a pair of gloves，注意 gloves 用复数。","topic":"daily","cefr":"A2"},{"w":"complete","uk":"/kəmˈpliːt/","p":"v.","zh":"完成；填写完","ex":{"en":"I completed the puzzle just before dinner was ready.","zh":"我刚拼好拼图，晚饭就做好了。"},"tip":"complete a form指填写完表格，不是制作表格。","topic":"daily","cefr":"A2"},{"w":"kiss","uk":"/kɪs/","p":"v.","zh":"亲吻","ex":{"en":"She kissed her daughter gently before leaving for work.","zh":"她上班前轻轻亲了亲女儿。"},"tip":"吻某人的脸颊用 kiss someone on the cheek。","topic":"daily","cefr":"A2"},{"w":"space","uk":"/speɪs/","p":"n.","zh":"空间；空地；间隔","ex":{"en":"There is enough space for your bike beside mine.","zh":"我的自行车旁边有足够的地方放你的车。"},"tip":"泛指空间、太空时不可数；具体车位等可数。","topic":"city","cefr":"A2"},{"w":"pronounce","uk":"/prəˈnaʊns/","p":"v.","zh":"发音；读出","ex":{"en":"Could you teach me how to pronounce your name?","zh":"你能教我怎么读你的名字吗？"},"tip":"名词是pronunciation，注意中间没有字母o。","topic":"education","cefr":"A2"},{"w":"ability","uk":"/əˈbɪləti/","p":"n.","zh":"能力；才能","ex":{"en":"Her ability to fix bicycles impressed all her friends.","zh":"她修自行车的本领让朋友们都很佩服。"},"tip":"表示“做某事的能力”用ability to do。","topic":"education","cefr":"A2"},{"w":"recorder","uk":"/rɪˈkɔːdə/","p":"n.","zh":"录音机；记录器","ex":{"en":"I placed the recorder beside her before the interview.","zh":"采访前，我把录音机放在她身旁。"},"tip":"play the recorder指吹竖笛，不是播放录音机。","topic":"technology","cefr":"A2"},{"w":"along","uk":"/əˈlɒŋ/","p":"prep.","zh":"沿着；顺着","ex":{"en":"We walked along the river and watched the ducks.","zh":"我们沿着河边散步，看着水里的鸭子。"},"tip":"along沿着长线走；across强调从一边横穿到另一边。","topic":"travel","cefr":"A2"},{"w":"madam","uk":"/ˈmædəm/","p":"n.","zh":"女士；夫人（尊称）","ex":{"en":"Would you like a table by the window, madam?","zh":"女士，您想坐靠窗的桌子吗？"},"tip":"正式称呼女性时使用；日常熟人交谈中通常不用。","topic":"daily","cefr":"A2"},{"w":"missed","uk":"/mɪst/","p":"v.","zh":"错过；未赶上","ex":{"en":"We missed the bus and walked home together.","zh":"我们没赶上公交车，便一起走回了家。"},"tip":"miss的过去式和过去分词；词尾-ed读/t/。","topic":"daily","cefr":"A2"},{"w":"gold","uk":"/ɡəʊld/","p":"n.","zh":"金；黄金","ex":{"en":"My grandmother keeps her gold ring in a wooden box.","zh":"我奶奶把她的金戒指放在一个木盒里。"},"tip":"gold作材料名通常不可数；a gold可指一枚金牌。","topic":"economy","cefr":"A2"},{"w":"pronunciation","uk":"/prəˌnʌnsiˈeɪʃən/","p":"n.","zh":"发音；读音","ex":{"en":"I practise my pronunciation by recording short voice messages.","zh":"我通过录制简短的语音消息练习发音。"},"tip":"拼写是pronunciation，注意中间不是noun。","topic":"education","cefr":"A2"},{"w":"training","uk":"/ˈtreɪnɪŋ/","p":"n.","zh":"培训；训练","ex":{"en":"My first day of training involved helping customers.","zh":"培训第一天，我就参与了为顾客提供帮助的工作。"},"tip":"通常不可数；一次培训可说a training session。","topic":"work","cefr":"A2"},{"w":"slice","uk":"/slaɪs/","p":"n.","zh":"薄片；一片","ex":{"en":"She put a slice of lemon in my tea.","zh":"她在我的茶里放了一片柠檬。"},"tip":"slice强调切出的片；piece泛指一块或一件。","topic":"daily","cefr":"A2"},{"w":"diet","uk":"/ˈdaɪət/","p":"n.","zh":"日常饮食","ex":{"en":"My usual diet includes plenty of rice and vegetables.","zh":"我的日常饮食中有大量米饭和蔬菜。"},"tip":"diet不一定指节食，也可指日常饮食。","topic":"health","cefr":"A2"},{"w":"less","uk":"/les/","p":"det.","zh":"更少的","ex":{"en":"Please put less sugar in my tea this time.","zh":"这次请在我的茶里少放点糖。"},"tip":"修饰不可数名词用less；可数名词复数通常用fewer。","topic":"daily","cefr":"A2"},{"w":"army","uk":"/ˈɑːmi/","p":"n.","zh":"陆军；军队","ex":{"en":"My cousin joined the army after leaving school.","zh":"我的表亲毕业后参军了。"},"tip":"army主要指陆军；armed forces泛指各军种。","topic":"government","cefr":"A2"},{"w":"broken","uk":"/ˈbrəʊkən/","p":"adj.","zh":"破碎的；断裂的","ex":{"en":"She carefully swept the broken glass into a dustpan.","zh":"她小心地把碎玻璃扫进簸箕里。"},"tip":"也是break的过去分词；过去式为broke。","topic":"daily","cefr":"A2"},{"w":"forest","uk":"/ˈfɒrɪst/","p":"n.","zh":"森林；林区","ex":{"en":"We followed a narrow path deep into the forest.","zh":"我们沿着一条狭窄的小路走进森林深处。"},"tip":"forest通常指大片森林；wood也可指较小树林。","topic":"nature","cefr":"A2"},{"w":"sausage","uk":"/ˈsɒs.ɪdʒ/","p":"n.","zh":"香肠","ex":{"en":"We grilled sausages and served them with fresh vegetables.","zh":"我们烤了香肠，配上新鲜蔬菜端上桌。"},"tip":"单根香肠可数；sausage meat指香肠肉馅，不可数。","topic":"daily","cefr":"A2"},{"w":"organize","uk":"/ˈɔːɡənaɪz/","p":"v.","zh":"组织；筹办","ex":{"en":"Our neighbours organized a picnic by the river.","zh":"我们的邻居组织了一次河边野餐。"},"tip":"英式也常拼作organise；organize是规范拼写。","topic":"work","cefr":"A2"},{"w":"donkey","uk":"/ˈdɒŋki/","p":"n.","zh":"驴","ex":{"en":"A grey donkey carried baskets along the narrow mountain path.","zh":"一头灰驴驮着篮子走在狭窄的山路上。"},"tip":"指动物时donkey最常用；用来称呼人有贬义。","topic":"nature","cefr":"A2"},{"w":"wild","uk":"/waɪld/","p":"adj.","zh":"野生的；野长的","ex":{"en":"We spotted wild deer drinking beside the forest stream.","zh":"我们看见野鹿在森林的小溪旁喝水。"},"tip":"表示“在野外”用in the wild，不能漏掉the。","topic":"nature","cefr":"A2"},{"w":"social","uk":"/ˈsəʊʃəl/","p":"adj.","zh":"社会的","ex":{"en":"My new job leaves little time for social activities.","zh":"我的新工作让我几乎没时间参加社交活动。"},"tip":"social指社会或社交的；sociable指人爱交际。","topic":"society","cefr":"A2"},{"w":"hole","uk":"/həʊl/","p":"n.","zh":"洞；孔；坑","ex":{"en":"There's a small hole in my favourite sock.","zh":"我最喜欢的袜子上有一个小洞。"},"tip":"hole指洞；whole指完整的，两词同音。","topic":"daily","cefr":"A2"},{"w":"euro","uk":"/ˈjʊərəʊ/","p":"n.","zh":"欧元","ex":{"en":"I found a euro in my coat pocket today.","zh":"今天我在外套口袋里发现了一枚一欧元硬币。"},"tip":"普通英语中复数通常为euros；并非所有欧盟国家都用欧元。","topic":"economy","cefr":"A2"},{"w":"bookcase","uk":"/ˈbʊkkeɪs/","p":"n.","zh":"书柜；书架","ex":{"en":"She keeps her favourite novels in a wooden bookcase.","zh":"她把最喜欢的小说放在一个木书柜里。"},"tip":"bookcase指整件书柜，bookshelf指书架或一层搁板。","topic":"daily","cefr":"A2"},{"w":"rule","uk":"/ruːl/","p":"n.","zh":"规则；规定","ex":{"en":"Our main rule is to leave muddy shoes outside.","zh":"我们最主要的规矩是把沾泥的鞋子留在外面。"},"tip":"as a rule意为“通常”；rule out意为“排除”。","topic":"government","cefr":"A2"},{"w":"brush","uk":"/brʌʃ/","p":"n.","zh":"刷子；画笔","ex":{"en":"Use a soft brush to clean your muddy shoes.","zh":"用软毛刷清理你沾满泥的鞋子。"},"tip":"brush against表示轻擦；brush up on表示温习。","topic":"daily","cefr":"A2"},{"w":"proud","uk":"/praʊd/","p":"adj.","zh":"自豪的；骄傲的","ex":{"en":"He felt proud of the cake he baked himself.","zh":"他为自己亲手烤出的蛋糕感到自豪。"},"tip":"be proud of后接名词或动名词，表示为……自豪。","topic":"emotion","cefr":"A2"},{"w":"simple","uk":"/ˈsɪmpəl/","p":"adj.","zh":"简单的；容易的","ex":{"en":"This simple recipe takes just ten minutes to prepare.","zh":"这道简单的菜只需十分钟就能做好。"},"tip":"simple可指容易或朴素，不一定表示简陋。","topic":"daily","cefr":"A2"},{"w":"yet","uk":"/jet/","p":"adv.","zh":"还；尚；已经","ex":{"en":"I haven't finished dinner yet, so please wait.","zh":"我还没吃完晚饭，请等一下。"},"tip":"表示“还未”常用于否定句末；疑问句中可表示“已经”。","topic":"daily","cefr":"A2"},{"w":"jewelry","uk":"/ˈdʒuːəlri/","p":"n.","zh":"珠宝；首饰","ex":{"en":"She keeps her jewelry in a small wooden box.","zh":"她把首饰放在一个小木盒里。"},"tip":"美式拼写，英式为jewellery；不可数，用piece计件。","topic":"daily","cefr":"A2"},{"w":"distance","uk":"/ˈdɪstəns/","p":"n.","zh":"距离；间距","ex":{"en":"The distance from our house to school is quite short.","zh":"从我们家到学校的距离很短。"},"tip":"in the distance指在远处；at a distance指隔一段距离。","topic":"travel","cefr":"A2"},{"w":"underground","uk":"/ˌʌndəˈɡraʊnd/","p":"adj.","zh":"地下的；秘密的","ex":{"en":"We left our car in an underground garage.","zh":"我们把车停在了地下车库。"},"tip":"名词表地铁主要用于英式英语，此时重音在首音节。","topic":"city","cefr":"A2"},{"w":"refuse","uk":"/rɪˈfjuːz/","p":"v.","zh":"拒绝；谢绝","ex":{"en":"She refused to leave without her favourite blue umbrella.","zh":"不带上她最喜欢的蓝色雨伞，她就不肯走。"},"tip":"名词读/ˈrefjuːs/；动词后接to do，不接doing。","topic":"daily","cefr":"A2"},{"w":"lazy","uk":"/ˈleɪzi/","p":"adj.","zh":"懒惰的；不愿出力的","ex":{"en":"I felt too lazy to cook dinner tonight.","zh":"今晚我懒得做饭。"},"tip":"lazy afternoon指悠闲的午后，不一定含贬义。","topic":"daily","cefr":"A2"},{"w":"scary","uk":"/ˈskeəri/","p":"adj.","zh":"吓人的；令人害怕的","ex":{"en":"That scary noise was just a branch against the window.","zh":"那个吓人的声音只不过是树枝在碰窗户。"},"tip":"scary形容事物吓人；scared形容人感到害怕。","topic":"emotion","cefr":"A2"},{"w":"grandson","uk":"/ˈɡrænsʌn/","p":"n.","zh":"孙子；外孙","ex":{"en":"Her grandson visits every Sunday and helps with cooking.","zh":"她的孙子每周日都来看她，并帮忙做饭。"},"tip":"不区分父系与母系，既指孙子也指外孙。","topic":"society","cefr":"A2"},{"w":"anywhere","uk":"/ˈeniweə/","p":"adv.","zh":"在任何地方；去任何地方","ex":{"en":"You can sit anywhere you like in this room.","zh":"在这个房间里，你想坐哪儿都行。"},"tip":"不定副词，通常不直接作名词；anywhere else指别处。","topic":"daily","cefr":"A2"},{"w":"flag","uk":"/flæɡ/","p":"n.","zh":"旗；旗帜","ex":{"en":"A bright flag fluttered above the school gate.","zh":"一面鲜艳的旗帜在校门上方飘扬。"},"tip":"动词过去式flagged，进行式flagging，双写g。","topic":"society","cefr":"A2"},{"w":"marry","uk":"/ˈmæri/","p":"v.","zh":"与……结婚；结婚","ex":{"en":"My cousin plans to marry her partner next spring.","zh":"我表姐计划明年春天与伴侣结婚。"},"tip":"说marry someone或get married to，不说marry with。","topic":"society","cefr":"A2"},{"w":"seventh","uk":"/ˈsevənθ/","p":"num.","zh":"第七","ex":{"en":"Our new flat is on the seventh floor.","zh":"我们的新公寓在七楼。"},"tip":"序数词前通常用the；已有物主限定词时不用the。","topic":"daily","cefr":"A2"},{"w":"natural","uk":"/ˈnætʃərəl/","p":"adj.","zh":"天然的；自然界的","ex":{"en":"This soap is made entirely from natural ingredients.","zh":"这块肥皂完全由天然原料制成。"},"tip":"natural指天然的；nature是名词，指自然。","topic":"nature","cefr":"A2"},{"w":"gardening","uk":"/ˈɡɑːdənɪŋ/","p":"n.","zh":"园艺；种植花木","ex":{"en":"My grandmother enjoys gardening on cool spring mornings.","zh":"我奶奶喜欢在凉爽的春日早晨打理花园。"},"tip":"通常为不可数名词：do some gardening。","topic":"daily","cefr":"A2"},{"w":"surfing","uk":"/ˈsɜːfɪŋ/","p":"n.","zh":"冲浪运动","ex":{"en":"We went surfing at the beach early this morning.","zh":"今天一大早我们去海滩冲浪了。"},"tip":"运动用go surfing；网上浏览也可说surf the internet。","topic":"sport","cefr":"A2"},{"w":"user","uk":"/ˈjuːzə/","p":"n.","zh":"使用者；用户","ex":{"en":"Each user can choose a different colour for their profile.","zh":"每位用户都可以为自己的个人资料选择不同的颜色。"},"tip":"use作动词及user中的s读/z/。","topic":"technology","cefr":"A2"},{"w":"metro","uk":"/ˈmetrəʊ/","p":"n.","zh":"地铁；地铁系统","ex":{"en":"We took the metro to the museum this morning.","zh":"今天上午，我们乘地铁去了博物馆。"},"tip":"metro不限于法国；乘地铁常说take the metro。","topic":"city","cefr":"A2"},{"w":"save","uk":"/seɪv/","p":"v.","zh":"挽救；救助","ex":{"en":"The lifeguard saved a child from the deep water.","zh":"救生员从深水中救起了一个孩子。"},"tip":"save money既可指省钱，也可指存钱。","topic":"daily","cefr":"A2"},{"w":"jewellery","uk":"/ˈdʒuːəlri/","p":"n.","zh":"珠宝；首饰","ex":{"en":"She keeps her jewellery in a small wooden box.","zh":"她把首饰放在一个小木盒里。"},"tip":"不可数；一件用a piece of；美式拼写jewelry。","topic":"daily","cefr":"A2"},{"w":"plastic","uk":"/ˈplæstɪk/","p":"n.","zh":"塑料","ex":{"en":"This lunch box is made of strong recycled plastic.","zh":"这个午餐盒由结实的再生塑料制成。"},"tip":"表示塑料材料时通常不可数；a plastic指一种塑料。","topic":"environment","cefr":"A2"},{"w":"towards","uk":"/təˈwɔːdz/","p":"prep.","zh":"朝；向","ex":{"en":"The puppy ran towards me with its tail wagging.","zh":"小狗摇着尾巴朝我跑来。"},"tip":"towards与toward意思相同；前者英式更常用。","topic":"daily","cefr":"A2"},{"w":"broccoli","uk":"/ˈbrɒkəli/","p":"n.","zh":"西兰花","ex":{"en":"We steamed the broccoli until it turned bright green.","zh":"我们把西兰花蒸到颜色变得鲜绿。"},"tip":"通常不可数；小朵西兰花可说broccoli florets。","topic":"health","cefr":"A2"},{"w":"protect","uk":"/prəˈtekt/","p":"v.","zh":"保护；防护","ex":{"en":"Wear thick gloves to protect your hands from thorns.","zh":"戴上厚手套，保护双手不被刺扎伤。"},"tip":"常用protect sb/sth from或against，表示免受伤害。","topic":"environment","cefr":"A2"},{"w":"strange","uk":"/streɪndʒ/","p":"adj.","zh":"奇怪的；反常的","ex":{"en":"There was a strange noise coming from the cupboard.","zh":"橱柜里传出一阵奇怪的声音。"},"tip":"strange 可指奇怪，也可指陌生；stranger 是陌生人。","topic":"daily","cefr":"A2"},{"w":"latest","uk":"/ˈleɪtɪst/","p":"adj.","zh":"最新的；最近的","ex":{"en":"Have you heard the latest news about our neighbour?","zh":"你听说关于我们邻居的最新消息了吗？"},"tip":"latest指最新；last常指上一个或最后一个。","topic":"daily","cefr":"A2"},{"w":"snake","uk":"/sneɪk/","p":"n.","zh":"蛇","ex":{"en":"A small snake slid quietly through the dry grass.","zh":"一条小蛇悄悄滑过干草丛。"},"tip":"作动词表示蜿蜒，常搭配through或along。","topic":"nature","cefr":"A2"},{"w":"wardrobe","uk":"/ˈwɔːdrəʊb/","p":"n.","zh":"衣柜；衣橱","ex":{"en":"Her winter coats fill most of the wardrobe.","zh":"她的冬季外套占了衣柜的大部分空间。"},"tip":"既指衣柜，也可指某人拥有的全部衣物。","topic":"daily","cefr":"A2"},{"w":"hometown","uk":"/ˈhəʊmtaʊn/","p":"n.","zh":"家乡；故乡","ex":{"en":"I return to my hometown every summer to visit relatives.","zh":"我每年夏天都回家乡探望亲人。"},"tip":"可指小镇或城市，不一定是出生地。","topic":"city","cefr":"A2"},{"w":"smart","uk":"/smɑːt/","p":"adj.","zh":"聪明的；明智的","ex":{"en":"That was a smart way to fix the shelf.","zh":"用那个办法修好架子真聪明。"},"tip":"英式常指衣着整洁时髦；美式常指聪明。","topic":"daily","cefr":"A2"},{"w":"mother-in-law","uk":"/ˈmʌðər ɪn lɔː/","p":"n.","zh":"婆婆；岳母","ex":{"en":"My mother-in-law taught me how to grow tomatoes.","zh":"我婆婆教我如何种番茄。"},"tip":"指配偶的母亲；复数mothers-in-law。","topic":"society","cefr":"A2"},{"w":"goat","uk":"/ɡəʊt/","p":"n.","zh":"山羊","ex":{"en":"A curious goat poked its head through the fence.","zh":"一只好奇的山羊把头探出了围栏。"},"tip":"goat是山羊，sheep是绵羊；替罪羊用scapegoat。","topic":"nature","cefr":"A2"},{"w":"clear","uk":"/klɪə/","p":"adj.","zh":"清楚的；明确的","ex":{"en":"The instructions were clear, so I assembled the shelf easily.","zh":"说明很清楚，所以我轻松地组装好了架子。"},"tip":"make it clear that…表示明确说明……。","topic":"daily","cefr":"A2"},{"w":"blog","uk":"/blɒɡ/","p":"n.","zh":"博客；网络日志","ex":{"en":"She writes a blog about growing vegetables at home.","zh":"她写一个介绍在家种菜的博客。"},"tip":"一篇博文叫a blog post；blog常指整个博客。","topic":"media","cefr":"A2"},{"w":"digital","uk":"/ˈdɪdʒɪtəl/","p":"adj.","zh":"数字技术的；数码的","ex":{"en":"She keeps digital copies of all her family photos.","zh":"她保存着所有家庭照片的电子副本。"},"tip":"digital侧重数字技术；表示“数字上的”常用numerical。","topic":"technology","cefr":"A2"},{"w":"polite","uk":"/pəˈlaɪt/","p":"adj.","zh":"有礼貌的；客气的","ex":{"en":"The polite child held the door open for us.","zh":"那个有礼貌的孩子为我们扶着门。"},"tip":"对某人有礼貌用be polite to，不用polite with。","topic":"society","cefr":"A2"},{"w":"energy","uk":"/ˈenədʒi/","p":"n.","zh":"精力；活力","ex":{"en":"After a short nap, I had energy to cook.","zh":"小睡一会儿后，我有精力做饭了。"},"tip":"表示精力或能源时通常不可数，不说 an energy。","topic":"environment","cefr":"A2"},{"w":"government","uk":"/ˈɡʌvənmənt/","p":"n.","zh":"政府","ex":{"en":"The government plans to build a new hospital nearby.","zh":"政府计划在附近建一所新医院。"},"tip":"英国英语中，指政府群体时可接单数或复数谓语。","topic":"government","cefr":"A2"},{"w":"organise","uk":"/ˈɔːɡənaɪz/","p":"v.","zh":"组织；筹办","ex":{"en":"We organise a picnic for our neighbours every summer.","zh":"我们每年夏天都会为邻居们组织一次野餐。"},"tip":"organise常见于英式英语；美式通常写organize。","topic":"work","cefr":"A2"},{"w":"correctly","uk":"/kəˈrektli/","p":"adv.","zh":"正确地；恰当地","ex":{"en":"Check that you have entered your address correctly.","zh":"检查一下，确保你的地址输入正确。"},"tip":"修饰动作；correct是形容词或动词，不作副词使用。","topic":"education","cefr":"A2"},{"w":"fair","uk":"/feə/","p":"adj.","zh":"公平的；合理的","ex":{"en":"We took turns choosing games to keep things fair.","zh":"我们轮流选游戏，以保证公平。"},"tip":"fair指待遇公平；fairly还可表示“相当”。","topic":"society","cefr":"A2"},{"w":"vacation","uk":"/vəˈkeɪʃən/","p":"n.","zh":"假期；度假","ex":{"en":"We spent our summer vacation camping beside a lake.","zh":"我们暑假在湖边露营。"},"tip":"主要用于美式英语；英式英语一般用holiday。","topic":"travel","cefr":"A2"},{"w":"traveler","uk":"/ˈtrævələ/","p":"n.","zh":"旅行者；旅客","ex":{"en":"A tired traveler asked me where the station was.","zh":"一位疲惫的旅客问我车站在哪里。"},"tip":"traveler是美式拼写；英式通常写traveller。","topic":"travel","cefr":"A2"},{"w":"tool","uk":"/tuːl/","p":"n.","zh":"工具；用具","ex":{"en":"This small tool helps me tighten the loose screws.","zh":"这个小工具帮我拧紧松动的螺丝。"},"tip":"tool是可数名词；equipment通常不可数。","topic":"technology","cefr":"A2"},{"w":"ankle","uk":"/ˈæŋkəl/","p":"n.","zh":"脚踝；踝关节","ex":{"en":"She twisted her ankle while walking down the steps.","zh":"她下台阶时扭伤了脚踝。"},"tip":"ankle指脚与小腿连接处，不是脚后跟heel。","topic":"health","cefr":"A2"},{"w":"cereal","uk":"/ˈsɪəriəl/","p":"n.","zh":"早餐麦片","ex":{"en":"She poured cold milk over her bowl of cereal.","zh":"她把冷牛奶倒进盛着早餐麦片的碗里。"},"tip":"早餐食品泛指时常不可数；指谷物种类可用cereals。","topic":"daily","cefr":"A2"},{"w":"insect","uk":"/ˈɪnsekt/","p":"n.","zh":"昆虫","ex":{"en":"A tiny green insect landed on my sleeve.","zh":"一只绿色的小昆虫落在了我的袖子上。"},"tip":"可数名词；蜘蛛有八条腿，不属于昆虫。","topic":"nature","cefr":"A2"},{"w":"manager","uk":"/ˈmænɪdʒə/","p":"n.","zh":"经理；管理者","ex":{"en":"The manager helped a new employee arrange the shelves.","zh":"经理帮一位新员工整理了货架。"},"tip":"manager指管理者；management可指管理工作或管理层。","topic":"work","cefr":"A2"},{"w":"alone","uk":"/əˈləʊn/","p":"adj.","zh":"独自的；单独的","ex":{"en":"I was alone in the kitchen when the kettle boiled.","zh":"水壶里的水烧开时，厨房里只有我一个人。"},"tip":"alone指独自，不一定孤独；lonely强调孤独感。","topic":"daily","cefr":"A2"},{"w":"competition","uk":"/ˌkɒmpəˈtɪʃən/","p":"n.","zh":"竞争","ex":{"en":"Our school is holding a painting competition next Friday.","zh":"我们学校下周五要举办绘画比赛。"},"tip":"表示竞争通常不可数；表示一场比赛时可数。","topic":"society","cefr":"A2"},{"w":"beef","uk":"/biːf/","p":"n.","zh":"牛肉","ex":{"en":"We cooked the beef slowly with carrots and potatoes.","zh":"我们把牛肉和胡萝卜、土豆一起慢炖。"},"tip":"表示食物时通常不可数：some beef，不用a beef。","topic":"daily","cefr":"A2"},{"w":"discuss","uk":"/dɪˈskʌs/","p":"v.","zh":"讨论；商讨","ex":{"en":"Let's discuss our holiday plans over dinner tonight.","zh":"今晚我们边吃晚饭边商量度假计划吧。"},"tip":"直接接讨论内容：discuss sth，不加about。","topic":"education","cefr":"A2"},{"w":"snack","uk":"/snæk/","p":"n.","zh":"零食；小吃","ex":{"en":"I packed an apple and some nuts for a snack.","zh":"我装了一个苹果和一些坚果，留着当零食吃。"},"tip":"动词常用snack on sth，表示吃某物当零食。","topic":"health","cefr":"A2"},{"w":"ketchup","uk":"/ˈketʃəp/","p":"n.","zh":"番茄调味酱","ex":{"en":"He squeezed some ketchup onto his plate of chips.","zh":"他往那盘薯条上挤了些番茄酱。"},"tip":"不可数；与浓缩烹饪用的tomato paste不同。","topic":"daily","cefr":"A2"},{"w":"model","uk":"/ˈmɒdəl/","p":"n.","zh":"模型；模式","ex":{"en":"He built a model of a bridge from cardboard.","zh":"他用硬纸板做了一座桥的模型。"},"tip":"model还可作动词，表示建模或当模特。","topic":"science","cefr":"A2"},{"w":"photocopier","uk":"/ˈfəʊtəʊkɒpiə/","p":"n.","zh":"复印机","ex":{"en":"The office photocopier has run out of paper again.","zh":"办公室的复印机又没纸了。"},"tip":"photocopier是机器；photocopy是复印件或复印动作。","topic":"work","cefr":"A2"},{"w":"mail","uk":"/meɪl/","p":"n.","zh":"邮件；邮政","ex":{"en":"The mail arrived just as we finished breakfast.","zh":"我们刚吃完早饭，邮件就到了。"},"tip":"mail作“邮件”通常不可数；英式日常也常用post。","topic":"daily","cefr":"A2"},{"w":"weak","uk":"/wiːk/","p":"adj.","zh":"虚弱的；无力的","ex":{"en":"I felt too weak to carry the shopping upstairs.","zh":"我觉得浑身无力，没法把买来的东西提上楼。"},"tip":"weak与week同音；weakness可指弱点，也可指虚弱。","topic":"health","cefr":"A2"},{"w":"invent","uk":"/ɪnˈvent/","p":"v.","zh":"发明；创造","ex":{"en":"My sister invented a clever tool for picking apples.","zh":"我姐姐发明了一种巧妙的摘苹果工具。"},"tip":"invent是创造新事物；discover是发现已有事物。","topic":"technology","cefr":"A2"},{"w":"discover","uk":"/dɪˈskʌvə/","p":"v.","zh":"发现","ex":{"en":"We discovered a quiet beach behind the cliffs.","zh":"我们在悬崖后面发现了一片安静的海滩。"},"tip":"discover发现原本存在的事物；invent创造新事物。","topic":"science","cefr":"A2"},{"w":"designer","uk":"/dɪˈzaɪnə/","p":"n.","zh":"设计师；设计者","ex":{"en":"The designer showed us a model of our kitchen.","zh":"设计师给我们看了我们厨房的模型。"},"tip":"作形容词常置于衣物等名词前，强调设计师品牌。","topic":"arts","cefr":"A2"},{"w":"stadium","uk":"/ˈsteɪdiəm/","p":"n.","zh":"体育场","ex":{"en":"Fans filled the stadium before the football match began.","zh":"足球比赛开始前，球迷们就坐满了体育场。"},"tip":"复数可用stadiums或stadia，前者更常见。","topic":"sport","cefr":"A2"},{"w":"pupil","uk":"/ˈpjuːpəl/","p":"n.","zh":"小学生；中学生","ex":{"en":"Each pupil brought a leaf to the science lesson.","zh":"每个学生都带了一片树叶来上科学课。"},"tip":"英式英语常指中小学生；大学生用 student。","topic":"education","cefr":"A2"},{"w":"lost","uk":"/lɒst/","p":"adj.","zh":"迷路的；丢失的","ex":{"en":"We got lost while walking through the old town.","zh":"我们在老城区步行时迷路了。"},"tip":"get lost可指迷路；单独用作命令语气粗鲁。","topic":"travel","cefr":"A2"},{"w":"thousand","uk":"/ˈθaʊzənd/","p":"num.","zh":"一千","ex":{"en":"The repair cost nearly a thousand dollars in total.","zh":"维修费总共将近一千美元。"},"tip":"具体数词后不加s；泛指数千用thousands of。","topic":"daily","cefr":"A2"},{"w":"part-time","uk":"/ˌpɑːt ˈtaɪm/","p":"adj.","zh":"兼职的；非全日制的","ex":{"en":"My sister has a part-time job at a bakery.","zh":"我姐姐在一家面包店做兼职。"},"tip":"可作形容词或副词：a part-time job；work part-time。","topic":"work","cefr":"A2"},{"w":"certainly","uk":"/ˈsɜːtənli/","p":"adv.","zh":"无疑；肯定","ex":{"en":"This warm coat will certainly keep you comfortable outside.","zh":"这件暖和的大衣肯定能让你在外面也舒舒服服的。"},"tip":"常置于实义动词前、be后；也可单独礼貌回应请求。","topic":"daily","cefr":"A2"},{"w":"vocabulary","uk":"/vəˈkæbjələri/","p":"n.","zh":"词汇量；词汇","ex":{"en":"Reading short stories helps me build my English vocabulary.","zh":"读短篇故事有助于我扩大英语词汇量。"},"tip":"单个词用word；vocabulary通常指词汇总量或集合。","topic":"education","cefr":"A2"},{"w":"danger","uk":"/ˈdeɪndʒə/","p":"n.","zh":"危险；风险","ex":{"en":"Keep away from the edge; there's a danger of falling.","zh":"离边缘远一点，有掉下去的危险。"},"tip":"in danger指处于危险中；dangerous指会带来危险。","topic":"daily","cefr":"A2"},{"w":"hardworking","uk":"/ˌhɑːdˈwɜːkɪŋ/","p":"adj.","zh":"勤奋的；努力工作的","ex":{"en":"Our hardworking neighbour grows vegetables for the whole street.","zh":"我们勤劳的邻居种菜，供整条街的居民享用。"},"tip":"是形容词；“努力工作”用动词短语work hard。","topic":"work","cefr":"A2"},{"w":"indoor","uk":"/ˈɪndɔː/","p":"adj.","zh":"室内的","ex":{"en":"Our hotel has an indoor pool beside the gym.","zh":"我们酒店的健身房旁边有一个室内游泳池。"},"tip":"indoor作定语；indoors作副词，如stay indoors。","topic":"daily","cefr":"A2"},{"w":"electric","uk":"/ɪˈlektrɪk/","p":"adj.","zh":"电的；电动的","ex":{"en":"Our electric kettle boils water in two minutes.","zh":"我们的电水壶两分钟就能把水烧开。"},"tip":"电动设备多用electric；电气系统多用electrical。","topic":"technology","cefr":"A2"},{"w":"director","uk":"/dəˈrektə/","p":"n.","zh":"主管；负责人；董事","ex":{"en":"Our director welcomed the new staff at breakfast.","zh":"我们的主管在早餐时欢迎了新员工。"},"tip":"既可指机构主管或董事，也可指影视、戏剧导演。","topic":"work","cefr":"A2"},{"w":"convenient","uk":"/kənˈviːniənt/","p":"adj.","zh":"方便的；合适的","ex":{"en":"Is Saturday morning a convenient time for your visit?","zh":"你周六上午来方便吗？"},"tip":"说 It is convenient for me，不说 I am convenient。","topic":"daily","cefr":"A2"},{"w":"downtown","uk":"/ˌdaʊnˈtaʊn/","p":"adv.","zh":"在市中心；往市中心","ex":{"en":"We took the bus downtown to buy new shoes.","zh":"我们乘公交车去市中心买新鞋。"},"tip":"主要用于美式英语；作副词时前面不加to。","topic":"city","cefr":"A2"},{"w":"war","uk":"/wɔː/","p":"n.","zh":"战争","ex":{"en":"The museum displays uniforms worn during the war.","zh":"博物馆展出了战争期间穿过的军服。"},"tip":"表示处于交战状态用at war，不加冠词。","topic":"history","cefr":"A2"},{"w":"reader","uk":"/ˈriːdə/","p":"n.","zh":"读者；阅读者","ex":{"en":"An eager reader, Lina always carries a book.","zh":"莉娜热爱阅读，总是随身带着一本书。"},"tip":"reader既可指人，也可指设备或供学习的读物。","topic":"education","cefr":"A2"},{"w":"education","uk":"/ˌedʒuˈkeɪʃən/","p":"n.","zh":"教育；受教育过程","ex":{"en":"Her grandparents saved money to pay for her education.","zh":"她的祖父母攒钱供她读书。"},"tip":"通常不可数；但可说a good education（良好教育）。","topic":"education","cefr":"A2"},{"w":"career","uk":"/kəˈrɪə/","p":"n.","zh":"职业；职业生涯","ex":{"en":"My sister hopes to build a career in nursing.","zh":"我姐姐希望在护理行业发展事业。"},"tip":"career侧重长期职业发展，job指具体工作。","topic":"work","cefr":"A2"},{"w":"lonely","uk":"/ˈləʊnli/","p":"adj.","zh":"孤独的；寂寞的","ex":{"en":"I felt lonely until my neighbour invited me for tea.","zh":"我一直觉得孤单，直到邻居邀请我去喝茶。"},"tip":"alone强调独自一人；lonely强调内心孤独。","topic":"emotion","cefr":"A2"},{"w":"puppy","uk":"/ˈpʌpi/","p":"n.","zh":"小狗；幼犬","ex":{"en":"The puppy fell asleep inside my empty shoe.","zh":"小狗钻进我的空鞋子里睡着了。"},"tip":"复数为puppies；通常专指幼犬。","topic":"nature","cefr":"A2"},{"w":"style","uk":"/staɪl/","p":"n.","zh":"风格；方式","ex":{"en":"Her colourful paintings have a cheerful, playful style.","zh":"她色彩丰富的画作有一种欢快、俏皮的风格。"},"tip":"style可指个人风格，不一定表示流行时尚。","topic":"arts","cefr":"A2"},{"w":"taste","uk":"/teɪst/","p":"n.","zh":"味道；味觉","ex":{"en":"The soup has a rich taste of roasted tomatoes.","zh":"这汤有浓郁的烤番茄味。"},"tip":"taste表示“尝起来”时接形容词，不接副词。","topic":"daily","cefr":"A2"},{"w":"jump","uk":"/dʒʌmp/","p":"v.","zh":"跳；跳过","ex":{"en":"The dog jumped over a puddle beside the gate.","zh":"狗跳过了大门旁的一摊积水。"},"tip":"jump at the chance意为欣然抓住机会。","topic":"daily","cefr":"A2"},{"w":"record","uk":"/ˈrekɔːd/","p":"n.","zh":"记录；档案","ex":{"en":"I keep a record of everything I spend.","zh":"我把每一笔花费都记下来。"},"tip":"名词重音在首音节；动词重音在第二音节。","topic":"daily","cefr":"A2"},{"w":"assistant","uk":"/əˈsɪstənt/","p":"n.","zh":"助手；助理","ex":{"en":"The assistant brought fresh towels into the treatment room.","zh":"助手把干净的毛巾拿进了治疗室。"},"tip":"assistant指人，assistance指帮助，通常不可数。","topic":"work","cefr":"A2"},{"w":"clearly","uk":"/ˈklɪəli/","p":"adv.","zh":"清楚地；清晰地","ex":{"en":"Please speak clearly so everyone can hear you.","zh":"请说清楚些，让大家都能听清。"},"tip":"句首Clearly常表示“显然”，而非“清晰地”。","topic":"daily","cefr":"A2"},{"w":"curry","uk":"/ˈkʌri/","p":"n.","zh":"咖喱菜肴","ex":{"en":"This vegetable curry tastes wonderful with rice and warm bread.","zh":"这道蔬菜咖喱配米饭和热面包非常好吃。"},"tip":"curry常指菜肴；咖喱粉用curry powder。","topic":"daily","cefr":"A2"},{"w":"nurse","uk":"/nɜːs/","p":"n.","zh":"护士","ex":{"en":"The nurse gently wrapped a bandage around my wrist.","zh":"护士轻轻地用绷带包住我的手腕。"},"tip":"作动词可直接接人：nurse a patient。","topic":"health","cefr":"A2"},{"w":"fan","uk":"/fæn/","p":"n.","zh":"迷；爱好者","ex":{"en":"As a football fan, I rarely miss a match.","zh":"作为一名足球迷，我几乎不错过任何一场比赛。"},"tip":"表示“……的爱好者”用a fan of。","topic":"sport","cefr":"A2"},{"w":"vase","uk":"/vɑːz/","p":"n.","zh":"花瓶","ex":{"en":"I put fresh flowers in the vase by the window.","zh":"我把鲜花插进窗边的花瓶里。"},"tip":"英式通常读/vɑːz/；美式常读/veɪs/。","topic":"daily","cefr":"A2"},{"w":"saw","uk":"/sɔː/","p":"n.","zh":"锯；锯子","ex":{"en":"He used a saw to cut the wooden shelf.","zh":"他用锯子切割那块木制搁板。"},"tip":"表“锯”的过去式为sawed；表“看见”则是see的过去式。","topic":"daily","cefr":"A2"},{"w":"trainer","uk":"/ˈtreɪnə/","p":"n.","zh":"教练；培训师","ex":{"en":"My trainer showed me how to lift weights safely.","zh":"我的教练教我如何安全地举重。"},"tip":"运动鞋英式常用trainers，美式常用sneakers。","topic":"sport","cefr":"A2"},{"w":"till","uk":"/tɪl/","p":"prep.","zh":"直到……为止","ex":{"en":"The little bakery stays open till six every evening.","zh":"这家小面包店每天晚上营业到六点。"},"tip":"till与until意思相同；作连词谈将来时通常接一般现在时。","topic":"daily","cefr":"A2"},{"w":"divorced","uk":"/dɪˈvɔːst/","p":"adj.","zh":"已离婚的","ex":{"en":"My divorced uncle lives happily near his children.","zh":"我离婚的叔叔住在孩子们附近，生活很幸福。"},"tip":"get divorced表示离婚；脱离某事用divorced from。","topic":"society","cefr":"A2"},{"w":"meaning","uk":"/ˈmiːnɪŋ/","p":"n.","zh":"意思；含义","ex":{"en":"Could you explain the meaning of this unusual word?","zh":"你能解释一下这个不常见的词是什么意思吗？"},"tip":"问词义用the meaning of；不要与opinion混淆。","topic":"education","cefr":"A2"},{"w":"spaghetti","uk":"/spəˈɡeti/","p":"n.","zh":"意大利细长面条","ex":{"en":"She twirled the spaghetti around her fork before taking a bite.","zh":"她先用叉子卷起意大利细面，再吃了一口。"},"tip":"不可数名词；一盘用a plate of spaghetti。","topic":"daily","cefr":"A2"},{"w":"garlic","uk":"/ˈɡɑːlɪk/","p":"n.","zh":"大蒜","ex":{"en":"Crush the garlic before adding it to the soup.","zh":"先把大蒜压碎，再放进汤里。"},"tip":"通常不可数；一瓣大蒜用a clove of garlic。","topic":"daily","cefr":"A2"},{"w":"control","uk":"/kənˈtrəʊl/","p":"n.","zh":"控制；管理","ex":{"en":"Keep control of the kite by holding the string firmly.","zh":"抓紧风筝线，控制好风筝。"},"tip":"过去式controlled、现在分词controlling均双写l。","topic":"daily","cefr":"A2"},{"w":"supper","uk":"/ˈsʌpə/","p":"n.","zh":"晚饭；睡前便餐","ex":{"en":"We had soup and fresh bread for supper.","zh":"我们晚饭喝了汤，吃了新鲜面包。"},"tip":"常指较随意的晚饭，也可指睡前便餐。","topic":"daily","cefr":"A2"},{"w":"serious","uk":"/ˈsɪəriəs/","p":"adj.","zh":"严重的；重大的","ex":{"en":"The leaking pipe caused serious damage to our kitchen.","zh":"漏水的管道给我们的厨房造成了严重损坏。"},"tip":"serious about 后接名词或动名词，表示认真对待。","topic":"daily","cefr":"A2"},{"w":"comfortable","uk":"/ˈkʌmftəbl/","p":"adj.","zh":"舒适的；舒服的","ex":{"en":"This soft chair is comfortable enough for an afternoon nap.","zh":"这把柔软的椅子很舒服，足以让人午睡一会儿。"},"tip":"comfortable指舒服；convenient指方便。","topic":"daily","cefr":"A2"},{"w":"active","uk":"/ˈæk.tɪv/","p":"adj.","zh":"活跃的；积极参与的","ex":{"en":"My grandfather stays active by swimming every morning.","zh":"我祖父每天早晨游泳，保持活力。"},"tip":"active指积极活动或参与；不等于表示乐观的positive。","topic":"health","cefr":"A2"},{"w":"climbing","uk":"/ˈklaɪmɪŋ/","p":"n.","zh":"攀岩；登山运动","ex":{"en":"I tried indoor climbing with my sister yesterday.","zh":"昨天我和姐姐尝试了室内攀岩。"},"tip":"climb中的b不发音；climbing plants指攀缘植物。","topic":"sport","cefr":"A2"},{"w":"tour","uk":"/tʊə/","p":"n.","zh":"游览；参观；巡游","ex":{"en":"We took a guided tour of the old castle.","zh":"我们在导游带领下参观了那座古堡。"},"tip":"tour强调参观或多站行程；trip泛指一次出行。","topic":"travel","cefr":"A2"},{"w":"apartment","uk":"/əˈpɑːtmənt/","p":"n.","zh":"公寓；套房","ex":{"en":"Our apartment has a small balcony overlooking the park.","zh":"我们的公寓有一个面向公园的小阳台。"},"tip":"美式常用apartment，英式日常多用flat。","topic":"city","cefr":"A2"},{"w":"among","uk":"/əˈmʌŋ/","p":"prep.","zh":"在……中间","ex":{"en":"We found a small wooden house among the trees.","zh":"我们在树林中发现了一座小木屋。"},"tip":"among强调群体内部；between也可用于多者的明确关系。","topic":"daily","cefr":"A2"},{"w":"toast","uk":"/təʊst/","p":"n.","zh":"烤面包片","ex":{"en":"I spread butter on my toast while it was warm.","zh":"我趁烤面包片还热着，在上面抹了黄油。"},"tip":"表示烤面包时不可数；表示一次祝酒时可数。","topic":"daily","cefr":"A2"},{"w":"couch","uk":"/kaʊtʃ/","p":"n.","zh":"长沙发","ex":{"en":"We curled up on the couch after dinner.","zh":"晚饭后，我们蜷坐在沙发上。"},"tip":"动词常用be couched in，指以某种措辞表达。","topic":"daily","cefr":"A2"},{"w":"field","uk":"/fiːld/","p":"n.","zh":"田地；牧场","ex":{"en":"We watched sheep grazing in the field behind our cottage.","zh":"我们看着羊群在小屋后面的牧场上吃草。"},"tip":"表示研究或工作领域时，常用in the field of。","topic":"nature","cefr":"A2"},{"w":"online","uk":"/ˌɒnˈlaɪn/","p":"adj.","zh":"网上的；联网的","ex":{"en":"I booked our train tickets online after dinner.","zh":"晚饭后，我在网上订了我们的火车票。"},"tip":"既可作形容词，也可作副词：shop online。","topic":"technology","cefr":"A2"},{"w":"armchair","uk":"/ˈɑːmtʃeə(r)/","p":"n.","zh":"扶手椅","ex":{"en":"Grandpa fell asleep in his armchair beside the window.","zh":"爷爷在窗边的扶手椅上睡着了。"},"tip":"坐在扶手椅里用in；作形容词时置于名词前，常含贬义。","topic":"daily","cefr":"A2"},{"w":"musician","uk":"/mjuˈzɪʃən/","p":"n.","zh":"音乐家；乐手","ex":{"en":"A musician played the violin outside the station.","zh":"一位乐手在车站外拉小提琴。"},"tip":"musician指音乐人；作曲家更具体地用composer。","topic":"arts","cefr":"A2"},{"w":"since","uk":"/sɪns/","p":"prep.","zh":"自……以来","ex":{"en":"I have lived in this neighbourhood since childhood.","zh":"我从小就住在这个街区。"},"tip":"表时间时，since接起点，for接时长。","topic":"daily","cefr":"A2"},{"w":"church","uk":"/tʃɜːtʃ/","p":"n.","zh":"教堂","ex":{"en":"The old church has beautiful windows and a stone tower.","zh":"这座古老的教堂有漂亮的窗户和一座石塔。"},"tip":"go to church指做礼拜；go to the church指去教堂。","topic":"society","cefr":"A2"},{"w":"firefighter","uk":"/ˈfaɪəfaɪtə/","p":"n.","zh":"消防员","ex":{"en":"The firefighter showed us how to use the hose.","zh":"那位消防员向我们演示了如何使用消防水带。"},"tip":"firefighter不区分性别，比fireman更通用。","topic":"work","cefr":"A2"},{"w":"palace","uk":"/ˈpæləs/","p":"n.","zh":"王宫；高级官邸","ex":{"en":"We walked through the palace gardens before lunch.","zh":"午饭前，我们在王宫花园里散了步。"},"tip":"主要用作名词；palace gardens中作名词定语。","topic":"history","cefr":"A2"},{"w":"bridge","uk":"/brɪdʒ/","p":"n.","zh":"桥；桥梁","ex":{"en":"We crossed the wooden bridge and entered the village.","zh":"我们走过木桥，进了村子。"},"tip":"bridge the gap常指缩小群体或事物间的差距。","topic":"city","cefr":"A2"},{"w":"eating","uk":"/ˈiːtɪŋ/","p":"n.","zh":"进食；饮食","ex":{"en":"Healthy eating starts with small changes to your meals.","zh":"健康饮食始于对日常餐食的小调整。"},"tip":"eating可作动名词；eat out表示外出就餐。","topic":"health","cefr":"A2"},{"w":"tip","uk":"/tɪp/","p":"n.","zh":"实用建议；窍门","ex":{"en":"My neighbour shared a useful tip for growing tomatoes.","zh":"邻居分享了一个种番茄的实用窍门。"},"tip":"tip作“建议”可数，advice不可数：a tip。","topic":"daily","cefr":"A2"},{"w":"technology","uk":"/tekˈnɒlədʒi/","p":"n.","zh":"技术；科技","ex":{"en":"New technology lets us control the lights from our phones.","zh":"新技术让我们可以用手机控制灯光。"},"tip":"泛指科技时不可数；多种具体技术可用technologies。","topic":"technology","cefr":"A2"},{"w":"path","uk":"/pɑːθ/","p":"n.","zh":"小路；小径","ex":{"en":"We followed a narrow path down to the beach.","zh":"我们沿着一条狭窄的小路走向海滩。"},"tip":"表示实现目标的途径，用a path to，to后接名词。","topic":"travel","cefr":"A2"},{"w":"system","uk":"/ˈsɪstəm/","p":"n.","zh":"系统","ex":{"en":"The heating system stopped working during a cold night.","zh":"在一个寒冷的夜晚，供暖系统停止了运行。"},"tip":"systematic指有条理的，systemic指全系统的。","topic":"technology","cefr":"A2"},{"w":"northeast","uk":"/ˌnɔːθˈiːst/","p":"n.","zh":"东北；东北部","ex":{"en":"The storm is moving northeast towards the coastal villages.","zh":"暴风雨正向东北方向的沿海村庄移动。"},"tip":"northeast of表示在……东北方；英式也写north-east。","topic":"travel","cefr":"A2"},{"w":"centimetre","uk":"/ˈsentɪmiːtə/","p":"n.","zh":"厘米；公分","ex":{"en":"This little plant grew one centimetre in a week.","zh":"这株小植物一周长高了一厘米。"},"tip":"英式拼写centimetre，美式centimeter；缩写cm。","topic":"science","cefr":"A2"},{"w":"biology","uk":"/baɪˈɒlədʒi/","p":"n.","zh":"生物学","ex":{"en":"We examined onion cells under microscopes in biology today.","zh":"今天的生物课上，我们用显微镜观察了洋葱细胞。"},"tip":"学科名称，通常不可数；生物学家是biologist。","topic":"science","cefr":"A2"},{"w":"painter","uk":"/ˈpeɪntə/","p":"n.","zh":"画家","ex":{"en":"The painter mixed blue and green on her palette.","zh":"画家在调色板上混合蓝色和绿色。"},"tip":"既可指艺术画家，也可指刷墙的油漆工。","topic":"arts","cefr":"A2"},{"w":"balloon","uk":"/bəˈluːn/","p":"n.","zh":"气球","ex":{"en":"A yellow balloon floated above the birthday cake.","zh":"一只黄色气球飘在生日蛋糕上方。"},"tip":"blow up a balloon指吹气球，不是炸毁气球。","topic":"daily","cefr":"A2"},{"w":"successful","uk":"/səkˈsesfəl/","p":"adj.","zh":"成功的；有成效的","ex":{"en":"Our first attempt at baking bread was surprisingly successful.","zh":"我们第一次尝试烤面包，出乎意料地成功了。"},"tip":"常用be successful in doing；动词为succeed。","topic":"work","cefr":"A2"},{"w":"subject","uk":"/ˈsʌbdʒɪkt/","p":"n.","zh":"话题；主题；学科","ex":{"en":"Science was my favourite subject when I was younger.","zh":"我小时候最喜欢的学科是科学。"},"tip":"动词重音在后：/səbˈdʒekt/；常用subject A to B。","topic":"education","cefr":"A2"},{"w":"crazy","uk":"/ˈkreɪzi/","p":"adj.","zh":"荒唐的；不理智的","ex":{"en":"It seems crazy to wear sandals in this snow.","zh":"下着这样的雪还穿凉鞋，实在很不明智。"},"tip":"偏口语；crazy about表示着迷，不宜用来称呼精神疾病患者。","topic":"emotion","cefr":"A2"},{"w":"couple","uk":"/ˈkʌpəl/","p":"n.","zh":"夫妇；情侣","ex":{"en":"The couple next door invited us over for dinner.","zh":"隔壁那对夫妇邀请我们去吃晚饭。"},"tip":"a couple of后接复数名词，可指两个或少数几个。","topic":"society","cefr":"A2"},{"w":"scared","uk":"/skeəd/","p":"adj.","zh":"害怕的；恐惧的","ex":{"en":"The puppy looked scared when it heard the thunder.","zh":"小狗听到雷声时显得很害怕。"},"tip":"scared形容感到害怕；scary形容令人害怕。","topic":"emotion","cefr":"A2"},{"w":"lower","uk":"/ˈləʊə/","p":"adj.","zh":"较低的；较下方的","ex":{"en":"Keep the heavy bowls on the lower shelf.","zh":"把重碗放在下面那层架子上。"},"tip":"lower作动词通常接宾语；表示物价下降也可不及物。","topic":"daily","cefr":"A2"},{"w":"coin","uk":"/kɔɪn/","p":"n.","zh":"硬币","ex":{"en":"A silver coin rolled under the kitchen table.","zh":"一枚银色硬币滚到了厨房桌子下面。"},"tip":"coin作动词常指创造词语，如coin a term。","topic":"economy","cefr":"A2"},{"w":"skill","uk":"/skɪl/","p":"n.","zh":"技能；技巧；本领","ex":{"en":"Baking good bread takes patience and a little skill.","zh":"烤出好面包需要耐心和一点技巧。"},"tip":"具体技能可数；泛指熟练程度时常不可数。","topic":"work","cefr":"A2"},{"w":"kite","uk":"/kaɪt/","p":"n.","zh":"风筝","ex":{"en":"We flew a bright kite on the windy beach.","zh":"我们在风大的海滩上放了一只色彩鲜艳的风筝。"},"tip":"“放风筝”用 fly a kite，不用 play a kite。","topic":"daily","cefr":"A2"},{"w":"action","uk":"/ˈækʃən/","p":"n.","zh":"行动；措施","ex":{"en":"We need to take action before the leak worsens.","zh":"我们得在漏水加重之前采取行动。"},"tip":"take action中的action不可数；具体举动可用actions。","topic":"society","cefr":"A2"},{"w":"built","uk":"/bɪlt/","p":"v.","zh":"建造；建立（过去式及分词）","ex":{"en":"We built a small shelter for the garden tools.","zh":"我们搭了一个小棚子，用来存放园艺工具。"},"tip":"build的过去式、过去分词均为built，不是builded。","topic":"city","cefr":"A2"},{"w":"depend","uk":"/dɪˈpend/","p":"v.","zh":"取决于","ex":{"en":"Our weekend plans depend on how the weather turns out.","zh":"我们周末的安排取决于天气怎么样。"},"tip":"常接on或upon；It depends意为“看情况”。","topic":"daily","cefr":"A2"},{"w":"mid-day","uk":"/ˌmɪdˈdeɪ/","p":"n.","zh":"中午；正午","ex":{"en":"We stopped for lunch at mid-day beside the river.","zh":"中午，我们在河边停下来吃午饭。"},"tip":"现代英语通常写midday；在正午用at midday。","topic":"daily","cefr":"A2"},{"w":"joke","uk":"/dʒəʊk/","p":"n.","zh":"笑话；玩笑","ex":{"en":"My brother told a joke that made everyone laugh.","zh":"我哥哥讲了个笑话，把大家都逗笑了。"},"tip":"讲笑话用tell a joke，不用say a joke。","topic":"daily","cefr":"A2"},{"w":"guest","uk":"/ɡest/","p":"n.","zh":"客人；受邀嘉宾","ex":{"en":"Each guest brought a dish to share at dinner.","zh":"每位客人都带了一道菜，在晚餐时与大家分享。"},"tip":"guest可指受邀客人，也可指付费的酒店住客。","topic":"daily","cefr":"A2"},{"w":"screen","uk":"/skriːn/","p":"n.","zh":"屏幕；银幕","ex":{"en":"I wiped the fingerprints off my laptop screen.","zh":"我擦掉了笔记本电脑屏幕上的指纹。"},"tip":"screen A for B表示检查A是否存在B问题。","topic":"technology","cefr":"A2"},{"w":"dishwasher","uk":"/ˈdɪʃwɒʃə/","p":"n.","zh":"洗碗机","ex":{"en":"Please load the dishwasher after you finish your lunch.","zh":"午饭吃完后，请把餐具放进洗碗机。"},"tip":"日常多指洗碗机；招聘语境中也可指洗碗工。","topic":"daily","cefr":"A2"},{"w":"completely","uk":"/kəmˈpliːtli/","p":"adv.","zh":"完全地；彻底地","ex":{"en":"My shoes were completely wet after walking through the rain.","zh":"在雨中走过之后，我的鞋全湿透了。"},"tip":"表示程度达到全部，常修饰形容词或动词。","topic":"daily","cefr":"A2"},{"w":"partner","uk":"/ˈpɑːtnə/","p":"n.","zh":"搭档；合作伙伴；合伙人","ex":{"en":"My dance partner waited patiently while I practised.","zh":"我练习时，我的舞伴耐心地等着。"},"tip":"partner不表明性别；作动词常用partner with。","topic":"work","cefr":"A2"},{"w":"badminton","uk":"/ˈbædmɪntən/","p":"n.","zh":"羽毛球运动","ex":{"en":"We play badminton at the sports centre every Saturday.","zh":"我们每周六都在体育中心打羽毛球。"},"tip":"运动名通常不可数；“打羽毛球”用play badminton。","topic":"sport","cefr":"A2"},{"w":"nobody","uk":"/ˈnəʊbədi/","p":"pron.","zh":"没有人","ex":{"en":"Nobody noticed the kitten sleeping behind the sofa.","zh":"没人注意到睡在沙发后面的小猫。"},"tip":"作主语时谓语用单数；本身含否定意义。","topic":"daily","cefr":"A2"},{"w":"coast","uk":"/kəʊst/","p":"n.","zh":"海岸；海滨","ex":{"en":"We walked along the coast and collected smooth stones.","zh":"我们沿着海岸散步，捡了一些光滑的石头。"},"tip":"on the coast指在海边；off the coast指在近海。","topic":"nature","cefr":"A2"},{"w":"enter","uk":"/ˈentə/","p":"v.","zh":"进入","ex":{"en":"Please wipe your shoes before you enter the kitchen.","zh":"进入厨房前，请把鞋底擦干净。"},"tip":"进入某地用enter a place，不加into。","topic":"daily","cefr":"A2"},{"w":"castle","uk":"/ˈkɑːsəl/","p":"n.","zh":"城堡","ex":{"en":"We climbed the hill to explore the old castle.","zh":"我们爬上山丘，去探索那座古堡。"},"tip":"castle中的t不发音；palace指宫殿。","topic":"history","cefr":"A2"},{"w":"awful","uk":"/ˈɔːfəl/","p":"adj.","zh":"糟糕的；令人难受的","ex":{"en":"The soup tasted awful, so I made a sandwich.","zh":"这汤太难喝了，所以我做了个三明治。"},"tip":"feel awful可指身体难受，也可指内疚或心情差。","topic":"daily","cefr":"A2"},{"w":"text","uk":"/tekst/","p":"n.","zh":"文字；文本","ex":{"en":"The text on this menu is too small.","zh":"这份菜单上的字太小了。"},"tip":"文字内容通常不可数；一条短信可说a text。","topic":"media","cefr":"A2"},{"w":"result","uk":"/rɪˈzʌlt/","p":"n.","zh":"结果；后果","ex":{"en":"The shiny floor was the result of hours of cleaning.","zh":"这光亮的地板是花了好几个小时打扫的成果。"},"tip":"result in后接结果；result from后接原因。","topic":"thinking","cefr":"A2"},{"w":"bathtub","uk":"/ˈbɑːθtʌb/","p":"n.","zh":"浴缸","ex":{"en":"The kitten watched water dripping into the empty bathtub.","zh":"小猫看着水滴进空浴缸。"},"tip":"bathtub尤常用于美式英语；英式常说bath。","topic":"daily","cefr":"A2"},{"w":"mailbox","uk":"/ˈmeɪlbɒks/","p":"n.","zh":"信箱；邮筒","ex":{"en":"A postcard from my cousin arrived in our mailbox.","zh":"表亲寄来的一张明信片到了我们家的信箱里。"},"tip":"美式常用词；英式常用letterbox或postbox。","topic":"daily","cefr":"A2"},{"w":"habit","uk":"/ˈhæbɪt/","p":"n.","zh":"习惯；习性","ex":{"en":"Checking my phone before breakfast has become a habit.","zh":"早餐前查看手机已经成了我的习惯。"},"tip":"表示做某事的习惯，用habit of doing。","topic":"daily","cefr":"A2"},{"w":"rock","uk":"/rɒk/","p":"n.","zh":"岩石；石块","ex":{"en":"We sat on a flat rock beside the river.","zh":"我们坐在河边一块平坦的岩石上。"},"tip":"rock 作岩石材料不可数；指一块石头时可数。","topic":"nature","cefr":"A2"},{"w":"driving","uk":"/ˈdraɪvɪŋ/","p":"n.","zh":"驾驶；驾车方式","ex":{"en":"Her careful driving made the mountain journey feel safe.","zh":"她开车很谨慎，让这段山路旅程令人安心。"},"tip":"driving force意为推动力；driving也可作drive的现在分词。","topic":"travel","cefr":"A2"},{"w":"keyboard","uk":"/ˈkiːbɔːd/","p":"n.","zh":"电脑键盘","ex":{"en":"I brushed the crumbs off my keyboard before starting work.","zh":"开始工作前，我把键盘上的碎屑刷掉了。"},"tip":"电脑键盘常说a keyboard；演奏键盘乐器用play the keyboard。","topic":"technology","cefr":"A2"},{"w":"drawer","uk":"/drɔː/","p":"n.","zh":"抽屉","ex":{"en":"I keep spare keys in the top kitchen drawer.","zh":"我把备用钥匙放在厨房最上面的抽屉里。"},"tip":"抽屉是drawer；衣橱是wardrobe。","topic":"daily","cefr":"A2"},{"w":"rubber","uk":"/ˈrʌbə/","p":"n.","zh":"橡胶","ex":{"en":"These rubber boots keep my feet dry in puddles.","zh":"这双橡胶靴让我踩水坑时双脚也不会湿。"},"tip":"橡胶不可数；橡皮擦可数，美式英语通常用eraser。","topic":"daily","cefr":"A2"},{"w":"mix","uk":"/mɪks/","p":"v.","zh":"混合；拌和","ex":{"en":"Mix the flour and eggs in a large bowl.","zh":"把面粉和鸡蛋放进大碗里拌匀。"},"tip":"mix A with B指混合；mix A up with B指混淆。","topic":"daily","cefr":"A2"},{"w":"electricity","uk":"/ɪˌlekˈtrɪsəti/","p":"n.","zh":"电；电力","ex":{"en":"The storm cut off electricity to our entire street.","zh":"暴风雨导致我们整条街停电了。"},"tip":"electricity不可数；electric多指用电的，electrical指电相关的。","topic":"science","cefr":"A2"},{"w":"product","uk":"/ˈprɒdʌkt/","p":"n.","zh":"产品；制品","ex":{"en":"This cleaning product removes stains from my kitchen tiles.","zh":"这款清洁产品能去除我家厨房瓷砖上的污渍。"},"tip":"product是产品或结果，production是生产过程。","topic":"economy","cefr":"A2"},{"w":"zebra","uk":"/ˈzebrə/","p":"n.","zh":"斑马","ex":{"en":"A zebra stood quietly beside the watering hole.","zh":"一匹斑马静静地站在水塘旁。"},"tip":"zebra crossing 是英式英语中的斑马线。","topic":"nature","cefr":"A2"},{"w":"shampoo","uk":"/ʃæmˈpuː/","p":"n.","zh":"洗发水","ex":{"en":"I packed a small bottle of shampoo for our trip.","zh":"我为这次旅行装了一小瓶洗发水。"},"tip":"泛指洗发水通常不可数；一瓶用a bottle of shampoo。","topic":"daily","cefr":"A2"},{"w":"lab","uk":"/læb/","p":"n.","zh":"实验室","ex":{"en":"We wore safety goggles while mixing liquids in the lab.","zh":"我们在实验室混合液体时戴着护目镜。"},"tip":"lab是laboratory的常用缩写，二者均为可数名词。","topic":"science","cefr":"A2"},{"w":"surprised","uk":"/səˈpraɪzd/","p":"adj.","zh":"惊讶的；感到意外的","ex":{"en":"I was surprised to find flowers outside my door.","zh":"发现门外放着鲜花，我很惊讶。"},"tip":"surprised形容人的感受；surprising形容事物令人惊讶。","topic":"emotion","cefr":"A2"},{"w":"heater","uk":"/ˈhiːtə/","p":"n.","zh":"加热器；取暖器","ex":{"en":"We switched on the heater before the guests arrived.","zh":"客人到来前，我们打开了取暖器。"},"tip":"heater是设备；heating指供暖或供暖系统。","topic":"daily","cefr":"A2"},{"w":"lawyer","uk":"/ˈlɔɪə/","p":"n.","zh":"律师","ex":{"en":"Our lawyer explained the contract before we signed it.","zh":"我们的律师在我们签字前解释了合同内容。"},"tip":"lawyer是律师的统称，区别于法官judge。","topic":"society","cefr":"A2"},{"w":"store","uk":"/stɔː/","p":"n.","zh":"商店","ex":{"en":"The store near our house sells fresh bread.","zh":"我们家附近的商店卖新鲜面包。"},"tip":"商店在美式中常用store，英式日常更常用shop。","topic":"daily","cefr":"A2"},{"w":"wheel","uk":"/wiːl/","p":"n.","zh":"轮子；车轮","ex":{"en":"The front wheel of my bicycle needs replacing.","zh":"我的自行车前轮需要更换。"},"tip":"at或behind the wheel常表示正在开车。","topic":"travel","cefr":"A2"},{"w":"item","uk":"/ˈaɪtəm/","p":"n.","zh":"一件物品；一件商品","ex":{"en":"Please place each item carefully in the shopping bag.","zh":"请把每件商品小心地放进购物袋。"},"tip":"item是可数名词；一件衣物可说an item of clothing。","topic":"daily","cefr":"A2"},{"w":"receptionist","uk":"/rɪˈsepʃənɪst/","p":"n.","zh":"接待员；前台人员","ex":{"en":"The receptionist smiled and handed us our room keys.","zh":"接待员微笑着把房间钥匙递给了我们。"},"tip":"reception 是接待处；receptionist 是接待员。","topic":"work","cefr":"A2"},{"w":"salesman","uk":"/ˈseɪlzmən/","p":"n.","zh":"男销售员；男推销员","ex":{"en":"The salesman showed us how to fold the bicycle.","zh":"那位男销售员向我们演示了如何折叠自行车。"},"tip":"salesman明确指男性；不强调性别时用salesperson。","topic":"work","cefr":"A2"},{"w":"fantastic","uk":"/fænˈtæstɪk/","p":"adj.","zh":"极好的；出色的","ex":{"en":"We had a fantastic view of the mountains from our balcony.","zh":"从阳台望去，山景美极了。"},"tip":"表示“极好的”偏口语；正式写作可用excellent。","topic":"emotion","cefr":"A2"},{"w":"running","uk":"/ˈrʌnɪŋ/","p":"n.","zh":"跑步","ex":{"en":"Running along the beach always clears my head.","zh":"沿着海滩跑步总能让我头脑清醒。"},"tip":"表示跑步活动时不可数；the running of指管理。","topic":"sport","cefr":"A2"},{"w":"gate","uk":"/ɡeɪt/","p":"n.","zh":"大门；栅栏门","ex":{"en":"She closed the garden gate to keep the dog inside.","zh":"她关上花园的门，免得狗跑出去。"},"tip":"gate多指围墙或栅栏上的门；房间的门通常用door。","topic":"travel","cefr":"A2"},{"w":"title","uk":"/ˈtaɪtəl/","p":"n.","zh":"标题；书名；名称","ex":{"en":"I remember the book's cover but not its title.","zh":"我记得这本书的封面，却不记得书名了。"},"tip":"title是标题或名称；topic是讨论的主题。","topic":"education","cefr":"A2"},{"w":"platform","uk":"/ˈplætfɔːm/","p":"n.","zh":"站台；月台","ex":{"en":"We waited on the platform as the train approached.","zh":"火车驶近时，我们正在站台上等候。"},"tip":"在站台上用on the platform，不用in。","topic":"travel","cefr":"A2"},{"w":"parking","uk":"/ˈpɑːkɪŋ/","p":"n.","zh":"停车；泊车","ex":{"en":"Parking is difficult on this narrow street after sunset.","zh":"日落后，在这条狭窄的街道上停车很困难。"},"tip":"名词通常不可数；一个停车位说a parking space。","topic":"city","cefr":"A2"},{"w":"replace","uk":"/rɪˈpleɪs/","p":"v.","zh":"替换；取代；更换","ex":{"en":"We need to replace the broken kitchen chair.","zh":"我们需要换掉厨房里那把坏椅子。"},"tip":"replace A with B是用B换掉A，别弄反方向。","topic":"daily","cefr":"A2"},{"w":"yard","uk":"/jɑːd/","p":"n.","zh":"院子；庭院","ex":{"en":"Our dog chased a yellow ball across the yard.","zh":"我们的狗追着一个黄色的球跑过院子。"},"tip":"美式yard可指住宅草坪庭院；英式多用garden。","topic":"daily","cefr":"A2"},{"w":"printer","uk":"/ˈprɪntə/","p":"n.","zh":"打印机","ex":{"en":"The printer ran out of paper halfway through my homework.","zh":"我的作业打印到一半时，打印机没纸了。"},"tip":"print是打印；printer可指机器，也可指印刷从业者。","topic":"technology","cefr":"A2"},{"w":"land","uk":"/lænd/","p":"n.","zh":"陆地；土地","ex":{"en":"After hours at sea, we finally spotted dry land.","zh":"在海上航行数小时后，我们终于看到了陆地。"},"tip":"表示土地通常不可数；land a job指成功获得工作。","topic":"nature","cefr":"A2"},{"w":"businessman","uk":"/ˈbɪznəsmæn/","p":"n.","zh":"商人；男企业家","ex":{"en":"A local businessman opened a bakery near our school.","zh":"一位当地商人在我们学校附近开了一家面包店。"},"tip":"复数为businessmen；不限定性别可用businessperson。","topic":"work","cefr":"A2"},{"w":"glad","uk":"/ɡlæd/","p":"adj.","zh":"高兴的；欣慰的","ex":{"en":"I'm glad you came to dinner with us tonight.","zh":"我很高兴你今晚来和我们一起吃饭。"},"tip":"常作表语；用be glad to do或be glad that从句。","topic":"emotion","cefr":"A2"},{"w":"shine","uk":"/ʃaɪn/","p":"v.","zh":"发光；照耀","ex":{"en":"The sun shone through my bedroom window this morning.","zh":"今天早上，阳光透过我卧室的窗户照了进来。"},"tip":"发光的过去式常用shone；擦亮的过去式用shined。","topic":"daily","cefr":"A2"},{"w":"pear","uk":"/peə/","p":"n.","zh":"梨","ex":{"en":"She sliced a ripe pear into her breakfast bowl.","zh":"她把一个熟梨切成片，放进早餐碗里。"},"tip":"pear与pair同音；一个梨用a pear。","topic":"daily","cefr":"A2"},{"w":"comedy","uk":"/ˈkɒmədi/","p":"n.","zh":"喜剧；喜剧作品","ex":{"en":"We watched a comedy and laughed all evening.","zh":"我们看了一部喜剧，整个晚上都笑个不停。"},"tip":"指喜剧类型时通常不可数；一部喜剧用a comedy。","topic":"arts","cefr":"A2"},{"w":"immediately","uk":"/ɪˈmiːdiətli/","p":"adv.","zh":"立即；马上","ex":{"en":"When the doorbell rang, I immediately opened the door.","zh":"门铃一响，我就立刻打开了门。"},"tip":"作连词表示“一……就”主要见于英式英语。","topic":"daily","cefr":"A2"},{"w":"freezer","uk":"/ˈfriːzə/","p":"n.","zh":"冷冻柜；冷冻室","ex":{"en":"Put the ice cream back in the freezer.","zh":"把冰激凌放回冷冻室。"},"tip":"freezer用于冷冻；fridge主要用于冷藏。","topic":"daily","cefr":"A2"},{"w":"rucksack","uk":"/ˈrʌksæk/","p":"n.","zh":"双肩背包","ex":{"en":"I packed my lunch and jacket in a rucksack.","zh":"我把午餐和夹克装进了双肩背包。"},"tip":"英式英语常用rucksack；不限定帆布材质。","topic":"travel","cefr":"A2"},{"w":"essay","uk":"/ˈeseɪ/","p":"n.","zh":"论说文；短文；随笔","ex":{"en":"I finished my history essay just before dinner.","zh":"我刚好在晚饭前写完了历史课论文。"},"tip":"可数名词；一篇关于某主题的文章用an essay on。","topic":"education","cefr":"A2"},{"w":"pub","uk":"/pʌb/","p":"n.","zh":"酒馆；酒吧","ex":{"en":"We had vegetable soup at the village pub.","zh":"我们在村里的酒馆喝了蔬菜汤。"},"tip":"pub多见于英国语境，常供应餐食，不等于旅馆。","topic":"daily","cefr":"A2"},{"w":"kid","uk":"/kɪd/","p":"n.","zh":"小孩；孩子","ex":{"en":"The kids built a tiny bridge across the stream.","zh":"孩子们在小溪上搭了一座小桥。"},"tip":"kid较口语；正式作文中“孩子”宜用child。","topic":"daily","cefr":"A2"},{"w":"manage","uk":"/ˈmænɪdʒ/","p":"v.","zh":"设法做到","ex":{"en":"I managed to carry all the bags upstairs.","zh":"我总算把所有袋子都提上了楼。"},"tip":"manage to do表示成功做成，不只是尝试。","topic":"work","cefr":"A2"},{"w":"circus","uk":"/ˈsɜːkəs/","p":"n.","zh":"马戏团；马戏表演","ex":{"en":"We watched the circus performers juggle brightly coloured balls.","zh":"我们看着马戏演员抛接色彩鲜艳的球。"},"tip":"可指马戏团或表演；复数为circuses。","topic":"arts","cefr":"A2"},{"w":"tourist","uk":"/ˈtʊərɪst/","p":"n.","zh":"游客；观光者","ex":{"en":"A tourist asked me how to reach the castle.","zh":"一位游客问我怎么去城堡。"},"tip":"tourist通常是名词，在tourist attraction中修饰名词。","topic":"travel","cefr":"A2"},{"w":"fork","uk":"/fɔːk/","p":"n.","zh":"餐叉；叉子","ex":{"en":"She picked up a carrot with her fork.","zh":"她用餐叉叉起了一块胡萝卜。"},"tip":"道路forks表示分叉；a fork in the road指岔路口。","topic":"daily","cefr":"A2"},{"w":"waste","uk":"/weɪst/","p":"v.","zh":"浪费","ex":{"en":"Don't waste water by leaving the tap running.","zh":"别让水龙头一直开着，白白浪费水。"},"tip":"用waste time doing sth，通常不用to do。","topic":"environment","cefr":"A2"},{"w":"president","uk":"/ˈprezɪdənt/","p":"n.","zh":"总统","ex":{"en":"The president waved to the crowd outside the palace.","zh":"总统向宫殿外的人群挥手致意。"},"tip":"可指总统，也可指机构负责人；具体译法看语境。","topic":"government","cefr":"A2"},{"w":"barber","uk":"/ˈbɑːbə/","p":"n.","zh":"理发师（主要为男士）","ex":{"en":"The barber trimmed my hair before the wedding.","zh":"婚礼前，理发师给我修剪了头发。"},"tip":"barber主要为男士理发修面；barber's可指理发店。","topic":"work","cefr":"A2"},{"w":"asleep","uk":"/əˈsliːp/","p":"adj.","zh":"睡着的","ex":{"en":"The baby was asleep before we reached home.","zh":"我们还没到家，宝宝就睡着了。"},"tip":"asleep通常作表语；“熟睡的婴儿”用a sleeping baby。","topic":"health","cefr":"A2"},{"w":"reporter","uk":"/rɪˈpɔːtə/","p":"n.","zh":"记者","ex":{"en":"A reporter interviewed the coach after the match.","zh":"比赛结束后，一名记者采访了教练。"},"tip":"reporter侧重新闻采访报道；journalist涵盖范围更广。","topic":"media","cefr":"A2"},{"w":"queen","uk":"/kwiːn/","p":"n.","zh":"女王；王后","ex":{"en":"The queen waved to the crowd from her carriage.","zh":"女王从马车里向人群挥手。"},"tip":"queen 可指统治国家的女王，也可指国王的妻子。","topic":"government","cefr":"A2"},{"w":"teaching","uk":"/ˈtiːtʃɪŋ/","p":"n.","zh":"教学；教师职业","ex":{"en":"Her love of teaching began at a small village school.","zh":"她对教学的热爱始于一所小乡村学校。"},"tip":"指教学时不可数；指教义或学说常用teachings。","topic":"education","cefr":"A2"},{"w":"physics","uk":"/ˈfɪzɪks/","p":"n.","zh":"物理学","ex":{"en":"Our physics teacher showed us how magnets attract iron.","zh":"我们的物理老师演示了磁铁如何吸引铁。"},"tip":"虽以s结尾，仍作不可数名词，谓语用单数。","topic":"science","cefr":"A2"},{"w":"check-out","uk":"/ˈtʃek aʊt/","p":"n.","zh":"结账离店；退房","ex":{"en":"We left our bags at reception after check-out.","zh":"退房后，我们把行李留在了前台。"},"tip":"名词也写作checkout；动词用check out。","topic":"travel","cefr":"A2"},{"w":"develop","uk":"/dɪˈveləp/","p":"v.","zh":"发展；成长；培养","ex":{"en":"Children develop confidence when they try new activities.","zh":"孩子们尝试新活动时会逐渐建立自信。"},"tip":"可及物也可不及物：develop skills；skills develop。","topic":"education","cefr":"A2"},{"w":"jogging","uk":"/ˈdʒɒɡɪŋ/","p":"n.","zh":"慢跑","ex":{"en":"She goes jogging around the park before breakfast.","zh":"她早饭前会绕着公园慢跑。"},"tip":"jog变为jogging时须双写g。","topic":"sport","cefr":"A2"},{"w":"prepare","uk":"/prɪˈpeə/","p":"v.","zh":"准备；做好准备","ex":{"en":"I prepare my lunch before leaving home each morning.","zh":"我每天早上出门前都会准备好午餐。"},"tip":"prepare for后接名词；prepare to后接动词原形。","topic":"daily","cefr":"A2"},{"w":"mug","uk":"/mʌɡ/","p":"n.","zh":"大柄杯；马克杯","ex":{"en":"I warmed my hands around a mug of tea.","zh":"我双手捧着一大杯茶取暖。"},"tip":"mug通常有柄、较大；作动词可指拦路抢劫。","topic":"daily","cefr":"A2"},{"w":"sand","uk":"/sænd/","p":"n.","zh":"沙；沙子","ex":{"en":"The children built a castle from wet sand.","zh":"孩子们用湿沙堆了一座城堡。"},"tip":"表示沙子时不可数；一粒沙用a grain of sand。","topic":"nature","cefr":"A2"},{"w":"raincoat","uk":"/ˈreɪnkəʊt/","p":"n.","zh":"雨衣","ex":{"en":"I grabbed my raincoat before stepping into the rain.","zh":"走进雨中之前，我一把拿起了雨衣。"},"tip":"英美英语都使用raincoat，并非仅限美式。","topic":"daily","cefr":"A2"},{"w":"diary","uk":"/ˈdaɪəri/","p":"n.","zh":"日记；日记簿","ex":{"en":"I write in my diary before going to bed.","zh":"我睡前会写日记。"},"tip":"diary是日记，dairy是乳制品；注意字母顺序。","topic":"daily","cefr":"A2"},{"w":"motorcycle","uk":"/ˈməʊtəsaɪkəl/","p":"n.","zh":"摩托车","ex":{"en":"He parked his motorcycle beside the garden gate.","zh":"他把摩托车停在花园门旁。"},"tip":"骑摩托车用ride，通常不用drive。","topic":"travel","cefr":"A2"},{"w":"hold","uk":"/həʊld/","p":"v.","zh":"握住；拿着","ex":{"en":"Could you hold my bag while I tie my shoes?","zh":"我系鞋带时，你能帮我拿一下包吗？"},"tip":"过去式、过去分词均为held；举行会议用hold。","topic":"daily","cefr":"A2"},{"w":"reception","uk":"/rɪˈsepʃən/","p":"n.","zh":"接待处；服务台","ex":{"en":"Please leave your room key at reception before breakfast.","zh":"请在早餐前把房间钥匙留在前台。"},"tip":"英式英语常说at reception，表示在接待处。","topic":"travel","cefr":"A2"},{"w":"foreign","uk":"/ˈfɒrən/","p":"adj.","zh":"外国的；来自国外的","ex":{"en":"My sister enjoys learning foreign languages in her spare time.","zh":"我姐姐喜欢在空闲时间学习外语。"},"tip":"foreign to可指对某人陌生，或与某事不相符。","topic":"travel","cefr":"A2"},{"w":"earth","uk":"/ɜːθ/","p":"n.","zh":"地球","ex":{"en":"The children dug into the damp earth with small spades.","zh":"孩子们用小铲子挖开湿润的泥土。"},"tip":"指行星时常写Earth；on earth中不加the。","topic":"nature","cefr":"A2"},{"w":"packet","uk":"/ˈpækɪt/","p":"n.","zh":"小包；小袋；小盒","ex":{"en":"She opened a packet of biscuits for the journey.","zh":"她打开了一包饼干，准备在路上吃。"},"tip":"英式常用a packet of；美式常依物品用pack或bag。","topic":"daily","cefr":"A2"},{"w":"skateboard","uk":"/ˈskeɪtbɔːd/","p":"n.","zh":"滑板","ex":{"en":"He carried his skateboard home when the rain started.","zh":"开始下雨时，他抱着滑板回家了。"},"tip":"skateboard无扶手；scooter通常有扶手。","topic":"sport","cefr":"A2"},{"w":"motorway","uk":"/ˈməʊtəweɪ/","p":"n.","zh":"高速公路","ex":{"en":"We left the motorway and stopped for lunch.","zh":"我们驶离高速公路，停下来吃午饭。"},"tip":"主要用于英式英语；美式常用freeway。","topic":"travel","cefr":"A2"},{"w":"pain","uk":"/peɪn/","p":"n.","zh":"疼痛","ex":{"en":"I felt a sharp pain in my left ankle.","zh":"我的左脚踝感到一阵剧痛。"},"tip":"泛指疼痛常不可数；具体一阵疼痛可用a pain。","topic":"health","cefr":"A2"},{"w":"definitely","uk":"/ˈdefɪnətli/","p":"adv.","zh":"肯定地；确实；当然","ex":{"en":"I will definitely bring an umbrella after yesterday's rain.","zh":"昨天下过雨后，我今天肯定会带伞。"},"tip":"拼写是definitely；不要与defiantly混淆。","topic":"thinking","cefr":"A2"},{"w":"mile","uk":"/maɪl/","p":"n.","zh":"英里","ex":{"en":"The nearest swimming pool is only a mile away.","zh":"最近的游泳池只有一英里远。"},"tip":"英里是距离单位；mile可数，复数加s。","topic":"travel","cefr":"A2"},{"w":"windy","uk":"/ˈwɪndi/","p":"adj.","zh":"风大的；多风的","ex":{"en":"It was too windy to eat lunch outside today.","zh":"今天风太大，没法在外面吃午饭。"},"tip":"天气义读/ˈwɪndi/；描述道路蜿蜒通常用winding。","topic":"nature","cefr":"A2"},{"w":"somewhere","uk":"/ˈsʌmweə/","p":"adv.","zh":"在某处；到某处","ex":{"en":"I left my keys somewhere near the sofa.","zh":"我把钥匙落在沙发附近的某个地方了。"},"tip":"形容词放后面：somewhere quiet；前面通常不加to。","topic":"daily","cefr":"A2"},{"w":"calculator","uk":"/ˈkælkjəleɪtə/","p":"n.","zh":"计算器","ex":{"en":"I used a calculator to check the shopping total.","zh":"我用计算器核对了购物总额。"},"tip":"calculator指工具；calculation指计算过程或结果。","topic":"education","cefr":"A2"},{"w":"moon","uk":"/muːn/","p":"n.","zh":"月亮；月球","ex":{"en":"The moon rose slowly above the trees behind our house.","zh":"月亮在我们屋后的树梢上缓缓升起。"},"tip":"指地球的月亮通常用the moon；其他行星的卫星可数。","topic":"science","cefr":"A2"},{"w":"such","uk":"/sʌtʃ/","p":"det.","zh":"这样的；这类的","ex":{"en":"It was such a lovely day that we ate outside.","zh":"天气如此宜人，我们就在外面吃了饭。"},"tip":"单数可数名词前用such a/an；so后直接接形容词。","topic":"daily","cefr":"A2"},{"w":"beat","uk":"/biːt/","p":"v.","zh":"打败；胜过","ex":{"en":"My sister beat me at chess again yesterday.","zh":"我姐姐昨天又下棋赢了我。"},"tip":"过去式 beat，过去分词 beaten；赢比赛用 win。","topic":"sport","cefr":"A2"},{"w":"petrol","uk":"/ˈpetrəl/","p":"n.","zh":"汽油","ex":{"en":"We stopped for petrol before driving into the mountains.","zh":"开车进山前，我们停车加了汽油。"},"tip":"不可数名词；英式用petrol，美式用gasoline或gas。","topic":"travel","cefr":"A2"},{"w":"salary","uk":"/ˈsæləri/","p":"n.","zh":"薪水；薪金","ex":{"en":"Her new job offers a higher salary and shorter hours.","zh":"她的新工作薪水更高，工时也更短。"},"tip":"salary指固定薪金；wages常指按时或按周计算的工资。","topic":"work","cefr":"A2"},{"w":"voice","uk":"/vɔɪs/","p":"n.","zh":"嗓音；说话声","ex":{"en":"Her gentle voice helped the frightened puppy settle down.","zh":"她温柔的声音让受惊的小狗安静了下来。"},"tip":"voice侧重人的嗓音；sound泛指声音。","topic":"society","cefr":"A2"},{"w":"king","uk":"/kɪŋ/","p":"n.","zh":"国王","ex":{"en":"The king waved to the crowd from his carriage.","zh":"国王从马车上向人群挥手。"},"tip":"king指男性君主；queen可指女王或王后。","topic":"government","cefr":"A2"},{"w":"difference","uk":"/ˈdɪfrəns/","p":"n.","zh":"差异；不同之处","ex":{"en":"The main difference between these jackets is their weight.","zh":"这两件夹克的主要区别在于重量。"},"tip":"比较两者用the difference between A and B。","topic":"thinking","cefr":"A2"},{"w":"hope","uk":"/həʊp/","p":"v.","zh":"希望；期望","ex":{"en":"I hope the rain stops before our picnic.","zh":"我希望野餐前雨能停。"},"tip":"可说hope to do，不说hope sb to do。","topic":"emotion","cefr":"A2"},{"w":"guide","uk":"/ɡaɪd/","p":"n.","zh":"导游；向导","ex":{"en":"Our guide led us through the narrow market streets.","zh":"导游带我们穿过市场里狭窄的街道。"},"tip":"指南用a guide to；指导某人完成用guide someone through。","topic":"travel","cefr":"A2"},{"w":"metal","uk":"/ˈmetl/","p":"n.","zh":"金属","ex":{"en":"The metal handle felt cold against my fingers.","zh":"金属把手摸起来冰凉。"},"tip":"泛指材料时不可数；指金属种类时可数。","topic":"science","cefr":"A2"},{"w":"bowl","uk":"/bəʊl/","p":"n.","zh":"碗；盆","ex":{"en":"She warmed her hands around a bowl of soup.","zh":"她双手捧着一碗汤取暖。"},"tip":"a bowl of表示“一碗”；bowling指保龄球运动。","topic":"daily","cefr":"A2"},{"w":"weekday","uk":"/ˈwiːkdeɪ/","p":"n.","zh":"工作日；周一至周五","ex":{"en":"The swimming pool is quieter on weekday mornings.","zh":"游泳池在工作日的早晨比较安静。"},"tip":"指周一至周五，不保证当天实际上需要上班。","topic":"daily","cefr":"A2"},{"w":"provide","uk":"/prəˈvaɪd/","p":"v.","zh":"提供；供应","ex":{"en":"The campsite provides clean towels and blankets for every guest.","zh":"营地为每位客人提供干净的毛巾和毯子。"},"tip":"用provide sb with sth或provide sth for sb。","topic":"society","cefr":"A2"},{"w":"mall","uk":"/mɔːl/","p":"n.","zh":"购物中心","ex":{"en":"We spent the rainy afternoon browsing in the mall.","zh":"下雨的下午，我们一直在购物中心闲逛。"},"tip":"mall常用于美式英语；英式常说shopping centre。","topic":"city","cefr":"A2"},{"w":"hall","uk":"/hɔːl/","p":"n.","zh":"门厅；走廊","ex":{"en":"Please leave your wet shoes in the hall.","zh":"请把湿鞋留在门厅里。"},"tip":"英式英语中，大学宿舍常称halls或halls of residence。","topic":"city","cefr":"A2"},{"w":"helpful","uk":"/ˈhelpfəl/","p":"adj.","zh":"有帮助的；有用的","ex":{"en":"Your map was helpful when we explored the village.","zh":"我们游览村庄时，你的地图帮了大忙。"},"tip":"helpful可形容事物有用，也可形容人乐于助人。","topic":"daily","cefr":"A2"},{"w":"disease","uk":"/dɪˈziːz/","p":"n.","zh":"疾病","ex":{"en":"The vet checked our rabbit for signs of disease.","zh":"兽医检查了我们的兔子，看是否有患病迹象。"},"tip":"重音在第二音节；泛指疾病可不加冠词。","topic":"health","cefr":"A2"},{"w":"noticeboard","uk":"/ˈnəʊtɪsbɔːd/","p":"n.","zh":"布告栏；公告板","ex":{"en":"Someone pinned a lost cat poster to the noticeboard.","zh":"有人把寻猫启事钉在了布告栏上。"},"tip":"英式常用noticeboard，美式常用bulletin board。","topic":"daily","cefr":"A2"},{"w":"pick","uk":"/pɪk/","p":"v.","zh":"挑选；选择","ex":{"en":"You can pick any colour for your new curtains.","zh":"新窗帘的颜色你可以随便选。"},"tip":"pick可指挑选或采摘；捡起通常用pick up。","topic":"daily","cefr":"A2"},{"w":"garage","uk":"/ˈɡærɑːʒ/","p":"n.","zh":"车库","ex":{"en":"We keep our car and bicycles in the garage.","zh":"我们把汽车和自行车停在车库里。"},"tip":"英式英语也常用 garage 指汽车修理厂。","topic":"daily","cefr":"A2"},{"w":"service","uk":"/ˈsɜːvɪs/","p":"n.","zh":"服务；公共服务","ex":{"en":"The friendly service made us feel welcome at the café.","zh":"咖啡馆里热情的服务让我们感到宾至如归。"},"tip":"表示服务质量常不可数；各项服务可用复数。","topic":"daily","cefr":"A2"},{"w":"classmate","uk":"/ˈklɑːsmeɪt/","p":"n.","zh":"同班同学","ex":{"en":"My classmate lent me a pencil before the lesson.","zh":"上课前，我的同班同学借给我一支铅笔。"},"tip":"classmate指同班同学，schoolmate指同校同学。","topic":"education","cefr":"A2"},{"w":"visitor","uk":"/ˈvɪzɪtə/","p":"n.","zh":"访客；参观者；游客","ex":{"en":"A visitor left her umbrella beside our front door.","zh":"一位访客把她的伞落在了我们前门旁。"},"tip":"visitor指人；visit可作动词或名词。","topic":"travel","cefr":"A2"},{"w":"kilometer","uk":"/kɪˈlɒmɪtə/","p":"n.","zh":"千米；公里","ex":{"en":"The nearest bakery is about a kilometer from here.","zh":"最近的面包店离这里大约一公里。"},"tip":"美式拼写；英式为kilometre，符号km不加s。","topic":"travel","cefr":"A2"},{"w":"death","uk":"/deθ/","p":"n.","zh":"死亡；去世","ex":{"en":"The old dog's death left the family deeply sad.","zh":"老狗的离世让全家人深感悲伤。"},"tip":"die是动词，dead是形容词，death是名词。","topic":"health","cefr":"A2"},{"w":"pop","uk":"/pɒp/","p":"n.","zh":"流行音乐","ex":{"en":"My sister listens to pop while she cooks dinner.","zh":"我姐姐做晚饭时会听流行音乐。"},"tip":"表示短暂去或顺手放时属非正式用法。","topic":"arts","cefr":"A2"},{"w":"cupboard","uk":"/ˈkʌbəd/","p":"n.","zh":"橱柜；壁橱","ex":{"en":"The clean bowls are in the cupboard above the sink.","zh":"干净的碗放在水槽上方的橱柜里。"},"tip":"cupboard中的p不发音；通常指带门的储物柜。","topic":"daily","cefr":"A2"},{"w":"worse","uk":"/wɜːs/","p":"adj.","zh":"更差的；更严重的","ex":{"en":"The weather grew worse as we climbed the hill.","zh":"我们爬山时，天气变得更糟了。"},"tip":"bad和badly的比较级；最高级是worst。","topic":"daily","cefr":"A2"},{"w":"document","uk":"/ˈdɒkjumənt/","p":"n.","zh":"文件；证件；文档","ex":{"en":"Please save the document before you close your laptop.","zh":"合上笔记本电脑之前，请保存文档。"},"tip":"动词末尾读/ment/，名词末尾读/mənt/。","topic":"work","cefr":"A2"},{"w":"cricket","uk":"/ˈkrɪkɪt/","p":"n.","zh":"板球运动","ex":{"en":"We played cricket in the park after lunch.","zh":"午饭后，我们在公园里打板球。"},"tip":"指板球运动时不可数；指蟋蟀时可数。","topic":"sport","cefr":"A2"},{"w":"shark","uk":"/ʃɑːk/","p":"n.","zh":"鲨鱼","ex":{"en":"We watched a shark swim slowly behind the aquarium glass.","zh":"我们看着一条鲨鱼在水族馆的玻璃后缓缓游动。"},"tip":"loan shark指放高利贷者，不是某种鲨鱼。","topic":"nature","cefr":"A2"},{"w":"cancel","uk":"/ˈkænsəl/","p":"v.","zh":"取消；撤销","ex":{"en":"We had to cancel our picnic because of heavy rain.","zh":"由于下大雨，我们不得不取消野餐。"},"tip":"英式过去式cancelled，美式常用canceled；抵消用out。","topic":"daily","cefr":"A2"},{"w":"quality","uk":"/ˈkwɒləti/","p":"n.","zh":"质量；品质","ex":{"en":"The quality of these shoes surprised me for the price.","zh":"以这个价格来说，这双鞋的质量让我感到惊喜。"},"tip":"表示质量通常不可数；表示特质时可数。","topic":"daily","cefr":"A2"},{"w":"international","uk":"/ˌɪntəˈnæʃənəl/","p":"adj.","zh":"国际的；跨国的","ex":{"en":"My sister is taking an international flight tomorrow morning.","zh":"我姐姐明天早上要乘坐国际航班。"},"tip":"international涉及多国；domestic指国内的。","topic":"society","cefr":"A2"},{"w":"event","uk":"/ɪˈvent/","p":"n.","zh":"活动；重大事件","ex":{"en":"The outdoor concert was our town's biggest summer event.","zh":"这场户外音乐会是我们镇上夏季最大的活动。"},"tip":"in the event of后接名词，意为“万一发生”。","topic":"society","cefr":"A2"},{"w":"however","uk":"/haʊˈevə/","p":"adv.","zh":"然而；不过","ex":{"en":"The jacket looked warm; however, it felt surprisingly thin.","zh":"这件夹克看起来很暖和，摸起来却出奇地薄。"},"tip":"表转折时不是并列连词；勿仅用逗号连接两句。","topic":"thinking","cefr":"A2"},{"w":"present","uk":"/ˈprezənt/; /prɪˈzent/","p":"adj.","zh":"在场的；目前的","ex":{"en":"All the children were present for the class photo.","zh":"拍班级合照时，所有孩子都在场。"},"tip":"名词、形容词重音在首音节；动词重音在第二音节。","topic":"daily","cefr":"A2"},{"w":"shape","uk":"/ʃeɪp/","p":"n.","zh":"形状；外形","ex":{"en":"She cut the biscuits into the shape of stars.","zh":"她把饼干坯切成了星星的形状。"},"tip":"in shape可指身体状态好，不只表示形状。","topic":"daily","cefr":"A2"},{"w":"washroom","uk":"/ˈwɒʃruːm/","p":"n.","zh":"洗手间；厕所","ex":{"en":"There is a washroom just beside the lifts.","zh":"电梯旁边就有一间洗手间。"},"tip":"主要用于北美，尤其加拿大；英国常说toilet。","topic":"daily","cefr":"A2"},{"w":"surprising","uk":"/səˈpraɪzɪŋ/","p":"adj.","zh":"令人惊讶的；出乎意料的","ex":{"en":"The tiny bakery offers a surprising variety of fresh bread.","zh":"这家小面包店的新鲜面包种类多得令人惊讶。"},"tip":"surprising形容事物；surprised形容人的感受。","topic":"emotion","cefr":"A2"},{"w":"snowy","uk":"/ˈsnəʊi/","p":"adj.","zh":"下雪的；多雪的","ex":{"en":"We stayed indoors and baked bread on that snowy afternoon.","zh":"那个下雪的下午，我们待在屋里烤面包。"},"tip":"snowy可描述天气，也可指地面等被雪覆盖。","topic":"nature","cefr":"A2"},{"w":"soda","uk":"/ˈsəʊdə/","p":"n.","zh":"汽水","ex":{"en":"I spilled orange soda all over the kitchen floor.","zh":"我把橙味汽水洒得厨房地板上到处都是。"},"tip":"美式常指汽水；baking soda才是小苏打。","topic":"daily","cefr":"A2"},{"w":"anybody","uk":"/ˈenibɒdi/","p":"pron.","zh":"任何人；有人","ex":{"en":"Does anybody know where I left my blue umbrella?","zh":"有人知道我把蓝色雨伞放在哪里了吗？"},"tip":"anybody作主语时，谓语用单数形式。","topic":"society","cefr":"A2"},{"w":"ping-pong","uk":"/ˈpɪŋ pɒŋ/","p":"n.","zh":"乒乓球运动","ex":{"en":"We played ping-pong together while waiting for dinner.","zh":"等晚饭时，我们一起打了乒乓球。"},"tip":"较口语化；正式比赛和写作常用table tennis。","topic":"sport","cefr":"A2"},{"w":"rent","uk":"/rent/","p":"n.","zh":"租金","ex":{"en":"My monthly rent includes water but not electricity.","zh":"我每月的租金包含水费，但不含电费。"},"tip":"rent可指租入或出租；rent out明确表示出租。","topic":"city","cefr":"A2"},{"w":"nephew","uk":"/ˈnefjuː/","p":"n.","zh":"侄子；外甥","ex":{"en":"My nephew proudly showed me his new bicycle.","zh":"我的侄子自豪地给我看他的新自行车。"},"tip":"nephew 指男性晚辈；女性对应词是 niece。","topic":"daily","cefr":"A2"},{"w":"fight","uk":"/faɪt/","p":"v.","zh":"打架；战斗","ex":{"en":"The two cats fought over a sunny window seat.","zh":"两只猫为了窗边一个有阳光的位置打了起来。"},"tip":"过去式、过去分词均为fought；fight for表示争取。","topic":"society","cefr":"A2"},{"w":"extremely","uk":"/ɪkˈstriːmli/","p":"adv.","zh":"极其；非常","ex":{"en":"The soup was extremely hot, so I waited.","zh":"汤烫极了，所以我等了一会儿。"},"tip":"修饰可分程度的形容词或副词，语气强于very。","topic":"daily","cefr":"A2"},{"w":"skateboarding","uk":"/ˈskeɪtbɔːdɪŋ/","p":"n.","zh":"滑板运动","ex":{"en":"We went skateboarding at the park after lunch.","zh":"午饭后，我们去公园玩滑板了。"},"tip":"运动用skateboarding；滑板这件器材用skateboard。","topic":"sport","cefr":"A2"},{"w":"lettuce","uk":"/ˈletɪs/","p":"n.","zh":"生菜；莴苣","ex":{"en":"Wash the lettuce before adding it to your sandwich.","zh":"把生菜洗净后再夹进三明治里。"},"tip":"指食材通常不可数；一棵生菜用a head of lettuce。","topic":"daily","cefr":"A2"},{"w":"ugly","uk":"/ˈʌɡli/","p":"adj.","zh":"丑陋的；难看的","ex":{"en":"We hid the ugly pipes behind a wooden screen.","zh":"我们用木制屏风遮住了那些难看的管道。"},"tip":"比较级uglier，最高级ugliest；形容人外貌不礼貌。","topic":"daily","cefr":"A2"},{"w":"success","uk":"/səkˈses/","p":"n.","zh":"成功；成就","ex":{"en":"The school concert was a success despite the rain.","zh":"尽管下了雨，学校音乐会还是很成功。"},"tip":"泛指成功时不可数；a success指成功的人或事。","topic":"work","cefr":"A2"},{"w":"jumper","uk":"/ˈdʒʌmpə/","p":"n.","zh":"套头毛衣（英）","ex":{"en":"I packed a warm jumper for the camping trip.","zh":"我为这次露营带了一件暖和的套头毛衣。"},"tip":"英式英语指套头毛衣；美式通常用sweater。","topic":"daily","cefr":"A2"},{"w":"period","uk":"/ˈpɪəriəd/","p":"n.","zh":"一段时间；时期","ex":{"en":"We stayed indoors during a short period of heavy rain.","zh":"在那阵短暂的大雨期间，我们一直待在室内。"},"tip":"表示一段时间常用a period of；美式英语也指句号。","topic":"daily","cefr":"A2"},{"w":"sheet","uk":"/ʃiːt/","p":"n.","zh":"床单","ex":{"en":"I spread a clean sheet over the mattress.","zh":"我在床垫上铺了一条干净的床单。"},"tip":"sheet是可数名词；一张纸说a sheet of paper。","topic":"daily","cefr":"A2"},{"w":"liter","uk":"/ˈliːtə/","p":"n.","zh":"升（容量单位）","ex":{"en":"This bottle holds exactly one liter of fresh milk.","zh":"这个瓶子正好能装一升鲜奶。"},"tip":"liter是美式拼写，英式为litre；一升等于一千毫升。","topic":"daily","cefr":"A2"},{"w":"lie","uk":"/laɪ/","p":"v.","zh":"躺；平放","ex":{"en":"I like to lie on the grass after lunch.","zh":"我喜欢午饭后躺在草地上。"},"tip":"躺：lie–lay–lain；说谎：lie–lied–lied。","topic":"daily","cefr":"A2"},{"w":"tower","uk":"/ˈtaʊə/","p":"n.","zh":"塔；塔楼","ex":{"en":"We climbed the tower and watched boats cross the bay.","zh":"我们爬上塔，看着船只驶过海湾。"},"tip":"作动词常接over或above，表示远高于周围事物。","topic":"city","cefr":"A2"},{"w":"stupid","uk":"/ˈstjuːpɪd/","p":"adj.","zh":"愚蠢的；欠考虑的","ex":{"en":"It was stupid to leave my umbrella at home.","zh":"把伞留在家里真是太傻了。"},"tip":"直接说别人stupid带侮辱性，评价人时应避免。","topic":"thinking","cefr":"A2"},{"w":"ever","uk":"/ˈevə/","p":"adv.","zh":"曾经；在任何时候","ex":{"en":"Have you ever watched the sunrise from a mountain?","zh":"你曾经在山上看过日出吗？"},"tip":"问经历常用Have you ever…；肯定句不随意代替always。","topic":"daily","cefr":"A2"},{"w":"happiness","uk":"/ˈhæpinəs/","p":"n.","zh":"幸福；快乐","ex":{"en":"Her face shone with happiness when the puppy arrived.","zh":"小狗到来时，她的脸上洋溢着喜悦。"},"tip":"通常不可数：表达幸福用happiness，不加a。","topic":"emotion","cefr":"A2"},{"w":"granddaughter","uk":"/ˈɡrændɔːtə/","p":"n.","zh":"孙女；外孙女","ex":{"en":"Her granddaughter brought fresh flowers when she visited on Sunday.","zh":"她的孙女星期天来看她时带来了鲜花。"},"tip":"既指孙女也指外孙女，英语不区分父系与母系。","topic":"society","cefr":"A2"},{"w":"passenger","uk":"/ˈpæsɪndʒə/","p":"n.","zh":"乘客；旅客","ex":{"en":"A passenger left a blue umbrella on the bus.","zh":"一位乘客把一把蓝色雨伞落在了公交车上。"},"tip":"指乘坐交通工具的人，不包括驾驶员或机组人员。","topic":"travel","cefr":"A2"},{"w":"article","uk":"/ˈɑːtɪkəl/","p":"n.","zh":"文章；报道","ex":{"en":"I read an interesting article about growing tomatoes indoors.","zh":"我读了一篇关于室内种植番茄的有趣文章。"},"tip":"一件衣物可说an article of clothing。","topic":"media","cefr":"A2"},{"w":"homepage","uk":"/ˈhəʊmpeɪdʒ/","p":"n.","zh":"网站主页","ex":{"en":"The library's homepage has a photo of its new reading room.","zh":"图书馆主页上有一张新阅览室的照片。"},"tip":"也可写作home page；不等于网站中的任意网页。","topic":"technology","cefr":"A2"},{"w":"percent","uk":"/pəˈsent/","p":"adv.","zh":"百分之……","ex":{"en":"I saved twenty percent on my new winter coat.","zh":"我买新冬衣时省了百分之二十的钱。"},"tip":"英式也写per cent；具体比例用percent。","topic":"economy","cefr":"A2"},{"w":"teenager","uk":"/ˈtiːneɪdʒə/","p":"n.","zh":"十三至十九岁青少年","ex":{"en":"As a teenager, I cycled to school every day.","zh":"我十几岁时每天骑自行车上学。"},"tip":"特指13至19岁的人，不泛指所有未成年人。","topic":"society","cefr":"A2"},{"w":"direction","uk":"/dəˈrekʃən/","p":"n.","zh":"方向；发展趋势","ex":{"en":"The dog suddenly ran in the opposite direction.","zh":"那只狗突然朝相反的方向跑去。"},"tip":"表示路线指引或操作说明时，通常用复数directions。","topic":"travel","cefr":"A2"},{"w":"instead","uk":"/ɪnˈsted/","p":"adv.","zh":"代替；反而","ex":{"en":"The café was closed, so we went home instead.","zh":"咖啡馆关门了，于是我们改为回家。"},"tip":"instead可单独作副词；instead of后接名词或动名词。","topic":"daily","cefr":"A2"},{"w":"amazing","uk":"/əˈmeɪzɪŋ/","p":"adj.","zh":"令人惊叹的；极好的","ex":{"en":"The view from the mountain was absolutely amazing.","zh":"从山上望去的景色真是令人惊叹。"},"tip":"amazing形容令人惊叹的事物；amazed形容人的感受。","topic":"emotion","cefr":"A2"},{"w":"housewife","uk":"/ˈhaʊswaɪf/","p":"n.","zh":"家庭主妇","ex":{"en":"As a housewife, she manages a busy household.","zh":"作为家庭主妇，她操持着一个忙碌家庭的日常事务。"},"tip":"复数为housewives；homemaker不限定性别。","topic":"society","cefr":"A2"},{"w":"owner","uk":"/ˈəʊnə/","p":"n.","zh":"所有者；物主","ex":{"en":"The owner of the bakery greets us every morning.","zh":"面包店老板每天早上都向我们打招呼。"},"tip":"表示某物的所有者，用the owner of加名词。","topic":"daily","cefr":"A2"},{"w":"dish","uk":"/dɪʃ/","p":"n.","zh":"盘；碟","ex":{"en":"Please put the strawberries in that blue dish.","zh":"请把草莓放进那个蓝色盘子里。"},"tip":"a dish可指一道菜；do the dishes指洗餐具。","topic":"daily","cefr":"A2"},{"w":"quite","uk":"/kwaɪt/","p":"adv.","zh":"相当；颇","ex":{"en":"The soup is quite spicy, but I like it.","zh":"这汤挺辣的，不过我喜欢。"},"tip":"quite good常指相当好；quite impossible指完全不可能。","topic":"daily","cefr":"A2"},{"w":"gram","uk":"/ɡræm/","p":"n.","zh":"克","ex":{"en":"Add one gram of salt and stir the soup.","zh":"加入一克盐，然后搅拌汤。"},"tip":"符号为g；复数为grams；一千克等于一千克中的一千克？","topic":"daily","cefr":"A2"},{"w":"cookie","uk":"/ˈkʊki/","p":"n.","zh":"曲奇饼；小甜饼","ex":{"en":"There is one chocolate cookie left in the jar.","zh":"罐子里还剩一块巧克力曲奇。"},"tip":"美式泛指小甜饼；网站cookie不等同于缓存文件。","topic":"daily","cefr":"A2"},{"w":"missing","uk":"/ˈmɪsɪŋ/","p":"adj.","zh":"找不到的；失踪的","ex":{"en":"We found the missing kitten asleep behind the sofa.","zh":"我们发现那只找不到的小猫正在沙发后面睡觉。"},"tip":"missing作形容词表不见或缺失；be missing from表缺少。","topic":"daily","cefr":"A2"},{"w":"left-hand","uk":"/ˌleft ˈhænd/","p":"adj.","zh":"左侧的；左手边的","ex":{"en":"Keep your ticket in the left-hand pocket of your jacket.","zh":"把票放在夹克左侧的口袋里。"},"tip":"left-hand指左侧；left-handed指惯用左手的。","topic":"daily","cefr":"A2"},{"w":"pocket","uk":"/ˈpɒkɪt/","p":"n.","zh":"口袋","ex":{"en":"I found my missing key in my coat pocket.","zh":"我在外套口袋里找到了丢失的钥匙。"},"tip":"pocket money指零花钱，英式英语中常用。","topic":"daily","cefr":"A2"},{"w":"total","uk":"/ˈtəʊtəl/","p":"adj.","zh":"总的；完全的","ex":{"en":"The total cost includes breakfast and a bus ticket.","zh":"总费用包含早餐和一张公交车票。"},"tip":"in total表示“总共”；totally常表示“完全地”。","topic":"economy","cefr":"A2"},{"w":"soldier","uk":"/ˈsəʊldʒə/","p":"n.","zh":"士兵；军人","ex":{"en":"The soldier helped carry supplies across the flooded road.","zh":"那名士兵帮忙把物资运过被洪水淹没的道路。"},"tip":"通常指陆军军人；水手和飞行员另有专称。","topic":"society","cefr":"A2"},{"w":"biscuit","uk":"/ˈbɪskɪt/","p":"n.","zh":"饼干（英式用法）","ex":{"en":"She dipped a biscuit into her warm tea.","zh":"她把一块饼干浸进温热的茶里。"},"tip":"英式biscuit通常对应美式cookie；美式另指松软面包。","topic":"daily","cefr":"A2"},{"w":"gallery","uk":"/ˈɡæləri/","p":"n.","zh":"画廊；美术馆","ex":{"en":"We spent a rainy afternoon exploring the local gallery.","zh":"一个下雨的下午，我们逛了当地的美术馆。"},"tip":"gallery主要展示艺术品；museum涵盖的展品范围更广。","topic":"arts","cefr":"A2"},{"w":"fat","uk":"/fæt/","p":"n.","zh":"脂肪；食用油脂","ex":{"en":"Let the soup cool, then remove the fat.","zh":"让汤凉下来，再撇去油脂。"},"tip":"用fat形容人可能冒犯；谈健康宜用overweight。","topic":"health","cefr":"A2"},{"w":"sale","uk":"/seɪl/","p":"n.","zh":"出售；销售","ex":{"en":"I bought these boots in the winter sale.","zh":"我在冬季促销时买了这双靴子。"},"tip":"for sale指待售；销售额或销量通常用复数sales。","topic":"economy","cefr":"A2"},{"w":"skiing","uk":"/ˈskiːɪŋ/","p":"n.","zh":"滑雪运动","ex":{"en":"We went skiing together during our winter holiday.","zh":"寒假期间，我们一起去滑雪了。"},"tip":"滑雪用go skiing；滑水需说water skiing。","topic":"sport","cefr":"A2"},{"w":"password","uk":"/ˈpɑːswɜːd/","p":"n.","zh":"密码；口令","ex":{"en":"I forgot my password and couldn't open my account.","zh":"我忘了密码，无法登录账户。"},"tip":"password是密码；passcode也可指数字口令。","topic":"technology","cefr":"A2"},{"w":"postbox","uk":"/ˈpəʊstbɒks/","p":"n.","zh":"邮筒；邮政信箱","ex":{"en":"I dropped the birthday card into the postbox outside.","zh":"我把生日贺卡投进了外面的邮筒。"},"tip":"英式英语指公共寄信邮筒；美式通常用mailbox。","topic":"city","cefr":"A2"},{"w":"ending","uk":"/ˈendɪŋ/","p":"n.","zh":"结尾；结局","ex":{"en":"The film had a surprisingly cheerful ending for everyone.","zh":"这部电影的结局出人意料，所有人都皆大欢喜。"},"tip":"故事结局用ending；at the end表示在末尾。","topic":"arts","cefr":"A2"},{"w":"support","uk":"/səˈpɔːt/","p":"v.","zh":"支持；帮助；供养","ex":{"en":"My sister supports me whenever I try something new.","zh":"每当我尝试新事物时，姐姐都会支持我。"},"tip":"support是及物动词；名词常用support for。","topic":"society","cefr":"A2"},{"w":"helicopter","uk":"/ˈhelɪkɒptə/","p":"n.","zh":"直升机","ex":{"en":"A helicopter landed in the field behind our house.","zh":"一架直升机降落在我们屋后的田野里。"},"tip":"乘直升机用by helicopter，中间不加冠词。","topic":"travel","cefr":"A2"},{"w":"untidy","uk":"/ʌnˈtaɪdi/","p":"adj.","zh":"凌乱的；不整洁的","ex":{"en":"Her untidy desk was covered with cups and notebooks.","zh":"她凌乱的书桌上堆满了杯子和笔记本。"},"tip":"untidy强调不整齐，不一定像dirty那样有污垢。","topic":"daily","cefr":"A2"},{"w":"soccer","uk":"/ˈsɒkə/","p":"n.","zh":"足球运动","ex":{"en":"We play soccer in the park every Saturday morning.","zh":"我们每周六早上都在公园踢足球。"},"tip":"英式英语通常称football，美式称soccer。","topic":"sport","cefr":"A2"},{"w":"boot","uk":"/buːt/","p":"n.","zh":"靴子","ex":{"en":"My boots kept my feet dry in the rain.","zh":"我的靴子让双脚在雨中保持干爽。"},"tip":"汽车后备箱英式说boot，美式说trunk。","topic":"daily","cefr":"A2"},{"w":"ring","uk":"/rɪŋ/","p":"n.","zh":"戒指；环状物","ex":{"en":"She slipped the silver ring onto her finger.","zh":"她把那枚银戒指戴在了手指上。"},"tip":"响铃、打电话的过去式为rang，过去分词为rung。","topic":"daily","cefr":"A2"},{"w":"heating","uk":"/ˈhiːtɪŋ/","p":"n.","zh":"供暖；暖气系统","ex":{"en":"We turned the heating on when the evening grew chilly.","zh":"傍晚天凉起来时，我们打开了暖气。"},"tip":"指供暖时通常不可数：turn on the heating。","topic":"daily","cefr":"A2"},{"w":"smoke","uk":"/sməʊk/","p":"n.","zh":"烟；烟雾","ex":{"en":"Dark smoke rose from the toast in the kitchen.","zh":"厨房里的吐司冒出了黑烟。"},"tip":"smoke作“烟雾”通常不可数；smoky意为烟雾弥漫的。","topic":"health","cefr":"A2"},{"w":"recording","uk":"/rɪˈkɔːdɪŋ/","p":"n.","zh":"录音；录像","ex":{"en":"We listened to a recording of birds during breakfast.","zh":"早餐时，我们听了一段鸟鸣录音。"},"tip":"一段录音可数；表示录制过程时通常不可数。","topic":"media","cefr":"A2"},{"w":"non-smoking","uk":"/ˌnɒn ˈsməʊkɪŋ/","p":"adj.","zh":"禁止吸烟的","ex":{"en":"We asked for a non-smoking room at reception.","zh":"我们在前台要求安排一间无烟客房。"},"tip":"可指场所禁烟，也可指人不吸烟。","topic":"health","cefr":"A2"},{"w":"postcode","uk":"/ˈpəʊstkəʊd/","p":"n.","zh":"邮政编码","ex":{"en":"Please include your postcode when you fill in the form.","zh":"填写表格时，请填上你的邮政编码。"},"tip":"英式常用postcode；美式常用ZIP code。","topic":"daily","cefr":"A2"},{"w":"blonde","uk":"/blɒnd/","p":"adj.","zh":"金发的；浅金色的","ex":{"en":"Her blonde hair shone brightly in the afternoon sun.","zh":"她的金发在午后的阳光下闪闪发亮。"},"tip":"blonde多用于女性；描述男性通常用blond。","topic":"daily","cefr":"A2"},{"w":"lend","uk":"/lend/","p":"v.","zh":"借出；贷出","ex":{"en":"Could you lend me your umbrella until tomorrow?","zh":"你能把雨伞借给我用到明天吗？"},"tip":"lend是借出，borrow是借入；过去式为lent。","topic":"daily","cefr":"A2"},{"w":"sandal","uk":"/ˈsændl/","p":"n.","zh":"凉鞋","ex":{"en":"A small stone got stuck inside my sandal.","zh":"一颗小石子卡进了我的凉鞋里。"},"tip":"单只用sandal，一双用a pair of sandals。","topic":"daily","cefr":"A2"},{"w":"interest","uk":"/ˈɪntrəst/","p":"n.","zh":"兴趣；关注","ex":{"en":"My interest in cooking began in my grandmother's kitchen.","zh":"我对烹饪的兴趣始于祖母的厨房。"},"tip":"兴趣用interest in；具体爱好可用复数interests。","topic":"thinking","cefr":"A2"},{"w":"dead","uk":"/ded/","p":"adj.","zh":"死的；枯死的","ex":{"en":"We removed the dead flowers from the balcony pots.","zh":"我们清除了阳台花盆里枯死的花。"},"tip":"dead是状态，die是动作，death是名词。","topic":"nature","cefr":"A2"},{"w":"duck","uk":"/dʌk/","p":"n.","zh":"鸭；鸭肉","ex":{"en":"A duck paddled past us with several tiny ducklings.","zh":"一只鸭子带着几只小鸭从我们身旁游过。"},"tip":"指鸭子时可数，指鸭肉时不可数。","topic":"nature","cefr":"A2"},{"w":"mean","uk":"/miːn/","p":"v.","zh":"意思是；意味着；打算","ex":{"en":"I didn't mean to leave you waiting outside.","zh":"我不是故意让你在外面等着的。"},"tip":"mean to do是“打算做”；mean doing是“意味着做”。","topic":"thinking","cefr":"A2"},{"w":"dream","uk":"/driːm/","p":"n.","zh":"梦；梦境","ex":{"en":"Last night, I had a dream about flying over mountains.","zh":"昨晚我做了一个飞越群山的梦。"},"tip":"dream of/about后接名词或动名词；过去式可用dreamt或dreamed。","topic":"thinking","cefr":"A2"},{"w":"regular","uk":"/ˈreɡjələ/","p":"adj.","zh":"定期的；经常的","ex":{"en":"Our dog needs regular walks to stay happy and healthy.","zh":"我们的狗需要经常散步，才能保持快乐和健康。"},"tip":"regular侧重规律或经常，不等于持续不停的continuous。","topic":"daily","cefr":"A2"},{"w":"stairs","uk":"/steəz/","p":"n.","zh":"楼梯；梯级","ex":{"en":"We carried the heavy suitcase up the narrow stairs.","zh":"我们把沉重的行李箱沿着狭窄的楼梯搬了上去。"},"tip":"stairs是复数，谓语用复数；一段楼梯用a flight of stairs。","topic":"daily","cefr":"A2"},{"w":"accept","uk":"/əkˈsept/","p":"v.","zh":"接受；同意","ex":{"en":"I gladly accepted her invitation to dinner on Saturday.","zh":"我欣然接受了她周六共进晚餐的邀请。"},"tip":"接受建议用accept；接受某物不等于仅仅收到receive。","topic":"daily","cefr":"A2"},{"w":"abroad","uk":"/əˈbrɔːd/","p":"adv.","zh":"在国外；到国外","ex":{"en":"My sister moved abroad and now lives near the sea.","zh":"我姐姐移居国外，现在住在海边。"},"tip":"abroad是副词：说go abroad，不说go to abroad。","topic":"travel","cefr":"A2"},{"w":"attend","uk":"/əˈtend/","p":"v.","zh":"出席；参加；上学","ex":{"en":"My sister attends a dance class every Saturday morning.","zh":"我姐姐每周六上午都去上舞蹈课。"},"tip":"参加活动直接接宾语；处理、照料用attend to。","topic":"education","cefr":"A2"},{"w":"candy","uk":"/ˈkændi/","p":"n.","zh":"糖果","ex":{"en":"She offered each guest a small piece of candy.","zh":"她给每位客人递了一小块糖果。"},"tip":"美式常用candy，英式常用sweets；一块用a piece of。","topic":"daily","cefr":"A2"},{"w":"basic","uk":"/ˈbeɪsɪk/","p":"adj.","zh":"基本的；基础的","ex":{"en":"This course teaches basic cooking skills to complete beginners.","zh":"这门课程向零基础学员教授基本烹饪技能。"},"tip":"名词“基础知识”用复数 the basics。","topic":"education","cefr":"A2"},{"w":"public","uk":"/ˈpʌblɪk/","p":"adj.","zh":"公众的；公用的；公开的","ex":{"en":"The public garden stays open until sunset every day.","zh":"这座公共花园每天开放到日落。"},"tip":"the public指公众；in public指在公共场合。","topic":"society","cefr":"A2"},{"w":"rubbish","uk":"/ˈrʌbɪʃ/","p":"n.","zh":"垃圾；废物","ex":{"en":"Please put your rubbish in the bin outside.","zh":"请把垃圾放进外面的垃圾桶。"},"tip":"通常不可数；英式常用词，美式常说garbage或trash。","topic":"environment","cefr":"A2"},{"w":"restroom","uk":"/ˈrestruːm/","p":"n.","zh":"公共洗手间；厕所","ex":{"en":"I stopped at the restroom before boarding the bus.","zh":"上公交车前，我去了一趟洗手间。"},"tip":"美式英语中指公共厕所，不是普通的休息室。","topic":"travel","cefr":"A2"},{"w":"midnight","uk":"/ˈmɪdnaɪt/","p":"n.","zh":"午夜；半夜十二点","ex":{"en":"We stayed awake until midnight watching the snow fall.","zh":"我们一直醒着看雪，直到午夜。"},"tip":"在午夜用at midnight，不用in midnight。","topic":"daily","cefr":"A2"},{"w":"bar","uk":"/bɑː/","p":"n.","zh":"酒吧；饮品吧台","ex":{"en":"We ordered fresh orange juice at the hotel bar.","zh":"我们在酒店的酒吧点了鲜榨橙汁。"},"tip":"表禁止用bar sb from doing；过去式barred。","topic":"daily","cefr":"A2"},{"w":"choice","uk":"/tʃɔɪs/","p":"n.","zh":"选择；选择权","ex":{"en":"You have a choice between soup and salad.","zh":"你可以在汤和沙拉之间选择。"},"tip":"choice是名词，choose是动词；选择做某事用choose to do。","topic":"thinking","cefr":"A2"},{"w":"return","uk":"/rɪˈtɜːn/","p":"v.","zh":"返回；归还","ex":{"en":"Please return these library books before you go away.","zh":"请在离开之前归还这些图书馆的书。"},"tip":"return已含“回”的意思，通常不再加back。","topic":"daily","cefr":"A2"},{"w":"properly","uk":"/ˈprɒpəli/","p":"adv.","zh":"正确地；恰当地","ex":{"en":"The kitchen door will not close properly in winter.","zh":"冬天厨房的门总是关不严。"},"tip":"修饰动作常用properly；修饰名词用proper。","topic":"daily","cefr":"A2"},{"w":"northwest","uk":"/ˌnɔːθˈwest/","p":"n.","zh":"西北方；西北部","ex":{"en":"Our cabin is in the northwest of the island.","zh":"我们的小木屋位于岛的西北部。"},"tip":"西北风从西北吹来；向西北走用head northwest。","topic":"travel","cefr":"A2"},{"w":"runner","uk":"/ˈrʌnə/","p":"n.","zh":"跑步者；赛跑选手","ex":{"en":"A runner in bright shoes passed us by the lake.","zh":"一位穿着亮色鞋子的跑步者在湖边从我们身旁跑过。"},"tip":"run加-er时双写n；runner-up指亚军。","topic":"sport","cefr":"A2"},{"w":"pork","uk":"/pɔːk/","p":"n.","zh":"猪肉","ex":{"en":"We cooked the pork slowly with apples and onions.","zh":"我们把猪肉和苹果、洋葱一起慢炖。"},"tip":"pork是不可数名词，指肉；活猪用pig。","topic":"daily","cefr":"A2"},{"w":"drama","uk":"/ˈdrɑːmə/","p":"n.","zh":"戏剧；戏剧艺术","ex":{"en":"Our drama group rehearses in the hall every Thursday.","zh":"我们的戏剧小组每周四在大厅排练。"},"tip":"戏剧艺术用不可数drama；一部戏剧用a drama。","topic":"arts","cefr":"A2"},{"w":"surprise","uk":"/səˈpraɪz/","p":"n.","zh":"惊讶；意外之事","ex":{"en":"Finding a birthday cake in the kitchen was a lovely surprise.","zh":"在厨房里发现一个生日蛋糕，真是个美好的惊喜。"},"tip":"人感到惊讶用surprised；事物令人惊讶用surprising。","topic":"emotion","cefr":"A2"},{"w":"case","uk":"/keɪs/","p":"n.","zh":"情况；事例；病例","ex":{"en":"Take an umbrella in case it rains later.","zh":"带把伞吧，以防待会儿下雨。"},"tip":"in case后接从句；in case of后接名词。","topic":"daily","cefr":"A2"},{"w":"spider","uk":"/ˈspaɪdə/","p":"n.","zh":"蜘蛛","ex":{"en":"A tiny spider built a web beside our window.","zh":"一只小蜘蛛在我们窗边结了网。"},"tip":"蜘蛛有八条腿，不属于六条腿的昆虫。","topic":"nature","cefr":"A2"},{"w":"pepper","uk":"/ˈpepə/","p":"n.","zh":"胡椒粉；胡椒","ex":{"en":"Could you pass me the pepper for my soup?","zh":"能把胡椒粉递给我，让我加到汤里吗？"},"tip":"胡椒粉不可数；指一个甜椒时可说a pepper。","topic":"daily","cefr":"A2"},{"w":"allow","uk":"/əˈlaʊ/","p":"v.","zh":"允许；准许","ex":{"en":"The library allows visitors to borrow five books at once.","zh":"图书馆允许访客一次借五本书。"},"tip":"用allow sb to do；无宾语时可用allow doing。","topic":"daily","cefr":"A2"},{"w":"camping","uk":"/ˈkæmpɪŋ/","p":"n.","zh":"露营；野营","ex":{"en":"We are going camping by the river this weekend.","zh":"这个周末我们要去河边露营。"},"tip":"活动名词camping不可数；去露营说go camping。","topic":"travel","cefr":"A2"},{"w":"ant","uk":"/ænt/","p":"n.","zh":"蚂蚁","ex":{"en":"An ant carried a crumb across the kitchen floor.","zh":"一只蚂蚁叼着面包屑爬过厨房地板。"},"tip":"ant是可数名词；一只蚂蚁用an ant。","topic":"nature","cefr":"A2"},{"w":"raise","uk":"/reɪz/","p":"v.","zh":"提高；举起","ex":{"en":"Please raise your hand if you need another pencil.","zh":"如果你还需要一支铅笔，请举手。"},"tip":"raise是及物动词，后接宾语；rise表示自身上升。","topic":"daily","cefr":"A2"},{"w":"set","uk":"/set/","p":"v.","zh":"放置；设置；确定","ex":{"en":"She set the bowl gently on the kitchen table.","zh":"她把碗轻轻放在厨房的桌子上。"},"tip":"过去式、过去分词均为set；现在分词为setting。","topic":"daily","cefr":"A2"},{"w":"feed","uk":"/fiːd/","p":"v.","zh":"喂养；进食","ex":{"en":"Please feed the cat before you leave for school.","zh":"请在上学前喂一下猫。"},"tip":"过去式和过去分词均为fed；feed on表示以……为食。","topic":"daily","cefr":"A2"},{"w":"pancake","uk":"/ˈpænkeɪk/","p":"n.","zh":"薄煎饼；松饼","ex":{"en":"He flipped the pancake and reached for the honey.","zh":"他把煎饼翻了个面，伸手去拿蜂蜜。"},"tip":"英式通常较薄，美式通常较厚且蓬松。","topic":"daily","cefr":"A2"},{"w":"except","uk":"/ɪkˈsept/","p":"prep.","zh":"除……之外","ex":{"en":"Everyone except my brother wanted to walk home.","zh":"除了我弟弟，大家都想走路回家。"},"tip":"except排除在外；besides表示另外还包括。","topic":"daily","cefr":"A2"},{"w":"still","uk":"/stɪl/","p":"adv.","zh":"仍然；还","ex":{"en":"It is nearly midnight, but my sister is still awake.","zh":"快到午夜了，可我姐姐还醒着。"},"tip":"表“仍然”时，通常放实义动词前、be动词后。","topic":"daily","cefr":"A2"},{"w":"fresh","uk":"/freʃ/","p":"adj.","zh":"新鲜的","ex":{"en":"I bought fresh strawberries from the market this morning.","zh":"今天早上我在市场买了新鲜草莓。"},"tip":"fresh water指淡水；fresh air指新鲜空气。","topic":"daily","cefr":"A2"},{"w":"comma","uk":"/ˈkɒmə/","p":"n.","zh":"逗号","ex":{"en":"I added a comma to make the sentence clearer.","zh":"我加了一个逗号，让句子更清楚。"},"tip":"comma是逗号，句号通常叫full stop（英）或period（美）。","topic":"education","cefr":"A2"},{"w":"destroy","uk":"/dɪˈstrɔɪ/","p":"v.","zh":"摧毁；毁灭","ex":{"en":"A sudden storm destroyed the old shed behind our house.","zh":"一场突如其来的暴风雨摧毁了我们屋后的旧棚子。"},"tip":"destroy比damage程度重，通常指彻底毁坏。","topic":"environment","cefr":"A2"},{"w":"professor","uk":"/prəˈfesə/","p":"n.","zh":"教授","ex":{"en":"Our professor brought ancient coins to class today.","zh":"我们的教授今天带了古钱币来上课。"},"tip":"英国通常指高级职称；美国也泛指大学教师。","topic":"education","cefr":"A2"},{"w":"headphone","uk":"/ˈhedfəʊn/","p":"n.","zh":"耳机的一个听筒","ex":{"en":"I wear headphones so my music won't disturb anyone.","zh":"我戴着耳机听音乐，这样就不会打扰别人。"},"tip":"日常说耳机通常用复数headphones，一副用a pair of。","topic":"technology","cefr":"A2"},{"w":"improve","uk":"/ɪmˈpruːv/","p":"v.","zh":"改善；提高；变好","ex":{"en":"My cooking has improved since I started practising daily.","zh":"自从开始每天练习，我的厨艺进步了。"},"tip":"既可及物也可不及物：improve skills；skills improve。","topic":"education","cefr":"A2"},{"w":"cotton","uk":"/ˈkɒtən/","p":"n.","zh":"棉花","ex":{"en":"This cotton shirt feels soft even after many washes.","zh":"这件棉衬衫洗了很多次后摸起来仍然很柔软。"},"tip":"通常不可数；cotton shirt中cotton作名词定语。","topic":"daily","cefr":"A2"},{"w":"relationship","uk":"/rɪˈleɪʃənʃɪp/","p":"n.","zh":"人际关系；恋爱关系","ex":{"en":"She has a warm relationship with her younger sister.","zh":"她和妹妹的关系很亲密。"},"tip":"与某人的关系用with；两者关系用between。","topic":"society","cefr":"A2"},{"w":"plus","uk":"/plʌs/","p":"prep.","zh":"加；加上","ex":{"en":"The room costs sixty pounds plus breakfast each night.","zh":"房间每晚六十英镑，早餐另收费。"},"tip":"plus作名词表示优点时可数，如a big plus。","topic":"daily","cefr":"A2"},{"w":"jazz","uk":"/dʒæz/","p":"n.","zh":"爵士乐","ex":{"en":"We listened to jazz while cooking dinner together.","zh":"我们一起做晚饭时听了爵士乐。"},"tip":"表示音乐类型时通常不可数，不加 a。","topic":"arts","cefr":"A2"},{"w":"kilogramme","uk":"/ˈkɪləɡræm/","p":"n.","zh":"千克；公斤","ex":{"en":"We bought a kilogramme of apples at the market.","zh":"我们在市场买了一公斤苹果。"},"tip":"英式拼写变体；kilogram更常用，符号kg不加s。","topic":"daily","cefr":"A2"},{"w":"onion","uk":"/ˈʌnjən/","p":"n.","zh":"洋葱","ex":{"en":"Chopping this onion is making my eyes water again.","zh":"切这个洋葱又让我流眼泪了。"},"tip":"开头是元音音素，单数前用an：an onion。","topic":"daily","cefr":"A2"},{"w":"storm","uk":"/stɔːm/","p":"n.","zh":"暴风雨；风暴","ex":{"en":"We stayed indoors while the storm shook the windows.","zh":"暴风雨震得窗户直响，我们一直待在屋里。"},"tip":"storm out表示愤然离开，不是风暴向外移动。","topic":"nature","cefr":"A2"},{"w":"neighbourhood","uk":"/ˈneɪbəhʊd/","p":"n.","zh":"街区；附近地区","ex":{"en":"A small bakery has just opened in our neighbourhood.","zh":"我们街区刚开了一家小面包店。"},"tip":"英式拼写为neighbourhood，美式为neighborhood。","topic":"city","cefr":"A2"},{"w":"thin","uk":"/θɪn/","p":"adj.","zh":"薄的；细的","ex":{"en":"I wore a thin jacket and felt cold outside.","zh":"我穿了件薄外套，在外面觉得冷。"},"tip":"形容身材时，thin不一定褒义；slim通常含赞美。","topic":"daily","cefr":"A2"},{"w":"print","uk":"/prɪnt/","p":"v.","zh":"印刷；打印","ex":{"en":"Could you print two copies of this recipe?","zh":"你能把这份食谱打印两份吗？"},"tip":"print out指打印出来；out of print则指书已绝版。","topic":"technology","cefr":"A2"},{"w":"permission","uk":"/pəˈmɪʃən/","p":"n.","zh":"许可；准许","ex":{"en":"You need permission to borrow your sister's bicycle.","zh":"你得先征得姐姐同意，才能借她的自行车。"},"tip":"通常不可数；说give permission，不加a。","topic":"society","cefr":"A2"},{"w":"sleepy","uk":"/ˈsliːpi/","p":"adj.","zh":"困倦的；想睡的","ex":{"en":"I felt sleepy after lunch and took a short nap.","zh":"午饭后我觉得困，就小睡了一会儿。"},"tip":"sleepy是想睡的；asleep是已经睡着的。","topic":"health","cefr":"A2"},{"w":"sick","uk":"/sɪk/","p":"adj.","zh":"生病的；不舒服的","ex":{"en":"He stayed in bed because he felt sick this morning.","zh":"他今天早上觉得不舒服，所以一直躺在床上。"},"tip":"英式英语中be sick常指呕吐，feel sick常指恶心。","topic":"health","cefr":"A2"},{"w":"straight","uk":"/streɪt/","p":"adj.","zh":"直的；笔直的","ex":{"en":"Use a ruler to draw a straight line.","zh":"用尺子画一条直线。"},"tip":"straight本身可作副词，不用加-ly。","topic":"daily","cefr":"A2"},{"w":"housework","uk":"/ˈhaʊswɜːk/","p":"n.","zh":"家务劳动","ex":{"en":"We share the housework so nobody spends Sunday cleaning alone.","zh":"我们分担家务，这样就没人需要独自在周日打扫了。"},"tip":"不可数，不能说a housework；做家务用do。","topic":"daily","cefr":"A2"},{"w":"noun","uk":"/naʊn/","p":"n.","zh":"名词","ex":{"en":"Our teacher asked us to circle every noun.","zh":"老师让我们把每个名词都圈出来。"},"tip":"名词不只指实物，也可指advice等抽象概念。","topic":"education","cefr":"A2"},{"w":"tablet","uk":"/ˈtæblət/","p":"n.","zh":"平板电脑","ex":{"en":"I use my tablet to watch cooking videos.","zh":"我用平板电脑看烹饪视频。"},"tip":"tablet既指平板电脑，也指药片，需看语境。","topic":"technology","cefr":"A2"},{"w":"toothache","uk":"/ˈtuːθeɪk/","p":"n.","zh":"牙痛","ex":{"en":"My toothache kept me awake for most of the night.","zh":"牙痛让我大半夜都没睡着。"},"tip":"英式常说have toothache，美式常说have a toothache。","topic":"health","cefr":"A2"},{"w":"temperature","uk":"/ˈtemprətʃə/","p":"n.","zh":"温度；气温；体温","ex":{"en":"The temperature dropped sharply after the sun went down.","zh":"太阳落山后，气温急剧下降。"},"tip":"have a temperature通常指发烧，不只是有体温。","topic":"science","cefr":"A2"},{"w":"enemy","uk":"/ˈenəmi/","p":"n.","zh":"敌人；敌方","ex":{"en":"In the story, the prince becomes friends with his enemy.","zh":"故事里，王子和他的敌人成了朋友。"},"tip":"enemy指敌人；比赛对手通常用opponent。","topic":"society","cefr":"A2"},{"w":"snowboarding","uk":"/ˈsnəʊbɔːdɪŋ/","p":"n.","zh":"单板滑雪运动","ex":{"en":"I tried snowboarding yesterday and landed in soft snow.","zh":"昨天我尝试了单板滑雪，摔进了松软的雪里。"},"tip":"snowboarding双脚固定在一块板上，区别于双板滑雪。","topic":"sport","cefr":"A2"},{"w":"skate","uk":"/skeɪt/","p":"v.","zh":"滑冰；滑旱冰","ex":{"en":"We skate around the rink every Saturday afternoon.","zh":"我们每周六下午都在溜冰场滑冰。"},"tip":"鞋子常用复数skates；go skating表示去滑冰。","topic":"sport","cefr":"A2"},{"w":"point","uk":"/pɔɪnt/","p":"n.","zh":"观点；要点","ex":{"en":"You made a good point about sharing the kitchen.","zh":"关于共用厨房，你说得很有道理。"},"tip":"make a point是提出观点；point at是指着。","topic":"thinking","cefr":"A2"},{"w":"none","uk":"/nʌn/","p":"pron.","zh":"一个也没有；毫无","ex":{"en":"I checked the biscuit tin, but there were none left.","zh":"我看了看饼干罐，但一块也没剩下。"},"tip":"none可独立用；修饰名词用no，如no books。","topic":"daily","cefr":"A2"},{"w":"ocean","uk":"/ˈəʊʃən/","p":"n.","zh":"海洋；大洋","ex":{"en":"We watched the sun rise over the ocean.","zh":"我们看着太阳从海面上升起。"},"tip":"ocean通常比sea范围大；专名常加the。","topic":"environment","cefr":"A2"},{"w":"pleasant","uk":"/ˈplezənt/","p":"adj.","zh":"令人愉快的；舒适的","ex":{"en":"We enjoyed a pleasant walk beside the river.","zh":"我们在河边愉快地散了步。"},"tip":"pleasant形容事物令人愉快；pleased形容人感到高兴。","topic":"daily","cefr":"A2"},{"w":"borrow","uk":"/ˈbɒrəʊ/","p":"v.","zh":"借入；借用","ex":{"en":"Could I borrow your umbrella until tomorrow morning?","zh":"我能借用一下你的伞，明天早上还吗？"},"tip":"borrow是借入，lend是借出；向某人借用from。","topic":"daily","cefr":"A2"},{"w":"seem","uk":"/siːm/","p":"v.","zh":"似乎；看来","ex":{"en":"You seem tired after your long walk home.","zh":"你走了那么远的路回家，看起来很累。"},"tip":"常用seem＋形容词或seem to do，不表示装作。","topic":"thinking","cefr":"A2"},{"w":"shelf","uk":"/ʃelf/","p":"n.","zh":"搁板；架子","ex":{"en":"Put the clean cups on the shelf above the sink.","zh":"把干净杯子放在水槽上方的架子上。"},"tip":"复数是shelves；shelf life指保质期。","topic":"daily","cefr":"A2"},{"w":"anyway","uk":"/ˈeniweɪ/","p":"adv.","zh":"即使如此；无论如何","ex":{"en":"It started raining, but we went for a walk anyway.","zh":"虽然开始下雨了，但我们还是去散步了。"},"tip":"anyway是副词；any way指任何方式。","topic":"daily","cefr":"A2"},{"w":"lipstick","uk":"/ˈlɪpstɪk/","p":"n.","zh":"口红；唇膏","ex":{"en":"She put on red lipstick before leaving the house.","zh":"她出门前涂了红色口红。"},"tip":"物质义不可数；一管口红用a tube of lipstick。","topic":"daily","cefr":"A2"},{"w":"cooker","uk":"/ˈkʊkə/","p":"n.","zh":"炉灶；炊具","ex":{"en":"The soup is bubbling in a pot on the cooker.","zh":"锅里的汤正在炉灶上咕嘟咕嘟地冒泡。"},"tip":"英式cooker指炉灶，美式常用stove；厨师是cook。","topic":"daily","cefr":"A2"},{"w":"clothing","uk":"/ˈkləʊðɪŋ/","p":"n.","zh":"衣服；服装（总称）","ex":{"en":"Pack some warm clothing for our weekend camping trip.","zh":"为我们周末的露营之旅带些保暖衣物。"},"tip":"clothing不可数；一件衣服用an item of clothing。","topic":"daily","cefr":"A2"},{"w":"height","uk":"/haɪt/","p":"n.","zh":"高度；身高","ex":{"en":"She adjusted the chair's height so her feet reached the floor.","zh":"她调节了椅子的高度，让双脚能够踩到地面。"},"tip":"height 是名词；形容人高用 tall，物体高可用 high。","topic":"daily","cefr":"A2"},{"w":"bake","uk":"/beɪk/","p":"v.","zh":"烘焙；烤","ex":{"en":"I baked some bread while the children set the table.","zh":"孩子们摆餐具时，我烤了些面包。"},"tip":"bake常用于面包、蛋糕；烤肉通常用roast。","topic":"daily","cefr":"A2"},{"w":"gardener","uk":"/ˈɡɑːdənə/","p":"n.","zh":"园丁；园艺爱好者","ex":{"en":"The gardener planted bright flowers along our front path.","zh":"园丁沿着我们门前的小路种下了鲜艳的花。"},"tip":"既可指职业园丁，也可指在自家种花种菜的爱好者。","topic":"work","cefr":"A2"},{"w":"nearly","uk":"/ˈnɪəli/","p":"adv.","zh":"几乎；差不多","ex":{"en":"I nearly missed the bus because I overslept.","zh":"我睡过了头，差点没赶上公交车。"},"tip":"nearly表示差一点达到；not nearly表示远远不。","topic":"daily","cefr":"A2"},{"w":"pyjamas","uk":"/pəˈdʒɑːməz/","p":"n.","zh":"睡衣裤","ex":{"en":"I put on my pyjamas and climbed into bed.","zh":"我穿上睡衣裤，爬上了床。"},"tip":"用复数；一套用a pair of；美式拼pajamas。","topic":"daily","cefr":"A2"},{"w":"century","uk":"/ˈsentʃəri/","p":"n.","zh":"世纪；一百年","ex":{"en":"This bridge was built more than a century ago.","zh":"这座桥建于一个多世纪以前。"},"tip":"世纪序数比年份前两位大一：如1901—2000为20世纪。","topic":"history","cefr":"A2"},{"w":"score","uk":"/skɔː/","p":"n.","zh":"得分；分数","ex":{"en":"My score improved after a week of practice.","zh":"练习一周后，我的分数提高了。"},"tip":"score可作名词或动词；score a goal指进球得分。","topic":"sport","cefr":"A2"},{"w":"cycling","uk":"/ˈsaɪklɪŋ/","p":"n.","zh":"骑自行车；自行车运动","ex":{"en":"We go cycling beside the river every Sunday morning.","zh":"我们每个星期天早上都沿河骑自行车。"},"tip":"表示这项活动时通常不可数；常说go cycling。","topic":"sport","cefr":"A2"},{"w":"act","uk":"/ækt/","p":"v.","zh":"行动；表现；扮演","ex":{"en":"We must act quickly before the kitchen sink overflows.","zh":"我们必须赶快采取行动，免得厨房水槽里的水溢出来。"},"tip":"act as表示充当；act还可指戏剧的一幕。","topic":"society","cefr":"A2"},{"w":"season","uk":"/ˈsiːzən/","p":"n.","zh":"季节","ex":{"en":"Autumn is my favourite season for walking in the woods.","zh":"秋天是我最喜欢去林中散步的季节。"},"tip":"season作动词指调味，常用season food with…。","topic":"nature","cefr":"A2"},{"w":"guess","uk":"/ɡes/","p":"v.","zh":"猜测；猜中","ex":{"en":"Can you guess what is inside this little box?","zh":"你能猜出这个小盒子里装着什么吗？"},"tip":"I guess偏口语，表示“我想、大概”，语气不确定。","topic":"thinking","cefr":"A2"},{"w":"timetable","uk":"/ˈtaɪmteɪbəl/","p":"n.","zh":"时间表；时刻表；课程表","ex":{"en":"I checked the timetable before leaving for the station.","zh":"去车站前，我查看了时刻表。"},"tip":"英式常用timetable；美式常用schedule。","topic":"education","cefr":"A2"},{"w":"princess","uk":"/ˌprɪnˈses/","p":"n.","zh":"公主；王妃","ex":{"en":"The princess waved to the crowd from her carriage.","zh":"公主从马车里向人群挥手。"},"tip":"可指君主的女儿，也可指王子的妻子。","topic":"society","cefr":"A2"},{"w":"gramme","uk":"/ɡræm/","p":"n.","zh":"克","ex":{"en":"Add one gramme of salt to the soup.","zh":"往汤里加一克盐。"},"tip":"gramme是英式变体；gram更常用，单位符号为g。","topic":"science","cefr":"A2"},{"w":"able","uk":"/ˈeɪbəl/","p":"adj.","zh":"能够的","ex":{"en":"I am finally able to swim across the pool.","zh":"我终于能够游到泳池的另一端了。"},"tip":"表示能够做某事用be able to do，不用able doing。","topic":"daily","cefr":"A2"},{"w":"ham","uk":"/hæm/","p":"n.","zh":"火腿","ex":{"en":"I put some ham and cheese in my sandwich.","zh":"我在三明治里放了些火腿和奶酪。"},"tip":"表示火腿肉通常不可数；一片用a slice of ham。","topic":"daily","cefr":"A2"},{"w":"garbage","uk":"/ˈɡɑːbɪdʒ/","p":"n.","zh":"垃圾；废弃物","ex":{"en":"Please take the garbage out before it starts smelling.","zh":"请在垃圾发臭之前把它拿出去。"},"tip":"不可数名词；常见于美式英语，英式多用rubbish。","topic":"environment","cefr":"A2"},{"w":"cleaner","uk":"/ˈkliːnə/","p":"n.","zh":"清洁工","ex":{"en":"The cleaner emptied the bins before the office opened.","zh":"清洁工在办公室开门前清空了垃圾桶。"},"tip":"a cleaner通常指清洁工；cleaner也是clean的比较级。","topic":"work","cefr":"A2"},{"w":"degree","uk":"/dɪˈɡriː/","p":"n.","zh":"学位","ex":{"en":"My cousin earned a degree in engineering last summer.","zh":"我表姐去年夏天获得了工程学学位。"},"tip":"某专业的学位用a degree in；程度义常见to some degree。","topic":"education","cefr":"A2"},{"w":"textbook","uk":"/ˈtekstbʊk/","p":"n.","zh":"教科书；课本","ex":{"en":"I left my science textbook on the kitchen table.","zh":"我把科学课本落在厨房桌上了。"},"tip":"作形容词时指典型或标准，如textbook example。","topic":"education","cefr":"A2"},{"w":"leather","uk":"/ˈleðə/","p":"n.","zh":"皮革","ex":{"en":"Her old leather bag still feels soft and smooth.","zh":"她的旧皮包摸起来仍然柔软光滑。"},"tip":"通常不可数；leather jacket中名词作定语。","topic":"daily","cefr":"A2"},{"w":"truck","uk":"/trʌk/","p":"n.","zh":"卡车；载货汽车","ex":{"en":"A truck delivered fresh vegetables to the market this morning.","zh":"今天早晨，一辆卡车把新鲜蔬菜送到了市场。"},"tip":"truck常用于美式英语，英式英语常用lorry。","topic":"travel","cefr":"A2"},{"w":"toaster","uk":"/ˈtəʊstə/","p":"n.","zh":"烤面包机","ex":{"en":"Two slices of bread popped out of the toaster.","zh":"两片面包从烤面包机里弹了出来。"},"tip":"toaster是电器；toast指烤面包时不可数。","topic":"daily","cefr":"A2"},{"w":"yogurt","uk":"/ˈjɒɡət/","p":"n.","zh":"酸奶","ex":{"en":"I mix fresh berries into my yogurt every morning.","zh":"我每天早上都往酸奶里拌入新鲜浆果。"},"tip":"英式也常拼作yoghurt；通常不可数，一份可用a yogurt。","topic":"health","cefr":"A2"},{"w":"recent","uk":"/ˈriːsənt/","p":"adj.","zh":"最近的；不久前的","ex":{"en":"Have you seen any recent photos of our puppy?","zh":"你看过我们家小狗最近的照片吗？"},"tip":"recent是形容词；修饰动作要用recently。","topic":"daily","cefr":"A2"},{"w":"burger","uk":"/ˈbɜːɡə/","p":"n.","zh":"汉堡包；汉堡肉饼","ex":{"en":"I ordered a bean burger with salad for lunch.","zh":"我午餐点了一个豆类汉堡配沙拉。"},"tip":"burger也可指肉饼本身，并非都以牛肉制成。","topic":"daily","cefr":"A2"},{"w":"nearest","uk":"/ˈnɪərɪst/","p":"adj.","zh":"最近的；最接近的","ex":{"en":"Could you show me the way to the nearest pharmacy?","zh":"你能告诉我去最近的药店怎么走吗？"},"tip":"near的最高级；作定语时通常用the nearest。","topic":"city","cefr":"A2"},{"w":"candle","uk":"/ˈkændl/","p":"n.","zh":"蜡烛","ex":{"en":"He lit a candle when the electricity went off.","zh":"停电时，他点了一支蜡烛。"},"tip":"点蜡烛用light；吹灭用blow out。","topic":"daily","cefr":"A2"},{"w":"behavior","uk":"/bɪˈheɪvjə/","p":"n.","zh":"行为；举止","ex":{"en":"The puppy's calm behavior surprised everyone at the park.","zh":"这只小狗安静的表现让公园里的每个人都很惊讶。"},"tip":"美式拼写；英式为behaviour。通常不可数。","topic":"society","cefr":"A2"},{"w":"factory","uk":"/ˈfæktəri/","p":"n.","zh":"工厂","ex":{"en":"My aunt works at a factory that makes bicycles.","zh":"我姑姑在一家生产自行车的工厂工作。"},"tip":"复数为factories；指制造产品的场所。","topic":"work","cefr":"A2"},{"w":"available","uk":"/əˈveɪləbl/","p":"adj.","zh":"可获得的；可使用的","ex":{"en":"There are still tickets available for the afternoon show.","zh":"下午那场演出的门票还有余票。"},"tip":"available to接使用者；available for接用途。","topic":"daily","cefr":"A2"},{"w":"wish","uk":"/wɪʃ/","p":"v.","zh":"但愿；希望","ex":{"en":"I wish our flat had a bigger kitchen.","zh":"要是我们的公寓有个更大的厨房就好了。"},"tip":"wish后用过去式表现在的遗憾；过去完成式表过去的遗憾。","topic":"emotion","cefr":"A2"},{"w":"furniture","uk":"/ˈfɜːnɪtʃə/","p":"n.","zh":"家具","ex":{"en":"We moved the furniture to make room for dancing.","zh":"我们挪开家具，腾出地方跳舞。"},"tip":"不可数：一件家具说a piece of furniture。","topic":"daily","cefr":"A2"},{"w":"rose","uk":"/rəʊz/","p":"n.","zh":"玫瑰；蔷薇","ex":{"en":"She placed a single rose in a glass vase.","zh":"她把一枝玫瑰插进了玻璃花瓶。"},"tip":"rose也可作rise的过去式；过去分词是risen。","topic":"nature","cefr":"A2"},{"w":"button","uk":"/ˈbʌtən/","p":"n.","zh":"按钮","ex":{"en":"Press the green button to start the washing machine.","zh":"按绿色按钮启动洗衣机。"},"tip":"button up指扣好纽扣；拉链用zip，不用button。","topic":"daily","cefr":"A2"},{"w":"island","uk":"/ˈaɪlənd/","p":"n.","zh":"岛；岛屿","ex":{"en":"We took a small boat to the island yesterday.","zh":"昨天我们乘小船去了那座岛。"},"tip":"s不发音；在岛上用on an island。","topic":"nature","cefr":"A2"},{"w":"cream","uk":"/kriːm/","p":"n.","zh":"奶油；乳脂","ex":{"en":"She poured fresh cream over a bowl of strawberries.","zh":"她把新鲜奶油浇在一碗草莓上。"},"tip":"cream是奶油或乳霜；cheese才是奶酪。","topic":"daily","cefr":"A2"},{"w":"worried","uk":"/ˈwʌrid/","p":"adj.","zh":"担心的；焦虑的","ex":{"en":"She looked worried when her cat failed to return.","zh":"猫没有回来时，她显得很担心。"},"tip":"worried形容人担忧；worrying形容事物令人担忧。","topic":"emotion","cefr":"A2"},{"w":"careful","uk":"/ˈkeəfəl/","p":"adj.","zh":"小心的；谨慎的","ex":{"en":"Be careful with that bowl; it belonged to Grandma.","zh":"小心拿那个碗，那是奶奶以前用的。"},"tip":"be careful with后接物；be careful to后接动词。","topic":"daily","cefr":"A2"},{"w":"unusual","uk":"/ʌnˈjuːʒuəl/","p":"adj.","zh":"不寻常的；与众不同的","ex":{"en":"This carrot has an unusual shape, like a tiny hand.","zh":"这根胡萝卜的形状很特别，像一只小手。"},"tip":"It is unusual for sb to do表示某人很少这样做。","topic":"daily","cefr":"A2"},{"w":"app","uk":"/æp/","p":"n.","zh":"应用程序","ex":{"en":"This app reminds me to water my plants every Sunday.","zh":"这个应用程序每周日提醒我给植物浇水。"},"tip":"app是application的缩写；为可数名词，用an app。","topic":"technology","cefr":"A2"},{"w":"lip","uk":"/lɪp/","p":"n.","zh":"嘴唇","ex":{"en":"My lips felt dry after walking in the wind.","zh":"在风中走了一阵后，我觉得嘴唇很干。"},"tip":"上下嘴唇合称lips；lip也可指容器等的边沿。","topic":"health","cefr":"A2"},{"w":"tourism","uk":"/ˈtʊərɪzəm/","p":"n.","zh":"旅游业；观光旅游","ex":{"en":"Tourism brings many visitors to our village each summer.","zh":"每年夏天，旅游业都会为我们村带来许多游客。"},"tip":"tourism通常不可数；表示一个游客用a tourist。","topic":"travel","cefr":"A2"},{"w":"kangaroo","uk":"/ˌkæŋɡəˈruː/","p":"n.","zh":"袋鼠","ex":{"en":"A young kangaroo peeked out of its mother's pouch.","zh":"一只小袋鼠从妈妈的育儿袋里探出头来。"},"tip":"复数直接加-s：kangaroos；育儿袋叫pouch。","topic":"nature","cefr":"A2"},{"w":"journey","uk":"/ˈdʒɜːni/","p":"n.","zh":"旅行；行程","ex":{"en":"The train journey took us through snowy mountains.","zh":"这趟火车旅程带我们穿过了白雪覆盖的群山。"},"tip":"journey侧重路途；trip常指包含往返的出行。","topic":"travel","cefr":"A2"},{"w":"handbag","uk":"/ˈhændbæɡ/","p":"n.","zh":"手提包；女式手袋","ex":{"en":"She found her keys at the bottom of her handbag.","zh":"她在手提包底部找到了钥匙。"},"tip":"美式常用purse指女式手袋；英式purse通常指零钱包。","topic":"daily","cefr":"A2"},{"w":"cherry","uk":"/ˈtʃeri/","p":"n.","zh":"樱桃","ex":{"en":"He placed a ripe cherry on top of the cake.","zh":"他在蛋糕顶上放了一颗熟透的樱桃。"},"tip":"复数为cherries；果核用stone（英）或pit（美）。","topic":"daily","cefr":"A2"},{"w":"heavy","uk":"/ˈhevi/","p":"adj.","zh":"沉重的","ex":{"en":"This suitcase is too heavy for me to lift.","zh":"这个行李箱太重了，我提不起来。"},"tip":"大雨用heavy rain，不用big rain。","topic":"daily","cefr":"A2"},{"w":"postman","uk":"/ˈpəʊstmən/","p":"n.","zh":"男邮递员","ex":{"en":"The postman left a parcel beside our front door.","zh":"邮递员把一个包裹放在了我们家门旁。"},"tip":"英式常用；美式常用mail carrier，且不限定性别。","topic":"work","cefr":"A2"},{"w":"chat","uk":"/tʃæt/","p":"v.","zh":"闲聊；网聊","ex":{"en":"We chatted about our weekend while waiting for the bus.","zh":"等公交车时，我们聊起了各自的周末。"},"tip":"chat with人、about话题；过去式chatted双写t。","topic":"daily","cefr":"A2"},{"w":"hurt","uk":"/hɜːt/","p":"v.","zh":"疼痛；使受伤","ex":{"en":"My ankle still hurts when I climb the stairs.","zh":"我上楼梯时，脚踝还是疼。"},"tip":"过去式和过去分词均为 hurt；疼痛部位可作主语。","topic":"health","cefr":"A2"},{"w":"fortunately","uk":"/ˈfɔːtʃənətli/","p":"adv.","zh":"幸运地；幸好","ex":{"en":"Fortunately, I found my keys before the bus arrived.","zh":"幸好，我在公交车到站前找到了钥匙。"},"tip":"常置于句首，后加逗号，评价整件事令人庆幸。","topic":"emotion","cefr":"A2"},{"w":"roll","uk":"/rəʊl/","p":"v.","zh":"滚动；使滚动","ex":{"en":"The orange rolled off the table and under my chair.","zh":"橙子从桌上滚下来，滚到了我的椅子底下。"},"tip":"roll强调翻转滚动；卷起常用roll up。","topic":"daily","cefr":"A2"},{"w":"quarter","uk":"/ˈkwɔːtə/","p":"n.","zh":"四分之一","ex":{"en":"She cut the sandwich into quarters for the children.","zh":"她把三明治切成四等份给孩子们吃。"},"tip":"a quarter of an hour是一刻钟；季度也是quarter。","topic":"daily","cefr":"A2"},{"w":"task","uk":"/tɑːsk/","p":"n.","zh":"任务；工作","ex":{"en":"My first task today is to water the plants.","zh":"我今天的第一项任务是给植物浇水。"},"tip":"作动词用task sb with doing sth，表示指派任务。","topic":"work","cefr":"A2"},{"w":"advice","uk":"/ədˈvaɪs/","p":"n.","zh":"建议；忠告","ex":{"en":"Your advice helped me choose a comfortable bicycle.","zh":"你的建议帮我选到了一辆骑着舒服的自行车。"},"tip":"不可数，不用an advice；动词advise末尾读/z/。","topic":"daily","cefr":"A2"},{"w":"excellent","uk":"/ˈeksələnt/","p":"adj.","zh":"极好的；优秀的","ex":{"en":"The soup was excellent, so I ordered another bowl.","zh":"这汤好喝极了，所以我又点了一碗。"},"tip":"已含“极好”之意，通常不用very修饰。","topic":"daily","cefr":"A2"},{"w":"boil","uk":"/bɔɪl/","p":"v.","zh":"沸腾；使煮沸","ex":{"en":"Boil the potatoes until you can pierce them easily.","zh":"把土豆煮到能轻松戳穿为止。"},"tip":"boil指沸腾或煮沸；simmer指小火慢煮。","topic":"daily","cefr":"A2"},{"w":"sauce","uk":"/sɔːs/","p":"n.","zh":"酱；调味汁","ex":{"en":"This tomato sauce tastes lovely with fresh pasta.","zh":"这种番茄酱汁配新鲜意面很好吃。"},"tip":"sauce泛指酱汁；酱油应说soy sauce。","topic":"daily","cefr":"A2"},{"w":"moustache","uk":"/məˈstɑːʃ/","p":"n.","zh":"上唇胡须；小胡子","ex":{"en":"My uncle carefully trims his moustache every Sunday.","zh":"我叔叔每个星期天都会仔细修剪他的小胡子。"},"tip":"moustache指上唇胡须；beard指下巴等处的胡须。","topic":"daily","cefr":"A2"},{"w":"uniform","uk":"/ˈjuːnɪfɔːm/","p":"n.","zh":"制服；校服","ex":{"en":"My school uniform is still drying by the window.","zh":"我的校服还在窗边晾着。"},"tip":"开头是辅音/j/，所以说a uniform，不用an。","topic":"work","cefr":"A2"},{"w":"instruction","uk":"/ɪnˈstrʌkʃən/","p":"n.","zh":"指示；操作说明","ex":{"en":"The instructor gave one clear instruction: hold the rope tightly.","zh":"教练给出了一条明确指示：紧紧抓住绳子。"},"tip":"操作说明常用复数instructions；表示教学时不可数。","topic":"education","cefr":"A2"},{"w":"download","uk":"/ˌdaʊnˈləʊd/","p":"v.","zh":"下载","ex":{"en":"Download the map before you leave the hotel tomorrow.","zh":"明天离开酒店前，先把地图下载好。"},"tip":"动词重音在后，名词重音在前；反义词是upload。","topic":"technology","cefr":"A2"},{"w":"frightened","uk":"/ˈfraɪtənd/","p":"adj.","zh":"害怕的；受惊的","ex":{"en":"The frightened kitten hid behind the sofa during the storm.","zh":"暴风雨中，受惊的小猫躲到了沙发后面。"},"tip":"frightened形容感到害怕；frightening形容令人害怕。","topic":"emotion","cefr":"A2"},{"w":"surname","uk":"/ˈsɜːneɪm/","p":"n.","zh":"姓；姓氏","ex":{"en":"My surname is often difficult for strangers to pronounce.","zh":"陌生人常常觉得我的姓很难念。"},"tip":"surname指姓，given name指名；姓不一定在最后。","topic":"society","cefr":"A2"},{"w":"memory","uk":"/ˈmeməri/","p":"n.","zh":"记忆力；记忆","ex":{"en":"My grandmother has an excellent memory for faces.","zh":"我奶奶特别善于记住别人的长相。"},"tip":"记忆力通常不可数；一段段回忆用memories。","topic":"thinking","cefr":"A2"},{"w":"pillow","uk":"/ˈpɪləʊ/","p":"n.","zh":"枕头","ex":{"en":"She placed a fresh pillow on the guest bed.","zh":"她在客床上放了一个干净的枕头。"},"tip":"pillow主要用于睡觉；cushion多指靠垫或坐垫。","topic":"daily","cefr":"A2"},{"w":"program","uk":"/ˈprəʊɡræm/","p":"n.","zh":"计算机程序","ex":{"en":"This program helps me organise all my holiday photos.","zh":"这个程序帮我整理所有度假照片。"},"tip":"英式计算机程序用program；计划、节目用programme。","topic":"technology","cefr":"A2"},{"w":"sign","uk":"/saɪn/","p":"n.","zh":"迹象；征兆","ex":{"en":"Those dark clouds are a sign of approaching rain.","zh":"那些乌云预示着雨就要来了。"},"tip":"sign中的g不发音；a sign of后接名词或动名词。","topic":"daily","cefr":"A2"},{"w":"per","uk":"/pə(r)/","p":"prep.","zh":"每；每一","ex":{"en":"The swimming pool costs five pounds per visit.","zh":"这个游泳池每次收费五英镑。"},"tip":"per后通常接单数名词，不加冠词，如per day。","topic":"economy","cefr":"A2"},{"w":"chemistry","uk":"/ˈkemɪstri/","p":"n.","zh":"化学","ex":{"en":"We mixed two clear liquids in chemistry class today.","zh":"今天化学课上，我们把两种透明液体混合在一起。"},"tip":"学科名通常不可数：study chemistry，不加a。","topic":"science","cefr":"A2"},{"w":"hang","uk":"/hæŋ/","p":"v.","zh":"悬挂；吊着","ex":{"en":"Please hang your wet coat beside the front door.","zh":"请把你的湿外套挂在前门旁边。"},"tip":"悬挂的过去式、过去分词均为hung；绞死则用hanged。","topic":"daily","cefr":"A2"},{"w":"especially","uk":"/ɪˈspeʃəli/","p":"adv.","zh":"尤其；特别","ex":{"en":"I enjoy cooking, especially when friends come for dinner.","zh":"我喜欢做饭，尤其是在朋友来吃晚饭的时候。"},"tip":"especially强调“尤其”；specially常指“专门地”。","topic":"daily","cefr":"A2"},{"w":"countryside","uk":"/ˈkʌntrisaɪd/","p":"n.","zh":"乡村；农村地区","ex":{"en":"We spent the weekend cycling through the quiet countryside.","zh":"我们周末在宁静的乡间骑车游玩。"},"tip":"通常不可数，常说the countryside，不说a countryside。","topic":"nature","cefr":"A2"},{"w":"health","uk":"/helθ/","p":"n.","zh":"健康；身体状况","ex":{"en":"Walking to work has really improved my health.","zh":"步行上班确实改善了我的健康状况。"},"tip":"通常不可数；表示身体健康用in good health。","topic":"health","cefr":"A2"},{"w":"mobile","uk":"/ˈməʊbaɪl/","p":"adj.","zh":"可移动的；流动的","ex":{"en":"The mobile library visits our village every Friday morning.","zh":"流动图书馆每周五早晨来我们村。"},"tip":"英式英语常用a mobile指手机；美式常说a cell phone。","topic":"technology","cefr":"A2"},{"w":"leaves","uk":"/liːvz/","p":"n.","zh":"叶子（leaf的复数）","ex":{"en":"Golden leaves covered the path outside our house.","zh":"金黄色的落叶铺满了我们家门外的小路。"},"tip":"既是leaf的复数，也是leave的第三人称单数形式。","topic":"nature","cefr":"A2"},{"w":"super","uk":"/ˈsuːpə/","p":"adj.","zh":"极好的；棒极了的","ex":{"en":"We had a super afternoon playing games in the garden.","zh":"我们在花园里玩游戏，度过了一个特别愉快的下午。"},"tip":"口语色彩强；正式写作宜用excellent或very。","topic":"daily","cefr":"A2"},{"w":"decision","uk":"/dɪˈsɪʒən/","p":"n.","zh":"决定；抉择","ex":{"en":"Moving closer to work was a good decision.","zh":"搬到离工作地点更近的地方是个明智的决定。"},"tip":"作决定用make a decision，不用do。","topic":"thinking","cefr":"A2"},{"w":"heat","uk":"/hiːt/","p":"n.","zh":"热；高温","ex":{"en":"We rested under a tree to escape the heat.","zh":"我们在树下休息，躲避酷热。"},"tip":"heat作名词指热，hot作形容词指热的。","topic":"daily","cefr":"A2"},{"w":"lunchtime","uk":"/ˈlʌntʃtaɪm/","p":"n.","zh":"午餐时间","ex":{"en":"At lunchtime, we sat outside and shared some sandwiches.","zh":"午餐时，我们坐在外面分着吃了一些三明治。"},"tip":"表示“在午餐时间”通常用at lunchtime。","topic":"daily","cefr":"A2"},{"w":"winner","uk":"/ˈwɪnə/","p":"n.","zh":"获胜者；优胜者","ex":{"en":"The winner lifted her trophy as the crowd cheered.","zh":"获胜者举起奖杯，人群欢呼起来。"},"tip":"winner 指获胜者；winning 可作形容词修饰队伍。","topic":"sport","cefr":"A2"},{"w":"mathematics","uk":"/ˌmæθəˈmætɪks/","p":"n.","zh":"数学","ex":{"en":"She enjoys mathematics, especially solving puzzles about shapes.","zh":"她喜欢数学，尤其喜欢解与图形有关的谜题。"},"tip":"虽以s结尾，作学科名用单数谓语；英式简称maths。","topic":"education","cefr":"A2"},{"w":"fear","uk":"/fɪə/","p":"n.","zh":"恐惧；担忧","ex":{"en":"She held my hand because of her fear of heights.","zh":"她因为恐高而握住了我的手。"},"tip":"fear sth是害怕某事；fear for sb是为某人担忧。","topic":"emotion","cefr":"A2"},{"w":"prefer","uk":"/prɪˈfɜː/","p":"v.","zh":"更喜欢；宁愿","ex":{"en":"I prefer fresh fruit to cake after dinner.","zh":"晚饭后，比起蛋糕，我更喜欢吃新鲜水果。"},"tip":"用prefer A to B；过去式preferred双写r。","topic":"thinking","cefr":"A2"},{"w":"cucumber","uk":"/ˈkjuːkʌmbə/","p":"n.","zh":"黄瓜","ex":{"en":"She sliced a cucumber and added it to the salad.","zh":"她把一根黄瓜切成片，加入沙拉。"},"tip":"通常可数：a cucumber；表示食材时也可不可数。","topic":"daily","cefr":"A2"},{"w":"wifi","uk":"/ˈwaɪ faɪ/","p":"n.","zh":"无线网络；无线联网技术","ex":{"en":"The café offers free wifi near the window seats.","zh":"这家咖啡馆靠窗的座位附近有免费无线网络。"},"tip":"常规范写作Wi-Fi；通常不可数，不加a。","topic":"technology","cefr":"A2"},{"w":"beauty","uk":"/ˈbjuːti/","p":"n.","zh":"美；美丽","ex":{"en":"We stopped to admire the beauty of the lake.","zh":"我们停下来欣赏湖泊的美景。"},"tip":"表示“美”通常不可数；the beauty of也指妙处。","topic":"nature","cefr":"A2"},{"w":"nearby","uk":"/ˌnɪəˈbaɪ/","p":"adj.","zh":"附近的；邻近的","ex":{"en":"We bought fresh bread from a nearby bakery.","zh":"我们从附近的一家面包店买了新鲜面包。"},"tip":"nearby不用作介词：说near the school，不说nearby the school。","topic":"city","cefr":"A2"},{"w":"cost","uk":"/kɒst/","p":"n.","zh":"费用；成本","ex":{"en":"The cost of our weekly groceries keeps rising.","zh":"我们每周购买食品杂货的费用不断上涨。"},"tip":"表示花费时，过去式和过去分词均为cost。","topic":"economy","cefr":"A2"},{"w":"tent","uk":"/tent/","p":"n.","zh":"帐篷","ex":{"en":"We pitched our tent beside a quiet lake.","zh":"我们在一个宁静的湖边搭起帐篷。"},"tip":"“搭帐篷”用pitch或put up a tent。","topic":"travel","cefr":"A2"},{"w":"whose","uk":"/huːz/","p":"det.","zh":"谁的；其…的","ex":{"en":"Whose umbrella is dripping water all over the floor?","zh":"谁的雨伞把水滴得满地都是？"},"tip":"whose表示所属；who’s是who is或who has的缩写。","topic":"daily","cefr":"A2"},{"w":"bacon","uk":"/ˈbeɪkən/","p":"n.","zh":"培根；腌熏猪肉","ex":{"en":"He cooked bacon and eggs for breakfast on Sunday.","zh":"星期天，他做了培根和鸡蛋当早餐。"},"tip":"通常不可数；一片培根用a slice of bacon。","topic":"daily","cefr":"A2"},{"w":"happily","uk":"/ˈhæpɪli/","p":"adv.","zh":"快乐地；高兴地","ex":{"en":"The children chatted happily while making sandwiches together.","zh":"孩子们一起做三明治，开心地聊着天。"},"tip":"句首Happily可表“幸好”，不只表示开心。","topic":"emotion","cefr":"A2"},{"w":"brain","uk":"/breɪn/","p":"n.","zh":"大脑；脑","ex":{"en":"A helmet helps protect your brain if you fall.","zh":"跌倒时，头盔有助于保护你的大脑。"},"tip":"表示智力时常用复数brains；器官用brain。","topic":"health","cefr":"A2"},{"w":"crowded","uk":"/ˈkraʊdɪd/","p":"adj.","zh":"拥挤的；挤满的","ex":{"en":"The bus was so crowded that we stood all the way.","zh":"公交车太拥挤了，我们一路都站着。"},"tip":"be crowded with 表示“挤满……”。","topic":"city","cefr":"A2"},{"w":"promise","uk":"/ˈprɒmɪs/","p":"v.","zh":"承诺；答应","ex":{"en":"I promise to return your bicycle before dinner.","zh":"我保证晚饭前把自行车还给你。"},"tip":"用promise to do，不用promise doing。","topic":"society","cefr":"A2"},{"w":"unhappy","uk":"/ʌnˈhæpi/","p":"adj.","zh":"不快乐的；难过的","ex":{"en":"He looked unhappy when the picnic was cancelled.","zh":"野餐取消后，他显得很不开心。"},"tip":"unhappy with常表示“对……不满意”。","topic":"emotion","cefr":"A2"},{"w":"matter","uk":"/ˈmætə/","p":"n.","zh":"事情；问题","ex":{"en":"We can discuss this matter after lunch today.","zh":"我们可以今天午饭后讨论这件事。"},"tip":"指事情时通常可数；指物质时不可数；作动词表示要紧。","topic":"daily","cefr":"A2"},{"w":"sunshine","uk":"/ˈsʌnʃaɪn/","p":"n.","zh":"阳光","ex":{"en":"We ate our breakfast outside in the warm sunshine.","zh":"我们在外面温暖的阳光下吃了早餐。"},"tip":"sunshine通常不可数；表示晴天可说a sunny day。","topic":"nature","cefr":"A2"},{"w":"engineer","uk":"/ˌendʒɪˈnɪə/","p":"n.","zh":"工程师","ex":{"en":"An engineer checked the bridge before it opened.","zh":"一位工程师在桥梁通车前进行了检查。"},"tip":"engineer也可作动词，表示设计或策划促成。","topic":"work","cefr":"A2"},{"w":"midday","uk":"/ˌmɪdˈdeɪ/","p":"n.","zh":"中午；正午","ex":{"en":"We stopped for a picnic beside the lake at midday.","zh":"中午，我们停下来在湖边野餐。"},"tip":"时间前用at；也可置于名词前，如midday sun。","topic":"daily","cefr":"A2"},{"w":"bookshelf","uk":"/ˈbʊkʃelf/","p":"n.","zh":"书架；书橱中的搁板","ex":{"en":"She placed her favourite novel on the wooden bookshelf.","zh":"她把最喜欢的小说放到了木书架上。"},"tip":"复数为bookshelves，注意把f变为ves。","topic":"daily","cefr":"A2"},{"w":"attractive","uk":"/əˈtræktɪv/","p":"adj.","zh":"好看的；有魅力的","ex":{"en":"The garden looks especially attractive when the roses bloom.","zh":"玫瑰盛开时，这座花园显得格外美丽。"},"tip":"既可形容外表好看，也可形容方案、薪资诱人。","topic":"daily","cefr":"A2"},{"w":"view","uk":"/vjuː/","p":"n.","zh":"观点；看法","ex":{"en":"My view is that we should leave earlier.","zh":"我的看法是我们应该早点出发。"},"tip":"观点用view on；把某事视为用view…as…。","topic":"thinking","cefr":"A2"},{"w":"finally","uk":"/ˈfaɪnəli/","p":"adv.","zh":"终于","ex":{"en":"After searching all morning, I finally found my keys.","zh":"找了一上午后，我终于找到了钥匙。"},"tip":"表示终于常置于实义动词前；引出最后一点常置句首。","topic":"daily","cefr":"A2"},{"w":"doll","uk":"/dɒl/","p":"n.","zh":"玩偶；洋娃娃","ex":{"en":"My little cousin tucked her doll into a tiny bed.","zh":"我的小表妹把她的洋娃娃安顿在一张小床上。"},"tip":"通常指人形玩具；用来称呼女性可能显得轻慢。","topic":"daily","cefr":"A2"},{"w":"excuse","uk":"/ɪkˈskjuːs/","p":"n.","zh":"借口；辩解理由","ex":{"en":"He made an excuse for arriving late to dinner.","zh":"他为晚餐迟到找了个借口。"},"tip":"名词末尾读/s/，动词读/z/；excuse me常用于礼貌打断。","topic":"daily","cefr":"A2"},{"w":"thick","uk":"/θɪk/","p":"adj.","zh":"厚的；粗的","ex":{"en":"She wrapped a thick blanket around her cold shoulders.","zh":"她把一条厚毯子裹在冰冷的肩膀上。"},"tip":"形容液体时指黏稠，不一定表示味道浓。","topic":"daily","cefr":"A2"},{"w":"chess","uk":"/tʃes/","p":"n.","zh":"国际象棋","ex":{"en":"My grandfather taught me chess during the winter holidays.","zh":"寒假期间，爷爷教我下国际象棋。"},"tip":"说play chess，不加冠词the。","topic":"sport","cefr":"A2"},{"w":"kilo","uk":"/ˈkiːləʊ/","p":"n.","zh":"千克；公斤","ex":{"en":"Could I have half a kilo of tomatoes, please?","zh":"请给我半公斤西红柿，好吗？"},"tip":"kilo通常是kilogram的简称，不指公里。","topic":"daily","cefr":"A2"},{"w":"illness","uk":"/ˈɪlnəs/","p":"n.","zh":"疾病；生病","ex":{"en":"She missed our picnic because of a sudden illness.","zh":"她突然生病，没能参加我们的野餐。"},"tip":"泛指生病时不可数；指具体疾病时可数。","topic":"health","cefr":"A2"},{"w":"headache","uk":"/ˈhedeɪk/","p":"n.","zh":"头痛","ex":{"en":"I have a headache, so I need some quiet.","zh":"我头痛，需要安静一会儿。"},"tip":"表示一次头痛用a headache，通常说have a headache。","topic":"health","cefr":"A2"},{"w":"dustbin","uk":"/ˈdʌstbɪn/","p":"n.","zh":"垃圾桶","ex":{"en":"Please put that rubbish in the dustbin outside.","zh":"请把那些垃圾放进外面的垃圾桶。"},"tip":"英式用词；美式常用garbage can或trash can。","topic":"daily","cefr":"A2"},{"w":"appear","uk":"/əˈpɪə/","p":"v.","zh":"出现；显现","ex":{"en":"Stars began to appear as the sky grew darker.","zh":"天空渐渐变暗，星星开始出现。"},"tip":"表“似乎”可接形容词或to do；不能直接接宾语。","topic":"daily","cefr":"A2"},{"w":"nowhere","uk":"/ˈnəʊweə/","p":"adv.","zh":"无处；哪里都不","ex":{"en":"There was nowhere to sit on the crowded train.","zh":"拥挤的火车上没有地方可坐。"},"tip":"本身含否定意义：I have nowhere to go。","topic":"daily","cefr":"A2"},{"w":"bee","uk":"/biː/","p":"n.","zh":"蜜蜂","ex":{"en":"A bee landed gently on the yellow flower.","zh":"一只蜜蜂轻轻落在那朵黄花上。"},"tip":"bee与be同音；蜂群可用a swarm of bees。","topic":"nature","cefr":"A2"},{"w":"barbecue","uk":"/ˈbɑːbɪkjuː/","p":"n.","zh":"户外烧烤聚餐","ex":{"en":"We invited our neighbours to a barbecue in the garden.","zh":"我们邀请邻居来花园参加烧烤聚餐。"},"tip":"既指烧烤聚餐或烤架，也可作动词；常缩写为BBQ。","topic":"daily","cefr":"A2"},{"w":"invitation","uk":"/ˌɪnvɪˈteɪʃən/","p":"n.","zh":"邀请；请帖","ex":{"en":"We received an invitation to our neighbour's garden party.","zh":"我们收到了邻居花园聚会的邀请。"},"tip":"参加活动用invitation to；邀请做事用to do。","topic":"society","cefr":"A2"},{"w":"secretary","uk":"/ˈsekrətri/","p":"n.","zh":"秘书","ex":{"en":"The secretary arranged a meeting for tomorrow afternoon.","zh":"秘书安排了明天下午的会议。"},"tip":"既可指办公室秘书，也可指某些政府部长。","topic":"work","cefr":"A2"},{"w":"onto","uk":"/ˈɒntə/","p":"prep.","zh":"到……上面","ex":{"en":"The cat jumped onto the sofa beside me.","zh":"猫跳到我旁边的沙发上。"},"tip":"onto强调移动到表面；on常表示已在上面。","topic":"daily","cefr":"A2"},{"w":"prize","uk":"/praɪz/","p":"n.","zh":"奖品；奖金；奖项","ex":{"en":"Lina won a prize for her colourful garden.","zh":"莉娜因她色彩缤纷的花园获了奖。"},"tip":"prize可作动词表珍视，常见be highly prized。","topic":"education","cefr":"A2"},{"w":"popcorn","uk":"/ˈpɒpkɔːn/","p":"n.","zh":"爆米花","ex":{"en":"We shared a bowl of popcorn during the film.","zh":"看电影时，我们一起吃了一碗爆米花。"},"tip":"通常是不可数名词；一颗可说a piece of popcorn。","topic":"daily","cefr":"A2"},{"w":"speed","uk":"/spiːd/","p":"n.","zh":"速度；速率","ex":{"en":"The train picked up speed as we left town.","zh":"我们离开小镇时，火车加快了速度。"},"tip":"speed up表示加快；speed也可作动词指超速驾驶。","topic":"travel","cefr":"A2"},{"w":"stove","uk":"/stəʊv/","p":"n.","zh":"炉灶；火炉","ex":{"en":"A pot of soup is bubbling on the stove.","zh":"一锅汤正在炉灶上咕嘟咕嘟地煮着。"},"tip":"stove用于烹饪或取暖；oven专指烤箱。","topic":"daily","cefr":"A2"},{"w":"mango","uk":"/ˈmæŋɡəʊ/","p":"n.","zh":"芒果","ex":{"en":"This mango is sweet enough to eat without sugar.","zh":"这个芒果已经很甜了，不用加糖就能吃。"},"tip":"复数mangoes和mangos均正确。","topic":"daily","cefr":"A2"},{"w":"pill","uk":"/pɪl/","p":"n.","zh":"药丸；药片","ex":{"en":"He swallowed the pill with a glass of water.","zh":"他用一杯水把药片吞了下去。"},"tip":"take a pill指服药；the pill常特指口服避孕药。","topic":"health","cefr":"A2"},{"w":"local","uk":"/ˈləʊkəl/","p":"adj.","zh":"当地的；本地的","ex":{"en":"We buy fresh bread from our local bakery every morning.","zh":"我们每天早晨都在附近的面包店买新鲜面包。"},"tip":"名词复数locals指当地人；locally是副词。","topic":"city","cefr":"A2"},{"w":"hide","uk":"/haɪd/","p":"v.","zh":"隐藏；躲藏","ex":{"en":"We hid the birthday present under the bed.","zh":"我们把生日礼物藏在了床底下。"},"tip":"过去式hid，过去分词hidden；hide from意为躲避。","topic":"daily","cefr":"A2"},{"w":"awake","uk":"/əˈweɪk/","p":"adj.","zh":"醒着的","ex":{"en":"I was still awake when the rain finally stopped.","zh":"雨终于停下时，我还醒着。"},"tip":"形容词通常作表语；动词变化为awoke、awoken。","topic":"health","cefr":"A2"},{"w":"noise","uk":"/nɔɪz/","p":"n.","zh":"噪音；响声","ex":{"en":"The noise outside woke me before my alarm rang.","zh":"外面的噪音在闹钟响之前就把我吵醒了。"},"tip":"泛指噪音时不可数；指某个具体声响可用a noise。","topic":"environment","cefr":"A2"},{"w":"stick","uk":"/stɪk/","p":"n.","zh":"棍；枝条；手杖","ex":{"en":"The dog brought a stick back to me.","zh":"那只狗把一根树枝叼回给我。"},"tip":"动词过去式和过去分词均为stuck；stick to表示坚持。","topic":"daily","cefr":"A2"},{"w":"common","uk":"/ˈkɒmən/","p":"adj.","zh":"常见的；普遍的","ex":{"en":"Heavy rain is common here during the summer.","zh":"这里夏天经常下大雨。"},"tip":"common指常见或共有；ordinary强调普通、不特别。","topic":"daily","cefr":"A2"},{"w":"kettle","uk":"/ˈketəl/","p":"n.","zh":"烧水壶","ex":{"en":"Put the kettle on while I find the cups.","zh":"你先烧水，我来找杯子。"},"tip":"kettle 用来烧水，teapot 用来泡茶。","topic":"daily","cefr":"A2"},{"w":"judo","uk":"/ˈdʒuːdəʊ/","p":"n.","zh":"柔道","ex":{"en":"Our judo teacher showed us how to fall safely.","zh":"我们的柔道老师教了我们如何安全地倒地。"},"tip":"练柔道用do judo，不用play judo。","topic":"sport","cefr":"A2"},{"w":"opposite","uk":"/ˈɒpəzɪt/","p":"adj.","zh":"相反的；对面的","ex":{"en":"We left the station and walked in opposite directions.","zh":"我们离开车站，朝相反的方向走去。"},"tip":"介词opposite后直接接地点；名词常用the opposite of。","topic":"daily","cefr":"A2"},{"w":"female","uk":"/ˈfiːmeɪl/","p":"adj.","zh":"女性的；雌性的","ex":{"en":"The female lion rested beside her cubs in the shade.","zh":"母狮和幼狮一起在阴凉处休息。"},"tip":"指成年女性通常用women；female作定语较自然。","topic":"society","cefr":"A2"},{"w":"imagine","uk":"/ɪˈmædʒɪn/","p":"v.","zh":"想象；设想","ex":{"en":"Imagine living in a little house beside the sea.","zh":"想象一下住在海边一栋小房子里的情景。"},"tip":"imagine后接动名词，不接to do。","topic":"thinking","cefr":"A2"},{"w":"file","uk":"/faɪl/","p":"n.","zh":"文件；档案；文件夹","ex":{"en":"I saved the file before switching off my laptop.","zh":"我关掉笔记本电脑之前保存了文件。"},"tip":"file a complaint 指正式投诉，不是把投诉归档。","topic":"technology","cefr":"A2"},{"w":"airline","uk":"/ˈeəlaɪn/","p":"n.","zh":"航空公司","ex":{"en":"The airline sent us new tickets after cancelling our flight.","zh":"航班取消后，航空公司给我们发了新机票。"},"tip":"airline指航空公司；具体航班用flight。","topic":"travel","cefr":"A2"},{"w":"suggestion","uk":"/səˈdʒestʃən/","p":"n.","zh":"建议；提议","ex":{"en":"Your suggestion to bring a picnic was really helpful.","zh":"你提议带上野餐食物，真是帮了大忙。"},"tip":"suggestion是可数名词；advice通常不可数。","topic":"thinking","cefr":"A2"},{"w":"seaside","uk":"/ˈsiːsaɪd/","p":"n.","zh":"海滨；海边","ex":{"en":"We spent the afternoon building sandcastles at the seaside.","zh":"我们下午在海边堆沙堡。"},"tip":"名词常用 the seaside；表示“在海边”用 at。","topic":"travel","cefr":"A2"},{"w":"ourselves","uk":"/aʊəˈselvz/","p":"pron.","zh":"我们自己","ex":{"en":"We saw ourselves reflected in the clear lake.","zh":"我们看到了自己映在清澈湖水中的倒影。"},"tip":"by ourselves可指独自，也可指不靠别人。","topic":"daily","cefr":"A2"},{"w":"fried","uk":"/fraɪd/","p":"adj.","zh":"油炸的；油煎的","ex":{"en":"We had fried eggs and toast for breakfast.","zh":"我们早餐吃了煎蛋和烤面包。"},"tip":"fried是fry的过去式和过去分词，也作形容词；不限于油炸。","topic":"daily","cefr":"A2"},{"w":"offer","uk":"/ˈɒfə/","p":"v.","zh":"主动提供；提议","ex":{"en":"Our neighbour offered to carry the heavy bags upstairs.","zh":"邻居主动提出帮我们把沉重的袋子搬上楼。"},"tip":"主动做某事用offer to do，不用offer doing。","topic":"daily","cefr":"A2"},{"w":"sort","uk":"/sɔːt/","p":"n.","zh":"种类；类型","ex":{"en":"What sort of music do you listen to at home?","zh":"你在家听哪种音乐？"},"tip":"a sort of表示“一种”；sort of也可口语表示“有点”。","topic":"daily","cefr":"A2"},{"w":"project","uk":"/ˈprɒdʒekt/; /prəˈdʒekt/","p":"n.","zh":"项目；工程；课题","ex":{"en":"Our garden project started with three pots of herbs.","zh":"我们的园艺项目是从三盆香草开始的。"},"tip":"名词重音在前，动词重音在后；音标按此顺序列出。","topic":"work","cefr":"A2"},{"w":"actress","uk":"/ˈæktrəs/","p":"n.","zh":"女演员","ex":{"en":"The actress waved to the crowd outside the theatre.","zh":"那位女演员向剧院外的人群挥手。"},"tip":"actor也可指女性；actress明确指女演员。","topic":"arts","cefr":"A2"},{"w":"arrange","uk":"/əˈreɪndʒ/","p":"v.","zh":"安排；筹备","ex":{"en":"I arranged to meet my cousin outside the cinema.","zh":"我约好和表亲在电影院外见面。"},"tip":"安排某人做某事用arrange for sb to do。","topic":"daily","cefr":"A2"},{"w":"popular","uk":"/ˈpɒpjələ/","p":"adj.","zh":"受欢迎的；流行的","ex":{"en":"This small café is popular with local students.","zh":"这家小咖啡馆很受当地学生欢迎。"},"tip":"表示受某群体欢迎，常用popular with或among。","topic":"society","cefr":"A2"},{"w":"fix","uk":"/fɪks/","p":"v.","zh":"修理；解决","ex":{"en":"My neighbour helped me fix the broken kitchen tap.","zh":"邻居帮我修好了厨房里坏掉的水龙头。"},"tip":"fix既可修理物品，也可解决问题或确定日期。","topic":"daily","cefr":"A2"},{"w":"bin","uk":"/bɪn/","p":"n.","zh":"垃圾桶；储物箱","ex":{"en":"Please put the banana skin in the kitchen bin.","zh":"请把香蕉皮放进厨房的垃圾桶。"},"tip":"“垃圾桶”英式常说bin，美式常说trash can。","topic":"daily","cefr":"A2"},{"w":"grilled","uk":"/ɡrɪld/","p":"adj.","zh":"烤制的；炙烤的","ex":{"en":"We shared grilled vegetables and warm bread for lunch.","zh":"午餐我们一起吃了烤蔬菜和热面包。"},"tip":"grilled强调直接高温烤制；不表示“有格子的”。","topic":"daily","cefr":"A2"},{"w":"across","uk":"/əˈkrɒs/","p":"prep.","zh":"穿过；横过","ex":{"en":"We walked across the bridge before the rain started.","zh":"下雨前，我们走过了那座桥。"},"tip":"across强调横跨表面；through强调从内部穿过。","topic":"travel","cefr":"A2"},{"w":"behave","uk":"/bɪˈheɪv/","p":"v.","zh":"表现；举止","ex":{"en":"Our dog behaves calmly when visitors come to the house.","zh":"有客人来家里时，我们的狗表现得很平静。"},"tip":"behave yourself意为守规矩，不是“表现自己”。","topic":"society","cefr":"A2"},{"w":"post","uk":"/pəʊst/","p":"n.","zh":"邮件；邮政","ex":{"en":"A parcel arrived in the post this morning.","zh":"今天早上寄来了一个包裹。"},"tip":"邮寄义中，英式常用post，美式常用mail。","topic":"daily","cefr":"A2"},{"w":"create","uk":"/kriˈeɪt/","p":"v.","zh":"创造；创作","ex":{"en":"We created a colourful bird from folded paper.","zh":"我们用折纸做出了一只色彩鲜艳的小鸟。"},"tip":"create强调创造新事物，也可接problem表示造成问题。","topic":"arts","cefr":"A2"},{"w":"organisation","uk":"/ˌɔːɡənaɪˈzeɪʃən/","p":"n.","zh":"组织；机构；团体","ex":{"en":"He joined a local organisation that rescues injured birds.","zh":"他加入了一个救助受伤鸟类的当地组织。"},"tip":"英式常写organisation，美式通常写organization。","topic":"society","cefr":"A2"},{"w":"fit","uk":"/fɪt/","p":"v.","zh":"合身；装得下；适合","ex":{"en":"These boots fit perfectly, even with my thick socks.","zh":"即使穿着厚袜子，这双靴子也非常合脚。"},"tip":"衣物fit指尺寸合适；suit多指款式或颜色适合。","topic":"daily","cefr":"A2"},{"w":"normal","uk":"/ˈnɔːməl/","p":"adj.","zh":"正常的；通常的","ex":{"en":"It is normal to feel nervous before an interview.","zh":"面试前感到紧张是正常的。"},"tip":"normal强调符合常态；ordinary强调普通、不特别。","topic":"daily","cefr":"A2"},{"w":"volleyball","uk":"/ˈvɒlibɔːl/","p":"n.","zh":"排球运动；排球","ex":{"en":"We played volleyball on the beach until the sun set.","zh":"我们在沙滩上打排球，一直打到日落。"},"tip":"指运动时不可数，play volleyball中不加冠词。","topic":"sport","cefr":"A2"},{"w":"ancient","uk":"/ˈeɪnʃənt/","p":"adj.","zh":"古代的","ex":{"en":"We explored an ancient temple during our holiday.","zh":"我们度假时游览了一座古代寺庙。"},"tip":"ancient强调年代久远，不宜代替一般的old。","topic":"history","cefr":"A2"},{"w":"amount","uk":"/əˈmaʊnt/","p":"n.","zh":"数量；数额","ex":{"en":"Add a small amount of milk to the bowl.","zh":"往碗里加少量牛奶。"},"tip":"amount of接不可数名词；动词常用amount to。","topic":"daily","cefr":"A2"},{"w":"selfie","uk":"/ˈselfi/","p":"n.","zh":"自拍照","ex":{"en":"We took a selfie beside the lake after our walk.","zh":"散步后，我们在湖边拍了一张自拍照。"},"tip":"拍自拍照用take a selfie，不用make a selfie。","topic":"technology","cefr":"A2"},{"w":"pass","uk":"/pɑːs/","p":"v.","zh":"经过；通过","ex":{"en":"We pass a small bakery on our way home.","zh":"我们回家的路上会经过一家小面包店。"},"tip":"pass是动词；past可作介词：walk past。","topic":"daily","cefr":"A2"},{"w":"honey","uk":"/ˈhʌn.i/","p":"n.","zh":"蜂蜜","ex":{"en":"She stirred a spoonful of honey into her tea.","zh":"她往茶里加了一勺蜂蜜，搅拌均匀。"},"tip":"表示蜂蜜时不可数；一罐蜂蜜说a jar of honey。","topic":"daily","cefr":"A2"},{"w":"southeast","uk":"/ˌsaʊθˈiːst/","p":"n.","zh":"东南；东南部","ex":{"en":"Our kitchen window faces southeast and catches the morning sun.","zh":"我们厨房的窗户朝东南，早晨能照到阳光。"},"tip":"名词前常用the；副词不用：head southeast。","topic":"travel","cefr":"A2"},{"w":"programme","uk":"/ˈprəʊɡræm/","p":"n.","zh":"计划；方案；课程","ex":{"en":"I joined a fitness programme at the local gym.","zh":"我参加了当地健身房的一项健身计划。"},"tip":"英式通常用programme，计算机程序用program；美式均用program。","topic":"education","cefr":"A2"},{"w":"shorts","uk":"/ʃɔːts/","p":"n.","zh":"短裤","ex":{"en":"I packed shorts and sandals for our beach holiday.","zh":"我为这次海滨度假打包了短裤和凉鞋。"},"tip":"shorts用复数；一条短裤说a pair of shorts。","topic":"daily","cefr":"A2"},{"w":"bracelet","uk":"/ˈbreɪslət/","p":"n.","zh":"手镯；手链","ex":{"en":"She wears a silver bracelet that her grandmother gave her.","zh":"她戴着祖母送给她的一条银手链。"},"tip":"bracelet戴在手腕；anklet戴在脚踝。","topic":"daily","cefr":"A2"},{"w":"board","uk":"/bɔːd/","p":"n.","zh":"木板；板","ex":{"en":"She placed a wooden board across the muddy path.","zh":"她在泥泞的小路上横放了一块木板。"},"tip":"board作动词可直接接交通工具：board a train。","topic":"daily","cefr":"A2"},{"w":"speaker","uk":"/ˈspiːkə/","p":"n.","zh":"演讲者；发言者","ex":{"en":"The speaker made everyone laugh with her opening story.","zh":"演讲者开场讲的故事把大家都逗笑了。"},"tip":"a native speaker of English指英语母语者。","topic":"education","cefr":"A2"},{"w":"sunglasses","uk":"/ˈsʌnɡlɑːsɪz/","p":"n.","zh":"太阳镜；墨镜","ex":{"en":"I put on my sunglasses before leaving the house.","zh":"出门前，我戴上了太阳镜。"},"tip":"通常用复数；一副说a pair of sunglasses。","topic":"daily","cefr":"A2"},{"w":"niece","uk":"/niːs/","p":"n.","zh":"侄女；外甥女","ex":{"en":"My niece brought her new puppy to our picnic.","zh":"我的侄女带着她新养的小狗来参加我们的野餐。"},"tip":"niece指女性晚辈，nephew指男性晚辈。","topic":"society","cefr":"A2"},{"w":"make-up","uk":"/ˈmeɪk ʌp/","p":"n.","zh":"化妆品","ex":{"en":"She keeps her make-up in a small blue bag.","zh":"她把化妆品放在一个蓝色小包里。"},"tip":"名词也写作makeup；动词短语make up不加连字符。","topic":"daily","cefr":"A2"},{"w":"concert","uk":"/ˈkɒnsət/","p":"n.","zh":"音乐会；演唱会","ex":{"en":"We enjoyed an outdoor concert in the park yesterday.","zh":"昨天我们在公园欣赏了一场露天音乐会。"},"tip":"去听音乐会用 go to a concert。","topic":"arts","cefr":"A2"},{"w":"joining","uk":"/ˈdʒɔɪnɪŋ/","p":"v.","zh":"加入；参加","ex":{"en":"I'm joining a swimming club near my house.","zh":"我正准备加入家附近的一家游泳俱乐部。"},"tip":"是join的-ing形式；加入组织直接接宾语，不加in。","topic":"society","cefr":"A2"},{"w":"greeting","uk":"/ˈɡriːtɪŋ/","p":"n.","zh":"问候；招呼","ex":{"en":"She gave us a cheerful greeting at the door.","zh":"她在门口愉快地向我们打招呼。"},"tip":"表示节日祝福常用复数greetings，如birthday greetings。","topic":"society","cefr":"A2"},{"w":"half-price","uk":"/ˌhɑːf ˈpraɪs/","p":"adj.","zh":"半价的","ex":{"en":"We bought half-price tickets for the afternoon boat trip.","zh":"我们买了下午游船的半价票。"},"tip":"名词前常写half-price；at half price不加连字符。","topic":"economy","cefr":"A2"},{"w":"sadly","uk":"/ˈsædli/","p":"adv.","zh":"悲伤地；难过地","ex":{"en":"He waved sadly as his best friend's train departed.","zh":"最好的朋友乘坐的火车离站时，他难过地挥手告别。"},"tip":"句首Sadly常表示“遗憾的是”，修饰整句话。","topic":"emotion","cefr":"A2"},{"w":"report","uk":"/rɪˈpɔːt/","p":"n.","zh":"报告；报道","ex":{"en":"I finished my report before lunch and emailed it.","zh":"我午饭前写完了报告，并通过电子邮件发了出去。"},"tip":"report on后接报道主题；report for duty指报到上班。","topic":"media","cefr":"A2"},{"w":"crossing","uk":"/ˈkrɒsɪŋ/","p":"n.","zh":"人行横道；穿越处","ex":{"en":"We waited at the crossing until the cars stopped.","zh":"我们在人行横道前等到车辆停下才过马路。"},"tip":"作名词可指过街地点，也可指乘船横渡的行程。","topic":"city","cefr":"A2"},{"w":"cover","uk":"/ˈkʌvə/","p":"v.","zh":"覆盖；遮盖","ex":{"en":"Cover the bread with a cloth while it cools.","zh":"面包冷却时，用一块布盖住它。"},"tip":"cover A with B表示用B盖住A；cover费用指足以支付。","topic":"daily","cefr":"A2"},{"w":"baseball","uk":"/ˈbeɪsbɔːl/","p":"n.","zh":"棒球运动","ex":{"en":"We played baseball in the park after lunch.","zh":"午饭后，我们在公园打棒球。"},"tip":"运动名称不可数；表示一个棒球时用a baseball。","topic":"sport","cefr":"A2"},{"w":"clever","uk":"/ˈklevə/","p":"adj.","zh":"聪明的；机灵的","ex":{"en":"That clever child fixed the puzzle before lunch.","zh":"那个聪明的孩子午饭前就解开了这道谜题。"},"tip":"比较级cleverer，最高级cleverest。","topic":"thinking","cefr":"A2"},{"w":"everywhere","uk":"/ˈevriweə/","p":"adv.","zh":"到处；处处","ex":{"en":"We looked everywhere, but the kitten was under the sofa.","zh":"我们到处找，结果小猫就在沙发底下。"},"tip":"everywhere是副词，前面通常不加in或at。","topic":"daily","cefr":"A2"},{"w":"passport","uk":"/ˈpɑːspɔːt/","p":"n.","zh":"护照","ex":{"en":"I checked my bag twice to find my passport.","zh":"我翻了两遍包才找到护照。"},"tip":"比喻用法a passport to中，to后接名词。","topic":"travel","cefr":"A2"},{"w":"cash","uk":"/kæʃ/","p":"n.","zh":"现金；现款","ex":{"en":"I keep some cash in my wallet for emergencies.","zh":"我在钱包里放了一些现金，以备急用。"},"tip":"cash作现金讲不可数；用现金付款是pay in cash。","topic":"economy","cefr":"A2"},{"w":"scarf","uk":"/skɑːf/","p":"n.","zh":"围巾；头巾","ex":{"en":"She wrapped a wool scarf around her neck.","zh":"她在脖子上围了一条羊毛围巾。"},"tip":"复数可用scarves或scarfs，前者更常见。","topic":"daily","cefr":"A2"},{"w":"shoulder","uk":"/ˈʃəʊldə/","p":"n.","zh":"肩；肩膀","ex":{"en":"She rested her head on her father's shoulder.","zh":"她把头靠在父亲的肩膀上。"},"tip":"作动词常接responsibility或burden，表示承担。","topic":"health","cefr":"A2"},{"w":"refrigerator","uk":"/rɪˈfrɪdʒəreɪtə/","p":"n.","zh":"冰箱；冷藏柜","ex":{"en":"Put the milk in the refrigerator before it spoils.","zh":"把牛奶放进冰箱，免得变质。"},"tip":"日常口语常用fridge；freezer专指冷冻柜或冷冻室。","topic":"daily","cefr":"A2"},{"w":"prince","uk":"/prɪns/","p":"n.","zh":"王子；亲王","ex":{"en":"The prince waved to visitors from the palace balcony.","zh":"王子在宫殿阳台上向来访者挥手。"},"tip":"prince不一定是王子，也可指亲王或公国君主。","topic":"society","cefr":"A2"},{"w":"sailing","uk":"/ˈseɪlɪŋ/","p":"n.","zh":"帆船运动；帆船航行","ex":{"en":"We went sailing on the lake last weekend.","zh":"上周末我们去湖上玩帆船了。"},"tip":"运动义不可数；航班义可数，如daily sailings。","topic":"sport","cefr":"A2"},{"w":"ninth","uk":"/naɪnθ/","p":"num.","zh":"第九","ex":{"en":"Our new apartment is on the ninth floor.","zh":"我们的新公寓在九楼。"},"tip":"nine变ninth时去掉e；序数词前通常用the。","topic":"daily","cefr":"A2"},{"w":"nature","uk":"/ˈneɪtʃə/","p":"n.","zh":"大自然；自然界","ex":{"en":"Camping helps us enjoy nature away from busy streets.","zh":"露营让我们远离繁忙的街道，享受大自然。"},"tip":"指大自然时通常不加the；某事的性质用the nature of。","topic":"nature","cefr":"A2"},{"w":"reply","uk":"/rɪˈplaɪ/","p":"v.","zh":"回答；答复","ex":{"en":"Please reply before Friday so I can book dinner.","zh":"请在周五之前回复，好让我预订晚餐。"},"tip":"reply to后接人或消息，不直接接宾语。","topic":"daily","cefr":"A2"},{"w":"oil","uk":"/ɔɪl/","p":"n.","zh":"石油；原油","ex":{"en":"The truck carried oil from the well to the refinery.","zh":"卡车把原油从油井运往炼油厂。"},"tip":"通常不可数；表示不同种类的油时可用oils。","topic":"environment","cefr":"A2"},{"w":"bean","uk":"/biːn/","p":"n.","zh":"豆；豆类植物","ex":{"en":"I added some beans to the vegetable soup.","zh":"我在蔬菜汤里加了些豆子。"},"tip":"可数名词；泛指食用豆类时通常用beans。","topic":"daily","cefr":"A2"},{"w":"fail","uk":"/feɪl/","p":"v.","zh":"失败；未能做到","ex":{"en":"The cake failed to rise despite an extra egg.","zh":"尽管多加了一个鸡蛋，蛋糕还是没发起来。"},"tip":"fail to do表示未能做；fail an exam表示考试不及格。","topic":"daily","cefr":"A2"},{"w":"introduce","uk":"/ˌɪntrəˈdjuːs/","p":"v.","zh":"介绍；引见","ex":{"en":"Let me introduce you to my new neighbour.","zh":"让我把你介绍给我的新邻居。"},"tip":"把甲介绍给乙用introduce A to B，不能用with。","topic":"society","cefr":"A2"},{"w":"dancer","uk":"/ˈdɑːnsə/","p":"n.","zh":"舞者；舞蹈演员","ex":{"en":"The dancer spun gracefully across the small stage.","zh":"那位舞者在小舞台上优雅地旋转。"},"tip":"dancer不限定性别，也不一定指职业舞者。","topic":"arts","cefr":"A2"},{"w":"unlucky","uk":"/ʌnˈlʌki/","p":"adj.","zh":"倒霉的；不幸的","ex":{"en":"We were unlucky to miss the bus by seconds.","zh":"我们真倒霉，只差几秒就错过了公交车。"},"tip":"unlucky强调运气差，不等于unhappy（不开心）。","topic":"daily","cefr":"A2"},{"w":"impossible","uk":"/ɪmˈpɒsəbəl/","p":"adj.","zh":"不可能的","ex":{"en":"It is impossible to fit this sofa through the doorway.","zh":"这张沙发根本无法从门口搬进去。"},"tip":"常用it is impossible to do，表示不可能做某事。","topic":"thinking","cefr":"A2"},{"w":"ahead","uk":"/əˈhed/","p":"adv.","zh":"在前面；向前","ex":{"en":"Walk straight ahead until you reach the little bridge.","zh":"一直往前走，直到走到那座小桥。"},"tip":"ahead是副词；后接人或事物时用ahead of。","topic":"daily","cefr":"A2"},{"w":"luggage","uk":"/ˈlʌɡɪdʒ/","p":"n.","zh":"行李","ex":{"en":"Our luggage barely fitted into the small taxi.","zh":"我们的行李勉强塞进了那辆小出租车。"},"tip":"不可数；一件行李用a piece of luggage。","topic":"travel","cefr":"A2"},{"w":"steak","uk":"/steɪk/","p":"n.","zh":"牛排；肉排；鱼排","ex":{"en":"She served the steak with potatoes and green beans.","zh":"她端上牛排，配了土豆和四季豆。"},"tip":"steak与stake同音；单说steak通常指牛排。","topic":"daily","cefr":"A2"},{"w":"tidy","uk":"/ˈtaɪdi/","p":"adj.","zh":"整洁的；整齐的","ex":{"en":"Her desk stays tidy, even during the busiest weeks.","zh":"即使在最忙的几周里，她的书桌也保持整洁。"},"tip":"tidy强调摆放整齐；clean强调没有污垢。","topic":"daily","cefr":"A2"},{"w":"wool","uk":"/wʊl/","p":"n.","zh":"羊毛；毛线；毛料","ex":{"en":"This wool scarf keeps my neck warm on windy mornings.","zh":"这条羊毛围巾让我的脖子在刮风的早晨保持温暖。"},"tip":"通常不可数；一团毛线说a ball of wool。","topic":"daily","cefr":"A2"},{"w":"purse","uk":"/pɜːs/","p":"n.","zh":"零钱包；女式手提包","ex":{"en":"She opened her purse and took out a coin.","zh":"她打开零钱包，取出一枚硬币。"},"tip":"英式purse多指零钱包，美式常指女式手提包。","topic":"daily","cefr":"A2"},{"w":"sunset","uk":"/ˈsʌnset/","p":"n.","zh":"日落；日落时分","ex":{"en":"We reached the beach just before sunset yesterday.","zh":"昨天我们在日落前刚好赶到了海滩。"},"tip":"表示在日落时用at sunset，通常不加冠词。","topic":"nature","cefr":"A2"},{"w":"notice","uk":"/ˈnəʊ.tɪs/","p":"v.","zh":"注意到；察觉","ex":{"en":"Did you notice the tiny bird outside our window?","zh":"你注意到窗外那只小鸟了吗？"},"tip":"notice sb do强调全过程；notice sb doing强调正在发生。","topic":"daily","cefr":"A2"},{"w":"probably","uk":"/ˈprɒbəbli/","p":"adv.","zh":"很可能；大概","ex":{"en":"The bakery will probably close before we get there.","zh":"我们到那儿之前，面包店很可能就关门了。"},"tip":"通常置于实义动词前、be动词后或第一个助动词后。","topic":"thinking","cefr":"A2"},{"w":"cloth","uk":"/klɒθ/","p":"n.","zh":"布；织物","ex":{"en":"She chose soft cotton cloth for the baby's blanket.","zh":"她选了柔软的棉布来做婴儿毯。"},"tip":"布料义不可数；抹布可数，复数cloths；勿混clothes。","topic":"daily","cefr":"A2"},{"w":"transport","uk":"/ˈtrænspɔːt/","p":"n.","zh":"交通运输；交通工具","ex":{"en":"We rely on public transport to get around town.","zh":"我们在城里出行靠公共交通。"},"tip":"上列为名词音标；动词重音后移，英/t/前为/n/。","topic":"travel","cefr":"A2"},{"w":"drop","uk":"/drɒp/","p":"v.","zh":"落下；使掉落；下降","ex":{"en":"I dropped my keys while reaching for my phone.","zh":"我伸手拿手机时，钥匙掉了。"},"tip":"drop by表示下降了多少；drop to表示降至多少。","topic":"daily","cefr":"A2"},{"w":"share","uk":"/ʃeə/","p":"v.","zh":"分享；共用；分担","ex":{"en":"My sister and I share a desk by the window.","zh":"我和姐姐共用窗边的一张书桌。"},"tip":"与某人分享用share something with someone。","topic":"society","cefr":"A2"},{"w":"tram","uk":"/træm/","p":"n.","zh":"有轨电车","ex":{"en":"We caught the tram outside the library this morning.","zh":"今天早上我们在图书馆外乘上了有轨电车。"},"tip":"指车辆，不是轨道；美式英语常用streetcar。","topic":"travel","cefr":"A2"},{"w":"envelope","uk":"/ˈenvələʊp/","p":"n.","zh":"信封","ex":{"en":"She slipped the birthday card into a blue envelope.","zh":"她把生日贺卡放进了一个蓝色信封。"},"tip":"envelope是“信封”；envelop是“包围”的动词。","topic":"daily","cefr":"A2"},{"w":"parrot","uk":"/ˈpærət/","p":"n.","zh":"鹦鹉","ex":{"en":"The green parrot cracked a seed with its beak.","zh":"那只绿色鹦鹉用喙啄开了一粒种子。"},"tip":"作动词常带贬义，强调不加理解或思考地重复。","topic":"nature","cefr":"A2"},{"w":"windsurfing","uk":"/ˈwɪndsɜːfɪŋ/","p":"n.","zh":"帆板运动","ex":{"en":"My sister tried windsurfing during our holiday by the lake.","zh":"我们在湖边度假时，我姐姐尝试了帆板运动。"},"tip":"windsurfing借帆利用风力；surfing主要借海浪滑行。","topic":"sport","cefr":"A2"},{"w":"cross","uk":"/krɒs/","p":"v.","zh":"穿过；横渡；交叉","ex":{"en":"We waited for the traffic to stop before crossing.","zh":"我们等车辆停下后才过马路。"},"tip":"cross是动词；across是介词或副词。","topic":"travel","cefr":"A2"},{"w":"stage","uk":"/steɪdʒ/","p":"n.","zh":"阶段；时期","ex":{"en":"The cake is cooling at this stage of preparation.","zh":"制作进行到这个阶段，蛋糕正在冷却。"},"tip":"表示阶段常用at a stage；表示在舞台上用on stage。","topic":"daily","cefr":"A2"},{"w":"forward","uk":"/ˈfɔːwəd/","p":"adv.","zh":"向前；向将来","ex":{"en":"Please step forward when there is space ahead.","zh":"前面有空位时，请向前走一步。"},"tip":"look forward to中的to是介词，后接名词或动名词。","topic":"daily","cefr":"A2"},{"w":"colleague","uk":"/ˈkɒliːɡ/","p":"n.","zh":"同事；同僚","ex":{"en":"My colleague brought homemade soup to the office today.","zh":"我的同事今天把自制的汤带到了办公室。"},"tip":"colleague指同事，不一定是朋友或同级员工。","topic":"work","cefr":"A2"},{"w":"mess","uk":"/mes/","p":"n.","zh":"脏乱；杂乱","ex":{"en":"The kitchen was a mess after we baked biscuits.","zh":"我们烤完饼干后，厨房一片狼藉。"},"tip":"常说make a mess；mess up可指弄乱或搞砸。","topic":"daily","cefr":"A2"},{"w":"level","uk":"/ˈlevəl/","p":"n.","zh":"水平；程度；高度","ex":{"en":"The water level rose after last night's heavy rain.","zh":"昨晚的大雨过后，水位上升了。"},"tip":"at表示所处水平；on the same level可指同一楼层。","topic":"daily","cefr":"A2"},{"w":"afterwards","uk":"/ˈɑːftəwədz/","p":"adv.","zh":"后来；之后","ex":{"en":"We watched a film and had dinner afterwards.","zh":"我们看了一部电影，之后吃了晚饭。"},"tip":"是副词，后面不直接接宾语；after可接宾语。","topic":"daily","cefr":"A2"},{"w":"empty","uk":"/ˈempti/","p":"adj.","zh":"空的；无人的","ex":{"en":"The biscuit tin was empty when I opened it.","zh":"我打开饼干盒时，里面已经空了。"},"tip":"empty强调里面没有东西；vacant常指房屋或职位空缺。","topic":"daily","cefr":"A2"},{"w":"earn","uk":"/ɜːn/","p":"v.","zh":"挣得；赚取","ex":{"en":"She earns extra money by walking dogs after school.","zh":"她放学后帮人遛狗，赚些零花钱。"},"tip":"earn强调劳动或表现所得；win多指比赛获胜。","topic":"work","cefr":"A2"},{"w":"adventure","uk":"/ədˈventʃə/","p":"n.","zh":"冒险；奇遇","ex":{"en":"Our camping trip turned into an adventure after dark.","zh":"天黑后，我们的露营之旅变成了一次冒险。"},"tip":"adventure指具体经历时可数，指冒险精神时不可数。","topic":"travel","cefr":"A2"},{"w":"twelfth","uk":"/twelfθ/","p":"num.","zh":"第十二","ex":{"en":"We celebrated her twelfth birthday with a homemade cake.","zh":"我们用自制蛋糕庆祝了她的十二岁生日。"},"tip":"twelve变序数词为twelfth，注意ve变为f。","topic":"daily","cefr":"A2"},{"w":"belt","uk":"/belt/","p":"n.","zh":"腰带；皮带","ex":{"en":"This belt keeps my trousers from slipping down.","zh":"这条腰带能防止我的裤子往下滑。"},"tip":"belt除腰带外也指带状区域，如green belt。","topic":"daily","cefr":"A2"},{"w":"fireman","uk":"/ˈfaɪəmən/","p":"n.","zh":"男消防员","ex":{"en":"The fireman rescued a kitten from the smoky kitchen.","zh":"这名男消防员从烟雾弥漫的厨房里救出了一只小猫。"},"tip":"复数为firemen；现代通用表达多用中性的firefighter。","topic":"work","cefr":"A2"},{"w":"interview","uk":"/ˈɪntəvjuː/","p":"n.","zh":"面试；面谈","ex":{"en":"I practised answering questions before my first job interview.","zh":"第一次求职面试前，我练习了如何回答问题。"},"tip":"interviewer是提问者；interviewee是接受面试或采访者。","topic":"work","cefr":"A2"},{"w":"similar","uk":"/ˈsɪmələ/","p":"adj.","zh":"相似的；类似的","ex":{"en":"Your jacket looks similar to mine, but slightly darker.","zh":"你的夹克看起来和我的相似，不过颜色稍深一点。"},"tip":"用similar to，不用similar with；相似不等于相同。","topic":"thinking","cefr":"A2"},{"w":"whole","uk":"/həʊl/","p":"adj.","zh":"整个的；完整的","ex":{"en":"We spent the whole afternoon baking bread together.","zh":"我们整个下午都在一起烤面包。"},"tip":"注意语序：the whole day＝all the day。","topic":"daily","cefr":"A2"},{"w":"thought","uk":"/θɔːt/","p":"n.","zh":"想法；念头","ex":{"en":"A sudden thought made me check my coat pocket.","zh":"一个突然冒出的念头让我检查了一下外套口袋。"},"tip":"表具体想法时可数；表思考过程时通常不可数。","topic":"thinking","cefr":"A2"},{"w":"loudly","uk":"/ˈlaʊdli/","p":"adv.","zh":"大声地；响亮地","ex":{"en":"Everyone cheered loudly when our team won the match.","zh":"我们队赢得比赛时，大家都大声欢呼。"},"tip":"loudly强调音量大；aloud强调出声而非默读。","topic":"daily","cefr":"A2"},{"w":"weight","uk":"/weɪt/","p":"n.","zh":"重量；体重","ex":{"en":"The weight of this suitcase makes it hard to lift.","zh":"这个行李箱太重，很难提起来。"},"tip":"weight是名词；weigh是动词：How much does it weigh?","topic":"health","cefr":"A2"},{"w":"folder","uk":"/ˈfəʊldə/","p":"n.","zh":"文件夹；纸夹","ex":{"en":"Keep your receipts in this folder beside the desk.","zh":"把收据放在桌子旁的这个文件夹里。"},"tip":"file是文件；folder是存放文件的文件夹。","topic":"work","cefr":"A2"},{"w":"steal","uk":"/stiːl/","p":"v.","zh":"偷窃；盗用","ex":{"en":"Someone stole my bicycle while I was buying bread.","zh":"我买面包的时候，有人偷走了我的自行车。"},"tip":"过去式stole，过去分词stolen；宾语通常是物。","topic":"society","cefr":"A2"},{"w":"modern","uk":"/ˈmɒdən/","p":"adj.","zh":"现代的；近代的","ex":{"en":"Our flat has a modern kitchen with large windows.","zh":"我们的公寓有一间新式厨房，窗户很大。"},"tip":"modern强调现代或新式；不一定表示刚刚制造。","topic":"society","cefr":"A2"},{"w":"opinion","uk":"/əˈpɪnjən/","p":"n.","zh":"意见；看法","ex":{"en":"What is your opinion of our new kitchen?","zh":"你觉得我们的新厨房怎么样？"},"tip":"表达“在我看来”用in my opinion，不用according to me。","topic":"thinking","cefr":"A2"},{"w":"patient","uk":"/ˈpeɪʃənt/","p":"n.","zh":"病人；患者","ex":{"en":"The nurse brought the patient a glass of water.","zh":"护士给病人端来了一杯水。"},"tip":"作名词是“患者”；作形容词常接with。","topic":"health","cefr":"A2"},{"w":"robot","uk":"/ˈrəʊbɒt/","p":"n.","zh":"机器人；自动机械","ex":{"en":"A small robot cleaned the floor while we ate breakfast.","zh":"我们吃早饭时，一台小机器人清扫了地板。"},"tip":"robot是可数名词；robotics指机器人学。","topic":"technology","cefr":"A2"},{"w":"father-in-law","uk":"/ˈfɑːðər ɪn lɔː/","p":"n.","zh":"公公；岳父","ex":{"en":"My father-in-law helped us repair the garden fence.","zh":"我岳父帮我们修好了花园的围栏。"},"tip":"不是继父；继父是stepfather。","topic":"society","cefr":"A2"},{"w":"leader","uk":"/ˈliːdə/","p":"n.","zh":"领导者；带领者","ex":{"en":"Our group leader showed us the safest mountain path.","zh":"我们的领队给我们指明了最安全的山路。"},"tip":"leader指领导者；leadership指领导能力或领导层。","topic":"work","cefr":"A2"},{"w":"subway","uk":"/ˈsʌbweɪ/","p":"n.","zh":"地铁（美式）","ex":{"en":"We took the subway to the museum this morning.","zh":"今天上午我们乘地铁去了博物馆。"},"tip":"美式指地铁；英式常指地下人行通道。","topic":"city","cefr":"A2"},{"w":"pleased","uk":"/pliːzd/","p":"adj.","zh":"高兴的；满意的","ex":{"en":"I'm really pleased with how the cake turned out.","zh":"我对这个蛋糕做出来的效果非常满意。"},"tip":"对结果满意用pleased with；听到喜讯用pleased to hear。","topic":"emotion","cefr":"A2"},{"w":"main","uk":"/meɪn/","p":"adj.","zh":"主要的；最重要的","ex":{"en":"The main entrance is beside the little coffee shop.","zh":"正门就在那家小咖啡馆旁边。"},"tip":"形容词通常放在名词前；主要地用mainly。","topic":"daily","cefr":"A2"},{"w":"drugstore","uk":"/ˈdrʌɡstɔː/","p":"n.","zh":"药店（兼售日用品）","ex":{"en":"I bought some toothpaste at the drugstore near the station.","zh":"我在车站附近的药店买了些牙膏。"},"tip":"主要用于美式英语；英式常用chemist’s或pharmacy。","topic":"health","cefr":"A2"},{"w":"several","uk":"/ˈsevrəl/","p":"det.","zh":"几个；数个","ex":{"en":"I tried several jackets before choosing the blue one.","zh":"我试了几件夹克后，选中了蓝色的那件。"},"tip":"后接可数名词复数；several of后接限定词或代词。","topic":"daily","cefr":"A2"},{"w":"hairdresser","uk":"/ˈheədresə/","p":"n.","zh":"理发师；美发师","ex":{"en":"The hairdresser trimmed my hair and dried it gently.","zh":"美发师修剪了我的头发，然后轻轻吹干。"},"tip":"hairdresser指人；the hairdresser's通常指理发店。","topic":"work","cefr":"A2"},{"w":"customer","uk":"/ˈkʌstəmə/","p":"n.","zh":"顾客；客户","ex":{"en":"The customer asked for a larger pair of shoes.","zh":"这位顾客想要一双大一点的鞋。"},"tip":"customer泛指顾客；client常指专业服务的客户。","topic":"economy","cefr":"A2"},{"w":"collect","uk":"/kəˈlekt/","p":"v.","zh":"收集；收藏","ex":{"en":"I collect smooth stones whenever we visit the beach.","zh":"每次去海边，我都会收集光滑的石头。"},"tip":"英式英语collect someone可指去接某人。","topic":"daily","cefr":"A2"},{"w":"frog","uk":"/frɒɡ/","p":"n.","zh":"青蛙","ex":{"en":"A green frog jumped from the stone into our pond.","zh":"一只绿色的青蛙从石头上跳进了我们的池塘。"},"tip":"可数名词，复数为frogs；toad指蟾蜍。","topic":"nature","cefr":"A2"},{"w":"magic","uk":"/ˈmædʒɪk/","p":"n.","zh":"魔法；魔术","ex":{"en":"The children laughed when he performed a magic trick.","zh":"他表演魔术时，孩子们笑了起来。"},"tip":"magic 多指魔法或魔术；magical 也可形容美妙体验。","topic":"arts","cefr":"A2"},{"w":"topic","uk":"/ˈtɒpɪk/","p":"n.","zh":"话题；主题","ex":{"en":"Food is always a popular topic in our house.","zh":"食物在我们家一直是个热门话题。"},"tip":"topic指讨论或写作的主题；title指文章等的标题。","topic":"education","cefr":"A2"},{"w":"horrible","uk":"/ˈhɒrəbl/","p":"adj.","zh":"糟糕的；令人厌恶的","ex":{"en":"A horrible smell came from the forgotten lunch box.","zh":"那个被遗忘的午餐盒散发出难闻的气味。"},"tip":"horrible常指很糟糕；horrific多指骇人、惨烈。","topic":"emotion","cefr":"A2"},{"w":"extra","uk":"/ˈekstrə/","p":"adj.","zh":"额外的；附加的","ex":{"en":"I packed an extra sweater because the evenings get cold.","zh":"我多带了一件毛衣，因为晚上会冷。"},"tip":"形容词指额外的；pay extra中作副词。","topic":"daily","cefr":"A2"},{"w":"against","uk":"/əˈɡenst/","p":"prep.","zh":"反对；与……对抗","ex":{"en":"Our team is playing against the neighbours this afternoon.","zh":"今天下午我们队要和邻居们比赛。"},"tip":"against是介词，后接名词、代词或动名词。","topic":"society","cefr":"A2"},{"w":"smartphone","uk":"/ˈsmɑːtfəʊn/","p":"n.","zh":"智能手机","ex":{"en":"I used my smartphone to photograph the evening sky.","zh":"我用智能手机拍下了傍晚的天空。"},"tip":"smartphone是可数名词，通常写成一个词。","topic":"technology","cefr":"A2"},{"w":"exact","uk":"/ɪɡˈzækt/","p":"adj.","zh":"精确的；确切的","ex":{"en":"Can you tell me the exact time we should arrive?","zh":"你能告诉我我们应该到达的确切时间吗？"},"tip":"exact强调分毫不差；副词形式为exactly。","topic":"thinking","cefr":"A2"},{"w":"photocopy","uk":"/ˈfəʊtəʊkɒpi/","p":"n.","zh":"复印件","ex":{"en":"Please bring a photocopy of your passport tomorrow.","zh":"请明天带一份你的护照复印件来。"},"tip":"既作名词也作动词；复数和三单均为photocopies。","topic":"work","cefr":"A2"},{"w":"smoking","uk":"/ˈsməʊkɪŋ/","p":"n.","zh":"吸烟","ex":{"en":"My uncle gave up smoking and now enjoys long walks.","zh":"我叔叔戒了烟，现在很喜欢长距离散步。"},"tip":"表示吸烟活动时不可数；戒烟可用give up smoking。","topic":"health","cefr":"A2"},{"w":"guy","uk":"/ɡaɪ/","p":"n.","zh":"男人；小伙子","ex":{"en":"The guy next door helped carry my groceries.","zh":"隔壁那位小伙子帮我提了买回来的东西。"},"tip":"guy属口语；正式写作通常用man或person。","topic":"daily","cefr":"A2"},{"w":"compare","uk":"/kəmˈpeə/","p":"v.","zh":"比较；对比","ex":{"en":"We compared several backpacks before choosing the lightest one.","zh":"我们比较了几个背包，最后选了最轻的那个。"},"tip":"比较可用with或to；表示比喻时通常用to。","topic":"thinking","cefr":"A2"},{"w":"coloured","uk":"/ˈkʌləd/","p":"adj.","zh":"有颜色的；着色的","ex":{"en":"Sunlight streamed through the coloured glass onto the floor.","zh":"阳光透过彩色玻璃洒在地板上。"},"tip":"英式coloured，美式colored；避免用于泛指族群。","topic":"daily","cefr":"A2"},{"w":"suitcase","uk":"/ˈsuːtkeɪs/","p":"n.","zh":"手提箱；行李箱","ex":{"en":"Her suitcase was too heavy to lift onto the train.","zh":"她的行李箱太重，搬不上火车。"},"tip":"suitcase可数；统称行李的luggage不可数。","topic":"travel","cefr":"A2"},{"w":"poster","uk":"/ˈpəʊstə/","p":"n.","zh":"海报；招贴画","ex":{"en":"She hung a colourful poster above her desk.","zh":"她在书桌上方挂了一张色彩鲜艳的海报。"},"tip":"poster 是海报；postcard 是明信片，注意区分。","topic":"media","cefr":"A2"},{"w":"gift","uk":"/ɡɪft/","p":"n.","zh":"礼物；赠品","ex":{"en":"My sister wrapped the gift in bright yellow paper.","zh":"姐姐用鲜黄色的纸把礼物包了起来。"},"tip":"表示天赋时常用 a gift for，后接名词或动名词。","topic":"daily","cefr":"A2"},{"w":"blouse","uk":"/blaʊz/","p":"n.","zh":"女式衬衫","ex":{"en":"She wore a blue blouse with her favourite grey trousers.","zh":"她穿了一件蓝色女式衬衫，搭配最喜欢的灰色长裤。"},"tip":"通常指女式衬衫；shirt的适用范围更广。","topic":"daily","cefr":"A2"},{"w":"detail","uk":"/ˈdiːteɪl/","p":"n.","zh":"细节；具体信息","ex":{"en":"Please check every detail before you send the invitation.","zh":"发送邀请前，请核对每一处细节。"},"tip":"in detail不用复数；联系方式用contact details。","topic":"daily","cefr":"A2"},{"w":"perhaps","uk":"/pəˈhæps/","p":"adv.","zh":"也许；可能","ex":{"en":"Perhaps we should take an umbrella; those clouds look dark.","zh":"也许我们该带把伞，那些云看起来很阴沉。"},"tip":"perhaps比maybe略正式，可放句首使建议更委婉。","topic":"thinking","cefr":"A2"},{"w":"bakery","uk":"/ˈbeɪkəri/","p":"n.","zh":"面包店；烘焙坊","ex":{"en":"The bakery near our house sells warm bread every morning.","zh":"我们家附近的面包店每天早上都卖热乎乎的面包。"},"tip":"bakery指店铺或制作场所；烘焙食品用baked goods。","topic":"city","cefr":"A2"},{"w":"serve","uk":"/sɜːv/","p":"v.","zh":"端上；供应；接待","ex":{"en":"This little café serves fresh soup with warm bread.","zh":"这家小咖啡馆供应新鲜的汤和温热的面包。"},"tip":"serve as后接角色或用途；serve for不这样用。","topic":"daily","cefr":"A2"},{"w":"neighbour","uk":"/ˈneɪbə/","p":"n.","zh":"邻居；邻近的人或事物","ex":{"en":"Our neighbour watered the plants while we were away.","zh":"我们不在家时，邻居帮忙给植物浇了水。"},"tip":"英式拼写neighbour，美式拼写neighbor。","topic":"society","cefr":"A2"},{"w":"click","uk":"/klɪk/","p":"v.","zh":"点击","ex":{"en":"Click on the picture to see a larger version.","zh":"点击图片即可查看大图。"},"tip":"点击链接常用click on；it clicked可指突然想通了。","topic":"technology","cefr":"A2"},{"w":"jog","uk":"/dʒɒɡ/","p":"v.","zh":"慢跑","ex":{"en":"We jog around the park before breakfast every morning.","zh":"我们每天早饭前都绕着公园慢跑。"},"tip":"jog someone's memory意为“唤起某人的记忆”。","topic":"sport","cefr":"A2"},{"w":"least","uk":"/liːst/","p":"det.","zh":"最少的；最小量的","ex":{"en":"This soup needs the least salt of all.","zh":"这些汤里，这道汤需要的盐最少。"},"tip":"least是little的最高级；修饰可数名词用fewest。","topic":"daily","cefr":"A2"},{"w":"microwave","uk":"/ˈmaɪkrəweɪv/","p":"n.","zh":"微波炉","ex":{"en":"I heated yesterday's soup in the microwave for lunch.","zh":"我用微波炉热了昨天的汤，当作午餐。"},"tip":"作动词可直接接食物：microwave the soup。","topic":"daily","cefr":"A2"},{"w":"butterfly","uk":"/ˈbʌtəflaɪ/","p":"n.","zh":"蝴蝶","ex":{"en":"A yellow butterfly landed gently on my sleeve.","zh":"一只黄色蝴蝶轻轻落在我的袖子上。"},"tip":"复数为butterflies；蝶泳义通常不可数。","topic":"nature","cefr":"A2"},{"w":"congratulations","uk":"/kənˌɡrætʃəˈleɪʃənz/","p":"n.","zh":"祝贺；贺词","ex":{"en":"Congratulations on passing your driving test this morning!","zh":"恭喜你今天上午通过了驾照考试！"},"tip":"祝贺通常用复数；congratulations on后接名词或动名词。","topic":"emotion","cefr":"A2"},{"w":"reach","uk":"/riːtʃ/","p":"v.","zh":"到达；达到","ex":{"en":"We reached the station just before the rain started.","zh":"我们刚到车站，雨就下起来了。"},"tip":"表示到达时直接接地点：reach the station，不加at。","topic":"travel","cefr":"A2"},{"w":"neck","uk":"/nek/","p":"n.","zh":"脖子；颈部","ex":{"en":"He wrapped a warm scarf around his neck.","zh":"他在脖子上围了一条暖和的围巾。"},"tip":"neck指脖子；throat指喉咙，勿混用。","topic":"health","cefr":"A2"},{"w":"lamp","uk":"/læmp/","p":"n.","zh":"灯","ex":{"en":"She switched on the lamp beside her bed.","zh":"她打开了床边的灯。"},"tip":"lamp指灯具；light也可指光或光线。","topic":"daily","cefr":"A2"},{"w":"grape","uk":"/ɡreɪp/","p":"n.","zh":"葡萄","ex":{"en":"She packed some grapes in my lunch box.","zh":"她在我的午餐盒里装了一些葡萄。"},"tip":"单颗葡萄用a grape，一串用a bunch of grapes。","topic":"daily","cefr":"A2"},{"w":"pan","uk":"/pæn/","p":"n.","zh":"平底锅；烤盘","ex":{"en":"Heat the oil in a pan before adding onions.","zh":"先把锅里的油烧热，再放入洋葱。"},"tip":"作动词时过去式为panned，现在分词为panning。","topic":"daily","cefr":"A2"},{"w":"step","uk":"/step/","p":"n.","zh":"一步；台阶","ex":{"en":"Take one step forward and close the door.","zh":"向前迈一步，把门关上。"},"tip":"take steps to do sth表示“采取措施做某事”。","topic":"daily","cefr":"A2"},{"w":"foggy","uk":"/ˈfɒɡi/","p":"adj.","zh":"有雾的；雾蒙蒙的","ex":{"en":"The road was so foggy that we drove slowly.","zh":"路上雾很大，我们只好慢慢开车。"},"tip":"foggy既可形容天气，也可形容记忆模糊。","topic":"nature","cefr":"A2"},{"w":"double","uk":"/ˈdʌbəl/","p":"adj.","zh":"两倍的；双份的","ex":{"en":"I ordered a double portion of rice for lunch.","zh":"我午饭点了双份米饭。"},"tip":"double表示变为原来的两倍，即增加一倍。","topic":"daily","cefr":"A2"},{"w":"carpet","uk":"/ˈkɑːpɪt/","p":"n.","zh":"地毯","ex":{"en":"We sat on the carpet and played cards.","zh":"我们坐在地毯上打牌。"},"tip":"carpet常指大面积地毯；rug多指可移动的小块地毯。","topic":"daily","cefr":"A2"},{"w":"twin","uk":"/twɪn/","p":"n.","zh":"双胞胎之一","ex":{"en":"My twin and I share a love of swimming.","zh":"我的双胞胎手足和我都喜欢游泳。"},"tip":"a twin指双胞胎中的一人；twins指两人。","topic":"society","cefr":"A2"},{"w":"through","uk":"/θruː/","p":"prep.","zh":"穿过；贯穿","ex":{"en":"Sunlight streamed through the curtains and warmed the room.","zh":"阳光透过窗帘洒进来，让房间暖和起来。"},"tip":"through强调从内部穿过；across强调横越表面。","topic":"daily","cefr":"A2"},{"w":"equipment","uk":"/ɪˈkwɪpmənt/","p":"n.","zh":"设备；器材；装备","ex":{"en":"Please put the camping equipment back in the garage.","zh":"请把露营装备放回车库。"},"tip":"不可数；一件设备说a piece of equipment。","topic":"technology","cefr":"A2"},{"w":"trouble","uk":"/ˈtrʌbəl/","p":"n.","zh":"麻烦；困难；故障","ex":{"en":"We had trouble opening the stiff kitchen window.","zh":"厨房的窗户很紧，我们费了好大劲才打开。"},"tip":"表示做某事有困难，用have trouble doing。","topic":"daily","cefr":"A2"},{"w":"glue","uk":"/ɡluː/","p":"n.","zh":"胶；胶水","ex":{"en":"Use a little glue to fix the paper wing.","zh":"用一点胶水把纸翅膀粘好。"},"tip":"作名词通常不可数；be glued to可指目不转睛地看。","topic":"daily","cefr":"A2"},{"w":"argue","uk":"/ˈɑːɡjuː/","p":"v.","zh":"争吵；争论","ex":{"en":"The children argued about whose turn it was to play.","zh":"孩子们为轮到谁玩而争吵。"},"tip":"argue that常用于议论文，表示提出有理由的主张。","topic":"society","cefr":"A2"},{"w":"safe","uk":"/seɪf/","p":"adj.","zh":"安全的；无危险的","ex":{"en":"Your bike is safe inside our locked garage.","zh":"你的自行车放在我们锁好的车库里很安全。"},"tip":"safe是形容词，safety是名词；注意词性区别。","topic":"daily","cefr":"A2"},{"w":"tasty","uk":"/ˈteɪsti/","p":"adj.","zh":"美味的；可口的","ex":{"en":"This tasty soup is perfect for a cold evening.","zh":"这道美味的汤很适合寒冷的夜晚。"},"tip":"tasty指食物美味；tasteful指有品位。","topic":"daily","cefr":"A2"},{"w":"behaviour","uk":"/bɪˈheɪvjə/","p":"n.","zh":"行为；举止","ex":{"en":"The puppy's calm behaviour surprised everyone at the park.","zh":"小狗温顺的表现让公园里的每个人都感到意外。"},"tip":"通常不可数；英式拼写behaviour，美式拼写behavior。","topic":"society","cefr":"A2"},{"w":"stamp","uk":"/stæmp/","p":"n.","zh":"邮票","ex":{"en":"She put a stamp on the envelope before leaving.","zh":"她出门前在信封上贴了一张邮票。"},"tip":"邮票用a stamp；“在信封上贴邮票”用put a stamp on。","topic":"daily","cefr":"A2"},{"w":"unfortunately","uk":"/ʌnˈfɔːtʃənətli/","p":"adv.","zh":"不幸的是；遗憾的是","ex":{"en":"Unfortunately, the bakery had sold out of fresh bread.","zh":"遗憾的是，面包店的新鲜面包已经卖完了。"},"tip":"常置于句首并加逗号，对整件事表示遗憾。","topic":"daily","cefr":"A2"},{"w":"usual","uk":"/ˈjuːʒuəl/","p":"adj.","zh":"通常的；惯常的","ex":{"en":"Our usual table by the window was already taken.","zh":"我们平时坐的窗边那张桌子已经有人了。"},"tip":"as usual意为“照常”；than usual意为“比平时”。","topic":"daily","cefr":"A2"},{"w":"method","uk":"/ˈmeθəd/","p":"n.","zh":"方法；办法","ex":{"en":"This method keeps my herbs fresh for several days.","zh":"这个方法能让我的香草保鲜好几天。"},"tip":"常用a method of/for doing sth表示做事的方法。","topic":"thinking","cefr":"A2"},{"w":"square","uk":"/skweə/","p":"n.","zh":"正方形","ex":{"en":"Fold the paper into a square before cutting it.","zh":"先把纸折成正方形，再剪。"},"tip":"面积用square metres；长度用metres，勿混淆。","topic":"city","cefr":"A2"},{"w":"bottom","uk":"/ˈbɒtəm/","p":"n.","zh":"底部；最下端","ex":{"en":"My keys were at the bottom of my bag.","zh":"我的钥匙在包的最底下。"},"tip":"在某物底部用at the bottom of。","topic":"daily","cefr":"A2"},{"w":"crocodile","uk":"/ˈkrɒkədaɪl/","p":"n.","zh":"鳄鱼","ex":{"en":"We watched a crocodile slide into the river.","zh":"我们看着一条鳄鱼滑入河中。"},"tip":"alligator指短吻鳄，与crocodile并非同一种动物。","topic":"nature","cefr":"A2"},{"w":"clap","uk":"/klæp/","p":"v.","zh":"鼓掌；拍手","ex":{"en":"Everyone clapped when the children finished their song.","zh":"孩子们唱完歌时，大家都鼓起掌来。"},"tip":"过去式clapped；现在分词clapping，双写p。","topic":"arts","cefr":"A2"},{"w":"noon","uk":"/nuːn/","p":"n.","zh":"中午；正午","ex":{"en":"Let's meet outside the library at noon tomorrow.","zh":"我们明天中午在图书馆外见吧。"},"tip":"说at noon，不说in noon；正午是12 p.m.。","topic":"daily","cefr":"A2"},{"w":"discussion","uk":"/dɪˈskʌʃən/","p":"n.","zh":"讨论；商讨","ex":{"en":"We had a lively discussion about our holiday plans.","zh":"我们热烈讨论了度假计划。"},"tip":"名词可接about或of；动词discuss后直接接话题。","topic":"education","cefr":"A2"},{"w":"wedding","uk":"/ˈwedɪŋ/","p":"n.","zh":"婚礼","ex":{"en":"Their wedding took place in a small garden.","zh":"他们的婚礼在一个小花园里举行。"},"tip":"wedding指婚礼；marriage指婚姻关系。","topic":"society","cefr":"A2"},{"w":"blood","uk":"/blʌd/","p":"n.","zh":"血；血液","ex":{"en":"The nurse took some blood from my arm.","zh":"护士从我的手臂抽了一些血。"},"tip":"blood通常不可数；一次验血用a blood test。","topic":"health","cefr":"A2"},{"w":"wallet","uk":"/ˈwɒlɪt/","p":"n.","zh":"钱包；皮夹","ex":{"en":"I left my wallet beside the kitchen sink.","zh":"我把钱包落在厨房水槽旁了。"},"tip":"wallet通常指放纸币和卡片的折叠式钱包。","topic":"daily","cefr":"A2"},{"w":"according","uk":"/əˈkɔː.dɪŋ/","p":"phr.","zh":"据……所说；根据","ex":{"en":"According to the forecast, rain will arrive this evening.","zh":"据天气预报，今晚会下雨。"},"tip":"通常用according to，不单独作形容词。","topic":"thinking","cefr":"A2"},{"w":"bowling","uk":"/ˈbəʊlɪŋ/","p":"n.","zh":"保龄球运动","ex":{"en":"My cousins and I went bowling on Saturday.","zh":"星期六，我和表兄弟姐妹一起去打保龄球了。"},"tip":"保龄球运动用go bowling；也可指板球中的投球。","topic":"sport","cefr":"A2"},{"w":"crowd","uk":"/kraʊd/","p":"n.","zh":"人群；观众","ex":{"en":"A crowd gathered around the musicians in the square.","zh":"一群人聚在广场上的乐手周围。"},"tip":"a crowd of后接复数名词；crowded表示拥挤的。","topic":"society","cefr":"A2"},{"w":"oven","uk":"/ˈʌvən/","p":"n.","zh":"烤箱；烤炉","ex":{"en":"The bread is still warm from the oven.","zh":"面包刚出烤箱，还热乎着。"},"tip":"oven指封闭烤箱；炉顶灶具通常叫hob或stove。","topic":"daily","cefr":"A2"},{"w":"worst","uk":"/wɜːst/","p":"adj.","zh":"最差的；最严重的","ex":{"en":"That was the worst meal I have ever cooked.","zh":"那是我做过的最糟糕的一顿饭。"},"tip":"worst是bad和badly的最高级；比较级是worse。","topic":"daily","cefr":"A2"},{"w":"quietly","uk":"/ˈkwaɪətli/","p":"adv.","zh":"轻声地；安静地","ex":{"en":"Please close the door quietly; the baby is sleeping.","zh":"请轻轻关门，宝宝正在睡觉。"},"tip":"quietly是副词；注意别与quite（相当）混淆。","topic":"daily","cefr":"A2"},{"w":"cute","uk":"/kjuːt/","p":"adj.","zh":"可爱的；讨人喜欢的","ex":{"en":"That cute kitten is sleeping inside my slipper.","zh":"那只可爱的小猫正睡在我的拖鞋里。"},"tip":"偏口语，常形容婴儿、小动物或讨喜的外表。","topic":"daily","cefr":"A2"},{"w":"coach","uk":"/kəʊtʃ/","p":"n.","zh":"教练","ex":{"en":"Our coach showed us how to hold the racket.","zh":"我们的教练示范了如何握球拍。"},"tip":"英式英语中coach也指长途客车，bus多指公交车。","topic":"sport","cefr":"A2"},{"w":"engine","uk":"/ˈendʒɪn/","p":"n.","zh":"发动机；引擎","ex":{"en":"The engine stopped just as we reached the driveway.","zh":"我们刚到车道入口，发动机就熄火了。"},"tip":"engine多指燃料发动机；电动机通常用motor。","topic":"technology","cefr":"A2"},{"w":"law","uk":"/lɔː/","p":"n.","zh":"法律；法规","ex":{"en":"The law requires drivers to stop at red lights.","zh":"法律要求驾驶员在红灯前停车。"},"tip":"具体一条法律可数；法学用不可数的law。","topic":"government","cefr":"A2"},{"w":"bill","uk":"/bɪl/","p":"n.","zh":"账单","ex":{"en":"We asked for the bill after finishing our lunch.","zh":"吃完午饭后，我们请服务员拿来账单。"},"tip":"bill是待审议的法案；通过并生效后才成为法律。","topic":"daily","cefr":"A2"},{"w":"should","uk":"/ʃʊd/","p":"v.","zh":"应该；应当","ex":{"en":"You should take an umbrella because it looks cloudy.","zh":"你应该带把伞，因为天看起来阴沉沉的。"},"tip":"情态动词，后接动词原形；should have done常指本该做却未做。","topic":"daily","cefr":"A2"},{"w":"environment","uk":"/ɪnˈvaɪrənmənt/","p":"n.","zh":"自然环境","ex":{"en":"We cycle to school to help protect the environment.","zh":"我们骑车上学，为保护环境出一份力。"},"tip":"泛指自然环境常用the environment。","topic":"environment","cefr":"A2"},{"w":"perfect","uk":"/ˈpɜːfɪkt/","p":"adj.","zh":"完美的；最合适的","ex":{"en":"This quiet corner is perfect for reading after lunch.","zh":"这个安静的角落特别适合午饭后看书。"},"tip":"形容词重音在前；动词读/pəˈfekt/（英）。","topic":"daily","cefr":"A2"},{"w":"southwest","uk":"/ˌsaʊθˈwest/","p":"n.","zh":"西南方；西南部","ex":{"en":"Our village lies southwest of the nearest town.","zh":"我们的村庄位于最近那座城镇的西南方。"},"tip":"英国英语也常写作south-west。","topic":"travel","cefr":"A2"},{"w":"weekly","uk":"/ˈwiːkli/","p":"adj.","zh":"每周的；每周一次的","ex":{"en":"Our weekly shopping trip usually ends at the bakery.","zh":"我们每周的购物之行通常以去面包店收尾。"},"tip":"既可作形容词也可作副词：a weekly meeting；meet weekly。","topic":"daily","cefr":"A2"},{"w":"kill","uk":"/kɪl/","p":"v.","zh":"杀死；使死亡","ex":{"en":"This soap helps kill germs on your hands.","zh":"这种肥皂有助于杀灭手上的病菌。"},"tip":"kill强调造成死亡；die表示自身死亡，不接宾语。","topic":"environment","cefr":"A2"},{"w":"curtain","uk":"/ˈkɜːtən/","p":"n.","zh":"窗帘；帘子","ex":{"en":"She pulled the curtain aside to watch the rain.","zh":"她把窗帘拉到一边，看着外面的雨。"},"tip":"draw the curtains可指拉开或拉上，需看语境。","topic":"daily","cefr":"A2"},{"w":"pull","uk":"/pʊl/","p":"v.","zh":"拉；拖；拔","ex":{"en":"Please pull the door gently instead of pushing it.","zh":"请轻轻拉门，不要推。"},"tip":"pull是朝自己方向拉；push是向外推。","topic":"daily","cefr":"A2"},{"w":"traffic","uk":"/ˈtræfɪk/","p":"n.","zh":"交通；路上车辆","ex":{"en":"Heavy traffic made us late for dinner again.","zh":"交通拥堵又让我们吃晚饭迟到了。"},"tip":"表示交通或车流时不可数，不说a traffic。","topic":"city","cefr":"A2"},{"w":"toward","uk":"/təˈwɔːd/","p":"prep.","zh":"朝；向","ex":{"en":"The puppy ran toward me with a muddy ball.","zh":"小狗叼着一个沾满泥的球向我跑来。"},"tip":"toward与towards同义；前者美式更常用。","topic":"daily","cefr":"A2"},{"w":"planet","uk":"/ˈplænɪt/","p":"n.","zh":"行星","ex":{"en":"We watched a bright planet through the telescope tonight.","zh":"今晚我们用望远镜观察了一颗明亮的行星。"},"tip":"planet是行星，star是恒星；the planet常指地球。","topic":"science","cefr":"A2"},{"w":"traditional","uk":"/trəˈdɪʃənəl/","p":"adj.","zh":"传统的；沿袭已久的","ex":{"en":"We cooked a traditional meal for the family gathering.","zh":"我们为家庭聚会做了一顿传统饭菜。"},"tip":"traditional强调传承已久，不一定表示落后。","topic":"society","cefr":"A2"},{"w":"software","uk":"/ˈsɒftweə/","p":"n.","zh":"软件","ex":{"en":"This software helps me edit photos on my laptop.","zh":"这个软件帮助我在笔记本电脑上编辑照片。"},"tip":"不可数：说some software，不说a software。","topic":"technology","cefr":"A2"},{"w":"shall","uk":"/ʃæl/","p":"v.","zh":"要不要；好吗","ex":{"en":"Shall we take a short walk after dinner?","zh":"我们晚饭后去散一会儿步好吗？"},"tip":"情态动词，后接动词原形；Shall we常用于提议。","topic":"daily","cefr":"A2"},{"w":"basket","uk":"/ˈbɑːskɪt/","p":"n.","zh":"篮子；筐","ex":{"en":"I carried a basket of fresh apples into the kitchen.","zh":"我提着一篮新鲜苹果走进厨房。"},"tip":"a basket of apples指一篮苹果；篮子数量用baskets。","topic":"daily","cefr":"A2"},{"w":"thief","uk":"/θiːf/","p":"n.","zh":"小偷；窃贼","ex":{"en":"The thief took my bicycle while I was shopping.","zh":"我购物时，小偷偷走了我的自行车。"},"tip":"复数是thieves；robber通常涉及暴力或威胁抢劫。","topic":"society","cefr":"A2"},{"w":"web","uk":"/web/","p":"n.","zh":"万维网","ex":{"en":"I found a simple soup recipe on the web.","zh":"我在网上找到了一份简单的汤谱。"},"tip":"上网常用on the web；web不完全等同于internet。","topic":"technology","cefr":"A2"},{"w":"employee","uk":"/ɪmˈplɔɪiː/","p":"n.","zh":"雇员；员工","ex":{"en":"A new employee showed me around the bakery.","zh":"一位新员工带我参观了面包店。"},"tip":"employee是雇员，employer是雇主。","topic":"work","cefr":"A2"},{"w":"railway","uk":"/ˈreɪlweɪ/","p":"n.","zh":"铁路；铁路系统","ex":{"en":"Our house overlooks the railway near the old bridge.","zh":"从我们家能望见旧桥附近的铁路。"},"tip":"railway常用于英式英语，美式常用railroad。","topic":"travel","cefr":"A2"},{"w":"description","uk":"/dɪˈskrɪpʃən/","p":"n.","zh":"描述；描写","ex":{"en":"Your description helped me find the little bakery.","zh":"你的描述帮我找到了那家小面包店。"},"tip":"表示对某物的描述，用a description of，不用about。","topic":"education","cefr":"A2"},{"w":"pot","uk":"/pɒt/","p":"n.","zh":"锅","ex":{"en":"The soup is bubbling gently in a large pot.","zh":"汤在一口大锅里咕嘟咕嘟地轻轻翻滚。"},"tip":"锅、盆、罐都可用pot；平底煎锅常用pan。","topic":"daily","cefr":"A2"},{"w":"kilometre","uk":"/ˈkɪləmiːtə/","p":"n.","zh":"千米；公里","ex":{"en":"The nearest bus stop is about a kilometre away.","zh":"最近的公交车站大约在一公里外。"},"tip":"英式拼写为kilometre，美式为kilometer。","topic":"travel","cefr":"A2"},{"w":"milkman","uk":"/ˈmɪlkmən/","p":"n.","zh":"送奶工","ex":{"en":"The milkman left two glass bottles outside our door.","zh":"送奶工在我们门外放了两瓶玻璃瓶装的牛奶。"},"tip":"复数为milkmen；不指挤奶者，挤奶者是milker。","topic":"work","cefr":"A2"},{"w":"flight","uk":"/flaɪt/","p":"n.","zh":"航班；空中旅程","ex":{"en":"Our flight leaves early, so we should pack tonight.","zh":"我们的航班出发很早，所以今晚应该收拾好行李。"},"tip":"a flight of stairs指两层或平台之间的一段楼梯。","topic":"travel","cefr":"A2"},{"w":"cause","uk":"/kɔːz/","p":"n.","zh":"原因；起因","ex":{"en":"The plumber found the cause of the leak.","zh":"水管工找到了漏水的原因。"},"tip":"名词常接of；动词可用cause sb to do sth。","topic":"thinking","cefr":"A2"},{"w":"knowledge","uk":"/ˈnɒlɪdʒ/","p":"n.","zh":"知识；学识","ex":{"en":"My grandfather shared his knowledge of birds with me.","zh":"祖父和我分享了他对鸟类的了解。"},"tip":"通常不可数；可说a good knowledge of某领域。","topic":"education","cefr":"A2"},{"w":"order","uk":"/ˈɔːdə/","p":"n.","zh":"顺序；秩序","ex":{"en":"Please put these photos in the correct order.","zh":"请把这些照片按正确顺序排列。"},"tip":"in order指按顺序；in order to后接动词，表示为了。","topic":"daily","cefr":"A2"},{"w":"ground","uk":"/ɡraʊnd/","p":"n.","zh":"地面；土地","ex":{"en":"We spread a blanket on the ground beneath a tree.","zh":"我们在树下的地面上铺了一条毯子。"},"tip":"表示理由常用复数grounds；ground也是grind的过去式。","topic":"nature","cefr":"A2"},{"w":"lorry","uk":"/ˈlɒri/","p":"n.","zh":"卡车；货车","ex":{"en":"A lorry delivered fresh vegetables to the shop.","zh":"一辆货车把新鲜蔬菜送到了店里。"},"tip":"lorry主要用于英式英语，美式英语通常用truck。","topic":"travel","cefr":"A2"},{"w":"hurry","uk":"/ˈhʌri/","p":"v.","zh":"赶紧；催促","ex":{"en":"We hurried home before the rain began to fall.","zh":"我们赶在下雨前匆忙回家了。"},"tip":"hurry up表示催促；in a hurry表示匆忙。","topic":"daily","cefr":"A2"},{"w":"nail","uk":"/neɪl/","p":"n.","zh":"指甲；趾甲","ex":{"en":"I cut my nails before my piano lesson.","zh":"我在上钢琴课前剪了指甲。"},"tip":"既指指甲也指钉子；作动词表示用钉子固定。","topic":"daily","cefr":"A2"},{"w":"stomach","uk":"/ˈstʌmək/","p":"n.","zh":"胃；腹部","ex":{"en":"My stomach started rumbling while I was cooking dinner.","zh":"我做晚饭时，肚子开始咕咕叫。"},"tip":"表示“忍受”时，常用于 can't stomach 结构。","topic":"health","cefr":"A2"},{"w":"pie","uk":"/paɪ/","p":"n.","zh":"馅饼；派","ex":{"en":"We shared a warm apple pie after dinner.","zh":"晚饭后，我们分着吃了一个热苹果派。"},"tip":"pie指馅饼；“饼图”须说pie chart。","topic":"daily","cefr":"A2"},{"w":"form","uk":"/fɔːm/","p":"n.","zh":"类型；形式；形状","ex":{"en":"The clouds took the form of a giant rabbit.","zh":"那些云呈现出一只巨兔的形状。"},"tip":"fill in a form是英式说法；美式常用fill out a form。","topic":"daily","cefr":"A2"},{"w":"attention","uk":"/əˈtenʃən/","p":"n.","zh":"注意；注意力","ex":{"en":"Please pay attention while I explain the game.","zh":"我讲解游戏规则时，请认真听。"},"tip":"pay attention to后接名词或动名词，to是介词。","topic":"thinking","cefr":"A2"},{"w":"hairstyle","uk":"/ˈheəstaɪl/","p":"n.","zh":"发型","ex":{"en":"Your new hairstyle really suits your round glasses.","zh":"你的新发型和你的圆框眼镜真配。"},"tip":"可数名词，指剪出或梳出的整体发型。","topic":"daily","cefr":"A2"},{"w":"workbook","uk":"/ˈwɜːkbʊk/","p":"n.","zh":"练习册","ex":{"en":"I left my workbook in my school bag.","zh":"我把练习册落在书包里了。"},"tip":"workbook侧重练习；textbook侧重讲解知识。","topic":"education","cefr":"A2"},{"w":"type","uk":"/taɪp/","p":"n.","zh":"类型；种类","ex":{"en":"What type of bread would you like today?","zh":"你今天想要哪种面包？"},"tip":"type of后接名词；表示多种类型用types of。","topic":"daily","cefr":"A2"},{"w":"adjective","uk":"/ˈædʒɪktɪv/","p":"n.","zh":"形容词","ex":{"en":"Our teacher asked us to find adjectives describing weather.","zh":"老师让我们找出描述天气的形容词。"},"tip":"形容词常放在名词前或系动词后，如a cold day。","topic":"education","cefr":"A2"},{"w":"skin","uk":"/skɪn/","p":"n.","zh":"皮肤","ex":{"en":"My skin feels dry after swimming in the pool.","zh":"在泳池游泳后，我觉得皮肤很干。"},"tip":"指人体皮肤通常不可数；一张兽皮可数。","topic":"health","cefr":"A2"},{"w":"decide","uk":"/dɪˈsaɪd/","p":"v.","zh":"决定；选定","ex":{"en":"We decided to walk home after the film.","zh":"看完电影后，我们决定走路回家。"},"tip":"用decide to do，不用decide doing。","topic":"thinking","cefr":"A2"},{"w":"painful","uk":"/ˈpeɪnfəl/","p":"adj.","zh":"疼痛的；引起疼痛的","ex":{"en":"My ankle is still painful when I climb stairs.","zh":"我上楼梯时，脚踝还是很疼。"},"tip":"painful可指身体疼痛，也可指情感痛苦或难堪。","topic":"health","cefr":"A2"},{"w":"theirs","uk":"/ðeəz/","p":"pron.","zh":"他们的；她们的；它们的","ex":{"en":"Our garden is small, but theirs has several trees.","zh":"我们的花园很小，但他们的花园里有好几棵树。"},"tip":"theirs独立使用，后不接名词，也不加撇号。","topic":"daily","cefr":"A2"},{"w":"playground","uk":"/ˈpleɪɡraʊnd/","p":"n.","zh":"儿童游乐场；操场","ex":{"en":"The children raced to the playground after lunch.","zh":"午饭后，孩子们跑向了游乐场。"},"tip":"主要指儿童玩耍场所，不泛指专业体育场。","topic":"education","cefr":"A2"},{"w":"loud","uk":"/laʊd/","p":"adj.","zh":"响亮的；大声的","ex":{"en":"A loud crash woke everyone in the house.","zh":"一声巨响惊醒了屋里的所有人。"},"tip":"read out loud指读出声；loudly也可表示大声地。","topic":"daily","cefr":"A2"},{"w":"shout","uk":"/ʃaʊt/","p":"v.","zh":"喊叫；大声说","ex":{"en":"We shouted across the river, but nobody heard us.","zh":"我们朝河对岸大喊，却没有人听见。"},"tip":"shout at常含生气意味；shout to重在让远处的人听见。","topic":"daily","cefr":"A2"},{"w":"beside","uk":"/bɪˈsaɪd/","p":"prep.","zh":"在……旁边","ex":{"en":"Please leave your wet boots beside the door.","zh":"请把你的湿靴子放在门旁边。"},"tip":"beside表示“在旁边”；besides表示“此外；除……之外”。","topic":"daily","cefr":"A2"},{"w":"knee","uk":"/niː/","p":"n.","zh":"膝盖；膝关节","ex":{"en":"She bent her knee gently before starting the exercise.","zh":"开始锻炼前，她轻轻弯了弯膝盖。"},"tip":"词首k不发音；复数knees读作/niːz/。","topic":"health","cefr":"A2"},{"w":"tie","uk":"/taɪ/","p":"v.","zh":"系；绑；打结","ex":{"en":"Please tie your shoelaces before you run outside.","zh":"跑出去之前，请先系好鞋带。"},"tip":"tie的现在分词是tying；表示关系时通常用复数ties。","topic":"daily","cefr":"A2"},{"w":"including","uk":"/ɪnˈkluːdɪŋ/","p":"prep.","zh":"包括；包含","ex":{"en":"Everyone came to the picnic, including our new neighbours.","zh":"大家都来野餐了，包括我们的新邻居。"},"tip":"including后接名词或代词；included通常放其后。","topic":"daily","cefr":"A2"},{"w":"spelling","uk":"/ˈspelɪŋ/","p":"n.","zh":"拼写；拼写能力","ex":{"en":"My sister checks my spelling before I send emails.","zh":"我发邮件前，姐姐会帮我检查拼写。"},"tip":"指拼写能力通常不可数；指具体拼法可数。","topic":"education","cefr":"A2"},{"w":"mind","uk":"/maɪnd/","p":"n.","zh":"头脑；心智；思维","ex":{"en":"Would you mind closing the window before you leave?","zh":"你介意离开前把窗户关上吗？"},"tip":"表示介意做某事用mind doing，不用mind to do。","topic":"thinking","cefr":"A2"},{"w":"tiny","uk":"/ˈtaɪni/","p":"adj.","zh":"极小的；微小的","ex":{"en":"A tiny frog jumped out of the flower pot.","zh":"一只小小的青蛙从花盆里跳了出来。"},"tip":"比small语气更强，强调小得惊人。","topic":"daily","cefr":"A2"},{"w":"backpack","uk":"/ˈbækpæk/","p":"n.","zh":"双肩背包","ex":{"en":"I packed my lunch and jacket in my backpack.","zh":"我把午餐和外套装进了双肩背包。"},"tip":"指双肩背包；英式英语也常用rucksack。","topic":"travel","cefr":"A2"},{"w":"quiz","uk":"/kwɪz/","p":"n.","zh":"小测验；知识问答","ex":{"en":"We played a music quiz after dinner yesterday.","zh":"昨天晚饭后，我们玩了音乐知识问答游戏。"},"tip":"复数为quizzes；过去式为quizzed。","topic":"education","cefr":"A2"},{"w":"cartoon","uk":"/kɑːˈtuːn/","p":"n.","zh":"动画片","ex":{"en":"We watched a funny cartoon about a dancing penguin.","zh":"我们看了一部关于跳舞企鹅的搞笑动画片。"},"tip":"cartoon 可指动画片或单幅漫画；漫画书常用 comic。","topic":"media","cefr":"A2"},{"w":"naughty","uk":"/ˈnɔːti/","p":"adj.","zh":"淘气的；不听话的","ex":{"en":"The naughty puppy dragged my slippers into the garden.","zh":"那只淘气的小狗把我的拖鞋拖进了花园。"},"tip":"常用于小孩或宠物，通常不表示严重的恶行。","topic":"daily","cefr":"A2"},{"w":"elevator","uk":"/ˈelɪveɪtə/","p":"n.","zh":"电梯；升降机","ex":{"en":"We took the elevator because our bags were heavy.","zh":"我们的包很重，所以我们乘了电梯。"},"tip":"电梯在美式英语中常用elevator，英式常用lift。","topic":"city","cefr":"A2"},{"w":"final","uk":"/ˈfaɪnəl/","p":"adj.","zh":"最后的；最终的","ex":{"en":"We packed the final box and locked the door.","zh":"我们装好最后一个箱子，锁上了门。"},"tip":"finally是副词；final作名词可指决赛或期末考试。","topic":"daily","cefr":"A2"},{"w":"melon","uk":"/ˈmelən/","p":"n.","zh":"甜瓜","ex":{"en":"She sliced a ripe melon for our picnic.","zh":"她切了一个熟甜瓜，供我们野餐时吃。"},"tip":"melon泛指甜瓜类；watermelon专指西瓜。","topic":"daily","cefr":"A2"},{"w":"well-known","uk":"/ˌwel ˈnəʊn/","p":"adj.","zh":"著名的；广为人知的","ex":{"en":"We visited a well-known castle during our summer holiday.","zh":"暑假期间，我们参观了一座著名的城堡。"},"tip":"名词前通常加连字符；表语位置通常写well known。","topic":"society","cefr":"A2"},{"w":"chef","uk":"/ʃef/","p":"n.","zh":"专业厨师；主厨","ex":{"en":"The chef added fresh herbs to the steaming soup.","zh":"厨师往热气腾腾的汤里加入了新鲜香草。"},"tip":"chef 的 ch 发 /ʃ/；通常指餐馆或酒店的专业厨师。","topic":"work","cefr":"A2"},{"w":"actually","uk":"/ˈæktʃuəli/","p":"adv.","zh":"实际上；其实","ex":{"en":"I thought this soup was spicy, but it is actually sweet.","zh":"我以为这汤很辣，其实是甜的。"},"tip":"actually表示“其实”，不表示“目前”。","topic":"daily","cefr":"A2"},{"w":"towel","uk":"/ˈtaʊəl/","p":"n.","zh":"毛巾；浴巾","ex":{"en":"He wrapped a warm towel around his wet shoulders.","zh":"他把一条温暖的毛巾裹在湿漉漉的肩膀上。"},"tip":"可数名词；paper towel指吸水纸巾，不是布毛巾。","topic":"daily","cefr":"A2"},{"w":"toe","uk":"/təʊ/","p":"n.","zh":"脚趾","ex":{"en":"There is a little sand stuck between my toes.","zh":"我的脚趾缝里沾了一点沙子。"},"tip":"手指是finger，脚趾是toe；大脚趾用big toe。","topic":"health","cefr":"A2"},{"w":"human","uk":"/ˈhjuːmən/","p":"adj.","zh":"人的；人类的","ex":{"en":"This robot can recognise a familiar human voice.","zh":"这个机器人能识别熟悉的人声。"},"tip":"human是“人类的”；humane是“人道的”。","topic":"society","cefr":"A2"},{"w":"peace","uk":"/piːs/","p":"n.","zh":"和平；和睦","ex":{"en":"I enjoy the peace of this garden before breakfast.","zh":"我喜欢早餐前这座花园里的宁静。"},"tip":"通常不可数；peace of mind表示安心、心安。","topic":"society","cefr":"A2"},{"w":"wave","uk":"/weɪv/","p":"n.","zh":"海浪；波浪；波","ex":{"en":"A huge wave washed over our little sandcastle.","zh":"一个大浪冲过了我们的小沙堡。"},"tip":"向某人挥手用wave at或wave to someone。","topic":"nature","cefr":"A2"},{"w":"hit","uk":"/hɪt/","p":"v.","zh":"击打；碰撞","ex":{"en":"The ball hit the fence and bounced towards me.","zh":"球撞上围栏，又朝我弹了过来。"},"tip":"过去式、过去分词仍为hit；现在分词为hitting。","topic":"daily","cefr":"A2"},{"w":"lift","uk":"/lɪft/","p":"v.","zh":"举起；抬高","ex":{"en":"Can you help me lift this box onto the shelf?","zh":"你能帮我把这个箱子抬到架子上吗？"},"tip":"电梯英式用lift，美式用elevator。","topic":"daily","cefr":"A2"},{"w":"appointment","uk":"/əˈpɔɪntmənt/","p":"n.","zh":"预约；约定会面","ex":{"en":"I have a dental appointment early tomorrow morning.","zh":"我预约了明天一早看牙医。"},"tip":"与某人预约用appointment with；任命某人用appointment of。","topic":"health","cefr":"A2"},{"w":"penny","uk":"/ˈpeni/","p":"n.","zh":"便士；一便士硬币","ex":{"en":"I found a penny underneath the sofa this morning.","zh":"今天早上我在沙发底下发现了一枚便士硬币。"},"tip":"英国金额复数用pence；指多枚硬币用pennies。","topic":"economy","cefr":"A2"},{"w":"jam","uk":"/dʒæm/","p":"n.","zh":"果酱","ex":{"en":"I spread strawberry jam on my toast this morning.","zh":"今天早上我在吐司上抹了草莓酱。"},"tip":"果酱通常不可数；一次交通堵塞用a traffic jam。","topic":"daily","cefr":"A2"},{"w":"normally","uk":"/ˈnɔːməli/","p":"adv.","zh":"通常；一般情况下","ex":{"en":"I normally walk to work unless it rains heavily.","zh":"除非下大雨，我通常步行上班。"},"tip":"既可表频率“通常”，也可表状态“正常地”。","topic":"daily","cefr":"A2"},{"w":"pound","uk":"/paʊnd/","p":"n.","zh":"英镑","ex":{"en":"I paid one pound for this bag of apples.","zh":"我花了一英镑买了这袋苹果。"},"tip":"英镑和重量单位磅都用pound；复数通常加s。","topic":"economy","cefr":"A2"},{"w":"goal","uk":"/ɡəʊl/","p":"n.","zh":"目标","ex":{"en":"My goal is to swim across the pool unaided.","zh":"我的目标是不靠帮助游到泳池对面。"},"tip":"目标用set或achieve；进球用score a goal。","topic":"thinking","cefr":"A2"},{"w":"disappear","uk":"/ˌdɪsəˈpɪə/","p":"v.","zh":"消失；不见；失踪","ex":{"en":"We watched the boat disappear into the thick fog.","zh":"我们看着小船消失在浓雾中。"},"tip":"通常是不及物动词，不说 be disappeared。","topic":"daily","cefr":"A2"},{"w":"push","uk":"/pʊʃ/","p":"v.","zh":"推；按","ex":{"en":"Could you push the trolley while I carry these bags?","zh":"我来拿这些袋子，你能推一下手推车吗？"},"tip":"push表示推，pull表示拉；push for意为力争。","topic":"daily","cefr":"A2"},{"w":"theatre","uk":"/ˈθɪətə/","p":"n.","zh":"剧院","ex":{"en":"We arrived at the theatre just before the play started.","zh":"我们在话剧开演前刚好赶到了剧院。"},"tip":"英式拼写theatre，美式常写theater；英式电影院用cinema。","topic":"arts","cefr":"A2"},{"w":"scientist","uk":"/ˈsaɪəntɪst/","p":"n.","zh":"科学家","ex":{"en":"The scientist examined a drop of water under the microscope.","zh":"这位科学家用显微镜观察了一滴水。"},"tip":"scientist指人，science指科学，scientific是形容词。","topic":"science","cefr":"A2"},{"w":"eighth","uk":"/eɪtθ/","p":"num.","zh":"第八","ex":{"en":"Our apartment is on the eighth floor of this building.","zh":"我们的公寓在这栋楼的八楼。"},"tip":"序数词前通常用the；eighth末尾的th发/θ/。","topic":"daily","cefr":"A2"},{"w":"luckily","uk":"/ˈlʌkɪli/","p":"adv.","zh":"幸好；幸运地","ex":{"en":"My bag fell open, but luckily nothing dropped out.","zh":"我的包掉下来摔开了，幸好没有东西掉出来。"},"tip":"常修饰整个句子，放句首时通常后接逗号。","topic":"daily","cefr":"A2"},{"w":"lovely","uk":"/ˈlʌvli/","p":"adj.","zh":"美丽的；可爱的","ex":{"en":"There are lovely yellow flowers beside the kitchen window.","zh":"厨房窗边有一些漂亮的黄色花朵。"},"tip":"虽以-ly结尾，却是形容词；英式口语中很常见。","topic":"daily","cefr":"A2"},{"w":"exit","uk":"/ˈeksɪt/","p":"n.","zh":"出口；通道","ex":{"en":"We found the exit at the back of the cinema.","zh":"我们在电影院后部找到了出口。"},"tip":"名词指“出口”，动词指“离开”；不要与 exist 混淆。","topic":"city","cefr":"A2"},{"w":"race","uk":"/reɪs/","p":"n.","zh":"速度比赛；赛跑","ex":{"en":"We watched the boat race from the bridge.","zh":"我们在桥上观看了划船比赛。"},"tip":"race可指竞速比赛或种族；不要与民族混同。","topic":"sport","cefr":"A2"},{"w":"although","uk":"/ɔːlˈðəʊ/","p":"conj.","zh":"虽然；尽管","ex":{"en":"Although it was raining, we still walked home.","zh":"虽然下着雨，我们还是走回了家。"},"tip":"引导让步从句；同一句通常不再用but连接主句。","topic":"thinking","cefr":"A2"},{"w":"avoid","uk":"/əˈvɔɪd/","p":"v.","zh":"避免；防止","ex":{"en":"We left early to avoid the morning traffic.","zh":"我们很早就出发了，以避开早高峰的车流。"},"tip":"后接名词或动名词：avoid doing，不用to do。","topic":"daily","cefr":"A2"},{"w":"entrance","uk":"/ˈentrəns/","p":"n.","zh":"入口；大门","ex":{"en":"I'll meet you at the entrance after lunch.","zh":"午饭后我在入口处与你碰面。"},"tip":"某处的入口用entrance to，不用entrance of。","topic":"city","cefr":"A2"},{"w":"shy","uk":"/ʃaɪ/","p":"adj.","zh":"害羞的；腼腆的","ex":{"en":"Lina felt shy when she joined the new club.","zh":"莉娜刚加入这个新社团时有些害羞。"},"tip":"shy away from后接名词或动名词，表示回避。","topic":"emotion","cefr":"A2"},{"w":"lemon","uk":"/ˈlemən/","p":"n.","zh":"柠檬","ex":{"en":"I squeezed half a lemon over the grilled fish.","zh":"我把半个柠檬的汁挤在烤鱼上。"},"tip":"整个柠檬可数；lemon juice中的juice不可数。","topic":"daily","cefr":"A2"},{"w":"laptop","uk":"/ˈlæptɒp/","p":"n.","zh":"笔记本电脑","ex":{"en":"My laptop fits neatly into the front of my backpack.","zh":"我的笔记本电脑正好能放进背包前面的隔层。"},"tip":"laptop是便携电脑；desktop通常指台式电脑。","topic":"technology","cefr":"A2"},{"w":"forever","uk":"/fəˈrevə/","p":"adv.","zh":"永远","ex":{"en":"I wish these sunny afternoons could last forever.","zh":"我希望这些阳光明媚的午后能永远持续下去。"},"tip":"be forever doing常表示不满：老是做某事。","topic":"daily","cefr":"A2"},{"w":"dentist","uk":"/ˈdentɪst/","p":"n.","zh":"牙医","ex":{"en":"The dentist checked my teeth and recommended a softer toothbrush.","zh":"牙医检查了我的牙齿，并建议我用更软的牙刷。"},"tip":"dentist指牙医；the dentist's可指牙医诊所。","topic":"health","cefr":"A2"},{"w":"lock","uk":"/lɒk/","p":"v.","zh":"锁上；锁定","ex":{"en":"Please lock the back door before you go upstairs.","zh":"上楼前请把后门锁好。"},"tip":"lock是锁上，unlock是解锁；两者不可混用。","topic":"daily","cefr":"A2"},{"w":"curly","uk":"/ˈkɜːli/","p":"adj.","zh":"卷曲的；鬈曲的","ex":{"en":"Her curly hair bounced as she ran upstairs.","zh":"她跑上楼时，一头卷发随着步伐上下弹动。"},"tip":"curly卷曲程度明显；wavy通常指轻柔的波浪状。","topic":"daily","cefr":"A2"},{"w":"nervous","uk":"/ˈnɜːvəs/","p":"adj.","zh":"紧张的；忐忑不安的","ex":{"en":"I felt nervous before my first swimming lesson yesterday.","zh":"昨天第一次上游泳课前，我感到很紧张。"},"tip":"nervous about后接名词或动名词，表示对某事紧张。","topic":"emotion","cefr":"A2"},{"w":"practice","uk":"/ˈpræktɪs/","p":"n.","zh":"练习；训练","ex":{"en":"Daily practice helped me play the guitar more confidently.","zh":"每天练习让我弹吉他时更加自信。"},"tip":"英式名词用practice，动词用practise；美式均用practice。","topic":"education","cefr":"A2"},{"w":"roof","uk":"/ruːf/","p":"n.","zh":"屋顶；顶部","ex":{"en":"Rain drummed on the roof throughout the night.","zh":"雨点整夜敲打着屋顶。"},"tip":"复数是roofs；roof指外部屋顶，ceiling指室内天花板。","topic":"city","cefr":"A2"},{"w":"narrow","uk":"/ˈnærəʊ/","p":"adj.","zh":"狭窄的","ex":{"en":"The narrow path only allows us to walk single file.","zh":"这条狭窄的小路只容得下我们排成一列走。"},"tip":"narrow down表示缩小选择范围，不指道路变窄。","topic":"daily","cefr":"A2"},{"w":"anymore","uk":"/ˌeniˈmɔː/","p":"adv.","zh":"再也（不）；（不）再","ex":{"en":"I don't take the bus to school anymore.","zh":"我不再坐公交车上学了。"},"tip":"表示“不再”；英式常写any more，数量“更多”须分写。","topic":"daily","cefr":"A2"},{"w":"ill","uk":"/ɪl/","p":"adj.","zh":"生病的；身体不适的","ex":{"en":"I felt ill after the long bus journey.","zh":"长途乘车后，我感到身体不适。"},"tip":"表示生病时通常作表语：be ill。","topic":"health","cefr":"A2"},{"w":"stone","uk":"/stəʊn/","p":"n.","zh":"石头；石料","ex":{"en":"She picked up a smooth stone beside the lake.","zh":"她在湖边捡起了一块光滑的石头。"},"tip":"石料用不可数stone；一块石头用a stone。","topic":"nature","cefr":"A2"},{"w":"birth","uk":"/bɜːθ/","p":"n.","zh":"出生；分娩","ex":{"en":"The whole family celebrated the birth of our daughter.","zh":"全家人都庆祝了我们女儿的出生。"},"tip":"give birth to表示生下；be born表示出生。","topic":"health","cefr":"A2"},{"w":"tenth","uk":"/tenθ/","p":"num.","zh":"第十","ex":{"en":"Our apartment is on the tenth floor of this building.","zh":"我们的公寓在这栋楼的第十层。"},"tip":"第十通常用the tenth；十分之一用a tenth。","topic":"daily","cefr":"A2"},{"w":"calendar","uk":"/ˈkælɪndə/","p":"n.","zh":"日历；日程表","ex":{"en":"I marked our camping weekend on the kitchen calendar.","zh":"我在厨房的日历上标出了周末露营的日子。"},"tip":"calendar year指一月至十二月，不等于学年。","topic":"daily","cefr":"A2"},{"w":"comb","uk":"/kəʊm/","p":"n.","zh":"梳子","ex":{"en":"She pulled a comb from her bag and tidied her hair.","zh":"她从包里拿出梳子，梳理了一下头发。"},"tip":"词尾b不发音；comb through表示仔细搜查。","topic":"daily","cefr":"A2"},{"w":"golf","uk":"/ɡɒlf/","p":"n.","zh":"高尔夫球运动","ex":{"en":"My grandfather plays golf with his friends every Sunday.","zh":"我祖父每周日都和朋友打高尔夫球。"},"tip":"球类运动前通常不加冠词：play golf。","topic":"sport","cefr":"A2"},{"w":"noisy","uk":"/ˈnɔɪzi/","p":"adj.","zh":"嘈杂的；吵闹的","ex":{"en":"Our noisy washing machine woke everyone up this morning.","zh":"今天早上，吵闹的洗衣机把大家都吵醒了。"},"tip":"noisy是形容词，noise是名词；注意不是nosy。","topic":"daily","cefr":"A2"},{"w":"bench","uk":"/bentʃ/","p":"n.","zh":"长凳","ex":{"en":"We shared a park bench and watched the ducks.","zh":"我们一起坐在公园长凳上看鸭子。"},"tip":"长凳常无靠背，但并非一定如此；工作台也可用bench。","topic":"city","cefr":"A2"},{"w":"secret","uk":"/ˈsiːkrət/","p":"adj.","zh":"秘密的；保密的","ex":{"en":"We planned a secret picnic for our grandparents.","zh":"我们悄悄为祖父母策划了一次野餐。"},"tip":"秘诀常用the secret to，to后接名词或动名词。","topic":"daily","cefr":"A2"},{"w":"rise","uk":"/raɪz/","p":"v.","zh":"上升；增加；上涨","ex":{"en":"Warm air rises above the heater beside my desk.","zh":"我书桌旁的暖气上方，热空气向上升腾。"},"tip":"rise不及物，过去式rose，过去分词risen；raise及物。","topic":"economy","cefr":"A2"},{"w":"sir","uk":"/sɜː/","p":"n.","zh":"先生；老师（尊称）","ex":{"en":"Excuse me, sir, you left your umbrella behind.","zh":"打扰一下，先生，您忘拿伞了。"},"tip":"爵士头衔用Sir加名字或全名，不单加姓氏。","topic":"daily","cefr":"A2"},{"w":"wind","uk":"/wɪnd/, /waɪnd/","p":"n.","zh":"风","ex":{"en":"A sudden gust of wind blew my hat away.","zh":"突然一阵风把我的帽子吹走了。"},"tip":"风读/wɪnd/；缠绕读/waɪnd/，过去式wound。","topic":"nature","cefr":"A2"},{"w":"suppose","uk":"/səˈpəʊz/","p":"v.","zh":"认为；推测","ex":{"en":"I suppose we can eat outside if it stays warm.","zh":"我想，如果天气一直这么暖和，我们可以在外面吃饭。"},"tip":"be supposed to表示应该或按安排做某事。","topic":"thinking","cefr":"A2"},{"w":"wood","uk":"/wʊd/","p":"n.","zh":"木材；木头","ex":{"en":"This little chair is made entirely of solid wood.","zh":"这把小椅子完全由实木制成。"},"tip":"木材义不可数；树林可说a wood或the woods。","topic":"nature","cefr":"A2"},{"w":"private","uk":"/ˈpraɪvət/","p":"adj.","zh":"私人的；非公开的","ex":{"en":"Each guest has a private bathroom beside their bedroom.","zh":"每位客人的卧室旁都有一间专用浴室。"},"tip":"in private表示私下地；in public表示公开地。","topic":"society","cefr":"A2"},{"w":"million","uk":"/ˈmɪljən/","p":"num.","zh":"一百万","ex":{"en":"The city now has more than a million residents.","zh":"这座城市如今有一百多万居民。"},"tip":"具体数词后million不加s；millions of表示数百万。","topic":"society","cefr":"A2"},{"w":"silly","uk":"/ˈsɪli/","p":"adj.","zh":"愚蠢的；不明智的","ex":{"en":"It was silly to leave my umbrella at home.","zh":"把伞留在家里真是不明智。"},"tip":"语气通常比stupid轻，也可表示逗趣、不正经。","topic":"daily","cefr":"A2"},{"w":"repair","uk":"/rɪˈpeə/","p":"v.","zh":"修理；修复","ex":{"en":"Can you repair the broken zip on my jacket?","zh":"你能修好我夹克上坏掉的拉链吗？"},"tip":"具体维修常用复数repairs；beyond repair表示无法修复。","topic":"daily","cefr":"A2"},{"w":"shut","uk":"/ʃʌt/","p":"v.","zh":"关闭；关上；停业","ex":{"en":"Please shut the window before the rain gets in.","zh":"请在雨飘进来之前把窗户关上。"},"tip":"过去式和过去分词均为shut；现在分词为shutting。","topic":"daily","cefr":"A2"},{"w":"myself","uk":"/maɪˈself/","p":"pron.","zh":"我自己","ex":{"en":"I made myself a sandwich before the walk.","zh":"散步前，我给自己做了个三明治。"},"tip":"by myself表示独自或独立；不能用myself代替主语I。","topic":"daily","cefr":"A2"},{"w":"already","uk":"/ɔːlˈredi/","p":"adv.","zh":"已经；早已","ex":{"en":"I have already packed my bag for tomorrow.","zh":"我已经收拾好明天要用的包了。"},"tip":"常置于助动词后、实义动词前；表示已经或比预期早。","topic":"daily","cefr":"A2"},{"w":"medicine","uk":"/ˈmedɪsən/","p":"n.","zh":"药；药物","ex":{"en":"The pharmacist explained how often to take the medicine.","zh":"药剂师解释了这种药应该多久服用一次。"},"tip":"服药用take medicine；表示医学时不可数。","topic":"health","cefr":"A2"},{"w":"closed","uk":"/kləʊzd/","p":"adj.","zh":"关着的；闭合的","ex":{"en":"Keep the window closed while the heating is on.","zh":"开着暖气时，请把窗户关好。"},"tip":"形容词意为“关着的”；也是close的过去式和过去分词。","topic":"daily","cefr":"A2"},{"w":"learning","uk":"/ˈlɜːnɪŋ/","p":"n.","zh":"学习","ex":{"en":"Learning becomes easier when I practise a little every day.","zh":"每天练习一点，学习就变得更容易了。"},"tip":"通常不可数；强调学习过程，knowledge强调所掌握的知识。","topic":"education","cefr":"A2"},{"w":"fishing","uk":"/ˈfɪʃɪŋ/","p":"n.","zh":"钓鱼；捕鱼","ex":{"en":"We went fishing by the lake before breakfast.","zh":"早饭前，我们去湖边钓鱼了。"},"tip":"说“去钓鱼”用go fishing，不用go to fishing。","topic":"nature","cefr":"A2"},{"w":"kick","uk":"/kɪk/","p":"v.","zh":"踢","ex":{"en":"She kicked the ball gently towards her little brother.","zh":"她轻轻地把球踢向弟弟。"},"tip":"kick用脚踢；hit泛指击打，不限定用什么。","topic":"sport","cefr":"A2"},{"w":"certain","uk":"/ˈsɜːtən/","p":"adj.","zh":"确信的；有把握的","ex":{"en":"I'm certain I left my keys on the kitchen table.","zh":"我确信自己把钥匙放在厨房桌上了。"},"tip":"人作主语时，certain of表确信；certain to表必然。","topic":"thinking","cefr":"A2"},{"w":"department","uk":"/dɪˈpɑːtmənt/","p":"n.","zh":"部门；司局；系","ex":{"en":"Please ask our sales department about the delivery date.","zh":"请向我们的销售部门询问送货日期。"},"tip":"大学的系可用department；学院通常用faculty或school。","topic":"work","cefr":"A2"},{"w":"necklace","uk":"/ˈnekləs/","p":"n.","zh":"项链","ex":{"en":"She wore a silver necklace with a tiny bird.","zh":"她戴着一条带有小鸟吊坠的银项链。"},"tip":"结尾-lace读/ləs/，不是单词lace的读音。","topic":"daily","cefr":"A2"},{"w":"corner","uk":"/ˈkɔːnə/","p":"n.","zh":"角落；拐角","ex":{"en":"We put a small lamp in the corner.","zh":"我们在角落里放了一盏小灯。"},"tip":"室内角落用in the corner；街道拐角常用on或at。","topic":"city","cefr":"A2"},{"w":"soft","uk":"/sɒft/","p":"adj.","zh":"柔软的；软的","ex":{"en":"This soft blanket keeps me warm on chilly evenings.","zh":"这条柔软的毯子让我在寒冷的夜晚保持温暖。"},"tip":"soft是形容词；修饰说话等动作通常用softly。","topic":"daily","cefr":"A2"},{"w":"ordinary","uk":"/ˈɔːdənəri/","p":"adj.","zh":"普通的；平常的","ex":{"en":"It looked like an ordinary box until we opened it.","zh":"打开之前，它看起来就是一个普通盒子。"},"tip":"ordinary强调不特别；不等于表示平均水平的average。","topic":"daily","cefr":"A2"},{"w":"gun","uk":"/ɡʌn/","p":"n.","zh":"枪；炮","ex":{"en":"The old gun was displayed behind glass at the museum.","zh":"那支旧枪陈列在博物馆的玻璃展柜里。"},"tip":"gun也可指枪状工具，如glue gun（胶枪）。","topic":"society","cefr":"A2"},{"w":"care","uk":"/keə/","p":"n.","zh":"照料；护理","ex":{"en":"My grandmother receives excellent care at the local clinic.","zh":"我奶奶在当地诊所得到很好的照料。"},"tip":"care about指在意；care for可指照料或喜欢。","topic":"health","cefr":"A2"},{"w":"finger","uk":"/ˈfɪŋɡə/","p":"n.","zh":"手指","ex":{"en":"She wore a silver ring on her middle finger.","zh":"她的中指上戴着一枚银戒指。"},"tip":"通常不包括拇指；拇指专称thumb。","topic":"daily","cefr":"A2"},{"w":"worry","uk":"/ˈwʌri/","p":"v.","zh":"担心；使担忧","ex":{"en":"I worry about my cat when she stays outside.","zh":"猫待在外面时，我会担心她。"},"tip":"worry about表示担心某事；worried描述人的状态。","topic":"emotion","cefr":"A2"},{"w":"fashion","uk":"/ˈfæʃən/","p":"n.","zh":"时尚；流行款式","ex":{"en":"My sister follows fashion but rarely buys expensive clothes.","zh":"我姐姐关注时尚，但很少买昂贵的衣服。"},"tip":"表方式时常用in a ... fashion，语气较正式。","topic":"arts","cefr":"A2"},{"w":"ship","uk":"/ʃɪp/","p":"n.","zh":"大船；海船","ex":{"en":"We watched a huge ship glide into the harbour.","zh":"我们看着一艘巨轮缓缓驶入港口。"},"tip":"ship作动词不只指海运，也可指陆运或空运。","topic":"travel","cefr":"A2"},{"w":"slipper","uk":"/ˈslɪpə/","p":"n.","zh":"拖鞋；室内便鞋","ex":{"en":"I found my missing slipper underneath the sofa.","zh":"我在沙发下面找到了丢失的那只拖鞋。"},"tip":"通常用复数slippers；人字拖常叫flip-flops。","topic":"daily","cefr":"A2"},{"w":"badly","uk":"/ˈbædli/","p":"adv.","zh":"差劲地；糟糕地","ex":{"en":"I slept badly because the room was too hot.","zh":"房间太热，我睡得很不好。"},"tip":"比较级worse，最高级worst；不是bad的形容词用法。","topic":"daily","cefr":"A2"},{"w":"count","uk":"/kaʊnt/","p":"v.","zh":"数；计数","ex":{"en":"Please count the plates before our guests arrive.","zh":"请在客人到来之前数一下盘子。"},"tip":"count on意为依靠；count作“重要”时不及物。","topic":"daily","cefr":"A2"},{"w":"situation","uk":"/ˌsɪtʃuˈeɪʃən/","p":"n.","zh":"情况；形势；处境","ex":{"en":"We faced a difficult situation when our car broke down.","zh":"汽车抛锚时，我们陷入了困境。"},"tip":"表示处于某种情况，用in a situation。","topic":"daily","cefr":"A2"},{"w":"pilot","uk":"/ˈpaɪlət/","p":"n.","zh":"飞行员","ex":{"en":"The pilot landed the plane smoothly despite strong winds.","zh":"尽管风很大，飞行员还是平稳地让飞机着陆了。"},"tip":"pilot作定语常表示试点，如pilot project。","topic":"travel","cefr":"A2"},{"w":"continue","uk":"/kənˈtɪnjuː/","p":"v.","zh":"继续；持续","ex":{"en":"We continued walking along the beach despite the rain.","zh":"尽管下着雨，我们还是继续沿着海滩走。"},"tip":"可接to do或doing，通常都表示继续做某事。","topic":"daily","cefr":"A2"},{"w":"watermelon","uk":"/ˈwɔːtəmelən/","p":"n.","zh":"西瓜","ex":{"en":"We shared a cold watermelon after playing outside.","zh":"在外面玩耍后，我们一起吃了一个冰凉的西瓜。"},"tip":"整个西瓜可数；指切开的瓜肉时常不可数。","topic":"daily","cefr":"A2"},{"w":"heart","uk":"/hɑːt/","p":"n.","zh":"心脏","ex":{"en":"My heart beats faster when I run uphill.","zh":"我跑上坡时，心跳会加快。"},"tip":"by heart表示熟记；lose heart表示灰心。","topic":"health","cefr":"A2"},{"w":"dry","uk":"/draɪ/","p":"adj.","zh":"干的；干燥的","ex":{"en":"The towels are dry after hanging in the sunshine.","zh":"毛巾在阳光下晾过后已经干了。"},"tip":"形容词比较级drier；名词dryer指烘干设备。","topic":"daily","cefr":"A2"},{"w":"van","uk":"/væn/","p":"n.","zh":"厢式货车；面包车","ex":{"en":"We loaded the boxes into a small white van.","zh":"我们把箱子装进了一辆白色的小型厢式货车。"},"tip":"常指载货的封闭式车辆；不要与敞篷货车混淆。","topic":"travel","cefr":"A2"},{"w":"handwriting","uk":"/ˈhændraɪtɪŋ/","p":"n.","zh":"笔迹；手写字","ex":{"en":"Your handwriting is much neater with this new pen.","zh":"你用这支新笔写的字工整多了。"},"tip":"通常不可数；优美书法这门艺术用calligraphy。","topic":"education","cefr":"A2"},{"w":"round","uk":"/raʊnd/","p":"adj.","zh":"圆形的；球形的","ex":{"en":"We placed a round table beside the kitchen window.","zh":"我们在厨房窗边放了一张圆桌。"},"tip":"round作介词常见于英式英语，美式多用around。","topic":"daily","cefr":"A2"},{"w":"festival","uk":"/ˈfestɪvəl/","p":"n.","zh":"节日；庆祝活动","ex":{"en":"Our town holds a lantern festival every autumn.","zh":"我们镇每年秋天都会举办灯会。"},"tip":"festival强调庆祝或系列活动，不一定是放假的holiday。","topic":"arts","cefr":"A2"},{"w":"connect","uk":"/kəˈnekt/","p":"v.","zh":"连接；接通","ex":{"en":"Connect your phone to the speaker using this cable.","zh":"用这根线把手机连接到音箱上。"},"tip":"连接设备常用connect A to B。","topic":"technology","cefr":"A2"},{"w":"receive","uk":"/rɪˈsiːv/","p":"v.","zh":"收到；得到","ex":{"en":"Did you receive the photos I sent yesterday?","zh":"你收到我昨天发的照片了吗？"},"tip":"receive侧重收到；accept侧重愿意接受。","topic":"daily","cefr":"A2"},{"w":"hiking","uk":"/ˈhaɪkɪŋ/","p":"n.","zh":"徒步旅行；远足","ex":{"en":"These boots keep my feet dry when I go hiking.","zh":"我去远足时，这双靴子能让双脚保持干爽。"},"tip":"通常指乡野长途步行；也可作hike的现在分词。","topic":"travel","cefr":"A2"},{"w":"blond","uk":"/blɒnd/","p":"adj.","zh":"金黄色头发的","ex":{"en":"His blond hair looked almost white in the sunshine.","zh":"他的金发在阳光下看起来几乎是白色的。"},"tip":"blonde常用于女性；词义不限定肤色。","topic":"daily","cefr":"A2"},{"w":"mark","uk":"/mɑːk/","p":"n.","zh":"痕迹；记号","ex":{"en":"Your wet glass left a mark on the table.","zh":"你的湿杯子在桌上留下了一道印子。"},"tip":"表示考试分数常用复数marks，尤其在英式英语中。","topic":"education","cefr":"A2"},{"w":"huge","uk":"/hjuːdʒ/","p":"adj.","zh":"巨大的；大量的","ex":{"en":"A huge dog was sleeping beside the tiny kitten.","zh":"一只大狗正睡在那只小猫旁边。"},"tip":"本身表示极大，常用absolutely huge加强语气。","topic":"daily","cefr":"A2"},{"w":"flu","uk":"/fluː/","p":"n.","zh":"流行性感冒","ex":{"en":"She stayed in bed all weekend with the flu.","zh":"她得了流感，整个周末都卧床休息。"},"tip":"flu通常不可数；英式常说have flu，美式常加the。","topic":"health","cefr":"A2"},{"w":"advertisement","uk":"/ədˈvɜːtɪsmənt/","p":"n.","zh":"广告","ex":{"en":"I saw an advertisement for bicycles at the station.","zh":"我在车站看到了一则自行车广告。"},"tip":"广告内容用 for 引出；advertising 泛指广告活动。","topic":"media","cefr":"A2"},{"w":"hockey","uk":"/ˈhɒki/","p":"n.","zh":"曲棍球；冰球","ex":{"en":"We practised hockey on the school field yesterday.","zh":"昨天我们在学校运动场练习了曲棍球。"},"tip":"英国通常指草地曲棍球；美国通常指冰球。","topic":"sport","cefr":"A2"},{"w":"accident","uk":"/ˈæksɪdənt/","p":"n.","zh":"事故","ex":{"en":"Luckily, nobody was hurt in the accident outside our house.","zh":"幸好，我们家外面发生的事故没有造成人员受伤。"},"tip":"by accident表示无意中，反义短语是on purpose。","topic":"daily","cefr":"A2"},{"w":"speech","uk":"/spiːtʃ/","p":"n.","zh":"演讲；发言","ex":{"en":"Leila practised her speech in front of the mirror.","zh":"莱拉对着镜子练习演讲。"},"tip":"一次演讲用a speech；说话能力通常不可数。","topic":"education","cefr":"A2"},{"w":"lake","uk":"/leɪk/","p":"n.","zh":"湖；湖泊","ex":{"en":"We rented a small boat and crossed the lake.","zh":"我们租了一条小船，划到了湖对岸。"},"tip":"on the lake 指在湖面上；in the lake 指在湖水中。","topic":"nature","cefr":"A2"},{"w":"paragraph","uk":"/ˈpærəɡrɑːf/","p":"n.","zh":"段落","ex":{"en":"This paragraph is too long for a quick email.","zh":"对于一封简短的邮件来说，这一段太长了。"},"tip":"可数名词；写作中通常一段围绕一个中心意思。","topic":"education","cefr":"A2"},{"w":"chance","uk":"/tʃɑːns/","p":"n.","zh":"机会","ex":{"en":"Can you give me another chance to explain?","zh":"你能再给我一次解释的机会吗？"},"tip":"机会用chance to do；可能性常用chance of doing。","topic":"society","cefr":"A2"},{"w":"sightseeing","uk":"/ˈsaɪtsiːɪŋ/","p":"n.","zh":"观光；游览","ex":{"en":"We spent the morning sightseeing around the old harbour.","zh":"我们花了一上午在老港口一带观光。"},"tip":"不可数名词；说go sightseeing，不加a。","topic":"travel","cefr":"A2"},{"w":"touch","uk":"/tʌtʃ/","p":"v.","zh":"触摸；碰","ex":{"en":"Please don't touch the pan; it is still hot.","zh":"请别碰锅，它还很烫。"},"tip":"保持联系用keep in touch with someone。","topic":"daily","cefr":"A2"},{"w":"drawing","uk":"/ˈdrɔːɪŋ/","p":"n.","zh":"图画；素描","ex":{"en":"He showed me a drawing of his cat.","zh":"他给我看了一幅他画的猫。"},"tip":"指一幅画时可数；指绘画活动时通常不可数。","topic":"arts","cefr":"A2"},{"w":"dessert","uk":"/dɪˈzɜːt/","p":"n.","zh":"餐后甜点","ex":{"en":"We shared a bowl of ice cream for dessert.","zh":"我们分吃了一碗冰淇淋作为餐后甜点。"},"tip":"dessert有两个s，重音在后；desert作沙漠时重音在前。","topic":"daily","cefr":"A2"},{"w":"canteen","uk":"/kænˈtiːn/","p":"n.","zh":"食堂","ex":{"en":"We usually eat lunch together in the school canteen.","zh":"我们通常一起在学校食堂吃午饭。"},"tip":"英式英语中常指食堂；美式英语常用cafeteria。","topic":"education","cefr":"A2"},{"w":"builder","uk":"/ˈbɪldə/","p":"n.","zh":"建筑工人；建筑商","ex":{"en":"The builder replaced the broken bricks around our doorway.","zh":"建筑工人更换了我们家门口周围破损的砖块。"},"tip":"可指建筑工人，也可指承建房屋的公司。","topic":"work","cefr":"A2"},{"w":"solve","uk":"/sɒlv/","p":"v.","zh":"解决；解答","ex":{"en":"We solved the puzzle together after dinner last night.","zh":"昨晚晚饭后，我们一起解开了那道谜题。"},"tip":"solve直接接问题；“溶解”用dissolve。","topic":"thinking","cefr":"A2"},{"w":"spoon","uk":"/spuːn/","p":"n.","zh":"匙；勺子","ex":{"en":"She stirred her soup with a wooden spoon.","zh":"她用木勺搅了搅汤。"},"tip":"一勺的量通常用 a spoonful of 表达。","topic":"daily","cefr":"A2"},{"w":"disagree","uk":"/ˌdɪsəˈɡriː/","p":"v.","zh":"不同意；意见不合","ex":{"en":"We disagree about which colour to paint the kitchen.","zh":"我们对于厨房该刷什么颜色意见不一。"},"tip":"不同意某人用disagree with；争议话题用on或about。","topic":"thinking","cefr":"A2"},{"w":"author","uk":"/ˈɔːθə/","p":"n.","zh":"作者；作家","ex":{"en":"The author answered questions about her new adventure novel.","zh":"这位作者回答了有关她新出版的冒险小说的问题。"},"tip":"“……的作者”用the author of；也可作动词。","topic":"arts","cefr":"A2"},{"w":"soap","uk":"/səʊp/","p":"n.","zh":"肥皂","ex":{"en":"Please wash your hands with soap before lunch.","zh":"午饭前请用肥皂洗手。"},"tip":"指清洁用品通常不可数；一块用a bar of soap。","topic":"health","cefr":"A2"},{"w":"pea","uk":"/piː/","p":"n.","zh":"豌豆；豌豆粒","ex":{"en":"She added frozen peas to the vegetable soup.","zh":"她往蔬菜汤里加了些冷冻豌豆。"},"tip":"可数名词；泛指食用的豌豆通常用复数peas。","topic":"daily","cefr":"A2"},{"w":"colourful","uk":"/ˈkʌləfəl/","p":"adj.","zh":"色彩鲜艳的；五彩缤纷的","ex":{"en":"Colourful balloons floated above the tables at the party.","zh":"聚会上，五彩缤纷的气球飘浮在桌子上方。"},"tip":"英式拼写colourful，美式拼写colorful。","topic":"arts","cefr":"A2"},{"w":"throw","uk":"/θrəʊ/","p":"v.","zh":"扔；投；掷","ex":{"en":"Throw me the ball before the dog grabs it.","zh":"趁狗还没抢到球，快把球扔给我。"},"tip":"不规则变化：throw–threw–thrown；聚会也可用throw。","topic":"sport","cefr":"A2"},{"w":"nasty","uk":"/ˈnɑːsti/","p":"adj.","zh":"令人不快的；难闻的","ex":{"en":"A nasty smell came from the kitchen bin.","zh":"厨房垃圾桶里散发出一股难闻的气味。"},"tip":"比bad更带厌恶感；形容人时通常指刻薄、不友善。","topic":"daily","cefr":"A2"},{"w":"explain","uk":"/ɪkˈspleɪn/","p":"v.","zh":"解释；说明","ex":{"en":"Could you explain how this coffee machine works?","zh":"你能说明一下这台咖啡机怎么用吗？"},"tip":"说explain something to someone，不说explain someone。","topic":"education","cefr":"A2"},{"w":"possibly","uk":"/ˈpɒsəbli/","p":"adv.","zh":"可能；也许","ex":{"en":"We could possibly have a picnic if the rain stops.","zh":"如果雨停了，我们也许可以去野餐。"},"tip":"can't possibly表示“绝不可能”，语气很强。","topic":"thinking","cefr":"A2"},{"w":"silver","uk":"/ˈsɪlvə/","p":"n.","zh":"银","ex":{"en":"This little spoon is made of pure silver.","zh":"这把小勺子是纯银做的。"},"tip":"表示金属银时不可数；a silver可指一枚银牌。","topic":"daily","cefr":"A2"},{"w":"copy","uk":"/ˈkɒpi/","p":"n.","zh":"副本；一本；一份","ex":{"en":"Please keep a copy of the receipt at home.","zh":"请在家里留一份收据副本。"},"tip":"复数为copies；广告文案义的copy通常不可数。","topic":"education","cefr":"A2"},{"w":"travelling","uk":"/ˈtrævəlɪŋ/","p":"n.","zh":"旅行；出行","ex":{"en":"Travelling by train gives me time to enjoy the scenery.","zh":"乘火车旅行让我有时间欣赏沿途风景。"},"tip":"英式拼写双写l；美式通常写traveling。","topic":"travel","cefr":"A2"},{"w":"differently","uk":"/ˈdɪfrəntli/","p":"adv.","zh":"不同地；以不同方式","ex":{"en":"My sister and I arrange our desks differently.","zh":"我和姐姐布置书桌的方式不同。"},"tip":"副词修饰动词；形容人或事物不同用different。","topic":"daily","cefr":"A2"},{"w":"officer","uk":"/ˈɒfɪsə/","p":"n.","zh":"警察；警官","ex":{"en":"A police officer helped us find the station.","zh":"一位警察帮我们找到了车站。"},"tip":"officer可指警察或军官，具体含义看搭配。","topic":"society","cefr":"A2"},{"w":"panda","uk":"/ˈpændə/","p":"n.","zh":"大熊猫","ex":{"en":"The panda sat quietly, chewing a fresh bamboo shoot.","zh":"那只大熊猫静静地坐着，嚼着一根新鲜竹笋。"},"tip":"panda通常指大熊猫；red panda指小熊猫。","topic":"nature","cefr":"A2"},{"w":"experience","uk":"/ɪkˈspɪəriəns/","p":"n.","zh":"经验","ex":{"en":"My sister has years of experience repairing old bicycles.","zh":"我姐姐有多年修理旧自行车的经验。"},"tip":"表“经验”不可数；表具体“经历”可数。","topic":"work","cefr":"A2"},{"w":"increase","uk":"/ɪnˈkriːs/","p":"v.","zh":"增加；提高","ex":{"en":"The bakery increased its prices again this week.","zh":"这家面包店本周又涨价了。"},"tip":"动词重音在后，名词在前；by接增量，to接终值。","topic":"economy","cefr":"A2"},{"w":"belong","uk":"/bɪˈlɒŋ/","p":"v.","zh":"属于；归某人所有","ex":{"en":"This blue umbrella belongs to my younger sister.","zh":"这把蓝色雨伞是我妹妹的。"},"tip":"belong to表示属于，不用被动语态或进行时。","topic":"society","cefr":"A2"},{"w":"almost","uk":"/ˈɔːlməʊst/","p":"adv.","zh":"几乎；差不多","ex":{"en":"I almost missed the bus while tying my shoes.","zh":"我系鞋带时差点错过了公交车。"},"tip":"almost可接all、every和no；不能直接接most。","topic":"daily","cefr":"A2"},{"w":"tape-recorder","uk":"/ˈteɪp rɪˌkɔːdə/","p":"n.","zh":"磁带录音机","ex":{"en":"My grandfather still uses a tape-recorder to record songs.","zh":"我祖父仍用磁带录音机录制歌曲。"},"tip":"现代通常写作tape recorder，不加连字符。","topic":"technology","cefr":"A2"},{"w":"exactly","uk":"/ɪɡˈzæktli/","p":"adv.","zh":"精确地；恰好","ex":{"en":"This jacket is exactly the colour I wanted.","zh":"这件夹克正是我想要的颜色。"},"tip":"not exactly常表示并非完全，也可委婉否定。","topic":"daily","cefr":"A2"},{"w":"either","uk":"/ˈaɪðə/","p":"det.","zh":"两者任一；两边各一","ex":{"en":"You can borrow either umbrella; both are dry.","zh":"两把伞你随便借哪把都行，都是干的。"},"tip":"either…or…表二选一；否定句末either表“也不”。","topic":"daily","cefr":"A2"},{"w":"camp","uk":"/kæmp/","p":"n.","zh":"营地；度假营","ex":{"en":"We returned to camp before the rain started.","zh":"我们在下雨前回到了营地。"},"tip":"go camping表示去露营；camp也可指观点相同的阵营。","topic":"travel","cefr":"A2"},{"w":"suddenly","uk":"/ˈsʌdənli/","p":"adv.","zh":"突然；忽然","ex":{"en":"The lights suddenly went out while we were cooking.","zh":"我们做饭时，灯突然灭了。"},"tip":"可置于句首或动词前；强调变化突然、事先无预兆。","topic":"daily","cefr":"A2"},{"w":"gas","uk":"/ɡæs/","p":"n.","zh":"气体","ex":{"en":"We use gas to cook our meals at home.","zh":"我们在家用燃气做饭。"},"tip":"泛指气体通常不可数；多种气体用gases。","topic":"science","cefr":"A2"},{"w":"scissors","uk":"/ˈsɪzəz/","p":"n.","zh":"剪刀","ex":{"en":"Please use these scissors to cut the wrapping paper.","zh":"请用这把剪刀裁剪包装纸。"},"tip":"通常用复数；一把剪刀说a pair of scissors。","topic":"daily","cefr":"A2"},{"w":"goldfish","uk":"/ˈɡəʊldfɪʃ/","p":"n.","zh":"金鱼","ex":{"en":"Our goldfish swims between the plants in its large tank.","zh":"我们的金鱼在大鱼缸里的水草间游来游去。"},"tip":"goldfish单复数同形：one goldfish，two goldfish。","topic":"nature","cefr":"A2"},{"w":"tail","uk":"/teɪl/","p":"n.","zh":"尾巴；尾部","ex":{"en":"The dog wagged its tail when I came home.","zh":"我回家时，那只狗摇起了尾巴。"},"tip":"tail指尾巴；tale指故事，两词同音。","topic":"nature","cefr":"A2"},{"w":"own","uk":"/əʊn/","p":"adj.","zh":"自己的","ex":{"en":"I finally have my own room in our new flat.","zh":"在我们的新公寓里，我终于有了自己的房间。"},"tip":"own表“自己的”前通常有物主词，如my own。","topic":"daily","cefr":"A2"},{"w":"celebrate","uk":"/ˈselɪbreɪt/","p":"v.","zh":"庆祝","ex":{"en":"We cooked a special dinner to celebrate her graduation.","zh":"我们做了一顿特别的晚餐来庆祝她毕业。"},"tip":"庆祝某事用celebrate；祝贺某人用congratulate。","topic":"society","cefr":"A2"},{"w":"wooden","uk":"/ˈwʊdən/","p":"adj.","zh":"木制的","ex":{"en":"She stirred the soup slowly with a wooden spoon.","zh":"她用木勺慢慢搅拌汤。"},"tip":"wooden指木制；woody多指木质或像木头的。","topic":"daily","cefr":"A2"},{"w":"necessary","uk":"/ˈnesəsəri/","p":"adj.","zh":"必要的；必需的","ex":{"en":"Take a warm coat if you think it's necessary.","zh":"如果你觉得有必要，就带上一件暖和的外套。"},"tip":"常用it is necessary to do；necessarily意为“必然地”。","topic":"daily","cefr":"A2"},{"w":"suggest","uk":"/səˈdʒest/","p":"v.","zh":"建议；提议","ex":{"en":"I suggest taking an umbrella because those clouds look dark.","zh":"我建议带把伞，因为那些云看起来很阴沉。"},"tip":"用suggest doing或suggest that从句，不用suggest to do。","topic":"thinking","cefr":"A2"},{"w":"air-conditioning","uk":"/ˈeə kəndɪʃənɪŋ/","p":"n.","zh":"空调；空气调节系统","ex":{"en":"Please turn on the air-conditioning before the guests arrive.","zh":"请在客人到来之前打开空调。"},"tip":"不可数；一台空调机用an air conditioner。","topic":"daily","cefr":"A2"},{"w":"messy","uk":"/ˈmesi/","p":"adj.","zh":"凌乱的；脏乱的","ex":{"en":"His desk was messy after an afternoon of painting.","zh":"画了一下午画后，他的书桌变得脏乱不堪。"},"tip":"messy可指物品脏乱，也可指局面复杂难处理。","topic":"daily","cefr":"A2"},{"w":"recently","uk":"/ˈriːsəntli/","p":"adv.","zh":"最近；不久前","ex":{"en":"We recently moved into a flat near the river.","zh":"我们最近搬进了河边的一套公寓。"},"tip":"可用于一般过去时或现在完成时，不只限于完成时。","topic":"daily","cefr":"A2"},{"w":"mostly","uk":"/ˈməʊstli/","p":"adv.","zh":"主要地；大多","ex":{"en":"My weekend was mostly spent cooking and reading.","zh":"我的周末大部分时间都用来做饭和看书了。"},"tip":"mostly指大部分情况；almost指差一点或几乎。","topic":"daily","cefr":"A2"},{"w":"musical","uk":"/ˈmjuːzɪkəl/","p":"adj.","zh":"音乐的；有音乐天赋的","ex":{"en":"He keeps his musical instruments beside the sofa.","zh":"他把乐器放在沙发旁边。"},"tip":"作形容词指“音乐的”；作可数名词指音乐剧等。","topic":"arts","cefr":"A2"},{"w":"shake","uk":"/ʃeɪk/","p":"v.","zh":"摇动；抖动；颤抖","ex":{"en":"Shake the bottle well before pouring juice into your glass.","zh":"把果汁倒进杯子前，先充分摇匀瓶子。"},"tip":"不规则变化：shake—shook—shaken。","topic":"daily","cefr":"A2"},{"w":"litre","uk":"/ˈliːtə/","p":"n.","zh":"升（容积单位）","ex":{"en":"We need a litre of milk for this pudding.","zh":"做这道布丁需要一升牛奶。"},"tip":"英式拼写litre，美式liter；复数加s。","topic":"daily","cefr":"A2"},{"w":"haircut","uk":"/ˈheəkʌt/","p":"n.","zh":"理发；发型","ex":{"en":"I need a haircut before my cousin's wedding.","zh":"表亲的婚礼之前，我需要理个发。"},"tip":"说get或have a haircut，不说cut a haircut。","topic":"daily","cefr":"A2"},{"w":"expect","uk":"/ɪkˈspekt/","p":"v.","zh":"预料；预计","ex":{"en":"We expect rain, so take an umbrella with you.","zh":"我们预计会下雨，所以带上雨伞吧。"},"tip":"expect偏重认为会发生，hope偏重希望发生。","topic":"thinking","cefr":"A2"},{"w":"pineapple","uk":"/ˈpaɪnæpəl/","p":"n.","zh":"菠萝；凤梨","ex":{"en":"She sliced a fresh pineapple for our picnic.","zh":"她为我们的野餐切了一个新鲜菠萝。"},"tip":"整个菠萝可数，作为食物的菠萝果肉常不可数。","topic":"daily","cefr":"A2"},{"w":"bone","uk":"/bəʊn/","p":"n.","zh":"骨；骨头","ex":{"en":"He broke a bone in his wrist while skating.","zh":"他滑冰时摔断了手腕的一块骨头。"},"tip":"bone作动词指去骨；boneless表示无骨的。","topic":"health","cefr":"A2"},{"w":"mirror","uk":"/ˈmɪrə/","p":"n.","zh":"镜子","ex":{"en":"He checked his hair in the mirror before leaving.","zh":"他离开前照镜子检查了一下头发。"},"tip":"照镜子用look in the mirror，不用look the mirror。","topic":"daily","cefr":"A2"}];

